    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Part A: Number of Participants With Treatment Emergent Adverse Events (TEAEs)",
   "description": "An adverse event (AE) was defined as any untoward medical occurrence in any participant participating in a clinical investigation, regardless of the suspected cause. An AE was therefore any unfavorable and unintended sign, symptom, disease, concurrent illness, or clinically significant abnormal laboratory finding that emerged or worsened during the study. A TEAE was defined as an AE that first occurred or worsened after initiation of study drug.",
   "timeFrame": "Up to Week 80"
  },
  {
   "measure": "Part A: Number of Participants With TEAEs by Severity",
   "description": "A TEAE was defined as an AE that first occurred or worsened after initiation of study drug and was graded by severity per protocol-specified Common Terminology Criteria for Adverse Events (CTCAE) criteria: Grade 1, Mild (asymptomatic or mild symptoms; clinical or diagnostic observations only; intervention not indicated); Grade 2, Moderate (minimal, local, or noninvasive intervention indicated; limited age-appropriate instrumental activities of daily living (ADL)); Grade 3, Severe or medically significant (medically significant but not immediately life-threatening; hospitalization or prolongation of hospitalization indicated; disabling; or limiting self-care ADL); Grade 4, Life-threatening (threatening consequences; urgent intervention indicated); and Grade 5, Death (death related to an AE).",
   "timeFrame": "Up to Week 80"
  },
  {
   "measure": "Part A: Number of Participants With TEAEs Related to Study Drug",
   "description": "An AE was defined as any untoward medical occurrence in any participant participating in a clinical investigation, regardless of the suspected cause. An AE was therefore can be any unfavorable and unintended sign, symptom, disease, concurrent illness, or clinically significant abnormal laboratory finding that emerged or worsened during the study. A TEAE was defined as an AE that first occurred or worsened after initiation of study drug. An AE with missing relationship to study drug was considered as related to study drug.",
   "timeFrame": "Up to Week 80"
  },
  {
   "measure": "Part A: Mean Change From Baseline in the Inclusion Body Myositis Functional Rating Scale (IBMFRS) Total Score at Week 76",
   "description": "The IBMFRS was used as an ordinal rating scale to determine participant's assessments of their capabilities. It included 10 measures (swallowing, handwriting, cutting food and handling utensils, fine motor tasks, dressing, hygiene, turning in bed and adjusting covers, changing position from sitting to standing, walking, and climbing stairs) graded on a Likert scale (a psychometric tool) from 0 (being unable to perform) to 4 (normal). The sum of the 10 items provided a value between 0 and 40, with a higher score representing less functional limitation or better functional status. Baseline value was defined as the last non-missing valid value prior to first administration of study treatment (on Day 1). Change from Baseline was calculated as the data collected at post-randomization visits minus the Baseline.",
   "timeFrame": "Baseline (Day 1) and at Week 76"
  },
  {
   "measure": "Part B: Number of Participants With TEAEs",
   "description": "An AE was defined as any untoward medical occurrence in any participant participating in a clinical investigation, regardless of the suspected cause. An AE was therefore can be any unfavorable and unintended sign, symptom, disease, concurrent illness, or clinically significant abnormal laboratory finding that emerged or worsened during the study. A TEAE was defined as an AE that first occurred or worsened after initiation of study drug.",
   "timeFrame": "Day 1 to Week 80"
