forecastInput:
{
 "nctId": "NCT03625622",
 "briefTitle": "Efficacy and Safety of 26-Week Treatment of AR1001 in Patients With Mild to Moderate Alzheimer's Disease",
 "officialTitle": "A Double-Blind, Randomized, Placebo-Controlled Study to Evaluate Efficacy and Safety of 26-Week Treatment of AR1001 in Patients With Mild to Moderate Alzheimer's Disease",
 "leadSponsor": {
  "name": "AriBio Co., Ltd.",
  "class": "INDUSTRY"
 },
 "startDate": "2019-04-01",
 "firstRegistered": "2018-08-08",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Mild to Moderate Alzheimer's Disease"
 ],
 "keywords": [
  "Alzheimer's disease"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "interventionModelDescription": "After the first 26 weeks, subjects can participate in an optional extension study to receive either 10 mg or 30 mg AR1001 for an additional 26 weeks.",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "maskingDescription": "Double-blind for study site and participants",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 210,
 "briefSummary": "A double-blinded, randomized, placebo-controlled study will be performed to evaluate the efficacy and safety of treating AR1001 in patients with mild to moderate Alzheimer's disease for 26 weeks. An optional 26 week extension phase will be available to participants who successfully complete the original phase of the study.",
 "detailedDescription": "Alzheimer's Disease (AD) is the most prevalent neurodegenerative disorder in The United States affecting approximately 5.4 million Americans. AD is characterized by progressive loss in memory and as well as a decline in the ability to learn that is associated with neuronal death. Well known hallmarks of AD are neuritic plaques and neurofibrillary tangles and extensive inflammation. Currently, no treatment has been developed to fully cure or prevent the progression of dementia that is associated with AD.\n\nAR1001 is a polypharmacological drug candidate being developed as a treatment for AD and shows great potential with favorable attributes for a central nervous system (CNS) drug (i.e., high specificity and potency, as well as good pharmacokinetic, bioavailability, CNS penetration, and ensured safety).\n\nThe clinical study of AR1001 aims to evaluate the efficacy and safety of AR1001 as a potential treatment for AD. Based on the preclinical results, AR1001 could be an effective treatment option with a mechanism of action that has not been explored for AD indication.",
 "arms": [
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Placebo, orally administered once daily for 26 weeks.",
   "interventionNames": [
    "Drug: Placebo"
   ]
  },
  {
   "label": "AR1001 - 10 mg",
   "type": "ACTIVE_COMPARATOR",
   "description": "Active, AR1001 - 10 mg, orally administered once daily for 26 weeks plus a 26 week extension phase.",
   "interventionNames": [
    "Drug: AR1001 10mg"
   ]
  },
  {
