   ]
  },
  {
   "type": "DRUG",
   "name": "AVP-786",
   "description": "oral capsules",
   "armGroupLabels": [
    "AVP-786"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline (Week 3) to Week 15 in the Positive and Negative Syndrome Scale (PANSS) Marder Negative Factors Score",
   "description": "The PANSS is a validated clinical scale used as a reliable and valid measure of the negative and positive symptom of schizophrenia. PANSS consists of three subscales: a total of 30 disparate items. Each item's severity was rated on a 7-point scale, with a score of 1 (absence of symptoms) and a score of 7 (extremely severe symptoms). The PANSS marder negative factors score is comprised of the following 7 items of the 30-item PANSS: blunted affect, emotional withdrawal, poor rapport, passive/apathetic social withdrawal, lack of spontaneity and flow of conversation, motor retardation and active social avoidance. The PANSS Negative Subscale ranges from 7 (absence of symptoms) to 49 (extremely severe symptoms). PANSS total score range is 30 to 210, with higher scores indicating more severe symptoms. Negative change from baseline indicates improvement. Baseline is defined as the end of the placebo run-in period (Week 3), and to be the last assessment prior to the first dose of study drug.",
   "timeFrame": "Baseline (Week 3); Week 15"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline (Week 3) to Week 15 in the Negative Symptom Assessment-16 (NSA-16) Global Negative Symptom Score",
   "description": "NSA-16=clinician-rated scale assessing presence, severity, \\& range of negative symptoms associated with schizophrenia. It consists of 16 items \\& uses 5-factor model to describe negative symptoms: communication (1-4, range=4-24), emotional/affective (5-7, range=3-18), social involvement (8-10, range=3-18), motivational (11-14, range=4-24), \\& retardation (15-16, range=3-18) \\&Global Negative Symptom Rating. NSA-16 items are rated on 6-point scale, 1=behavior is normal to 6=behavior severely reduced. Each item admits score of 9 if item is not ratable. Global Negative Symptom Rating range is 1=no evidence of symptoms to 7=extremely severe symptoms. 16 items yield a total of 16-96, with higher score indicating greater clinical severity of symptoms. Global rating range is 1-7, with higher score indicating extremely severe symptom. If more than 3 items were not ratable, total score was not evaluable \\& was regarded as missing. Negative change from baseline indicates improvement.",
   "timeFrame": "Baseline (Week 3); Week 15"
  },
  {
   "measure": "Change From Baseline (Week 3) to Week 15 in the Patient Global Impression of Severity (PGI-S) Score",
   "description": "The severity of participants illness with respect to their schizophrenia was rated using a 7-point PGI-S. PGI-S scores range from 1 to 7, where 1= normal, not at all ill, 2= borderline ill, 3=mildly ill, 4=moderately ill, 5= markedly ill, 6=severely ill, 7=extremely ill. Missing PGI-S rating were not imputed. Negative change from baseline indicates improvement. Baseline is defined as the end of the placebo run-in period (Week 3), and to be the last assessment prior to the first dose of study drug.",
   "timeFrame": "Baseline (Week 3); Week 15"
  },
  {
   "measure": "Patient Global Impression of Change (PGI-C) Score",
   "description": "The PGI-C is a 7-point (1-7) participant-rated scale used to assess treatment response with respect to schizophrenia as follows: 1 = very much improved, 2 = much improved, 3 = minimally improved, 4 = no change, 5 = minimally worse, 6 = much worse, or 7 = very much worse. Missing PGI-C rating were not imputed. .",
   "timeFrame": "At Weeks 6, 9, 12 and 15"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Participants who meet the Diagnostic and Statistical Manual of Mental Disorders, 5th Edition (DSM-V) diagnostic criteria for schizophrenia confirmed by the Mini International Neuropsychiatric Interview (M.I.N.I) Version 7.0.2\n* Participants must have well-controlled positive symptoms and prominent negative symptoms as defined by Positive and Negative Syndrome Scale (PANSS) criteria.\n* Participants currently receiving a second-generation atypical antipsychotic drug (SGA) are eligible if they are stable and adherent to their dosing schedule.\n* Participants must have a reliable informant (e.g., case manager, social worker, family member). The informant should be able to spend an adequate amount of time with the participant to be able to address behaviors, activities, and symptoms.\n\nExclusion Criteria:\n\n* Participants with current major depressive disorder (MDD)\n* Participants with pseudo-parkinsonism secondary to their ongoing antipsychotic medication\n* Participants currently using anticholinergic medications\n* Participants recently hospitalized as in-patients",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "60 Years"
 },
 "siteCount": 72,
 "countries": [
  "United States",
  "Bulgaria",
  "Poland",
  "Puerto Rico"
 ]
}

