   "masking": "NONE"
  }
 },
 "enrollment": 14,
 "briefSummary": "This study is comparing the use of Kcentra vs. standard transfusion in patients undergoing heart transplantation surgery. Half of the patients will receive Kcentra, while the other half will receive fresh frozen plasma.",
 "detailedDescription": "This study will be a randomized (1:1; PCC vs. plasma), open-label trial of hemostatic therapies during heart transplantation. The goal is to enroll 60 patients. Informed consent will be obtained from patients meeting the inclusion and exclusion criteria before the initiation of any study specific procedures. Eligible patients will be randomized to receive either PCC or plasma transfusion. The efficacy of interventions will be evaluated after 30 minutes of protamine administration. After the heart transplantation, thrombocytopenia and/or hypofibrinogenemia may worsen bleeding associated with vitamin K dependent factor deficiencies. Transfusion of platelets and/or cryoprecipitate is permitted if abnormal laboratory values are observed during the rewarming phase of CPB; platelet count \\<100 x 103/µl, and fibrinogen \\<200 mg/dl, respectively. Laboratory tests (hematocrit, platelet count, PT, PTT, POC-PT, coagulation factor and inhibitor levels (e.g., factor II, antithrombin), thromboelastometry or thromboelastography, endogenous thrombin generation) will also be obtained at baseline, twice during surgery and at 12-24 hours after surgery.",
 "arms": [
  {
   "label": "Kcentra (PCC)",
   "type": "EXPERIMENTAL",
   "description": "Half of subjects enrolled will be randomized to the Kcentra (PCC) group.",
   "interventionNames": [
    "Drug: Kcentra"
   ]
  },
  {
   "label": "Frozen Plasma Product, Human",
   "type": "ACTIVE_COMPARATOR",
   "description": "Half of subjects enrolled will be randomized to the standard transfusion group and receive fresh frozen plasma intra-operatively.",
   "interventionNames": [
    "Drug: Frozen Plasma Product, Human"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Kcentra",
   "description": "Kcentra will be administered in 2 divided doses; Pre-bypass (5-10 units/kg based on body weight and preoperative INR and post-protamine based of the pre-bypass dose and the preoperative INR; daily maximum dose not to exceed 5000 IU (50 IU/kg)",
   "armGroupLabels": [
    "Kcentra (PCC)"
   ],
   "otherNames": [
    "prothrombin complex concentrate"
   ]
  },
  {
   "type": "DRUG",
   "name": "Frozen Plasma Product, Human",
   "description": "If the patient is randomized to receive standard transfusion they will receive 2 U of fresh frozen plasma intravenously before cardiopulmonary bypass and then up to 4-8 U of plasma added to the cardiopulmonary bypass reservoir during rewarming.",
   "armGroupLabels": [
    "Frozen Plasma Product, Human"
   ],
   "otherNames": [
    "Fresh Frozen Plasma"
   ]
  }
 ],
 "primaryOutcomes": [
