 ],
 "primaryOutcomes": [
  {
   "measure": "Change in Absolute FVC From Baseline to Week 52",
   "description": "The FVC measurement indicates the amount of air a person can forcefully and quickly exhale after taking a deep breath.",
   "timeFrame": "Baseline to Week 52"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Time to Clinical Worsening",
   "description": "Clinical worsening was monitored from randomization until 1 of the following criteria were met: death (all causes), hospitalization due to a respiratory indication, or 10% relative decline in % predicted FVC. The number of participants with clinical worsening was reported. The time to first clinical worsening event was analyzed by stratified log-rank test (p-value) and presented with the hazard ratio calculated by proportional hazards model with treatment and baseline background therapy as explanatory variables.",
   "timeFrame": "Baseline to Week 52"
  },
  {
   "measure": "Time to First Acute Exacerbation of IPF",
   "description": "An acute exacerbation of IPF is defined as an acute, clinically significant, respiratory deterioration characterized by evidence of new widespread alveolar abnormality. The number of participants with an exacerbation of IPF was reported. The time to first acute exacerbation of IPF was analyzed by stratified log-rank test (p-value) and presented with the hazard ratio calculated by proportional hazards model with treatment and baseline background therapy as explanatory variables.",
   "timeFrame": "Baseline to Week 52"
  },
  {
   "measure": "Overall Survival at Week 52",
   "description": "Vital status was assessed for all subjects at Week 52, including those who discontinued the study prematurely. The number of deaths by Week 52 was reported. The time to death was analyzed by stratified log-rank test (p-value) and presented with the hazard ratio calculated by proportional hazards model with treatment and baseline background therapy as explanatory variables. Note: Participants who discontinued from the study early had their time to death censored at Day 373 or last contact date when known to be alive (whichever occurred first), and participants with lung transplantation had their time to death censored at lung transplant date. Therefore, the number of deaths for this outcome measure differ from the overall number on deaths (reported in the Adverse Events section).",
   "timeFrame": "Week 52"
  },
  {
   "measure": "Change in % Predicted FVC From Baseline to Week 52",
   "description": "The FVC measurement indicates the amount of air a person can forcefully and quickly exhale after taking a deep breath. Percent predicted FVC is calculated based on factors such as ethnicity, sex, age, height, and weight.",
   "timeFrame": "Baseline to Week 52"
  },
  {
   "measure": "Change in K-BILD Questionnaire Score From Baseline to Week 52",
   "description": "The King's Brief Interstitial Lung Disease Questionnaire (K-BILD) is a self-administered, 15-item questionnaire validated for patients with interstitial lung disease (ILD) consisting of 3 domains (breathlessness and activities, psychological, and chest symptoms). Each of the 15 questions is scored from 1 (worst score) to 7 (best score). The scores for the 15 questions are added together and converted into a Total Score from 0 to 100. Higher scores indicate a better quality of life.",
   "timeFrame": "Baseline to Week 52"
  },
  {
   "measure": "Change in DLCO From Baseline to Week 52",
   "description": "The DLCO measurement measures how well oxygen moves from the lungs to the blood.",
   "timeFrame": "Baseline to Week 52"
  }
