   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Semaglutide",
   "description": "Participants will receive semaglutide subcutaneous (s.c.; under the skin) injection(s) once-weekly for 52 weeks. Dose will be gradually increased to 2.4 mg: 0.25 mg from week 1 to 4, 0.5 mg from week 5 to 8, 1.0 mg from week 9 to 12, 1.7 mg from week 13 to 16 and 2.4 mg from week 17 to week 52.",
