forecastInput:
{
 "nctId": "NCT04701983",
 "briefTitle": "Study to Assess the Efficacy, Safety, and Tolerability of SAR440340/REGN3500/Itepekimab in Chronic Obstructive Pulmonary Disease (COPD)",
 "officialTitle": "Randomized, Double-blind, Placebo-controlled, Parallel Group Phase 3 Study to Evaluate the Efficacy, Safety, and Tolerability of SAR440340/REGN3500/Itepekimab (Anti-IL-33 mAb) in Patients With Moderate-to-severe Chronic Obstructive Pulmonary Disease (COPD)",
 "leadSponsor": {
  "name": "Sanofi",
  "class": "INDUSTRY"
 },
 "collaborators": [
  {
   "name": "Regeneron Pharmaceuticals",
   "class": "INDUSTRY"
  }
 ],
 "startDate": "2020-12-16",
 "firstRegistered": "2020-12-30",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Chronic Obstructive Pulmonary Disease"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 1127,
 "briefSummary": "Primary Objective:\n\nEvaluate the efficacy of itepekimab compared with placebo on the annualized rate of acute moderate-or-severe COPD exacerbations in former smokers with moderate-to-severe COPD\n\nSecondary Objectives:\n\n* Evaluate the efficacy of itepekimab compared with placebo on pulmonary function in former smokers with moderate-to-severe COPD\n* Evaluate the efficacy of itepekimab compared with placebo on occurrence of acute exacerbation of COPD (AECOPD) in former smokers with moderate-to-severe COPD\n* Evaluate the efficacy of itepekimab compared with placebo on severe AECOPD in former smokers with moderate-to-severe COPD\n* Evaluate the efficacy of itepekimab compared with placebo on corticosteroid-treated AECOPD in former smokers with moderate-to-severe COPD\n* Evaluate the efficacy of itepekimab compared with placebo on respiratory symptoms in former smokers with moderate-to-severe COPD\n* Evaluate the efficacy of itepekimab compared with placebo on Forced Expiratory Volume in 1 second (FEV1) slope in former smokers with moderate-to-severe COPD\n* Evaluate the efficacy of itepekimab compared with placebo on health-related quality of life (HRQoL) as assessed by St. George's Respiratory Questionnaire (SGRQ) in former smokers with moderate-to-severe COPD\n* Evaluate the safety and tolerability of itepekimab in former smokers with moderate-to-severe COPD\n* Evaluate the pharmacokinetic (PK) profile of itepekimab in former smokers with moderate-to-severe COPD\n* Evaluate immunogenicity to itepekimab in former smokers with moderate-to-severe COPD",
 "detailedDescription": "The study duration per participant:\n\n* Screening period was 3-5 weeks\n* Placebo-controlled treatment period was 52 weeks for first approximately 960 randomized participants, and 24 to 52 weeks for potential additional randomized participants\n* Post-investigational medicinal product (IMP) treatment follow-up period was 20 weeks for participants not transitioning to the extension study LTS18133 (NCT06208306)\n\nNote: A long-term, double-blinded extension study had been implemented to allow participants in this study to continue receiving active IMP for an additional period. Only participants completing their End-of-Treatment (EOT) visit per this study protocol was offered to participate in the LTS18133 study (NCT06208306).",
 "arms": [
  {
   "label": "Itepekimab Q2W",
   "type": "EXPERIMENTAL",
   "description": "Participants received itepekimab 300 mg as an SC injection every 2 weeks (Q2W) for up to 52 weeks.",
   "interventionNames": [
    "Drug: Itepekimab SAR440340"
   ]
  },
  {
   "label": "Itepekimab Q4W",
   "type": "EXPERIMENTAL",
   "description": "Participants received Itepekimab 300 mg as an SC injection every 4 weeks (Q4W) with alternating placebo matching Itepekimab administration at the 2-week interval between active study drug for up to 52 weeks.",
   "interventionNames": [
    "Drug: Itepekimab SAR440340",
    "Drug: Placebo"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Participants received placebo matching Itepekimab as subcutaneous (SC) injection every 2 weeks (Q2W) for up to 52 weeks.",
