   "armGroupLabels": [
    "Itepekimab Q4W",
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Annualized Rate of Adjudicated Moderate or Severe Acute Exacerbation of Chronic Obstructive Pulmonary Disease (AECOPD) Events Over the Placebo-Controlled Treatment Period",
   "description": "Exacerbations were recorded by Investigator. Moderate exacerbations were defined as acute worsening of respiratory symptoms that required either systemic corticosteroids (such as intramuscular \\[IM\\], intravenous \\[IV\\], or oral) and/or antibiotics. Severe exacerbations were defined as AECOPD that required hospitalization, observation for \\>24 hours in an emergency department/urgent care facility, or resulted in death. For both moderate and severe events to be counted as 2 separate events, they must be separated by at least 14 days between any course of systemic steroids/antibiotics or 14 days between discharge and new admission in case of hospitalization (severe events only). Annualized rate was the total number of moderate or severe exacerbation events divided by the total observation duration and was estimated based on negative binomial regression. Events were adjudicated by third party.",
   "timeFrame": "Baseline (Day 1) up to Week 52 for initial randomized participants; Baseline (Day 1) up to Week 24 to 52 for additional randomized participants"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Annualized Rate of Adjudicated Severe Acute Exacerbation of Chronic Obstructive Pulmonary Disease Events Over the Placebo-Controlled Treatment Period",
   "description": "Exacerbations were recorded by the Investigator. Severe exacerbations were defined as AECOPD that required hospitalization, observation for \\>24 hours in an emergency department/urgent care facility, or resulted in death. Annualized rate was the total number of severe exacerbation events divided by the total observation duration and was estimated based on negative binomial regression. Events were adjudicated by third party.",
   "timeFrame": "Baseline (Day 1) up to Week 52 for initial randomized participants; Baseline (Day 1) up to Week 24 to 52 for additional randomized participants"
  },
  {
   "measure": "Change From Baseline in Pre-Bronchodilator Forced Expiratory Volume in One Second at Week 24",
   "description": "The FEV1 was the volume of air exhaled from the lungs in the first second of a forced expiration as measured by spirometer. Pre-BD spirometry was performed after a wash out period of BD according to their action duration. Baseline was defined as the last available value before the first dose of study drug. Model-based average change from baseline to Week 24 is presented.",
   "timeFrame": "Baseline (Day 1) to Week 24"
  },
  {
   "measure": "Change From Baseline in Evaluating Respiratory Symptoms in Chronic Obstructive Pulmonary Disease (E-RS: COPD) Total Score at Week 24",
   "description": "The E-RS: COPD scale was a patient-reported outcome (PRO) that measured the severity of respiratory symptoms in COPD such as breathlessness, cough and sputum, and chest symptoms. It was derivative of the EXACT tool, which was daily symptom diary that quantified and measured exacerbations of COPD and assessed symptomatic manifestations of COPD exacerbations. E-RS: COPD utilized 11 respiratory symptom items contained in 14-item EXACT instrument. Daily E-RS: COPD RS-Total score was computed by taking the sum of the scores for the 11 items comprising the instrument. Total score ranged from 0 (no symptoms) to 40 (severe symptoms), higher values indicated more severe respiratory symptoms. Baseline was defined as the last available value before the first dose of study drug. Model-based average change from baseline to Week 24 is presented.",
   "timeFrame": "Baseline (Day 1) to Week 24"
  },
  {
   "measure": "Change From Baseline in Post-Bronchodilator Forced Expiratory Volume in One Second at Week 24",
   "description": "The FEV1 was the volume of air exhaled from the lungs in the first second of a forced expiration as measured by spirometer. Post-BD spirometry was performed after 4 actuations of short-acting beta-agonist (SABA; albuterol, salbutamol) with post-BD reversibility performed at least 15 minutes following the last actuation. Baseline was defined as the last available value before the first dose of study drug. Model-based average change from baseline to Week 24 is presented.",
   "timeFrame": "Baseline (Day 1) to Week 24"
  },
  {
   "measure": "Change From Baseline in St. George's Respiratory Questionnaire (SGRQ) Total Score at Week 24",
   "description": "SGRQ was 50-item PRO instrument developed to measure the health status of participants with airflow obstruction diseases. Questionnaire had 2 parts: part 1 consisted of 8 items pertaining to severity of respiratory symptoms in preceding 4 weeks; part 2 consisted of 42 items related to the daily activity and psychosocial impacts of the individual's respiratory condition. Total SGRQ score indicated impact of disease on overall health status. Total score was calculated by summing all positive responses in questionnaire and expressing result as percentage of total weight for questionnaire and ranged from 0 to 100; 100=worst possible health status; 0=best possible health status. Baseline: last available value before first dose of study drug. Model-based average change from baseline to Week 24 is presented.",
   "timeFrame": "Baseline (Day 1) to Week 24"
  },
  {
   "measure": "Percentage of Participants With a Decrease From Baseline of at Least 4 Points in St. George's Respiratory Questionnaire Total Score at Week 24",
   "description": "SGRQ was 50-item PRO instrument developed to measure health status of participants with airflow obstruction diseases. Questionnaire had 2 parts: part 1 consisted of 8 items pertaining to the severity of respiratory symptoms in preceding 4 weeks; part 2 consisted of 42 items related to daily activity and psychosocial impacts of the individual's respiratory condition. The total SGRQ score indicated the impact of disease on overall health status. Total score was calculated by summing all positive responses in questionnaire and expressing result as percentage of total weight for questionnaire and ranged from 0 to 100; 100 represented the worst possible health status and 0 indicated the best possible health status. Baseline was defined as the last available value before the first dose of study drug. Percentages are rounded off to tenth decimal place.",
   "timeFrame": "Baseline (Day 1) and Week 24"
  },
  {
   "measure": "Rate of Change in Post-Bronchodilator Forced Expiratory Volume in One Second From Baseline (Post-Bronchodilator Forced Expiratory Volume in One Second Slope) After Week 4",
   "description": "The rate of change from baseline in post-BD FEV1 (or post-BD FEV1 slope) after a period of initial BD effect (after Week 4) were estimated to assess the rate of decline in lung function over time, commonly observed in participants with inadequately controlled COPD. The FEV1 was the volume of air exhaled from the lungs in the first second of a forced expiration as measured by spirometer. Post-BD spirometry was performed after 4 actuations of SABA (albuterol, salbutamol) with post-BD reversibility performed at least 15 minutes following the last actuation. Baseline was defined as the last available value before the first dose of study drug.",
   "timeFrame": "Baseline (Day 1) and from Week 8 up to Week 52 for initial randomized participants; Baseline (Day 1) and from Week 8 up to a variable study treatment period (i.e., 24 weeks minimum and 52 weeks maximum) for additional randomized participants"
  },
  {
   "measure": "Change From Baseline in Post-Bronchodilator Forced Expiratory Volume in One Second at Week 52",
   "description": "The FEV1 was the volume of air exhaled from the lungs in the first second of a forced expiration as measured by spirometer. Post-BD spirometry was performed after 4 actuations of SABA (albuterol, salbutamol) with post-BD reversibility performed at least 15 minutes following the last actuation. Baseline was defined as the last available value before the first dose of study drug. Model-based average change from baseline to Week 52 is presented.",
   "timeFrame": "Baseline (Day 1) to Week 52"
  },
  {
   "measure": "Change From Baseline in Pre-Bronchodilator Forced Expiratory Volume in One Second at Week 52",
   "description": "The FEV1 was the volume of air exhaled from the lungs in the first second of a forced expiration as measured by spirometer. Pre-BD spirometry was performed after a wash out period of BD according to their action duration. Baseline was defined as the last available value before the first dose of study drug. Model-based average change from baseline to Week 52 is presented.",
   "timeFrame": "Baseline (Day 1) to Week 52"
  },
  {
   "measure": "Probability of Participants With First Adjudicated Moderate or Severe Acute Exacerbation of Chronic Obstructive Pulmonary Disease in Weeks 12, 24, 36 and 52 Over the Placebo-Controlled Treatment Period",
   "description": "Exacerbations were recorded by Investigator. Moderate exacerbations: acute worsening of respiratory symptoms that required either systemic corticosteroids (such as IM, IV, or oral) and/or antibiotics. Severe exacerbations: AECOPD that required hospitalization, observation for \\>24 hours in an emergency department/urgent care facility, or resulted in death. Probability of participants with first adjudicated moderate or severe AECOPD in Weeks 12, 24, 36, and 52 was based on Kaplan-Meier estimates. Events were adjudicated by third party.",
   "timeFrame": "Baseline (Day 1) up to Weeks 12, 24, 36 and 52"
  },
  {
   "measure": "Probability of Participants With First Adjudicated Severe Acute Exacerbation of Chronic Obstructive Pulmonary Disease in Weeks 12, 24, 36 and 52 Over the Placebo-Controlled Treatment Period",
   "description": "Exacerbations were recorded by Investigator. Severe exacerbations were defined as AECOPD that required hospitalization, observation for \\>24 hours in an emergency department/urgent care facility, or resulted in death. Probability of participants with first adjudicated severe AECOPD in Weeks 12, 24, 36, and 52 was based on Kaplan-Meier estimates. Events were adjudicated by third party.",
   "timeFrame": "Baseline (Day 1) up to Weeks 12, 24, 36 and 52"
  },
  {
   "measure": "Annualized Rate of Corticosteroid-Treated Acute Exacerbation of Chronic Obstructive Pulmonary Disease Events Over Placebo-Controlled Treatment Period",
   "description": "Exacerbations were recorded by Investigator. Moderate/severe AECOPD events which were treated with regimen containing systemic corticosteroids for AECOPD;at time of AECOPD were considered. Moderate exacerbations: acute worsening of respiratory symptoms that required either systemic corticosteroids (IM,IV, or oral) and/or antibiotics. Severe exacerbations: AECOPD that required hospitalization, observation for \\>24 hours in emergency department/urgent care facility or resulted in death. For moderate and severe events to be counted as 2 separate events, they must be separated by at least 14 days between any course of systemic steroids/antibiotics or 14 days between discharge and new admission in case of hospitalization (severe events). Annualized rate: total number of corticosteroid-treated AECOPD events divided by total observation duration and was estimated based on negative binomial regression.",
   "timeFrame": "Baseline (Day 1) up to Week 52 for initial randomized participants; Baseline (Day 1) up to Week 24 to 52 for additional randomized participants"
  },
  {
   "measure": "Change From Baseline in Evaluating Respiratory Symptoms in Chronic Obstructive Pulmonary Disease Total Score at Week 52",
   "description": "E-RS: COPD scale was PRO that measured severity of respiratory symptoms in COPD: breathlessness,cough and sputum,chest symptoms. It was derivative of EXACT tool which was daily symptom diary that quantified and measured exacerbations of COPD and assessed symptomatic manifestations of COPD exacerbations. E-RS: COPD used 11 respiratory symptom items contained in 14-item EXACT instrument. Daily E-RS: COPD RS-Total score was computed by taking sum of scores for 11 items comprising instrument. Total score:0 (no symptoms) to 40 (severe symptoms); higher values=more severe respiratory symptoms. Baseline: last available value before first dose of study drug. Model-based average change from baseline to Week 52 is presented.",
   "timeFrame": "Baseline (Day 1) to Week 52"
  },
  {
   "measure": "Change From Baseline in St. George's Respiratory Questionnaire Total Score at Week 52",
   "description": "SGRQ was 50-item PRO instrument developed to measure health status of participants with airflow obstruction diseases. Questionnaire had 2 parts: part 1 had 8 items pertaining to severity of respiratory symptoms in preceding 4 weeks; part 2 had 42 items related to daily activity and psychosocial impacts of individual's respiratory condition. Total score was calculated by summing all positive responses in questionnaire and expressing result as percentage of total weight for questionnaire; ranged 0 to 100;100=worst possible health status;0=best possible health status. Baseline: last available value before first dose of study drug. Model-based average change from baseline to Week 52 is presented.",
   "timeFrame": "Baseline (Day 1) to Week 52"
  },
  {
   "measure": "Percentage of Participants With a Decrease From Baseline of at Least 4 Points in St. George's Respiratory Questionnaire Total Score at Week 52",
   "description": "SGRQ was 50-item PRO instrument developed to measure health status of participants with airflow obstruction diseases. Questionnaire had 2 parts: part 1 consisted of 8 items pertaining to severity of respiratory symptoms in preceding 4 weeks; part 2 consisted of 42 items related to daily activity and psychosocial impacts of individual's respiratory condition. Total score was calculated by summing all positive responses in questionnaire and expressing result as percentage of total weight for questionnaire and ranged from 0 to 100; 100=worst possible health status; 0=best possible health status. Baseline: last available value before first dose of study drug. Percentages rounded off to tenth decimal place.",
   "timeFrame": "Baseline (Day 1) and Week 52"
  },
  {
   "measure": "Number of Participants With Treatment-Emergent Adverse Events (TEAEs), Treatment-Emergent Serious Adverse Events (TESAEs), TEAEs of Special Interest (TEAESIs) and TEAEs Leading to Permanent Treatment Discontinuation",
   "description": "AE was any untoward medical occurrence in a participant or clinical study participant, temporally associated with the use of study drug, whether or not considered related to the study drug. Serious AE (SAE) was any untoward medical occurrence that at any dose: resulted in death, was life-threatening, required inpatient hospitalization or prolongation of existing hospitalization, resulted in persistent disability/incapacity, was a congenital anomaly/birth defect, was a medically important event. AESI was any AE (serious or non-serious) of scientific and medical concern specific to Sponsor's product or program, for which ongoing monitoring and immediate notification by Investigator to Sponsor was required. TEAEs were AEs that developed, worsened or became serious during the treatment-emergent period.",
   "timeFrame": "1st dose (Day 1) up to 22 weeks post last dose (considering maximum treatment exposure) for who did not enter LTS18133 (approximately 78 weeks); up to EOT (considering maximum treatment exposure) for who entered LTS18133 (approximately 58 weeks)"
  },
  {
   "measure": "Functional Itepekimab Concentrations in Serum",
   "description": "Blood samples were collected at specified timepoints to obtain serum concentrations of itepekimab.",
   "timeFrame": "Baseline (Day 1), Weeks 2, 4, 8, 12, 24, 36, 52 (EOT), 58 and 72 (EOS) (Weeks 58 and 72 applicable for participants not transitioning to the LTS18133 study)"
  },
  {
   "measure": "Number of Participants With Treatment-Emergent Anti-Itepekimab Antibodies Response",
   "description": "Blood samples were collected to evaluate antibodies to itepekimab. Treatment-emergent response was defined as a positive response in the anti-drug antibody (ADA) assay post first dose when baseline results were negative or missing.",
   "timeFrame": "1st dose (Day 1) up to 22 weeks post last dose (considering maximum treatment exposure) for who did not enter LTS18133 (approximately 78 weeks); up to EOT (considering maximum treatment exposure) for who entered LTS18133 (approximately 58 weeks)"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion criteria :\n\n* Participant must be 40 to 85 years of age inclusive\n* Physician diagnosis of COPD for at least 1 year (based on Global Initiative for Chronic Obstructive Lung Disease \\[GOLD\\] definition)\n* Smoking history of ≥10 pack-years, but who were not currently smoking, and smoking cessation must have occurred ≥6 months prior to Screening (Visit 1A) with an intention to quit permanently\n* Participants with moderate-to-severe COPD\n* Participant-reported history of signs and symptoms of chronic bronchitis (chronic productive cough for at least 3 months in the year prior to screening in a participant in whom other causes of chronic cough \\[eg, inadequately treated gastroesophageal reflux or chronic rhinosinusitis; or clinical diagnosis of bronchiectasis\\] has been excluded)\n* Documented history of high exacerbation risk defined as having had ≥2 moderate or ≥1 severe exacerbations within the year prior to Screening (Visit 1A), with at least 1 exacerbation treated with systemic corticosteroids. At least one exacerbation must have occurred while participants were on their current controller therapy:\n\n  * Moderate exacerbations were recorded by the Investigator and were defined as acute worsening of respiratory symptoms that requires either systemic corticosteroids (IM, IV, or oral) and/or antibiotics\n  * Severe exacerbations were recorded by the Investigator and were defined as AECOPD that require hospitalization or observation for \\>24 hours in emergency department/urgent care facility\n* Participants with standard of care controller therapy, for ≥3 months prior to Screening (Visit 1A) and at a stable dose of controller therapy for at least 1 month prior to the screening, including either: inhaled corticosteroid (ICS) + long-acting beta-agonist (LABA), long-acting muscarinic antagonist (LAMA) + LABA or LAMA + LABA + ICS\n* Body mass index (BMI) ≥18.0 kg/m\\^2, or BMI ≥16.0 kg/m\\^2 for participants enrolled in East-Asian countries\n* Female participant was not pregnant, not breastfeeding, and at least one of the following conditions applies:\n\n  * not a women of child-bearing potential (WOCBP) OR\n  * a WOCBP who agrees to follow the contraceptive guidance during the intervention period and for at least 20 weeks after the last dose of study intervention\n\nExclusion criteria:\n\n* Current diagnosis of asthma according to the Global Initiative for Asthma (GINA) guidelines, or documented history of asthma unless asthma resolved before 18 years of age and has not recurred\n* Active smoking or vaping of any products (eg, nicotine, tetrahydrocannabinol \\[THC\\]) within 6 months prior to Screening (Visit 1A)\n* Clinically significant new abnormal electrocardiogram (ECG) within 6 months prior to, or at Screening (Visit 1A) that may affect the participant's participation in the study\n* Clinically significant and current pulmonary disease other than COPD, eg, sarcoidosis, interstitial lung disease, bronchiectasis (clinical diagnosis), diagnosis of α-1 anti-trypsin deficiency, or another diagnosed pulmonary disease\n* Diagnosis of cor pulmonale, evidence of right cardiac failure, or moderate-to-severe pulmonary hypertension\n* Hypercapnia requiring bilevel positive airway pressure (BiPAP)\n* Moderate or severe exacerbation of COPD (AECOPD) within 4 weeks prior to Screening (Visit 1A)\n* Prior history of / planned: lung pneumonectomy for any reason, or lung volume reduction procedures (including bronchoscopic volume reduction) for COPD. Note: Surgical biopsy, or segmentectomy, or wedge resection, or lobectomy for other diseases would not be excluded.\n* Unstable ischemic heart disease, including acute myocardial infarction within the past 1 year prior to Screening, or unstable angina in the 6 months prior to Screening (Visit 1A)\n* Cardiac arrhythmias including paroxysmal (eg, intermittent) atrial fibrillation\n* Uncontrolled hypertension (ie, systolic blood pressure \\[BP\\] \\>180 mm Hg or diastolic BP \\>110 mm Hg with or without use of anti-hypertensive therapy)\n* Participants with active tuberculosis (TB), latent TB, a history of incompletely treated TB, suspected extrapulmonary TB infection (TBI), or who were at high risk of contracting TB (such as close contact with individuals with active or latent TB) or received Bacillus Calmette-Guérin (BCG)-vaccination within 12 weeks prior to Screening (Visit 1A)\n* History of human immunodeficiency virus (HIV) infection or positive HIV 1/2 serology at Screening (Visit 1A)\n* Suspicion of, or confirmed, coronavirus disease 2019 (COVID-19) infection or in contact with known exposure to COVID-19 at Screening (Visit 1A); known history of COVID-19 infection within 4 weeks prior to Screening (Visit 1A); history of requiring mechanical ventilation or extracorporeal membrane oxygenation (ECMO) secondary to COVID-19 within 3 months prior to sScreening (Visit 1A); participants who have had a COVID-19 infection prior Screening (Visit 1A) who have not yet sufficiently recovered to participate in the procedures of a clinical trial\n* Evidence of acute or chronic infection requiring systemic treatment with antibacterial, antiviral, antifungal, antiparasitic, or antiprotozoal medications within 4 weeks before Screening (Visit 1A), significant viral infections within 4 weeks before Screening (Visit 1A) that may not have been treated with antiviral treatment (eg, influenza receiving only symptomatic treatment)\n* Participants with active autoimmune disease or participants using immunosuppressive therapy for autoimmune disease (eg, rheumatoid arthritis, inflammatory bowel disease, primary biliary cirrhosis, systemic lupus erythematosus, multiple sclerosis\n* History of malignancy within 5 years before Screening (Visit 1A), except completely treated in situ carcinoma of the cervix, completely treated and resolved nonmetastatic squamous or basal cell carcinoma of the skin\n* Previous use of itepekimab\n\nThe above information was not intended to contain all considerations relevant to a participant's potential participation in a clinical trial.",
  "healthyVolunteers": false,
