   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Rate of Change (Slope) From Baseline to Month 12 in GA Lesion Area",
   "description": "GA lesion area was assessed by fundus autofluorescence (FAF) imaging, by an independent central reading center for GA lesion area. A linear mixed effect (LME) model was used to analyze the rate of change from baseline to Month 12 GA lesion area (mm2) for all groups. The model included fixed effects of treatment, time point, treatment by time point interaction, baseline GA lesion area, baseline GA lesion area by timepoint interaction, and baseline lesion multifocality. A random intercept for participant ID and a random slope for timepoint are included to account for repeated measurements for participants. The GA lesion area was analyzed as reported (that is, not transformed).",
   "timeFrame": "Baseline to Month 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline to Month 12 in GA Lesion Area",
   "description": "GA lesion area was assessed by fundus autofluorescence (FAF) imaging, by an independent central reading center for GA lesion area.",
   "timeFrame": "Baseline to Month 12"
  },
  {
   "measure": "Number of Participants With Treatment Emergent Adverse Events (TEAEs)",
   "description": "An AE was defined as any new untoward medical occurrence or worsening of a pre-existing medical condition in a participant or clinical investigation participant administered a medicinal product and which does not necessarily have a causal relationship with this treatment. An AE could therefore be any unfavorable and unintended sign (including a clinically significant abnormal laboratory finding, for example), symptom, or disease temporally associated with the use of a medicinal (investigational) product, whether or not considered related to the investigational medicinal product. A summary of serious and all other non-serious adverse events regardless of causality is located in the Reported Adverse events module.",
   "timeFrame": "Baseline to Month 12"
  },
  {
   "measure": "Change From Baseline to Month 12 in Best Corrected Visual Acuity (BCVA)",
   "description": "BCVA was assessed by the Early Treatment Diabetic Retinopathy Study (ETDRS) letter score on a test chart at a starting distance of 4 meters at each study visit. BCVA scores range from 0 to 100 letters with a higher score indicating a better vision.",
   "timeFrame": "Baseline to Month 12"
  },
  {
   "measure": "Number of Events With Confirmed ≥ 15-Letter Loss BCVA Decline",
   "description": "Confirmed ETDRS BCVA ≥15-letter loss was deﬁned as ≥15-letter loss observed for 2 consecutive visits. BCVA was assessed by the Early Treatment Diabetic Retinopathy Study (ETDRS) letter score on a test chart at a starting distance of 4 meters at each study visit. BCVA scores range from 0 to 100 letters with a higher score indicating a better vision.",
   "timeFrame": "Baseline to Month 12"
  },
  {
   "measure": "Change From Baseline to Month 12 in LLVA",
   "description": "LLVA was assessed by the Early Treatment Diabetic Retinopathy Study (ETDRS) letter score on a test chart at a starting distance of 4 meters at each study visit. BCVA scores range from 0 to 100 letters with a higher score indicating a better vision.",
   "timeFrame": "Baseline to Month 12"
  },
  {
   "measure": "Number of Events With ≥ 15-Letter Loss LLVA Decline",
   "description": "LLVA ≥15-letter loss worsening from Baseline during the 12-month Treatment. LLVA was assessed by the Early Treatment Diabetic Retinopathy Study (ETDRS) letter score on a test chart at a starting distance of 4 meters at each study visit. BCVA scores range from 0 to 100 letters with a higher score indicating a better vision.",
   "timeFrame": "Baseline to Month 12"
  },
  {
   "measure": "Change From Baseline to Month 12 in LLVD",
   "description": "LLVD as assessed by the Early Treatment Diabetic Retinopathy Study (ETDRS) letter score on a test chart at a starting distance f 4 meters at each study visit. LL-VD will be derived by subtracting LL-BCVA from BCVA.",
   "timeFrame": "Baseline to Month 12"
  },
  {
   "measure": "Number of Events With ≥ 15-Letter Loss LLVD Decline",
   "description": "LLVD ≥15-letter loss worsening from Baseline during the 12-month Treatment. LLVD was assessed by the Early Treatment Diabetic Retinopathy Study (ETDRS) letter score on a test chart at a starting distance of 4 meters at each study visit. BCVA scores range from 0 to 100 letters with a higher score indicating a better vision.",
   "timeFrame": "Baseline to Month 12"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Diagnosis of geographic atrophy of the macula secondary to age-related macular degeneration as determined by the Investigator and confirmed by the Central Reading Center.\n* GA lesion must have the following characteristics as determined by the independent Central Reading\n\nCenter based on assessment of FAF imaging at screening:\n\n1. Well-demarcated GA with a total area (baseline lesion size) ≥2.5 millimeter squared (mm\\^2) and\n\n   * 17.5 mm\\^2.\n2. If GA is multifocal, at least 1 focal lesion must measure ≥1.25 mm\\^2 with the overall aggregate area of GA as specified above.\n3. Presence of hyper autofluorescence, any pattern, in the junctional zone of the GA. Absence of hyper autofluorescence (that is, pattern = none) is exclusionary.\n4. The entire GA lesion must be completely visualized on the macula centered image and must be able to be imaged in its entirety and not contiguous with any peripapillary atrophy.\n\n   * Normal luminance BCVA of 24 to 83 letters, inclusive, using ETDRS charts (20/25 to 20/320 Snellen equivalent, inclusive).\n   * A female participant is eligible if she is not pregnant or breastfeeding and is a woman of non-childbearing potential or is using a contraceptive method that is highly effective, with a failure rate of \\<1% during the study intervention period and for at least 30 days after the last dose of study intervention.\n\nExclusion Criteria:\n\n* Geographic atrophy due to other causes than AMD such as Stargardt disease, cone-rod dystrophy, pathologic myopia, or toxic maculopathies (for example, plaquenil maculopathy) in either eye.\n* Any evidence of choroidal neovascularization (CNV) in the study eye:\n\n  1. Any history of CNV of any cause based on medical history.\n  2. Evidence of prior or active CNV or related findings (for example, retinal pigment epithelial rips or tears) based on FAF, Spectral Domain Optical Coherence Tomography (SD-OCT) imaging, intravenous fluorescein angiography (IVFA) and color fundus photo as assessed by the Central Reading Center.\n* Spherical equivalent of -8.00 diopters (D) myopia or higher in the study eye.\n* Uncontrolled glaucoma in the study eye (Intraocular pressure \\[IOP\\] \\>25 mmHg despite treatment with anti- glaucoma medication) or history of neovascular glaucoma.\n* History of glaucoma filtration surgery, minimally-invasive glaucoma surgery involving an implant, or vitrectomy surgery, or other procedure in the study eye that could affect drug distribution and/or clearance.\n* Any current or prior ocular disease, other than geographic atrophy, that in the opinion of the Investigator could interfere with the conduct of the study including, but not limited to, insufficient pupil dilation, retinal or optic nerve disease, media opacity, or aphakia in the study eye.\n* History of any prior IVT treatment for any indication in the study eye.\n* Any prior treatment for AMD in the study eye (for example, surgical, radiation, thermotherapeutic, or laser intervention), except oral supplements or minerals.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "50 Years"
 },
 "siteCount": 53,
 "countries": [
