   "otherNames": [
    "zunsemetinib"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Percentage of Participants Achieving ACR20 at Week 12",
   "description": "Participants achieving American College of Rheumatology (ACR) 20 (responders) were defined as having ≥20% improvement in both the number of swollen and tender joints (66/68 joint counts) and ≥20% improvement in ≥3 of the following 5 measures: Patient's Global Assessment of Disease Activity (VAS), Patient's Assessment of Arthritis Pain (VAS), Health Assessment Questionnaire-Disability Index (HAQ-DI), Physician's Global Assessment of Disease Activity (VAS), and acute phase reactant as measured by hsCRP.\n\nModel-based estimates and 95% confidence intervals (CIs) were produced.",
   "timeFrame": "Week 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Percentage of Participants Achieving ACR50 at Week 12",
   "description": "Participant achieving ACR50 (responders) were defined as having ≥50% improvement in both the number of swollen and tender joints (66/68 joint counts) and ≥50% improvement in ≥3 of the following 5 measures: Patient's Global Assessment of Disease Activity (VAS), Patient's Assessment of Arthritis Pain (VAS), HAQ-DI, Physician's Global Assessment of Disease Activity (VAS), Acute phase reactant as measured by hsCRP.\n\nModel-based estimates and 95% CIs were produced.",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Percentage of Participants Achieving ACR70 at Week 12",
   "description": "Participants achieving ACR70 (responders) were defined as having ≥70% improvement in both the number of swollen and tender joints (66/68 joint counts) and ≥70% improvement in ≥3 of the following 5 measures: Patient's Global Assessment of Disease Activity (VAS), Patient's Assessment of Arthritis Pain (VAS), HAQ-DI, Physician's Global Assessment of Disease Activity (VAS), Acute phase reactant as measured by hsCRP.\n\nModel-based estimates and 95% CIs were produced.",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Change From Baseline in DAS28-CRP at Week 12",
   "description": "The DAS28-CRP consists of a composite score of the following variables: TJC28, SJC28, CRP (hsCRP was used for the purposes of this study), and Patient's Global Assessment of Disease Activity. Interpretation of the DAS28-CRP is on a scale of 0 to 9.4, where \\<2.6 is considered remission, ≥2.6 to \\<3.2 is considered low/minimal disease activity, ≥3.2 to ≤5.1 is considered moderate disease activity, and \\>5.1 is considered high/severe disease activity.\n\nThe least square (LS) mean change from baseline in DAS28-CRP at Week 12 was estimated from the Mixed Model Repeated Measures (MMRM) model.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Percentage of Participants Achieving DAS28-CRP Remission (Score <2.6) at Week 12",
   "description": "The Disease Activity Score using 28 Joint Count-C-reactive protein (DAS28-CRP) consists of a composite score of the following variables: TJC28, SJC28, CRP (hsCRP is used for the purposes of this study), and Patient's Global Assessment of Disease Activity. Interpretation of the DAS28-CRP is on a scale of 0 to 9.4, where \\<2.6 is considered remission, ≥2.6 to \\<3.2 is considered low/minimal disease activity, ≥3.2 to ≤5.1 is considered moderate disease activity, and \\>5.1 is considered high/severe disease activity.\n\nModel-based estimates and 95% CIs were produced.",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Percentage of Participants Achieving DAS28-CRP Low Disease Activity (Score ≤ 3.2) at Week 12",
   "description": "The DAS28-CRP consists of a composite score of the following variables: TJC28, SJC28, CRP (hsCRP is used for the purposes of this study), and Patient's Global Assessment of Disease Activity. Interpretation of the DAS28-CRP is on a scale of 0 to 9.4, where \\<2.6 is considered remission, ≥2.6 to \\<3.2 is considered low/minimal disease activity, ≥3.2 to ≤5.1 is considered moderate disease activity, and \\>5.1 is considered high/severe disease activity.\n\nModel-based estimates and 95% CIs were produced.",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Change From Baseline in HAQ-DI Score at Week12",
   "description": "The HAQ-DI (standard disability method calculation) was utilized to assess the participant's physical function or disability according to the participant. The HAQ-DI is a 20-item, validated questionnaire used to assess the degree of difficulty a person has in accomplishing tasks in 8 functional areas (dressing, arising, eating, walking, hygiene, reaching, gripping, and activities \\[errands and chores\\]). Responses in each functional area are scored from 0 (no difficulty) to 3 (inability to perform a ask in that area). Overall score was computed as the sum of category scores and divided by the number of categories answered, ranging from 0 to 3. A lower score demonstrated less disability.\n\nLS mean change from baseline in HAQ-DI score at Week 12 was estimated from the MMRM model.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Change From Baseline in CDAI Score at Week 12",
   "description": "The Clinical Disease Activity Index (CDAI) was the sum of 4 outcome parameters:\n\n* Tender joint count out of 28 joints (TJC28)\n* Swollen joint count out of 28 joints (SJC28)\n* Patient's Global Assessment of Disease Activity; and\n* Physician's Global Assessment of Disease Activity.\n\nInterpretation of the CDAI disease activity was measured on a scale of 0 to 76, where ≤2.8 was considered remission, \\>2.8 to ≤10 was considered low/minimal disease activity, \\>10 to ≤22 was considered moderate disease activity, and \\>22.0 was considered high/severe disease activity.\n\nLS mean change from baseline in CDAI score at Week 12 was estimated from the MMRM model.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Percentage of Participants Achieving CDAI Remission (Score ≤ 2.8)",
   "description": "The CDAI was the sum of 4 outcome parameters:\n\n* Tender joint count out of 28 joints (TJC28)\n* Swollen joint count out of 28 joints (SJC28)\n* Patient's Global Assessment of Disease Activity; and\n* Physician's Global Assessment of Disease Activity.\n\nInterpretation of the CDAI disease activity was measured on a scale of 0 to 76, where ≤2.8 was considered remission, \\>2.8 to ≤10 was considered low/minimal disease activity, \\>10 to ≤22 was considered moderate disease activity, and \\>22.0 was considered high/severe disease activity.\n\nModel-based estimates and 95% CIs were produced.",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Percent Change From Baseline in hsCRP Level at Week 12",
   "description": "Blood samples were evaluated to measure levels of hsCRP.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Change From Baseline in Short Form Health Survey SF-36 Physical Component Summary (PCS) Score at Week 12",
   "description": "The PCS is composed of 4 scales of the Short Form-36 Health Status Survey Questionnaire (SF-36) version 2 assessing physical function, role limitations caused by physical problems, bodily pain, and general health. The range of the SF-36 PCS is between 0 and 100, where higher scores represent better physical functioning.\n\nA 2.5 to 5-point change from baseline is established as the minimum clinically-important difference for the PCS in RA participants.\n\nLS mean change from baseline in SF-36 PCS score at Week 12 was estimated from the MMRM model.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Change From Baseline in Functional Assessment of Chronic Illness Therapy - Fatigue Scale (FACIT-Fatigue) Score at Week 12",
   "description": "The FACIT-Fatigue is a 13-item questionnaire that measures an individual's level of fatigue during their usual daily activities over the past week. The level of fatigue is measured on a 4 point Likert scale (4 = not at all fatigued to 0 = very much fatigued). The total score range is from 0 to 52. The higher the score, the lower the fatigue level.\n\nLS mean change from baseline in FACIT-Fatigue score at Week 12 was estimated from the MMRM model.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "ATI-450 and Metabolite (CDD-2164) Concentrations",
   "timeFrame": "2 hours postdose on Days 1, 8, and 85"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Able to comprehend and be willing to sign the Institutional Review Board (IRB)/Independent Ethics Committee (IEC) approved participant ICF prior to administration of any study-related procedures.\n* Diagnosis of adult-onset RA as defined by the 2010 American College of Rheumatology/European League Against Rheumatism (ACR/EULAR) classification criteria.\n* Have active moderate to severe RA at Screening.\n* A minimum of 12 weeks on MTX with a stable MTX dose.\n\nExclusion Criteria:\n\n* Current acute or chronic immunoinflammatory disease other than RA which may impact the course or assessment of RA.\n* Uncontrolled non-immunoinflammatory disease that may place the participant at increased risk during the study or impact the interpretation of results (eg, previous malignancy, recurrent infection, previous venous thromboembolism).\n* Participant has experience with \\> 2 biologics, \\> 1 JAK inhibitor, or a combination of 1 biologic experience and 1 JAK inhibitor.\n* Currently receiving corticosteroids at doses \\> 10 mg/day of prednisone (or equivalent) or have been receiving an unstable dosing regimen of corticosteroids within 2 weeks of screening.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "75 Years"
 },
 "siteCount": 50,
