forecastInput:
{
 "nctId": "NCT04335682",
 "briefTitle": "Androgen Receptor Directed Therapy on Cognitive Function in Patients Treated With Darolutamide or Enzalutamide",
 "officialTitle": "A Randomized Phase II Study of Androgen Receptor Directed Therapy on COGnitive Function in Patients Treated With Darolutamide or Enzalutamide (ARACOG)",
 "leadSponsor": {
  "name": "Alliance Foundation Trials, LLC.",
  "class": "OTHER"
 },
 "collaborators": [
  {
   "name": "Bayer",
   "class": "INDUSTRY"
  }
 ],
 "startDate": "2021-08-17",
 "firstRegistered": "2020-01-13",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Metastatic Prostate Cancer",
  "Prostate Cancer Metastatic",
  "Prostate Cancer",
  "Castrate Resistant Prostate Cancer",
  "Hormone Sensitive Prostate Cancer",
  "Non-metastatic Prostate Cancer"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "OTHER",
  "maskingInfo": {
   "masking": "NONE"
  }
 },
 "enrollment": 111,
 "briefSummary": "This is a prospective, randomized, open-label phase II study comparing cognitive outcomes between men with metastatic and non-metastatic castration resistant prostate cancer (CRPC) or metastatic hormone sensitive prostate cancer (HSPC). Approximately 132 patients will be enrolled. Eligible patients will be randomized in a 1:1 fashion to treatment with enzalutamide 160 mg orally daily or darolutamide 600 mg orally twice daily, in combination with standard LHRH agonist based treatment. Cognitive assessments will be performed using modules from Cambridge Neuropsychological Test Automated Battery (CANTAB) an internationally recognized software for assessing cognitive function and impairment.",
 "detailedDescription": "The goal of the trial is to assess cognitive and quality of life outcomes over the 48-week primary data collection period of the trial. This is a prospective, randomized, open-label phase II study comparing cognitive outcomes between men with Advanced prostate cancer: metastatic and non-metastatic castration resistant prostate cancer (CRPC) or metastatic hormone sensitive prostate cancer (HSPC).\n\nThe primary endpoint will be the percent change in the maximally changed cognitive domain by 24 weeks in each study arm. Patients will be stratified by age (\\<65, 65-80, \\> 80). Patients will be allowed to cross over from either treatment to the opposite treatment arm at 12 and 24 weeks if they meet any of the cross-over criteria as described in the protocol.\n\nCognitive assessments will be performed using Cambridge Neuropsychological Test Automated Battery (CANTAB), an internationally recognized software for assessing cognitive function and impairment. Tests available in the CANTAB battery include tests of learning and executive function; working memory; visual, verbal and episodic memory; and attention, information and processing time. The maximally changed cognitive domain is defined as the domain most changed from baseline in each individual.\n\nBlood samples will be collected for exploratory genomic analyses (AR CAG repeat length, PHS, exosome analysis).\n\nPatients will have the option to opt into an additional separate MRI sub-study. A subset of 40 patients (20 per arm) will undergo fMRI to measure percent signal change in the HP PFC circuit at baseline, 24 and 48 weeks or/and cross-over/end of treatment visit (if applicable).",
 "arms": [
  {
   "label": "Darolutamide (DARO)",
   "type": "ACTIVE_COMPARATOR",
   "description": "Patients will take DARO at a dose of 600 mg (300 mg ×2 tablets) by mouth twice daily beginning on Day 1, of Week 1. Patients will take DARO throughout planned treatment period or withdrawal of consent or progression of disease requiring change in therapy.",
   "interventionNames": [
    "Drug: Darolutamide"
   ]
  },
  {
   "label": "Enzalutamide (ENZ)",
   "type": "ACTIVE_COMPARATOR",
   "description": "Patients will take ENZ at a dose of 160 mg PO once daily (QD), beginning on Day 1, of Week 1. Patients will take ENZ throughout planned treatment period or withdrawal of consent or progression of disease requiring change in therapy.",
   "interventionNames": [
    "Drug: Enzalutamide"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Darolutamide",
   "description": "Patients randomized to darolutamide.",
   "armGroupLabels": [
    "Darolutamide (DARO)"
   ],
   "otherNames": [
    "Nubeqa"
   ]
  },
  {
   "type": "DRUG",
   "name": "Enzalutamide",
   "description": "Patients randomized to enzalutamide.",
   "armGroupLabels": [
    "Enzalutamide (ENZ)"
   ],
   "otherNames": [
    "Xtandi"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change in the Maximally Changed Cognitive Domain",
   "description": "To compare the effects of treatment with enzalutamide (ENZ) versus darolutamide (DARO) on the cognitive function of men with non-metastatic and metastatic castration-resistant prostate cancer by comparing the change in the maximally changed cognitive domain utilizing Cambridge Neuropsychological Test Automated Battery \\[CANTAB\\] cognitive tests from baseline in patients in each study arm. The maximally changed cognitive domain is defined as the domain most changed from baseline in each individual. CANTAB is the max score from 5 subscores Paired Associates Learning (0-20, Higher scores = better performance), Spatial Working Memory (0-63, Higher scores = worse performance), Rapid Visual Information Processing (0-1, Higher scores = better performance), Spatial Span (2-9, Higher scores = better performance), and One Touch Stockings of Cambridge (1-7, Higher scores = worse performance).",
   "timeFrame": "24 weeks"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Crossover From Enzalutamide to Darolutamide and Darolutamide to Enzalutamide",
   "description": "Proportion of patients crossing over from each treatment arm based on subjective (self-reported, FACT-Cognitive Function \\[Version 3\\], FACT-Cog V3, decline by \\>10 points from baseline score) cognitive effects.\n\n* Proportion of patients crossing over from each treatment arm based on objective cognitive effects (the Cambridge Neuropsychological Test Automated Battery \\[CANTAB\\] , decline by \\> 30% from baseline on any cognitive domain).\n* Proportion of patients crossing over from ENZ to DARO based on Timed Up and Go (TUG) times \\>12 seconds or 12 seconds or increase from baseline by \\>1 second.\n* Proportion of patient crossing over due to neurologic toxicity (fatigue) with a preference to cross over (ENZ or DARO) or severe neurological toxicity \\[seizures or posterior reversible encephalopathy syndrome PRES\\]). Cross over for severe neurologic toxicity is allowed for patients on ENZ only.",
   "timeFrame": "48 weeks"
  },
  {
   "measure": "Maximally Changed Cognitive Domain",
   "description": "Average decline in maximally changed cognitive domain in patients in each arm based on self-reported cognitive tests (Cambridge Neuropsychological Test Automated Battery \\[CANTAB\\]). Tests in the CANTAB battery include tests of learning and executive function; working memory; visual, verbal and episodic memory; and attention, information and processing time. The maximally changed cognitive domain is defined as the domain most changed from baseline in each individual.",
   "timeFrame": "48 weeks"
  },
  {
   "measure": "Proportion of Impaired Patients",
   "description": "Cumulative proportion of impaired patients in each arm",
   "timeFrame": "24 weeks"
  },
  {
   "measure": "Proportion of Impaired Patients",
   "description": "Cumulative proportion of impaired patients in each arm",
   "timeFrame": "48 weeks"
  },
  {
   "measure": "Change in Lowest Ranking Domain",
   "description": "Average change in lowest ranking domain Cambridge Neuropsychological Test Automated Battery \\[CANTAB\\] questionnaire outcomes at baseline (in a given individual). Tests in the CANTAB battery include tests of learning and executive function; working memory; visual, verbal and episodic memory; and attention, information and processing time.",
   "timeFrame": "24 weeks"
  },
