 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline in Pulmonary Vascular Resistance (PVR)",
   "description": "The effect of AZD3427 compared with placebo on PVR parameter as measured by right heart catheterization (RHC-a procedure which allows measurement of blood pressure in the right side of the heart) after 24 weeks of treatment in participants with heart failure (HF) and pulmonary hypertension (PH) Group 2 was evaluated. PVR was calculated using formula, PVR=80\\* \\[Mean pulmonary arterial pressure\\[mPAP\\](mmHg)- Pulmonary artery wedge pressure\\[PAWP\\](mmHg)\\]/Cardiac output (L/min).\n\nBaseline was defined as last non-missing value prior to or on the date of first study intervention dose. PVR was originally measured in dynes·sec/cm⁵. For the statistical analysis, PVR values were log-transformed, and change from baseline was assessed on the log-transformed scale. Results were subsequently back-transformed and presented on the original scale as the ratio of post-baseline to baseline PVR. Therefore, the unit of measure for this endpoint is a ratio.\n\nThe measure type is geometric mean ratio.",
   "timeFrame": "Baseline to Week 25"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline in Mean Pulmonary Arterial Pressure (mPAP)",
   "description": "The effect of AZD3427 compared with placebo on mPAP parameter as measured by RHC after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Pulmonary Artery Wedge Pressure (PAWP)",
   "description": "The effect of AZD3427 compared with placebo on PAWP parameter as measured by RHC after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated.\n\nBaseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention. PAWP was measured in mmHg. The analysis was done similar to the primary endpoint. Therefore, the unit of measure for this endpoint is a ratio.\n\nThe measure type is geometric mean ratio.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Cardiac Output (CO) ECHO",
   "description": "The effect of AZD3427 compared with placebo on CO parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Left Ventricular Stroke Volume (LV SV)",
   "description": "The effect of AZD3427 compared with placebo on LV SV parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Left Ventricular Ejection Fraction (LVEF)",
   "description": "The effect of AZD3427 compared with placebo on EF parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Left Ventricular Global Longitudinal Strain (LVGLS)",
   "description": "The effect of AZD3427 compared with placebo on LVGLS parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. LVGLS is measured by echocardiograohy.\n\nBaseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Pulmonary Arterial Systolic Pressure (PASP)",
   "description": "The effect of AZD3427 compared with placebo on PASP parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Right Ventricle/Left Ventricle (RV/LV) Ratio",
   "description": "The effect of AZD3427 compared with placebo on RV/LV parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Right Ventricular Outflow Tract Acceleration Time (RVOT AT)",
   "description": "The effect of AZD3427 compared with placebo on RVOT AT parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Tricuspid Regurgitation Velocity (TRV)",
   "description": "The effect of AZD3427 compared with placebo on TRV parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. TRV was measured by Echocardiography.\n\nBaseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in TAPSE/PASP [Tricuspid Annular Plane Systolic Excursion/ Pulmonary Arterial Systolic Pressure]",
   "description": "The effect of AZD3427 compared with placebo on TAPSE/PASP parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Systemic Vascular Resistance (SVR)",
   "description": "The effect of AZD3427 compared with placebo on systemic vascular resistance parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. SVR was measured by Echocardipgraphy.\n\nBaseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in 6-minute Walking Distance (6MWD)",
   "description": "The effect of AZD3427 compared with placebo on function and symptoms using 6MWD parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Kansas City Cardiomyopathy Questionnaire Total Symptom Score (KCCQ TSS)",
   "description": "The effect of AZD3427 compared with placebo on function and symptoms using KCCQ TSS parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. The score ranged from 0 to 100, where a higher score represents a better patient outcome. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Number of Participants With Improved Change From Baseline in New York Heart Association Functional Class (NYHA FC)",
   "description": "The effect of AZD3427 compared with placebo on function and symptoms using NYHA FC parameter after 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 25"
  },
  {
   "measure": "Change From Baseline in Serum Creatinine",
   "description": "The effect of AZD3427 compared with placebo using serum creatinine parameter after 12 and 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention. Creatinine was measured in micromoles/liter. The analysis was done similar to the primary endpoint. Therefore, the unit of measure for this endpoint is a ratio.",
   "timeFrame": "Baseline to Week 13 and Week 25"
  },
  {
   "measure": "Change From Baseline in N-terminal Prohormone of Brain Natriuretic Peptide (NT-proBNP)",
   "description": "The effect of AZD3427 compared with placebo using NT-proBNP parameter after 12 and 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention. NT-ProBNP was measured in picomole/Liter. The analysis was done similar to the primary endpoint. Therefore, the unit of measure for this endpoint is a ratio.",
   "timeFrame": "Baseline to Week 13 and Week 25"
  },
  {
   "measure": "Change From Baseline in Cystatin C",
   "description": "The effect of AZD3427 compared with placebo using cystatin C parameter after 12 and 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention. Cystatin C was measured in milligram/deciliter. The analysis was done similar to the primary endpoint. Therefore, the unit of measure for this endpoint is a ratio.",
   "timeFrame": "Baseline to Week 13 and Week 25"
  },
  {
   "measure": "Change From Baseline in eGFR (Estimated Glomerular Filtration Rate)",
   "description": "The effect of AZD3427 compared with placebo using eGFR parameter after 12 and 24 weeks of treatment in participants with HF and PH Group 2 was evaluated. Baseline was defined as the last non-missing value prior to or on the same date as the administration of the first dose of study intervention.",
   "timeFrame": "Baseline to Week 13 and Week 25"
  },
  {
   "measure": "AZD3427 Serum Concentration",
   "description": "Serum concentration of AZD3427 was summarised by timepoints and dose level. This was done to evaluate the pharmacokinetics (PK) of AZD3427 after dosing in participants with HF and PH Group 2.\n\nConsidering the approximately 13-14 days half-life of AZD3427, low or non-quantifiable serum concentrations at Week 31 are not unexpected. Therefore, the presentation of the Week 31 results, including the reported NA values, reflects the prespecified statistical handling of the data and the observed concentration profile.",
   "timeFrame": "On Week 3, Week 5, Week 13, Week 19, Week 25 and Week 31"
  },
  {
   "measure": "Number of Participants With Presence of Anti-drug Antibodies (ADAs)",
   "description": "The immunogenicity of AZD3427 was evaluated as measured by ADAs. The number of participants with treatment emergent (TE) ADA positive samples have been reported as they account for the ADA incidence during the study.",
   "timeFrame": "From Day 1 up to Day 211"
  },
  {
   "measure": "Evaluation of Positive ADA Titer",
   "description": "The immunogenicity of AZD3427 as measured by ADAs was evaluated. ADA titer was summarized descriptively as a continuous variable, with median, minimum and maximum values.\n\nThe antibody titer for the TE-ADA positive (ADA incidence) participants have been reported. It is defined as the sum of treatment-induced ADA (post-baseline positive only) and treatment-boosted ADA.\n\nCombined timepoint is used in summary for subject-level overall ADA status (i.e. TE-ADA positive). The summary statistics were calculated based on the maximum post-baseline titre for each ADA-positive subject within each treatment group,'",
   "timeFrame": "At Day 1, Day 15, Day 29, Day 85, Day 169 and Day 211."
  }
 ],
 "eligibility": {
  "criteria": "Inclusion criteria:\n\n1. Participant must be ≥ 18 years of age inclusive.\n2. Participants must have a pre-existing diagnosis of HF, NYHA function class (FC) II to IV, and a pre-existing diagnosis of PH-LHD or likely or intermediate probability of Pulmonary hypertension due to left heart disease (PH-LHD) as per 2022 Pulmonary hypertension due to left heart disease European Society of Cardiology/European Respiratory Society (ESC/ERS) guidelines. Participants must be on stable HF standard of care medication, including diuretics.\n3. Participants must have a combination of echocardiographic parameters that show intermediate or high probability of PH as per 2022 ESC/ERS guidelines.\n4. Participants must have an on-study elevated pulmonary artery pressure from RHC performed as per RHC manual provided by the Sponsor, at Screening Visit 2:\n\n   1. PAWP ≥ 15 mmHg\n   2. mPAP ≥ 20 mmHg\n5. Minimum body weight of 45 kg (inclusive).\n6. Capable and willing of giving signed informed consent.\n\nExclusion Criteria\n\n1. Diagnosis of PH in World Health Organization (WHO) Group 1, WHO Group 3, WHO Group 4, or WHO Group 5.\n2. Historical or current evidence of a clinically significant disease or disorder.\n3. Decompensated HF or hospitalisation due to decompensated HF.\n4. Any contraindications to RHC.\n5. History of hypersensitivity to SC injections or devices.\n6. History of hypersensitivity to drugs with a similar chemical structure or class to AZD3427 or any component of AZD3427 drug product, or ongoing clinically important allergy/hypersensitivity.\n7. Known lung disease with Forced expiratory volume in the first second (FEV1) \\< 30% of predicted.\n8. Congenital long QT syndrome.\n9. Cardiac ventricular arrhythmia which requires treatment. Participants with atrial fibrillation or flutter and controlled ventricular rate are permitted.\n10. History of or anticipated heart transplant or ventricular assist device implantation.\n11. Any known planned (scheduled) highly invasive Cardiovascular (CV) procedure (eg, coronary revascularisation, ablation of atrial fibrillation/flutter, valve repair/replacement, aortic aneurysm surgery, etc).\n12. Participants who have previously received AZD3427.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "130 Years"
 },
