{
 "nctId": "NCT05936151",
 "briefTitle": "A Study of Retatrutide (LY3437943) on Renal Function in Participants With Overweight or Obesity and Chronic Kidney Disease With or Without Type 2 Diabetes",
 "officialTitle": "A Phase 2b, Double-Blind Study to Investigate the Effect of Retatrutide on Renal Function in Participants With Overweight or Obesity and Chronic Kidney Disease With or Without Type 2 Diabetes",
 "leadSponsor": {
  "name": "Eli Lilly and Company",
  "class": "INDUSTRY"
 },
 "startDate": "2023-07-20",
 "firstRegistered": "2023-06-30",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Overweight or Obesity",
  "CKD",
  "Type 2 Diabetes"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
