  "maskingInfo": {
   "masking": "DOUBLE",
   "maskingDescription": "Phase 2b",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 146,
 "briefSummary": "The main purpose of this study is to investigate the effect of retatrutide on renal function in participants with overweight or obesity and chronic kidney disease (CKD), with or without Type 2 Diabetes (T2D). The study will last around 31 weeks.",
 "arms": [
  {
   "label": "Retatrutide",
   "type": "EXPERIMENTAL",
   "description": "Participants received retatrutide administered subcutaneously once weekly for approximately 24 weeks. Treatment was initiated at 2 milligrams (mg) once weekly and escalated every 4 weeks to 4 mg, 6 mg, 9 mg, and 12 mg. The target maintenance dose was 12 mg once weekly. Participants who did not tolerate the 12 mg dose could remain on a maintenance dose of 4 mg, 6 mg, or 9 mg.",
   "interventionNames": [
    "Drug: Retatrutide"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Participants received placebo matched retatrutide administered subcutaneously once weekly for approximately 24 weeks. To maintain blinding, participants followed a sham dose-escalation schedule with changes in administered volume every 4 weeks to match the retatrutide dose-escalation schedule.",
   "interventionNames": [
    "Drug: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Retatrutide",
   "description": "Administered Subcutaneously",
   "armGroupLabels": [
    "Retatrutide"
   ],
   "otherNames": [
    "LY3437943"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "Administered Subcutaneously",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline in Measured Glomerular Filtration Rate (mGFR) Using Iohexol Clearance at Week 24",
   "description": "Measured glomerular filtration rate (mGFR) was determined from iohexol plasma clearance following a single iohexol injection and serial blood sampling. LS mean was estimated using a mixed model for repeated measures (MMRM) including baseline, joint levels of stratification factors, treatment, time, time-by-baseline interaction, and treatment-by-time interaction (Type III sums of squares), with an unstructured covariance matrix. Change from baseline was calculated as the Week 24 Body Surface Area (BSA)-indexed mGFR minus the baseline BSA-indexed mGFR and was reported in milliliters per minute per 1.73 square meters (mL/min/1.73 m²). Only participants with a non-missing baseline value and at least one post-baseline value were analyzed.",
   "timeFrame": "Baseline, Week 24"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline in Measured Glomerular Filtration Rate (mGFR) Using Iohexol Clearance at Week 16",
   "description": "Measured glomerular filtration rate (mGFR) was determined from iohexol plasma clearance following a single iohexol injection and serial blood sampling. LS mean was estimated using a mixed model for repeated measures (MMRM) including baseline, joint levels of stratification factors, treatment, time, time-by-baseline interaction, and treatment-by-time interaction (Type III sums of squares), with an unstructured covariance matrix. Change from baseline was calculated as the Week 16 BSA-indexed mGFR minus the baseline BSA-indexed mGFR and was reported in mL/min/1.73 m².",
   "timeFrame": "Baseline, Week 16"
  },
  {
   "measure": "Percent Change From Baseline in Urine Albumin-to-Creatinine Ratio (UACR) at Week 24",
   "description": "Urine Albumin-to-Creatinine ratio (UACR) was calculated by the central laboratory from urinary albumin and urinary creatinine measurements. LS mean was estimated using a mixed model for repeated measures (MMRM) including baseline, joint levels of stratification factors, treatment, time, time-by-baseline interaction, and treatment-by-time interaction (Type III sums of squares), with an unstructured covariance matrix. Baseline and postbaseline UACR values were log-transformed for analysis. Model estimates were back-transformed and reported as percent change from baseline. A negative value indicates a decrease from baseline. Only participants with a non-missing baseline value and at least one post-baseline value were analyzed.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Change From Baseline in Creatinine-Corrected Fractional Urinary Sodium Excretion (FENa) at Week 24",
   "description": "Creatinine-corrected fractional excretion of sodium (FENa) was calculated as: FENa (%) = 100 × \\[(serum creatinine × urine sodium) / (serum sodium × urine creatinine)\\]. LS mean was estimated using a mixed model for repeated measures (MMRM) including baseline, joint levels of stratification factors, treatment, time, time-by-baseline interaction, and treatment-by-time interaction (Type III sums of squares), with an unstructured covariance matrix. Change from baseline was calculated as the Week 24 FENa minus the baseline FENa.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Change From Baseline in Filtration Fraction Estimated From Measured Glomerular Filtration Rate (mGFR) and MRI-Assessed Renal Mean Arterial Flow, Corrected by Hematocrit at Week 24",
   "description": "Filtration fraction was calculated as non-BSA-indexed mGFR (mL/min) divided by renal plasma flow (mL/min). Renal plasma flow was calculated as MRI-measured renal blood flow × (1 - hematocrit). LS mean was estimated using a mixed model for repeated measures (MMRM) including baseline, joint levels of stratification factors, treatment, time, time-by-baseline interaction, and treatment-by-time interaction (Type III sums of squares), with an unstructured covariance matrix. Change from baseline was calculated as the Week 24 filtration fraction minus the baseline filtration fraction.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Change From Baseline in Mean Arterial Flow (MAF) at Week 24",
   "description": "Mean arterial flow (MAF) was the bilateral mean blood flow in the renal arteries measured using phase-contrast magnetic resonance imaging (PC-MRI). LS mean was estimated using a mixed model for repeated measures (MMRM) including baseline, joint levels of stratification factors, treatment, time, time-by-baseline interaction, and treatment-by-time interaction (Type III sums of squares), with an unstructured covariance matrix. Change from baseline was calculated as the Week 24 MAF minus the baseline MAF.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Change From Baseline in Renal Artery Resistive Index (RARI) at Week 24",
   "description": "RARI is a dimensionless measure of resistance to renal arterial blood flow and was calculated from phase-contrast magnetic resonance imaging (PC-MRI) as: RARI= (peak systolic velocity \\[PSV\\]- end-diastolic velocity \\[EDV\\]) /PSV. RARI has a theoretical range of 0 to 1, with higher values generally representing a less favorable outcome. In general adult population, RARI values of 0.50 to 0.70 are typically considered normal, and values greater than 0.70 are generally considered elevated; however, these reference values are derived from Doppler ultrasound measurements, and MRI-based RARI values may differ and require further validation. LS mean was estimated using a MMRM including baseline, joint levels of stratification factors, treatment, time, time-by-baseline interaction, and treatment-by-time interaction (Type III sums of squares), with an unstructured covariance matrix. Change from baseline was calculated as Week 24 RARI minus the baseline RARI.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Change From Baseline in Renal Blood Flow Velocity Peak Systolic Velocity (PSV) at Week 24",
   "description": "Peak systolic velocity (PSV) was the highest renal arterial blood flow velocity measured during systole using cardiac-gated phase-contrast magnetic resonance imaging. LS mean was estimated using a mixed model for repeated measures (MMRM) including baseline, joint levels of stratification factors, treatment, time, time-by-baseline interaction, and treatment-by-time interaction (Type III sums of squares), with an unstructured covariance matrix. Change from baseline was calculated as the Week 24 PSV minus the baseline PSV.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Change From Baseline in Renal Blood Flow Velocity End-Diastolic Velocity (EDV) at Week 24",
   "description": "End-diastolic velocity (EDV) was the lowest renal arterial blood flow velocity measured during diastole using cardiac-gated phase-contrast magnetic resonance imaging. LS mean was estimated using a mixed model for repeated measures (MMRM) including baseline, joint levels of stratification factors, treatment, time, time-by-baseline interaction, and treatment-by-time interaction (Type III sums of squares), with an unstructured covariance matrix. Change from baseline was calculated as the Week 24 EDV minus the baseline EDV.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Percent Change From Baseline in Total Renal Parenchyma Volume (MRI) at Week 24",
   "description": "Total renal parenchyma volume was measured using magnetic resonance imaging by delineating the corresponding regions of interest on T1 maps. LS mean was estimated using a mixed model for repeated measures (MMRM) including baseline, joint levels of stratification factors, treatment, time, time-by-baseline interaction, and treatment-by-time interaction (Type III sums of squares), with an unstructured covariance matrix. Percent change from baseline in Total Renal Parenchyma Volume was calculated as: 100 × (Week 24 total renal parenchyma volume - baseline total renal parenchyma volume) / baseline total renal parenchyma volume.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Percent Change From Baseline in Renal Cortex Volume (MRI) at Week 24",
