{
 "nctId": "NCT05958407",
 "briefTitle": "A 32-week Trial to Evaluate the Efficacy and Safety of Tralokinumab in Subjects With Moderate-to-severe Atopic Hand Eczema Who Are Candidates for Systemic Therapy",
 "officialTitle": "A Phase 3b, Interventional, Adaptive, Clinical Trial to Evaluate the Efficacy and Safety of Tralokinumab 300 mg Every Second Week Monotherapy Compared With Placebo in Subjects With Moderate-to-severe Atopic Hand Eczema Who Are Candidates for Systemic Therapy",
 "leadSponsor": {
  "name": "LEO Pharma",
  "class": "INDUSTRY"
 },
 "startDate": "2023-08-28",
 "firstRegistered": "2023-07-13",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Atopic Dermatitis",
  "Atopic Hand Eczema"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "DOUBLE",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 235,
 "briefSummary": "The purpose of this study is to test if treatment with tralokinumab is safe and efficacious in treating moderate-to-severe atopic hand eczema. This will be judged by a range of assessments that rate the severity and extent of atopic hand eczema and its symptoms, as well as general health status and quality of life.\n\nThe trial will last for up to 40 weeks for each participant. There will be up to 15 visits for each participant, 3 of which will be conducted by phone. The first part of the trial is called a screening period and will last up to 4 weeks. For the first 16 weeks after screening, trial participants will receive either tralokinumab or dummy injections every two weeks. After the first 16 weeks, all trial participants will receive tralokinumab injections every two weeks for 16 weeks. The last part of the trial is a period of 4 weeks after the end of treatment period, where trial participants will not receive tralokinumab but are monitored for safety.",
 "arms": [
  {
   "label": "Tralokinumab",
   "type": "EXPERIMENTAL",
   "description": "Tralokinumab is administered for 32 weeks (16 weeks double-blinded period + 16 weeks open-label period)",
   "interventionNames": [
    "Drug: Tralokinumab"
   ]
  },
  {
   "label": "Placebo + tralokinumab",
   "type": "PLACEBO_COMPARATOR",
   "description": "Placebo is administered for 16 weeks (double-blinded period) prior to roll-over to a 16 weeks open-label period where tralokinumab is administered",
   "interventionNames": [
    "Drug: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Tralokinumab",
   "description": "After a loading dose of 600 mg under the skin (s.c.) at baseline, trial participants are administered a dose of 300 mg every two weeks for 32 weeks",
   "armGroupLabels": [
    "Tralokinumab"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "After a loading dose under the skin (s.c.) at baseline, trial participants are administered a placebo dose every two weeks for 16 weeks",
   "armGroupLabels": [
    "Placebo + tralokinumab"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Percentage of Participants With IGA-AHE Score of 0 (Clear) or 1 (Almost Clear)",
   "description": "IGA-AHE: The Investigator's Global Assessment for atopic hand eczema (IGA-AHE) is an instrument to rate the severity of the subject's AHE and is based on a 5-point scale ranging from 0 (clear) to 4 (severe).",
   "timeFrame": "At Week 16"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Percentage of Participants Having a ≥2-point Reduction in IGA-AHE Score",
   "description": "IGA-AHE: The Investigator's Global Assessment for atopic hand eczema (IGA-AHE) is an instrument to rate the severity of the subject's AHE and is based on a 5-point scale ranging from 0 (clear) to 4 (severe).",
   "timeFrame": "From baseline to Week 16"
  },
  {
   "measure": "Percentage of Participants Having a Decrease in HECSI of at Least 75% (HECSI-75)",
   "description": "The Hand Eczema Severity Index (HECSI) is an instrument used in clinical trials to rate the severity of 6 clinical signs (erythema, infiltration/papulation, vesicles, fissures, scaling, and oedema) and the extent of the lesions in each of the 5 hand regions (fingertips, fingers \\[except fingertips\\], palm of hands, back of hands, and wrists) by use of standard scales. The HECSI score will range from 0 (lowest possible score) to 360 (highest possible score), with a higher score indicating greater severity. HECSI-75 is defined as at least 75% improvement in HECSI score from baseline.",
   "timeFrame": "From baseline (Day 1) to Week 16"
  },
