 "primaryOutcomes": [
  {
   "measure": "Progression Free Survival (PFS) Per Response Evaluation Criteria in Solid Tumors Version 1.1 (RECIST 1.1) as Assessed by Blinded Independent Central Review (BICR)",
   "description": "PFS was defined as the time from the first dose of study intervention to the first documented progressive disease (PD) per RECIST 1.1 by BICR or death due to any cause, whichever occurs first. Per RECIST 1.1 adjusted for this study to allow a maximum of 10 target lesions and a maximum of 5 target lesions per organ, PD was defined as at least a 20% increase in the sum of diameters (SOD) of target lesions. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of at least 5 mm. The appearance of one or more new lesions was also considered PD. PFS per RECIST 1.1 as assessed by BICR was reported.",
   "timeFrame": "Up to approximately 43.5 Months"
  },
  {
   "measure": "Overall Survival (OS)",
   "description": "OS was defined as the time from randomization to death due to any cause.",
   "timeFrame": "Up to approximately 61.7 Months"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "PFS Per Modified RECIST (mRECIST) as Assessed by BICR",
   "description": "PFS was defined as the time from the first dose of study intervention to the first documented PD per mRECIST by BICR or death due to any cause, whichever occurs first. mRECIST for hepatocellular carcinoma (HCC) allows evaluation of treatment effects that are not reflected in simple total size changes of lesions. Per mRECIST, PD was defined as an increase of at least 20% in the SODs of viable target lesions, taking as reference the smallest SODs of viable target lesions recorded since the treatment started. PFS per mRECIST as assessed by BICR was reported.",
   "timeFrame": "Up to approximately 61.7 Months"
  },
  {
   "measure": "Objective Response Rate (ORR) Per mRECIST as Assessed by BICR",
   "description": "ORR was defined as the percentage of participants who achieve a confirmed complete response (CR) (disappearance of any intratumoral arterial enhancement in all target lesions) or a partial response (PR) (at least a 30% decrease in the SOD of viable \\[contrast enhancement in the arterial phase\\] target lesions, taking as reference the baseline SOD of target lesions) per mRECIST as assessed by BICR. mRECIST for HCC allows evaluation of treatment effects that are not reflected in simple total size changes of lesions. The percentage of participants who experienced CR or PR per mRECIST as assessed BICR was presented.",
   "timeFrame": "Up to approximately 61.7 Months"
  },
  {
   "measure": "Disease Control Rate (DCR) Per mRECIST as Assessed by BICR",
   "description": "DCR was defined as the percentage of participants who have achieved a confirmed complete response (CR) (disappearance of any intratumoral arterial enhancement in all target lesions) or a partial response (PR) (at least a 30% decrease in the SOD of viable \\[contrast enhancement in the arterial phase\\] target lesions, taking as reference the baseline SOD of target lesions) per mRECIST as assessed by BICR. mRECIST for HCC allows evaluation of treatment effects that are not reflected in simple total size changes of lesions. PD was defined as at least a 20% increase in the SOD of target lesions. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of at least 5 mm. The appearance of one or more new lesions was also considered PD. The percentage of participants who achieved CR, PR, or SD after ≥6 weeks per mRECIST assessed by BICR was presented.",
   "timeFrame": "Up to approximately 61.7 Months"
  },
  {
   "measure": "Duration of Response (DOR) Per mRECIST as Assessed by BICR",
   "description": "For participants who demonstrated confirmed CR or PR per mRECIST assessed by BICR, DOR was defined as the time from the first documented evidence of a confirmed complete response (CR) (disappearance of any intratumoral arterial enhancement in all target lesions) or a partial response (PR) (at least a 30% decrease in the SOD of viable \\[contrast enhancement in the arterial phase\\] target lesions, taking as reference the baseline SOD of target lesions) per mRECIST as assessed by BICR. mRECIST for HCC allows evaluation of treatment effects that are not reflected in simple total size changes of lesions. PD was defined as at least a 20% increase in the SOD of target lesions. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of at least 5 mm. The appearance of one or more new lesions was also considered PD. The DOR as assessed using mRECIST for all participants who experienced a confirmed CR or PR was presented.",
   "timeFrame": "Up to approximately 61.7 Months"
  },
  {
   "measure": "Time-To-Progression (TTP) Per mRECIST as Assessed by BICR",
   "description": "TTP was defined as the time from the first dose of study intervention to the first documented PD per mRECIST assessed by BICR. mRECIST for HCC allows evaluation of treatment effects that are not reflected in simple total size changes of lesions. PD was defined as at least a 20% increase in the SOD of target lesions. In addition to the relative increase of 20%, the sum must also demonstrate an absolute increase of at least 5 mm. The appearance of one or more new lesions was also considered PD. TTP per mRECIST as assessed by BICR was presented.",
