   "measure": "Percentage of Participants With Viral Control Without Antiretroviral Therapy (ART) Restart",
   "description": "Percentage of participants who achieve viral control (viral load \\< 1000 copies/mL) without ART restart at Week 24.",
   "timeFrame": "Week 24"
  },
  {
   "measure": "Number of Participants With Adverse Events (AEs)",
   "description": "An AE is defined as any untoward medical occurrence in a patient or clinical investigation in which a participant is administered a pharmaceutical product which does not necessarily have a causal relationship with this treatment.",
   "timeFrame": "Up to approximately Week 112"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Median Peak Log10 Viral Load (At Rebound) Prior to Re-Starting ART",
   "description": "The median peak log10 viral load (at rebound) before re-starting ART.",
   "timeFrame": "Up to 112 weeks"
  },
  {
   "measure": "Median Time to First Rebound to ≥ 1000 Copies/mL During ART Interruption",
   "description": "The median time to first rebound to ≥ 1000 copies/mL during ART interruption.",
   "timeFrame": "Up to 112 weeks"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* A condition of general good health in the opinion of the investigator, based upon the results of a medical history, physical examination, vital signs, laboratory profile, and a 12-lead electrocardiogram (ECG).\n* Must be on antiretroviral therapy (ART) for at least 12 months prior to screening and on a stable ART regimen for at least 8 weeks prior to screening (current ART regimen cannot include an Non-nucleoside reverse transcriptase inhibitor \\[NNRTI\\] or long-acting ART).\n* Negative human immuno-deficiency virus (HIV)-2 antibody (Ab)\n* Cluster of differentiation 4 (CD4+) T cell count \\>= 500 cells/μL at screening and no known evidence of CD4+ T cell count \\< 500 cells/μL in the last 12 months prior to screening\n* Participant must have plasma HIV-1 ribonucleic acid (RNA) below the lower limit of quantitation (LLOQ) at screening and for at least 12 months prior to screening\n\nExclusion Criteria:\n\n* Prior exposure to long acting antiretrovirals within 24 weeks or within a period defined by 5 half-lives, whichever is longer, prior to randomization and prior to the first dose of study drug.\n* History of CD4+ T cell nadir of \\<= 200 cells/μL during chronic HIV infection.\n* History of medical disorders (other than HIV-1 infection) that, in the opinion of the investigator, might expose the participant to undue risk of harm, confound study outcomes or prevent the participant from completing the study.",
  "healthyVolunteers": false,
  "sex": "ALL",
