 "primaryOutcomes": [
  {
   "measure": "Change From Baseline in Interferon-gamma Spot Forming Units (IFN-γ SFUs) in Human Leukocyte Antigens Density Quotient (HLA-DQ2.5-positive) Participants Based on Results of a Gliadin-Specific Enzyme-Linked Immunospot (ELISpot) Assay",
   "description": "IFN-γ SFUs were measured based on results of a gliadin-specific ELISpot assay using peripheral blood mononuclear cells (PBMCs). Gliadin-specific cluster of differentiation 4 (CD4) T cells were a small percentage of the PBMCs and responded to gliadin peptide stimulation in vitro by producing the IFN-γ cytokine. Baseline was defined as Day 15.",
   "timeFrame": "Baseline (Day 15), Week 3 (Day 20)"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Percentage of Participants Experiencing at Least One Treatment-emergent Adverse Event (TEAE) and Adverse Events of Special Interest (AESIs)",
   "description": "An adverse event (AE) is defined as any untoward medical occurrence in a clinical investigation participant administered a drug; it does not necessarily have to have a causal relationship with this treatment. An AE can therefore be any unfavorable and unintended sign (e.g., a clinically significant abnormal laboratory value), symptom, or disease temporally associated with the use of a drug whether or not it is considered related to the drug. A TEAE was defined as an AE that started, or severity worsened, or intensity increased after receiving the first study drug administration and up to within 30 days of last dose of study drug. An AESI (serious or nonserious) is one of scientific and medical concern specific to the compound or program, for which ongoing monitoring and rapid communication by the investigator to the sponsor may be appropriate. AESIs are reported based on the Standardized MedDRA Queries (SMQs) and based on case report forms (CRFs).",
   "timeFrame": "Up to Week 28"
  },
  {
   "measure": "Change From Run-in (Visit 2) to Weeks 8, 14, and 20 in the Pre- to Post-gluten Challenge Change of the 3-day Average Nausea Severity Score as Measured in Celiac Disease Symptom Diary (CDSD)",
   "description": "CDSD version 2.1 is a 8-item (severity of diarrhea, abdominal pain, bloating, nausea, and tiredness, frequency of bowel movement and vomiting, and a count of loosest stool forms), self-administered questionnaire that evaluates CeD symptoms using 5-point Likert-type scales (\\[0\\] none, \\[1\\] mild, \\[2\\] moderate, \\[3\\] severe, and \\[4\\] very severe), where lower score indicating no symptoms and higher score indicating severe symptoms for all items except for frequency questions relating to stool counts, diarrhea, and vomiting frequency. Scores from past 3 days with a 24-hour recall period were averaged. For Run-in, Weeks 8, 14, and 20, each score was calculated as average of available daily scores recorded in 3 days prior and after the respective gluten challenge. Results are reported as least squares (LS) mean change from run-in at Weeks 8, 14 and 20, determined using a linear mixed-effect model for repeated measures (MMRM) analysis. A negative change from run-in indicates improvement.",
   "timeFrame": "Run-in (Visit 2 at Week -4), Weeks 8, 14, and 20"
  },
  {
   "measure": "Change From Run-in (Visit 2) to Weeks 8,14, and 20 in the Pre- to Post-gluten Challenge Change in CDSD 3-day Peak Nausea Severity Score",
   "description": "CDSD version 2.1 is an 8-item (severity of diarrhea, abdominal pain, bloating, nausea, and tiredness, frequency of bowel movement and vomiting, and a count of loosest stool forms), self-administered questionnaire that evaluates CeD symptoms using 5-point Likert-type scales (\\[0\\] none, \\[1\\] mild, \\[2\\] moderate, \\[3\\] severe, and \\[4\\] very severe), where lower score indicating no symptoms and higher score indicating severe symptoms for all items except for frequency questions relating to stool counts, diarrhea, and vomiting frequency. Scores from past 3 days with a 24-hour recall period were averaged. For Run-in, Weeks 8, 14, and 20, each score was calculated as average of the available daily scores recorded in the 3 days prior and after the respective gluten challenge. Results are reported as LS mean change from run-in at Weeks 8, 14 and 20, determined using a linear MMRM analysis. A negative change from run-in indicates improvement.",
   "timeFrame": "Run-in (Visit 2 at Week -4), Weeks 8, 14, and 20"
  },
  {
   "measure": "Change From Run-in (Visit 2) to Weeks 8, 14, and 20 in the Pre- to Post-gluten Challenge Change in Weekly Gastrointestinal (GI) Symptom Severity Score",
   "description": "CDSD GI symptom severity score is an average of the daily GI symptom severity scores during the week. The daily GI symptom severity score is the average of the severity score for diarrhea, abdominal pain, bloating and nausea, ranging from 0 to 4. Symptom severity is evaluated using 5-point Likert-type scales (none, mild, moderate, severe, and very severe). Higher scores indicate more severe symptoms. Results are reported as LS mean change from run-in at Weeks 8, 14 and 20, determined using a linear MMRM analysis. A negative change from run-in indicates improvement.",
   "timeFrame": "Run-in (Visit 2 at Week -4), Weeks 8, 14, and 20"
  },
  {
   "measure": "Fold Change in Plasma Interleukin-2 (IL-2) From Run-in (Visit 2) to Day 15, and Weeks 8, 14, and 20",
   "description": "The pre-gluten to 4 hours post-gluten challenge log transformed fold change in plasma IL-2 from Run-in (Visit 2) to Day 15, and Weeks 8, 14, and 20 were compared. Results are reported as LS mean change from run-in at Day 15, Weeks 8, 14 and 20, determined using a linear MMRM analysis.",
   "timeFrame": "Run-in (Visit 2 at Week -4), Week 2 (Day 15), and Weeks 8, 14, and 20"
  },
  {
   "measure": "Fold Change in Plasma IL-2 at Specified Time Points",
   "description": "The pre-gluten to 4 hours post-gluten challenge log-transformed fold change in plasma IL-2 at each of the time points is reported.",
   "timeFrame": "Run-in (Visit 2 at Week -4), Week 2 (Day 15), and Weeks 8, 14, and 20"
  },
  {
   "measure": "Plasma Concentration of TAK-101 After Each Dose",
   "description": "Free gliadin concentration in the plasma was measured and reported.",
   "timeFrame": "At end of infusion of Weeks 0, 1 and 24"
  },
  {
   "measure": "Serum Concentration of Antidrug Antibody (ADAs) to Various Doses of TAK-101",
   "description": "ADA includes deamidated gliadin peptide- immunoglobulin G (DGP- IgG). Serum Concentration of ADAs was measured in Enzyme-Linked ImmunoAssay Units per milliliter denoted as EliA U/mL.",
   "timeFrame": "Predose at Weeks 1 and 24; and before gluten challenge at Weeks 2, 14, and 20"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1. Biopsy-confirmed CeD that is well-controlled, defined as mild or with no ongoing signs or symptoms felt to be related to active CeD and with immunoglobulin A (IgA) tissue transglutaminase (tTG) \\<2 × upper limit of normal (ULN) and IgG deamidated gliadin peptide (DGP) \\<3 × ULN.\n\n   Note: Participants may be retested for IgA tTG and IgG DGP to meet eligibility criteria at the discretion of the investigator. Intermittent symptoms would not exclude participants from participation as long as symptoms are generally well controlled in the opinion of the investigator, and as long as symptoms are back to baseline for 2 weeks before the run-in gluten challenge.\n2. Must be able to maintain a gluten-free diet (GFD) for ≥6 months.\n3. Must be HLA-DQ2.5 and/or HLA-DQ8 positive during screening laboratory testing.\n\nExclusion Criteria:\n\n1. Has received any investigational compound within 12 weeks (84 days) or 5 half-lives, whichever is longer, before signing of the informed consent form (ICF).\n2. Has received TAK-101 in a previous clinical study.\n3. Has presence of other inflammatory gastrointestinal (GI) disorders or systemic autoimmune diseases, that either have the potential to cause persistent GI symptoms similar to CeD or are not well controlled without the use of excluded medications.\n\n   * Examples of conditions that are exclusionary include: inflammatory bowel disease, eosinophilic gastroenteritis or colitis, and microscopic colitis requiring treatment in the 6 months before screening.\n   * Examples of conditions that may be permissible after discussion with the medical monitor/or sponsor include: systemic autoimmune disease such as scleroderma, psoriatic or rheumatoid arthritis, lupus that is stable and without GI involvement, well controlled autoimmune thyroid disease, well controlled type 1 diabetes or proton pump inhibitor -responsive eosinophilic esophagitis in symptomatic and histologically confirmed remission.\n4. Has known or suspected refractory CeD or ulcerative jejunitis.\n5. Has known or suspected allergy to wheat, such as hypersensitivity and/or anaphylaxis including wheat-dependent-exercise induced anaphylaxis (WDEIA). If there is a possible history of urticaria, angioedema, or anaphylaxis to wheat, investigators should perform testing for wheat anti-Immunoglobulin (anti-IgE) antibodies or refer to an allergist for evaluation prior to enrollment to rule out any of these allergies.\n6. Ongoing systemic immunosuppressant, systemic (oral or IV) corticosteroid treatment, or has received treatment with systemic immunosuppressants or corticosteroids in the 12 weeks before run-in gluten challenge.\n7. Has known or suspected clinically significant liver disease or positive test result for hepatitis B or C.\n8. Has intolerable symptoms after the run-in gluten challenge and is unwilling to undergo subsequent post treatment gluten challenges.\n9. Has known allergy to or intolerance of TAK-101 or any of its ingredients or excipients. Also, any subject with a symptomatic allergic reaction that is confirmed by laboratory serology such as elevated tryptase levels following the administration of TAK-101 will be excluded from future dosing.\n10. Has a current diagnosis of active malignancy or malignancy diagnosed in the 5 years prior to screening or is receiving ongoing treatment for malignancy.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "75 Years"
 },
 "siteCount": 48,
 "countries": [
