{
 "nctId": "NCT03048942",
 "briefTitle": "Pilot Study of Cabazitaxel and Paclitaxel in HER2 Negative Breast Cancer",
 "officialTitle": "A Randomised Phase II Pilot Study of 3 Weekly Cabazitaxel Versus Weekly Paclitaxel Chemotherapy in the First Line Treatment of HER2 Negative Breast Cancer",
 "leadSponsor": {
  "name": "University Hospitals Bristol and Weston NHS Foundation Trust",
  "class": "OTHER"
 },
 "startDate": "2014-12-18",
