  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "NONE"
  }
 },
 "enrollment": 158,
 "briefSummary": "90 patients with HER2 negative breast cancer will be randomised to receive 18 weeks of chemotherapy treatment, either 6 cycles of 3 weekly Cabazitaxel or 6 cycles of weekly Paclitaxel to determine the difference in progression free survival between the 2 groups. If results at that stage suggest a potential benefit then the trial will be developed further to accrue 70 more patients.",
 "detailedDescription": "This is a prospective multicentre, randomised, open label, study comparing the efficacy and the safety of six 3-weekly cycles cabazitaxel versus 18 x weekly paclitaxel given as first line chemotherapy treatment in patients with HER2-normal metastatic breast cancer. Randomisation will be conducted by a 1:1 ratio.",
 "arms": [
  {
   "label": "Cabazitaxel",
   "type": "EXPERIMENTAL",
   "description": "6 cycles of cabazitaxel intravenous chemotherapy 25mg/m2 on day 1 of each 21 day cycle",
   "interventionNames": [
    "Drug: Cabazitaxel"
   ]
  },
  {
   "label": "Paclitaxel",
   "type": "ACTIVE_COMPARATOR",
   "description": "6 cycles of Paclitaxel intravenous chemotherapy 80mg/m2 on days 1,8 and 15 of each 21 day cycle.",
   "interventionNames": [
    "Drug: Paclitaxel"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Cabazitaxel",
   "description": "3 weekly cyctotoxic chemotherapy",
   "armGroupLabels": [
    "Cabazitaxel"
   ],
   "otherNames": [
    "Jevtana"
   ]
  },
  {
   "type": "DRUG",
   "name": "Paclitaxel",
   "description": "Weekly cyctotoxic chemotherapy",
   "armGroupLabels": [
    "Paclitaxel"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Progression Free Survival",
   "description": "Duration of progression free survival",
   "timeFrame": "Defined as the time from randomisation to either disease progression or death from any cause, whichever came first, assessed up to 5 years."
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Clinical Benefit Rate",
   "description": "Defined as stable disease rate + partial response rate+complete response rate according to RECIST 1.1 criteria",
   "timeFrame": "At the completion of 6 cycles of chemotherapy, which is after 18 weeks"
  },
  {
   "measure": "Objective Response Rate",
   "description": "Objective response rate (ORR) is defined as complete response (CR) plus partial response (PR) as per Response Evaluation Criteria In Solid Tumors Criteria (RECIST v1.1) for target lesions and assessed by CT scan every 6 weeks. Tumours were assessed at baseline and compared to the response seen at the completion of treatment. Only responses seen within the 6 cycles of treatment e.g. up to and including the end of treatment tumour assessment are included in this measure.\n\nCR - Disappearance of all target lesions; PR \\>=30% decrease in the sum of the longest diameter of target lesions.",
   "timeFrame": "At completion of 6 cycles of chemotherapy, which is after 18 weeks."
  },
  {
   "measure": "Overall Survival",
   "description": "Survival duration from randomisation to date of death.",
   "timeFrame": "Determined as the time from randomisation to death from any cause. Average survival rates for this population may be approximately 18 months."
  },
  {
   "measure": "Time to Next Chemotherapy Treatment",
   "description": "time from randomisation to another chemotherapy treatment after confirmed progression.",
   "timeFrame": "Measured from from the date of the last day of trial treatment. approximately after progression which on average would be after 12 months."
  },
  {
   "measure": "Time to Response",
   "description": "Time taken for tumour burden to respond to treatment",
   "timeFrame": "Determined by time from randomisation to radiological partial response. This was sometimes seen after treatment end but all responses occurred by 8 months from randomisation therefore within 32 weeks."
  },
  {
   "measure": "Assessment of EQ-5D-5L Questionnaire",
   "description": "EQ-5D-5L will be assessed at baseline, prior to cycle 3 and cycle 5 and at the end of treatment. The patients answer 5 questions which have 5 possible answers from no issue to extreme issue. The answers are given a code, 1, 2, 3, 4 or 5 with 1 for no issue through to 5 for extreme issues which results in a 5 digit 'health state' for that time point. Using a formula this is translated into the 'EQ-5D index value' where 1 is full health and 0 is the worst health. This is what is presented here, the lower the score the worse the quality of life.",
   "timeFrame": "EQ5D-5L and FACT B will be completed at baseline, prior to cycle 3 (approximately Day 63), prior to cycle 5 (approximately Day 105) and at the end of treatment visit, (approximately 21 weeks)"
  },
  {
   "measure": "Assessment of EQ-5D-5L VAS Score",
   "description": "EQ-5D-5L VAS score was assessed at baseline, prior to cycle 3 and 5 and at the end of treatment. Patients are asked to score their health on a scale 0-100, the higher the score the better they are feeling.",
   "timeFrame": "EQ5D-5L and FACT B will be completed at baseline, prior to cycle 3 (approximately Day 63), prior to cycle 5 (approximately Day 105) and at the end of treatment visit, (approximately 21 weeks)"
  },
  {
   "measure": "Assessment of FACT-B Questionnaire",
   "description": "FACT-B will be assessed at baseline, prior to cycle 3 and cycle 5 and at the end of treatment. The patients answer 37 questions which have 5 possible answers from not at all to very much. The answers are given a code, 0, 1, 2, 3 or 4 with 0 for not at all through to 4 for very much. The scores are reversed and then totalled to give a value out of 148. This is what is presented here, the higher the score the better the quality of life.",
   "timeFrame": "EQ5D-5L and FACT B will be completed at baseline, prior to cycle 3 (approximately Day 63), prior to cycle 5 (approximately Day 105) and at the end of treatment visit, (approximately 21 weeks)"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Written informed consent\n* Metastatic breast cancer fit to receive cytotoxic chemotherapy for metastatic disease\n* Measurable disease as per RECIST 1.1\n* HER2 negative defined as ICH 0+, 1+ or 2+ and FISH/SISH/CISH(ration\\<2.0) in the case of IHC 2+\n* ECOG performance status 0 or 1\n* ER+ve or ER-ve\n* Female age ≥18 years\n* Anticipated life expectancy \\> 6 months\n* Haemoglobin \\>10.0g/DL\n* Absolute neutrophil count\\>1.5 x 10\\^9/L\n* Platelet count\\>100 x 10\\^9/L\n* ALT/SGPT\\<1.5 X ULN\n* Serum creatinine \\<1.5 x ULN\n* Negative pregnancy test for all women of child bearing potential\n\nExclusion Criteria:\n\n* Grade ≥2 oral mucositis or peripheral or sensory neuropathy\n* History of other malignancy\n* History of severe hypersensitivity ≥grade 3 to polysorbate 80- containing drugs and taxanes\n* Clinically significant cardiovascular disease\n* Any acute or chronic medical condition\n* Acute infection requiring systemic antibiotics or antifungal medication\n* Sex hormones\n* Administration of any live vaccine within 8 weeks\n* Concurrent or planned treatment with strong inhibitors or strong inducers of cytochrome P450 3A4/5\n* Participation in another clinical trial with an investigational drug within 30 days of randomisation\n* Pregnant or breast feeding women\n* Contraindications to the use of corticosteroid treatment\n* HER2 Positive breast cancer\n* Previous Paclitaxel chemotherapy in the adjuvant setting\n* Previous cytotoxic chemotherapy for metastatic disease\n* Palliative radiotherapy for metastatic disease within 4 weeks of randomisation\n* Symptomatic brain metastases confirmed with CT/MRI brain\n* History of other malignancy\n* Grade 2",
  "healthyVolunteers": false,
  "sex": "FEMALE",
  "minimumAge": "18 Years",
  "maximumAge": "99 Years"
 },
 "siteCount": 13,
 "countries": [
  "United Kingdom"
 ]
}

