forecastInput:
{
 "nctId": "NCT06074562",
 "briefTitle": "A Study of LY3556050 in Adult Participants With Diabetic Peripheral Neuropathic Pain",
 "officialTitle": "A Phase 2, Randomized, Double-Blind, Placebo Controlled, Dose-Ranging Study to Evaluate LY3556050 in Adult Participants With Diabetic Peripheral Neuropathic Pain",
 "leadSponsor": {
  "name": "Eli Lilly and Company",
  "class": "INDUSTRY"
 },
 "startDate": "2023-10-05",
 "firstRegistered": "2023-10-03",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Diabetic Peripheral Neuropathy"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "DOUBLE",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 404,
 "briefSummary": "The main purpose of this study is to determine the safety and efficacy of LY3556050 versus placebo in participants with diabetic peripheral neuropathic pain (DPNP). The study will lasts approximately 24 weeks, across 3 study periods.",
 "arms": [
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Participants received a matching dose of placebo administered orally twice daily (BID) over a period of 12 weeks.",
   "interventionNames": [
    "Drug: Placebo"
   ]
  },
  {
   "label": "Mazisotine 50 mg",
   "type": "EXPERIMENTAL",
   "description": "Participants received mazisotine 50 milligrams (mg) administered orally BID over a period of 12 weeks.",
   "interventionNames": [
    "Drug: Mazisotine"
   ]
  },
  {
   "label": "Mazisotine 200 mg",
   "type": "EXPERIMENTAL",
   "description": "Participants received mazisotine BID orally, starting at 50 mg and titrated weekly, reaching 100 mg BID by Week 2 and a target maintenance dose of 200 mg BID by Week 3, which was then maintained up to Week 12.",
   "interventionNames": [
    "Drug: Mazisotine"
   ]
  },
  {
   "label": "Mazisotine 400 mg",
   "type": "EXPERIMENTAL",
   "description": "Participants received mazisotine BID orally, starting at 50 mg and titrated weekly, reaching 100 mg BID by Week 2, 200 mg BID by Week 3, and 300 mg BID by Week 4, until reaching a target maintenance dose of 400 mg BID by Week 5, which was then maintained up to Week 12.",
   "interventionNames": [
    "Drug: Mazisotine"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Mazisotine",
   "description": "Administered orally.",
   "armGroupLabels": [
    "Mazisotine 200 mg",
    "Mazisotine 400 mg",
    "Mazisotine 50 mg"
   ],
   "otherNames": [
    "LY3556050"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "Administered orally.",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Mean Change From Baseline in Average Pain Intensity (API) as Measured by Weekly Average of Numeric Rating Scale (NRS) - Bayesian Model Averaging (BMA) Dose-response Model",
   "description": "* The NRS was a single-item numeric scale used to describe pain severity. Participants were asked to rate their average pain over the past 24 hours, on a scale of 0 to 10: 0 = no pain, and 10 = pain as bad as you can imagine; a higher score indicates worse outcome (greater pain severity).\n* The mixed-model repeated measures (MMRM) model included the fixed, centered, categorical effects of region, baseline NRS average pain score, as well as concurrent use of allowed concomitant medications (yes vs. no based on interactive web response system \\[IWRS\\]), and visit. The adjusted dose response value from the MMRM was used for fitting a Bayesian model averaging (BMA) dose-response model.\n* Posterior mean change from baseline, 95 percent (%) credible interval was derived using Bayesian mixed model repeated measures. Data presented were posterior mean with 95% credible interval.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Mean Change From Baseline in Average Pain Intensity (API) as Measured by Weekly Average of Numeric Rating Scale (NRS) - Frequentist Repeated Measures (FRM) Analysis",
   "description": "* The NRS was a single-item numeric scale used to describe pain severity. Participants were asked to rate their average pain over the past 24 hours, on a scale of 0 to 10: 0 = no pain, and 10 = pain as bad as you can imagine; a higher score indicates worse outcome (greater pain severity).\n* The Least Squares (LS) Mean was calculated using a frequentist repeated measures (FRM) analysis, where Change = treatment, time interval, treatment \\* time interval, region, average baseline pain severity category (mild or moderate versus \\[vs.\\] severe), concurrent use of allowed concomitant medication as entered in IWRS (yes versus no).",
   "timeFrame": "Baseline, Week 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Mean Change From Baseline in Worst Pain Intensity (WPI) as Measured by Weekly Average of Numeric Rating Scale (NRS)",
   "description": "* The NRS was a single-item numeric scale used to describe pain severity. Participants were asked to rate their worst pain intensity over the past 24 hours, on a scale of 0 to 10: 0 = no pain, and 10 = pain as bad as you can imagine; a higher score indicates worse outcome (greater pain severity).\n* The LS Mean was calculated using an FRM analysis, where Change = treatment, time interval, treatment \\* time interval, region, average baseline pain severity category (mild or moderate versus severe), concurrent use of allowed concomitant medication (yes versus no based on IWRS).",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Mean Change From Baseline in Patient-Reported Outcomes Measurement Information System Pain Interference Short Form 8a (PROMIS PI SF8a)",
   "description": "The Patient-Reported Outcomes Measurement Information System Pain Interference Short Form 8a (PROMIS PI SF8a) was administered to measure self-reported consequences of pain on various aspects of the participant's life within the previous 7 days. The scale consists of 8 items, all measuring a single domain of pain interference, including impact on day-to-day activities, work around the home, household chores, family life, social activities, activities done for fun, enjoyment of social activities, and enjoyment of life. Each item was rated on a 5-point response scale ranging from \"not at all\" (1) to \"very much\" (5); the 8 item scores were summed to produce a raw score ranging from 8 (minimum) to 40 (maximum). The raw score was then converted to a T-score with a mean of 50 and a standard deviation of 10; higher T-scores indicate worse outcome (greater pain interference). Range cannot be specified in norm-based scores.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Mean Change From Baseline in Pain Interference With Sleep",
   "description": "* Pain Interference with Sleep was assessed using a single-item measure: \"To what extent did diabetic nerve pain interfere with your sleep last night?\" Participants responded on a scale from 0 (minimum, \"Not at all\") to 4 (maximum, \"Unable to sleep at all\"); higher scores indicate worse outcome (greater sleep interference due to pain).\n* LS Mean was calculated using an FRM analysis, where Change = treatment, time interval, treatment \\* time interval, region, average baseline pain severity category (mild or moderate vs. severe), concurrent use of concomitant medication (yes vs. no based on IWRS).",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Mean Change From Baseline in Patient-Reported Outcomes Measurement Information System Physical Functioning Short Form 10a (PROMIS PF SF10a)",
   "description": "The PROMIS PF SF10a was administered to assess self-reported physical function and physical activities across 10 items at the present time.The first 5 items assess current physical limitations (health in doing vigorous activities, walking more than one mile, climbing stairs, lifting or carrying groceries, and bending, kneeling, or stooping), each rated on a 5-point Likert scale ranging from \"not at all\" to \"cannot do\". The remaining 5 items are self-reported ability to perform specific physical activities such as chores,dressing themselves, bathing,sitting on and getting up from the toilet, each rated on a 5-point likert scale ranging from \"without any difficulty\" to \"unable to do\". The 10 item scores were summed to produce a raw score ranging from 10 (minimum) to 50 (maximum).The raw score was then converted to a T-score with a mean of 50 and a standard deviation of 10; higher T-scores indicate better outcome (greater physical function).Range cannot be specified in norm-based scores.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Mean Change From Baseline in Patient-Reported Outcomes Measurement Information System Sleep Disturbance Short Form 8b (PROMIS SD SF8b)",
   "description": "The Patient-Reported Outcomes Measurement Information System Sleep Disturbance Short Form 8b (PROMIS SD SF8b) was administered to assess perceptions of sleep quality, sleep depth, and restoration associated with sleep within the previous 7 days, including perceived difficulties and concerns with getting to sleep or staying asleep, and perceptions of the adequacy of and satisfaction with sleep. The scale consists of 8 items, all measuring a single domain of sleep disturbance. Each item was rated on a 5-point response scale ranging from \"not at all\" to \"very much,\" \"never\" to \"always,\" or \"very poor\" to \"very good\"; the 8 item scores were summed to produce a raw score ranging from 8 (minimum) to 40 (maximum). The raw score was then converted to a T-score with a mean of 50 and a standard deviation of 10; higher T-scores indicate worse outcome (greater sleep disturbance). Range cannot be specified in norm-based scores.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Mean Change From Baseline in Patient's Global Impression of Illness Severity as Measured by Patient's Global Impression-Severity (PGI-Severity)",
   "description": "* The Patient's Global Impression-Severity (PGI-Severity) is a patient-reported single-item instrument designed to assess the participant's severity of diabetic nerve pain over the past week. The single item is rated on a 5-point Likert scale ranging from 1 (minimum, \"very severe\") to 5 (maximum, \"none\"); higher scores indicate better outcome (less pain severity).\n* The LS Mean was calculated using an FRM analysis, where Change = treatment, time interval, treatment \\* time interval, region, average baseline pain severity category (mild or moderate vs. severe), concurrent use of allowed concomitant medication (yes vs. no based on IWRS).",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Mean Change From Baseline in Patient's Global Impression (PGI) of Illness Status as Measured by PGI-Status",
   "description": "The Patient's Global Impression-Status (PGI-Status) is a patient-reported single-item instrument designed to assess the participant's status with diabetic nerve pain. Three PGI-Status scales were administered to assess physical activity, usual activity, and sleep disturbance. For physical activity, participants rated their status at the present time; for usual activity and sleep disturbance, participants rated their overall status over the past week. Physical activity and usual activity were each rated on a 5-point Likert scale ranging from 1 (minimum, \"extremely limited\") to 5 (maximum, \"not at all limited\"); higher scores indicate better outcome (less limitation). Sleep disturbance was rated on a 5-point Likert scale ranging from 1 (minimum, \"very much\") to 5 (maximum, \"not at all\"); higher scores indicate better outcome (less sleep disturbance).",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Patient's Global Impression of Change as Measured by Patient's Global Impression-Change (PGI-Change)",
   "description": "The Patient's Global Impression-Change (PGI-Change) is a patient-reported single-item instrument designed to assess the participant's rating of change in diabetic nerve pain since they began taking the study medication. Four PGI-Change scales were administered to assess diabetic nerve pain's impact on physical activities, usual activities, sleep disturbance, and overall change. Each item was rated on a 5-point Likert scale ranging from 1 (minimum, \"much worse\") to 5 (maximum, \"much better\"); higher scores indicate better outcome (greater improvement).",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Mean Change From Baseline in Neuropathy Total Symptom Score-6 (NTSS-6)",
   "description": "The NTSS-6 assessed the frequency and intensity of 6 diabetic peripheral neuropathic symptoms over the previous 7 days: (1) numbness and/or insensitivity, (2) prickling and/or tingling sensation, (3) burning sensation, (4) aching pain and/or tightness, (5) sharp, shooting, lancinating pain, and (6) allodynia and/or hyperalgesia. Each of the 6 symptoms was rated on two separate response scales: an intensity scale (Does not apply \\[0\\], Mild \\[1\\], Moderate \\[2\\], or Severe \\[3\\]) and a frequency scale (Never \\[0\\], Occasionally, less than 1/3 of the time \\[0\\], Often, 1/3 to 2/3 of the time \\[0.33\\], or Almost always, more than 2/3 of the time \\[0.66\\]). The total score was calculated as the weighted sum across all 6 symptoms, where intensity was given a weight of 1 and frequency was given a weight of 1/3, yielding a total score ranging from 0 (minimum, no symptoms) to 21.96 (maximum, most severe); higher scores indicate worse outcome (greater neuropathic symptom burden).",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Total Amount of Rescue Medication Use as Measured by Average Daily Dosage",
   "description": "Acetaminophen was used as rescue medication during the treatment period. The total amount of rescue medication use was summarized as the average daily dosage at Week 12.",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Percentage of Participants With at Least One Use of Rescue Medication",
   "description": "Acetaminophen was used as rescue medication during the treatment period. The percentage of participants with at least one use of rescue medication at Week 12 was reported.",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Pharmacokinetics (PK): Plasma Concentration of Mazisotine",
   "description": "Mazisotine plasma concentration was reported. The Measure Type was Median and the Measure of Dispersion/Precision was Inter-Quartile Range, where the lower and upper limits represented the 5th and 95th percentiles, respectively.",
   "timeFrame": "Postdose at Week 12"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Have a history and current diagnosis of Type 1 Diabetes (T1D) or Type 2 Diabetes (T2D) diagnosed for at least 6 months prior to screening.\n* Have a stable glycemic control on stable diabetes treatment regimen for at least 90 days prior to day 1 with a hemoglobin A1c (HbA1c) ≤10 for T1D and HbA1c ≤11 for participants with T2D at time of screening.\n* Have a history of daily peripheral neuropathic pain for at least 12 weeks based on participant report or medical history.\n* Have a visual analog scale (VAS) pain value ≥40 and \\<95 during screening.\n* Have presence of diabetic peripheral neuropathy of symmetrical nature and in lower extremities for ≥6 months and diagnosed by a score of Part B ≥3 on Michigan Neuropathy Screening Instrument\n* Are willing to maintain a consistent regimen of any ongoing nonpharmacologic pain-relieving therapies (for example, physical therapy) and will not start any new nonpharmacologic pain-relieving therapies during study participation.\n* Are willing to discontinue all medications taken for chronic pain conditions, except allowed concomitant pain medication permitted per protocol, for the duration of the study\n\n  * Have a body mass index ≤45 kilogram/square meter (kg/m²) (inclusive).\n  * Are men, or women able to abide by reproductive and contraceptive requirements.\n\nExclusion Criteria:\n\n* History of other potentially causative and/or confounding sources of pain that may impair self-assessment of pain due to DPNP.\n* Have had a procedure within the past 6 months intended to produce permanent sensory loss in the target area of interest (for example, ablation techniques.\n* Have had cancer within 2 years of baseline, except for cutaneous basal cell or squamous cell carcinoma resolved by excision.\n* Are, in the judgment of the investigator, actively suicidal and therefore deemed to be at significant risk for suicide.\n* Have in the judgement of the investigator, an acute, serious, or unstable medical condition or a history or presence of any other medical illness that would preclude study participation.\n* Have a positive HIV test result at screening.\n* Have a surgery planned during the study for any reason.\n* Have a substance use disorder as defined by the Diagnostic and Statistical Manual of Mental Disorders (5th edition; DSM-5; American Psychiatric Association)",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years"
 },
 "siteCount": 70,
 "countries": [
  "United States",
  "Czechia",
  "Japan",
  "Poland",
  "South Korea"
 ]
}

