{
 "nctId": "NCT06362759",
 "briefTitle": "A Study to Evaluate TOUR006 in Patients With Chronic Kidney Disease and Elevated Hs-CRP",
 "officialTitle": "A Phase 2, Randomized, Double-Blind, Placebo-Controlled Study to Evaluate Quarterly and Monthly TOUR006 in Participants With Chronic Kidney Disease and Elevated High-Sensitivity C-Reactive Protein",
 "leadSponsor": {
  "name": "Tourmaline Bio, Inc., a Novartis Company",
  "class": "INDUSTRY"
 },
 "startDate": "2024-05-15",
