   ]
  }
 },
 "enrollment": 143,
 "briefSummary": "This study will evaluate the safety, tolerability, pharmacokinetics, and CRP-lowering effect of quarterly and monthly subcutaneous administration of TOUR006 (also known as pacibekitug) in participants with chronic kidney disease and elevated hs-CRP.",
 "detailedDescription": "Previous clinical studies have suggested that IL-6-driven inflammation plays a key role in the pathogenesis of cardiovascular diseases including atherosclerotic cardiovascular disease (ASCVD) and heart failure. This Phase 2 study will evaluate the safety, tolerability, pharmacokinetics, and CRP-lowering effect of quarterly and monthly subcutaneous administration of TOUR006, a fully human monoclonal antibody against IL-6. TOUR006 binds the IL-6 cytokine and inhibits downstream IL-6 signaling, thereby reducing the pharmacodynamic marker, hs-CRP.",
 "arms": [
  {
   "label": "TOUR006 - 50 MG",
   "type": "EXPERIMENTAL",
   "description": "50 mg administered subcutaneously at Day 1 and Day 90 (Placebo administered at 30, 60, 120, and 150 Day timepoints)",
   "interventionNames": [
    "Drug: TOUR006 - 50 MG"
   ]
  },
  {
   "label": "TOUR006 - 25 MG",
   "type": "EXPERIMENTAL",
   "description": "25 mg administered subcutaneously at Day 1 and Day 90 (Placebo administered at 30, 60, 120, and 150 Day timepoints)",
   "interventionNames": [
    "Drug: TOUR006 - 25 MG"
   ]
  },
  {
   "label": "TOUR006 - 15 MG",
   "type": "EXPERIMENTAL",
   "description": "15 mg administered subcutaneously at Days 1, 30, 60, 90, 120, and 150",
   "interventionNames": [
    "Drug: TOUR006 - 15 MG"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Administered subcutaneously at Days 1, 30, 60, 90, 120, and 150",
   "interventionNames": [
    "Other: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "TOUR006 - 50 MG",
   "description": "TOUR006 50 MG",
   "armGroupLabels": [
