 ],
 "primaryOutcomes": [
  {
   "measure": "Time-Averaged Percent Change From Baseline in High-Sensitivity C-Reactive Protein (Hs-CRP) Through Day 90",
   "description": "Time-averaged percent change from baseline in high-sensitivity C-reactive protein (hs-CRP) through Day 90. The time-averaged percent change from baseline in hs-CRP is the area under the curve for percent change from baseline in hs-CRP divided by the number of days from the observed Day 30 to Day 90 visits (approximately 60 days if visits occur according to the protocol). The calculation uses the linear trapezoidal rule according to the observed visit days.",
   "timeFrame": "Baseline through 90 days. Baseline is defined as the average of the last two available visits prior to study treatment administration."
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Proportion of Participants With Time-averaged Hs-CRP < 2 mg/L (90 Days)",
   "description": "Proportion of participants with time-averaged hs-CRP \\< 2 mg/L (90 Days)",
   "timeFrame": "Baseline through 90 days. Baseline is defined as the average of the last two available visits prior to study treatment administration."
  },
  {
   "measure": "Time-Averaged Percent Change From Baseline in High-Sensitivity C-Reactive Protein (Hs-CRP) Through Day 180",
   "description": "Time-averaged percent change from baseline in high-sensitivity C-reactive protein (hs-CRP) through Day 180. The time-averaged percent change from baseline in hs-CRP is the area under the curve for percent change from baseline in hs-CRP divided by the number of days from the observed Day 30 to Day 180 visits (approximately 150 days if visits occur according to the protocol). The calculation uses the linear trapezoidal rule according to the observed visit days.",
   "timeFrame": "Baseline through 180 days. Baseline is defined as the average of the last two available visits prior to study treatment administration."
  },
  {
   "measure": "Evaluate the Pharmacokinetics by Measuring Serum Concentrations of TOUR006",
   "description": "Mean trough serum concentrations (ng/mL) of TOUR006 at Days 30, 60, 90,120, 150, 180, 240, 300, and 365. On dosing visits (BL and Day 30, 60, 90, 120, and 150 visits), PK samples were collected pre-dose. PK blood samples were collected on Study Days 180, 240, 300, and 365 at approximately the same time as the pre-dose samples were collected on previous dosing visits.",
   "timeFrame": "Baseline through Day 365"
