  }
 },
 "enrollment": 203,
 "briefSummary": "Researchers are looking for a way to treat classical Hodgkin lymphoma (cHL) that is relapsed (the cancer has come back after treatment) or refractory (current treatment has stopped working to slow or stop cancer growth). Researchers want to learn if people who receive coformulated favezelimab/pembrolizumab (MK-4280A) live longer without the cancer getting worse compared to those who receive chemotherapy.",
 "arms": [
  {
   "label": "Favezelimab/Pembrolizumab",
   "type": "EXPERIMENTAL",
   "description": "Participants will receive coformulated favezelimab/pembrolizumab (800 mg/200 mg) by intravenous (IV) infusion on Day 1, then every three weeks (Q3W), for up to 35 infusions.",
