   ]
  },
  {
   "label": "Chemotherapy (Bendamustine or Gemcitabine)",
   "type": "ACTIVE_COMPARATOR",
   "description": "Participants will receive physician's choice of EITHER bendamustine by IV infusion at a dose between 90 and 120 mg/m\\^2 on Day 1 and Day 2 of either a 3- or 4-week cycle for up to 6 cycles OR gemcitabine by IV infusion at a dose between 800 and 1200 mg/m\\^2 on Day 1 and Day 8 of a 3-week cycle for up to 6 cycles.",
   "interventionNames": [
    "Drug: bendamustine",
    "Drug: gemcitabine"
   ]
  }
 ],
 "interventions": [
