 "primaryOutcomes": [
  {
   "measure": "Progression Free Survival (PFS) Per Lugano Response Criteria as Assessed by Investigator",
   "description": "PFS was defined as the time from randomization to the first documented disease progression per Lugano criteria 2014 as assessed by investigator or death due to any cause, whichever occurred first. Progressive disease was defined as uptake moderately or markedly higher than the liver with an increase in overall uptake compared with nadir, and/or the appearance of new lesions consistent with lymphoma.",
   "timeFrame": "Up to approximately 34 months"
