 ],
 "secondaryOutcomes": [
  {
   "measure": "Overall Survival (OS)",
   "description": "OS was defined as the time from randomization to death due to any cause.",
   "timeFrame": "Up to approximately 34 months"
  },
  {
   "measure": "Objective Response Rate (ORR) Per Lugano Response Criteria as Assessed by Investigator",
   "description": "ORR was defined as the percentage of participants who achieved a complete response (CR) or partial response (PR) per Lugano criteria 2014 as assessed by investigator. CR or PR were evaluated using computed tomography (CT) and metabolic imaging (fluorodeoxyglucose-positron emission tomography (FDG-PET)). CR is complete metabolic (no/minimal FDG uptake) and radiologic response (target lesions regress to ≤1.5 cm in longest transverse diameter of a lesion) and no new lesions. PR is partial metabolic (moderate/high FDG uptake) and radiologic response (≥50% decrease in sum of product diameters for multiple lesions of up to 6 target measurable nodes and extranodal sites, no increase in lesions, and spleen regressed by \\>50% in length beyond normal).",
   "timeFrame": "Up to approximately 34 months"
  },
  {
   "measure": "Duration of Response (DOR) Per Lugano Response Criteria as Assessed by Investigator",
   "description": "For participants who demonstrated CR or PR per Lugano criteria 2014 as assessed by investigator, DOR was defined as the time from the first documented evidence of CR or PR until disease progression or death due to any cause, whichever occurred first. CR or PR were evaluated using computed tomography (CT) and metabolic imaging (fluorodeoxyglucose-positron emission tomography (FDG-PET)). CR is complete metabolic (no/minimal FDG uptake) and radiologic response (target lesions regress to ≤1.5 cm in longest transverse diameter of a lesion) and no new lesions. PR is partial metabolic (moderate/high FDG uptake) and radiologic response (≥50% decrease in sum of product diameters for multiple lesions of up to 6 target measurable nodes and extranodal sites, no increase in lesions, and spleen regressed by \\>50% in length beyond normal).",
   "timeFrame": "Up to approximately 34 months"
  },
  {
   "measure": "Number of Participants Who Experienced At Least One Adverse Event (AE)",
   "description": "An AE was any untoward medical occurrence in a clinical study participant temporally associated with the use of study intervention, whether or not considered related to the study intervention. The number of participants who experienced an AE is presented.",
   "timeFrame": "Up to approximately 28 months"
  },
  {
   "measure": "Number of Participants Who Discontinue Study Treatment Due to an AE",
   "description": "An AE was any untoward medical occurrence in a clinical study participant temporally associated with the use of study intervention, whether or not considered related to the study intervention. The number of participants who discontinued study treatment due to an AE is presented.",
   "timeFrame": "Up to approximately 28 months"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Has histologically confirmed diagnosis of classical Hodgkin lymphoma (cHL) that is 2-fluorodeoxyglucose-avid (FDG-avid).\n* Has relapsed (defined as disease progression after most recent therapy) or refractory (defined as failed to achieve CR or PR to most recent therapy) cHL and exhausted all available treatment options with known clinical benefit.\n* Has progressed on treatment with an anti-PD-(L)1 monoclonal antibody (mAb) administered either as monotherapy or in combination with other checkpoint inhibitors or other therapies.\n* Submits an archival (≤5 years) or newly obtained tumor tissue sample which has not been previously irradiated.\n\nExclusion Criteria:\n\n* Diagnosis of immunodeficiency or is receiving chronic systemic steroid therapy or any other form of immunosuppressive therapy.\n* History of central nervous system (CNS) metastases or active CNS involvement.\n* Has an active autoimmune disease that has required systemic treatment in past 2 years except replacement therapy.\n* History of (noninfectious) pneumonitis/interstitial lung disease that required steroids or has current pneumonitis/interstitial lung disease.\n* Has an active infection requiring systemic treatment.\n* History of hemophagocytic lymphohisticytosis.\n* Has an active seizure disorder that is not well controlled.\n* Has clinically significant (ie, active) cardiovascular disease.\n* Received prior systemic anticancer therapy including investigational agents within 4 weeks before randomization.\n* Received prior radiotherapy within 2 weeks of start of study intervention or radiation related toxicities requiring corticosteroids.\n* Has not adequately recovered from major surgical procedure.\n* Known additional malignancy that is progressing or has required active treatment within the past 3 years.\n* History of human immunodeficiency virus (HIV).\n* Has had an allogeneic hematopoietic stem cell or solid organ transplantation within the last 5 years.",
