forecastInput:
{
 "nctId": "NCT04404283",
 "briefTitle": "Brentuximab Vedotin Plus Lenalidomide and Rituximab for the Treatment of Relapsed/Refractory DLBCL",
 "officialTitle": "A Randomized, Double-blind, Placebo-Controlled, Active-Comparator, Multicenter, Phase 3 Study of Brentuximab Vedotin or Placebo in Combination With Lenalidomide and Rituximab in Subjects With Relapsed or Refractory Diffuse Large B-cell Lymphoma (DLBCL)",
 "leadSponsor": {
  "name": "Seagen, a wholly owned subsidiary of Pfizer",
  "class": "INDUSTRY"
 },
 "startDate": "2020-08-20",
 "firstRegistered": "2020-05-21",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Diffuse Large B-cell Lymphoma"
 ],
 "keywords": [
  "Seattle Genetics"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "TRIPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 240,
 "briefSummary": "Participants in this study will have diffuse large B-cell lymphoma (DLBCL) that has come back or not gotten better with treatment. The trial will study whether brentuximab vedotin plus two drugs works better to treat this type of cancer than the two drugs alone.\n\nParticipants will be randomly assigned to get either brentuximab vedotin or placebo. The placebo will look like brentuximab vedotin, but has no medicine in it. Since the study is \"blinded,\" participants and their doctors will not know whether a participant gets brentuximab vedotin or placebo. All participants in the study will get rituximab and lenalidomide. These are drugs that can be used to treat DLBCL.",
 "arms": [
  {
   "label": "Experimental Arm",
   "type": "EXPERIMENTAL",
   "description": "Brentuximab vedotin + lenalidomide + rituximab",
   "interventionNames": [
    "Drug: Brentuximab vedotin",
    "Drug: Rituximab",
    "Drug: Lenalidomide"
   ]
  },
  {
   "label": "Control Arm",
   "type": "ACTIVE_COMPARATOR",
   "description": "Placebo + lenalidomide + rituximab",
   "interventionNames": [
    "Drug: Rituximab",
    "Drug: Lenalidomide",
    "Other: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Brentuximab vedotin",
   "description": "1.2 mg/kg administered into the vein (IV; intravenously) infusion every 3 weeks",
   "armGroupLabels": [
    "Experimental Arm"
   ]
  },
  {
   "type": "DRUG",
   "name": "Rituximab",
   "description": "375 mg/m\\^2 administered via intravenous infusion on Cycle 1 Day 1. 1400 mg injected under the skin (subcutaneous) permitted every 3 weeks from Cycle 2 Day 1 through end of treatment.",
   "armGroupLabels": [
    "Control Arm",
    "Experimental Arm"
   ]
  },
  {
   "type": "DRUG",
   "name": "Lenalidomide",
   "description": "20 mg given by mouth (orally) daily",
   "armGroupLabels": [
    "Control Arm",
    "Experimental Arm"
   ]
  },
  {
   "type": "OTHER",
   "name": "Placebo",
   "description": "Administered via intravenous infusion every 3 weeks",
   "armGroupLabels": [
    "Control Arm"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Overall Survival (OS)",
   "description": "OS was defined as the time from the date of randomization to the date of death due to any cause. Participants who had not died were censored at the last known alive date or the data cutoff date, whichever was earlier. OS was estimated using the Kaplan-Meier method.",
   "timeFrame": "From the date of randomization until date of death or censoring date, whichever occurred first (maximum up to 50 months)"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Progression-Free Survival (PFS) as Assessed by Investigator Per Lugano 2014",
