 "primaryOutcomes": [
  {
   "measure": "EFFICACY: MATE-3 Score",
   "description": "MATE-3 is a validated score ranging from 0 to 12. The score adds together each subscore so that it represents the cumulative burden of three major adverse transplant events: Cardiac Allograft Vasculopathy (CAV), Chronic Kidney Disease (CKD), and Biopsy-proven Acute Cellular Rejection (ACR). Complete details of the score can be found in the study protocol. A higher score represents a worse outcome.",
   "timeFrame": "30 months post-randomization"
  },
  {
   "measure": "SAFETY: MATE-6 Score",
   "description": "MATE-6 is a validated score ranging from 0 to 24. The score adds together each subscore so that it represents the cumulative burden of all six major adverse transplant events: Coronary Artery Vasculopathy (CAV), Chronic Kidney Disease (CKD), Biopsy-proven Acute Cellular Rejection (ACR), pathologic diagnosis of Antibody-Mediated Rejection (AMR), Infection, and Post-Transplant Lymphoproliferative Disorder (PTLD). Complete details of the score can be found in the study protocol. A higher score represents a worse outcome.",
