{
 "nctId": "NCT01245569",
 "briefTitle": "A Study in Patients With Chronic Obstructive Pulmonary Disease",
 "officialTitle": "A 12-week, Multicentre, Multinational, Randomized, Double-blind, Double-dummy, 2-arm Parallel Group Study Comparing the Efficacy and Safety of Foster® 100/6 (Beclomethasone Dipropionate 100 µg Plus Formoterol 6 µg/Actuation), 2 Puffs b.i.d., Versus Seretide® 500/50 (Fluticasone 500 µg Plus Salmeterol 50 µg/Actuation), 1 Inhalation b.i.d., in Patients With Chronic Obstructive Pulmonary Disease",
