   "type": "PROCEDURE",
   "name": "MRI carotid",
   "description": "To assess the carotid atherosclerotic plaques",
   "armGroupLabels": [
    "Hydroxychloroquine (HCQ) Group",
    "Placebo Group"
   ],
   "otherNames": [
    "Carotid MRI"
   ]
  },
  {
   "type": "PROCEDURE",
   "name": "APWV",
   "description": "Doppler measurement of the APWV",
   "armGroupLabels": [
    "Hydroxychloroquine (HCQ) Group",
    "Placebo Group"
   ],
   "otherNames": [
    "aortic pulse wave velocity, pulse wave velocity, vascular stiffness"
   ]
  },
  {
   "type": "DRUG",
   "name": "Hydroxychloroquine",
   "description": "Active Drug",
   "armGroupLabels": [
    "Hydroxychloroquine (HCQ) Group"
   ],
   "otherNames": [
    "HCQ, Chloroquine"
   ]
  },
  {
   "type": "DRUG",
   "name": "Matching Placebo",
   "description": "Matching Placebo for the control group.",
   "armGroupLabels": [
    "Placebo Group"
   ],
   "otherNames": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Total Plaque Volume (TPV), Carotid",
   "description": "Measurements of Carotid TPV at enrollment and serially over 18th months",
   "timeFrame": "Baseline, 9 months, 18 months"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "High Sensitivity C-Reactive Protein (hsCRP)",
   "description": "Measurements of hsCRP at enrollment and serially over 18 months",
   "timeFrame": "Baseline, 9 months, 18 months"
  },
  {
   "measure": "Aortic Pulse Wave Velocity (APWV)",
   "description": "Measurements of APWV at enrollment and serially over 18 months",
   "timeFrame": "Baseline, 9 months, 18 months"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Veteran\n* Age 18-80 years;\n* Moderate to severe CKD at the time of screening, defined as one of the following: 1) Stage 3b or 4 CKD with latest eGFR of 25-59, with diabetes mellitus, OR 2) Stage 3b or 4 CKD with latest eGFR of 25 to 45 mL/min and maximum recorded albuminuria defined as urine albumin/creatinine ratio (UACR) of 30 mg/g, OR 3) Stage 3a CKD with eGFR 46-59 ml/min with urine albumin/creatinine (UACR) 100 mg/gm\n\nExclusion Criteria:\n\n* G6PD deficiency or known hypersensitivity to 4-aminoquinoline\n* Conventional contraindications for non-contrast MRI examination including\n\n  * Permanent pacemaker\n  * Automatic Implantable Cardioverter Defibrillator\n  * Significant fear of closed space\n  * Claustrophobia that prevents patients from participating\n  * Inability to lie down\n* Abnormal liver functions or diagnosis of cirrhosis\n\n  * AST and ALT more than 1.5 times the normal or INR without being anti-coagulated greater than 1.4\n* History of documented non-adherence to therapy\n\n  * Inability to attend treatment or follow-up scheduling\n* Less than 6 months since initiation of 'Statins'\n* Prior history of any dialysis within last 12 months, or history of diagnosed AKI in the prior three months\n* History of acute cardiovascular event defined as:\n\n  * myocardial infarction\n  * stroke or new diagnosis of congestive heart failure or heart failure related admission in prior 3 months\n* History of prolonged QTc interval 450, For patients with BBB an adjusted QT interval \\>450\n* Known chronic active infections like HIV, Hepatitis B or Hepatitis C positive, chronic osteomyelitis etc.\n* Recent serious infection including requiring hospitalization within 3 months or Recent minor infection such as skin, soft tissue or respiratory infections within 30 days of enrollment\n* Active or recently treated (\\< 1 year in remission) malignancy, transplantation, or systemic inflammatory diseases\n\n  * Patients with localized squamous cell carcinoma of the skin are eligible\n* Use of systemic corticosteroids or other immunosuppression within last 3 months (acute course of steroid for a gouty arthritis or chronic obstructive pulmonary disease is eligible if \\> 1 month ago)\n* Pregnancy, breastfeeding or planning to become pregnant during the course of the study\n* Life expectancy less than 12 months or uncontrolled congestive heart failure (CHF)\n\n  * defined as more than 2 admissions in prior 6 months)\n* Any other condition the PI determines may put the research subject in jeopardy during the course of the study\n* Recent unexplained weight loss or vision changes",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "80 Years"
 },
 "siteCount": 1,
 "countries": [
  "United States"
 ]
}

