{
 "nctId": "NCT03918915",
 "briefTitle": "The Safety and Efficacy of SYD-101 in Children With Myopia",
 "officialTitle": "A Multicenter, Randomized, Double-masked, Vehicle-controlled Study to Assess the Safety and Efficacy of SYD-101 Ophthalmic Solution for the Treatment of Myopia in Children",
 "leadSponsor": {
  "name": "Sydnexis, Inc.",
  "class": "INDUSTRY"
 },
 "startDate": "2019-04-24",
 "firstRegistered": "2019-04-12",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Nearsightedness",
  "Near Sightedness",
  "Near-sightedness"
 ],
 "keywords": [
  "Children",
  "Myopia"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 852,
 "briefSummary": "Myopia, or nearsightedness, is the most common eye disorder, often affecting more than 40% of adults in Europe, Asia and the USA. Severe myopia is associated with an increased risk of developing other eye conditions such as glucoma, cataracts and retinal detachment, which may lead to blindness. Early treatment of myopia in children could help slow the condition and minimize the risk of complications later in life. This study investigates the use of SYD-101, an eye solution, in slowing-down the progression of myopia in children.",
 "detailedDescription": "This will be a 3-arm, multicentered, randomized, double-masked, vehicle-controlled study conducted in 2 parts.\n\nPart 1 is the primary treatment period of 3 years, during which participants will receive 1 of 3 masked medications.\n\nPart 2 is the randomized withdrawal period of 1 year, during which participants originally receiving Vehicle will receive SYD-101, and participants originally receiving SYD-101 will receive either Vehicle or SYD-101.",
 "arms": [
  {
   "label": "SYD-101 0.01%",
   "type": "EXPERIMENTAL",
   "description": "1 drop in each eye at bedtime. Part 1: participants will be randomized to SYD-101 0.01% Part 2: participants will be re-randomized to SYD-101 0.01% or Vehicle",
   "interventionNames": [
    "Drug: SYD-101 0.01%"
   ]
  },
  {
   "label": "SYD-101 0.03%",
   "type": "EXPERIMENTAL",
   "description": "1 drop in each eye at bedtime. Part 1: participants will be randomized to SYD-101 0.03% Part 2: participants will be re-randomized to SYD-101 0.03% or Vehicle",
   "interventionNames": [
    "Drug: SYD-101 0.03%"
   ]
  },
  {
   "label": "Vehicle",
   "type": "PLACEBO_COMPARATOR",
   "description": "1 drop in each eye at bedtime. Part 1: participants will be randomized to Vehicle Part 2: participants will be re-randomized to SYD-101 0.03%",
   "interventionNames": [
    "Drug: Vehicle"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "SYD-101 0.01%",
   "description": "Sterile topical ophthalmic solution",
   "armGroupLabels": [
    "SYD-101 0.01%"
   ],
   "otherNames": [
    "atropine sulfate"
   ]
  },
  {
   "type": "DRUG",
   "name": "SYD-101 0.03%",
   "description": "Sterile topical ophthalmic solution",
   "armGroupLabels": [
    "SYD-101 0.03%"
   ],
   "otherNames": [
    "atropine sulfate"
   ]
  },
  {
   "type": "DRUG",
   "name": "Vehicle",
   "description": "Sterile topical ophthalmic solution without active ingredient",
   "armGroupLabels": [
    "Vehicle"
   ],
   "otherNames": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Myopic Progression <-0.75 D (Diopters)",
   "description": "Proportion of participants with confirmed myopic progression \\<-0.75 D (diopters), based on SE (spherical equivalent) as measured by cycloplegic autorefraction",
   "timeFrame": "Month 36"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Mean Annual Myopic Progression",
   "description": "Mean annual progression rate of myopia measured in diopters: Spherical Equivalent (SE) as measured by cycloplegic autorefraction.",
   "timeFrame": "Month 36"
  },
  {
   "measure": "Proportion of Participants With Annual Myopia Progression Rate >=-0.50 D/Year",
   "description": "Proportion of participants with annual progression rate of myopia no worse than -0.50 D/year",
   "timeFrame": "Through Month 36"
  },
  {
   "measure": "Proportion of Participants With Annual Myopia Progression Rate >=-0.25 D/Year",
   "description": "Proportion of participants with annual progression rate of myopia no worse than -0.25D/year",
   "timeFrame": "Through Month 36"
  },
  {
   "measure": "Proportion of Participants With Increase of Myopia More Than -0.50 D",
   "description": "Proportion of participants with increase of myopia more than -0.50D",
   "timeFrame": "Month 36"
  },
  {
   "measure": "Time to Progression of Myopia <-0.75 D (Diopters)",
   "description": "Time (days) to confirmed myopic progression of worse than -0.75D. Time to Progression (days) 95% CI is calculated for the median.",
   "timeFrame": "Up to 36 months (from date of randomization until date myopia progresses < -0.75 D)"
  },
  {
   "measure": "Mean Change From Baseline in Axial Length (Subset Only)",
   "description": "Mean change from baseline in axial length at sites with requisite equipment",
   "timeFrame": "Baseline to Month 36"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Myopia of 0.5 D (diopters) to 6.00 D (inclusive) in both eyes.\n* Astigmatism ≤1.50 D in both eyes.\n* Anisometropia ≤1.00 D in both eyes.\n* If myopia is ≥0.75 D, participant must be wearing single vision eyeglasses or soft, daily-wear, single-vision contact lenses that meet study investigator's criteria.\n* BCVA (best-corrected visual acuity) Snellen equivalent of 20/32 or better.\n\nExclusion Criteria:\n\n* Participants with a history or current evidence of a medical condition predisposing them to degenerative myopia (e.g. Marfan syndrome, Stickler syndrome), or a condition that may affect visual function or development (e.g. diabetes mellitus, chromosome anomaly).\n* Current use of a monoamine oxidase inhibitor.\n* Evidence of any ocular inflammation or infection in either eye, including blepharitis, conjunctivitis, keratitis, and scleritis.\n* Past, present or future plans to use orthokeratology (orthoK), rigid gas-permeable, bifocal, progressive-addition, multi-focal, or other lenses to reduce myopia progression; or the use of atropine, pirenzepine or other anti-muscarinic agent for myopia.\n* History or evidence of ocular surgery or planned future ocular surgery in either eye.\n\nOther protocol-defined inclusion/exclusion criteria could apply.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "3 Years",
  "maximumAge": "14 Years"
 },
 "siteCount": 47,
 "countries": [
  "United States",
  "Austria",
  "Slovakia"
 ]
}

