 "primaryOutcomes": [
  {
   "measure": "Percentage of Participants Achieving Hidradenitis Suppurativa Clinical Response (HiSCR) 75 at Week 12",
   "description": "HiSCR75 was defined as at least a 75% reduction from baseline in abscess and inflammatory nodule (AN) count, with no increase from baseline in abscess or draining fistula count. A non-responder imputation (NRI) method was used for missing data.",
   "timeFrame": "At Week 12"
