 ],
 "secondaryOutcomes": [
  {
   "measure": "Percentage of Participants Achieving HiSCR50 at Week 12",
   "description": "HiSCR50 was defined as at least a 50% reduction from baseline in abscess and AN count, with no increase from baseline in abscess or draining fistula count. An NRI method was used for missing data.",
   "timeFrame": "At Week 12"
  },
  {
   "measure": "Change From Baseline in International Hidradenitis Suppurativa Severity Score System (IHS4) at Week 12",
   "description": "The IHS4 is a validated tool to dynamically assess hidradenitis suppurativa (HS) severity. The IHS4 score was calculated as: number of nodules (multiplied by 1) plus the number of abscesses (multiplied by 2) plus the number of draining tunnels (multiplied by 4). A total score of ≤3 signified mild, score of 4 to 10 signified moderate, and score of ≥11 signified severe disease. A negative change from baseline indicated an improvement in HS severity.",
   "timeFrame": "Baseline and Week 12"
  },
  {
   "measure": "Percentage of Participants Achieving a Dermatology Life Quality Index (DLQI) Total Score of ≤5 at Week 12",
   "description": "The DLQI is an instrument designed to assess the impact of the disease on a participant's dermatology-specific quality of life (QoL). The DLQI total score ranged from 0 to 30, with higher scores indicating greater health-related QoL impairment. A negative change from baseline indicated an improvement in health-related QoL. An NRI method was used for missing data.",
   "timeFrame": "At Week 12"
  },
  {
   "measure": "Percentage of Participants Achieving a Numerical Rating Scale (NRS) 30 in Patient's Global Assessment (PGA) of Skin Pain at Week 12, in Participants With Baseline NRS ≥3",
   "description": "The PGA of Skin Pain NRS in the past 24 hours was used to assess pain \"at its worst\" due to HS in the last 24 hours and was completed by the participant using the electronic Diary device. NRS scores ranged from 0 to 10, with higher scores indicating greater skin pain. The weekly averages score was calculated based on the available daily scores from the 7 days on or prior to the nominal day of the visit. The average of the 7 days on or before the date of first dose of trial treatment was used as baseline. A PGA skin pain responder was a participant who achieved NRS30, defined as at least 30% reduction and at least 1-unit reduction from baseline in NRS in PGA skin pain. An NRI method was used for missing data.",
   "timeFrame": "At Week 12"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1. Participant is ≥18 years of age;\n2. Participant has been diagnosed with hidradenitis suppurativa as determined by the investigator and has a history of signs and symptoms of hidradenitis suppurativa dating back at least 6 months prior to the Screening Visit;\n3. Participant has a total abscess and/or inflammatory nodule (AN) count of ≥5;\n4. Participant has hidradenitis suppurativa lesions present in ≥2 distinct anatomical areas, at least one of which must contain single or multiple fistulas (i.e., be Hurley Stage II or III);\n5. Participant had an inadequate response to appropriate systemic antibiotics for treatment of hidradenitis suppurativa (or demonstrated intolerance to, or had a contraindication to, systemic antibiotics for treatment of their HS), in the investigator's opinion;\n6. Participant must be, in the opinion of the investigator, at both the Screening Visit and study treatment initiation, a suitable candidate for treatment with adalimumab per approved local product information.\n\nExclusion Criteria:\n\n1. Participants with known hypersensitivity to sonelokimab or any of its excipients;\n2. Participants with known hypersensitivity to adalimumab or any of its excipients;\n3. Participant has a draining fistula count of ≥20 at the Screening Visit;\n4. Participant has any other active skin disease or condition that may, in the opinion of the investigator, interfere with the assessment of hidradenitis suppurativa;\n5. Prior exposure to more than 2 biologic response modifiers;\n6. Participant has a diagnosis of ulcerative colitis or Crohn's disease.",
