{
 "nctId": "NCT05746559",
 "briefTitle": "ARTEMIS: Ravulizumab to Protect Patients With CKD From CSA-AKI and MAKE",
 "officialTitle": "ARTEMIS: RAvulizumab to PRotect PaTients With Chronic Kidney DisEase (CKD) froM Cardiac Surgery Associated Acute Kidney Injury (CSA-AKI) and Subsequent Major Adverse Kidney Events (MAKE): A Phase 3, Randomized, Double-blind, Placebo-controlled, Multicenter Study",
