   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Estimated Percentage of Participants Who Experienced Major Adverse Kidney Events (MAKE, Based on Serum Cystatin C [sCysC)] at Day 90 Post-CPB (MAKE90)",
   "description": "MAKE90 was defined as meeting at least one of the following three criteria:\n\n* Decrease from baseline in estimated glomerular filtration rate (eGFR) (Chronic Kidney Disease Epidemiology Collaboration \\[CKD-EPI\\] formula using sCysC) of ≥ 25% at Day 90 post CPB,\n* Initiation of kidney replacement therapy (KRT) through Day 90 post CPB, or\n* Death from any cause through Day 90 post CPB.\n\nEstimated percentages were calculated using imputation of missing data. Missing data for KRT initiation or death were imputed as non-events. Missing eGFR values were addressed using a two-step multiple imputation approach under the assumption of missing at random (MAR).",
   "timeFrame": "Day 90 post-CPB (surgery with CPB was within 7 days after study drug administration on Day 1)"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Estimated Percentage of Participants With Cardiac Surgery Associated Acute Kidney Injury (CSA-AKI) Without Recovery at Day 90 Post-CPB",
   "description": "CSA-AKI without recovery was defined as experiencing CSA-AKI based on highest observed serum creatinine (sCr) from randomization to Day 7 post CPB and had occurrence of non-recovered (complete \\[sCr \\< 1.1\\*baseline\\] or partial \\[sCr ≥ 1.1 to \\< 1.5\\*baseline\\]) CSA-AKI at Day 90.\n\nThe occurrence of post-operative CSA-AKI was defined as the presence of one of the following two observations during the 7 days after surgery with CPB, based on the modified Kidney Disease: Improving Global Outcomes (nonprofit foundation, KDIGO) criteria:\n\n* An increase in sCr by ≥ 0.3 milligrams per deciliter (mg/dL) in a 48-hour period, or\n* An increase in sCr to ≥ 1.5\\*baseline within the 7 days following CPB.\n\nEstimated percentages were calculated using imputation of missing data. Missing values were imputed as non-events.",
   "timeFrame": "Day 90 post-CPB (surgery with CPB was within 7 days after study drug administration on Day 1)"
  },
  {
   "measure": "Estimated Percentage of Participants With Severe CSA-AKI (KDIGO Stage 2 or 3)",
   "description": "Occurrence of severe CSA-AKI from randomization to Day 7 and Day 30 post-CPB was defined as meeting KDIGO stage 2 or 3 based on the highest observed sCr from randomization to Day 7 and Day 30 post-CPB. Estimated percentages were calculated using imputation of missing data. Missing values were imputed as non-events.\n\nCSA-AKI Staging by Modified KDIGO Criteria:\n\n* AKI Stage 1 - An increase in sCr by ≥ 0.3 mg/dL in a 48-hour period, or an increase in sCr to ≥ 1.5 to \\< 2.0\\*baseline.\n* AKI Stage 2 - An increase in sCr to ≥ 2.0 to \\< 3.0\\*baseline.\n* AKI Stage 3 - An increase in sCr to ≥ 3.0\\*baseline, or an increase in sCr to ≥ 4.0 mg/dL in participants meeting AKI criteria, or initiation of KRT.",
   "timeFrame": "From randomization to Days 7 and 30 post-CPB (surgery with CPB was within 7 days after study drug administration on Day 1)"
  },
  {
   "measure": "Estimated Percentage of Participants Who Died or Required KRT From Randomization to Day 90 Post-CPB",
   "description": "Estimated percentages were calculated using imputation of missing data. Missing data for the death component were addressed using a multiple imputation approach under the assumption of MAR. Missing values for the KRT component were imputed as non-events.",
   "timeFrame": "From randomization to Day 90 post-CPB (surgery with CPB was within 7 days after study drug administration on Day 1)"
  },
  {
   "measure": "Estimated All-cause Mortality From Randomization to Day 90 Post-CPB",
   "description": "Estimated all-cause mortality data (estimated percentage of participants who died) from randomization to Day 90 post-CPB is reported in this outcome measure.\n\nEstimated percentages were calculated using imputation of missing data. Missing data for death were addressed using a multiple imputation approach under the assumption of MAR. A summary of all-cause mortality through to the end of the study, without imputation for missing data, is located in the 'Reported Adverse Events' Section.",
   "timeFrame": "From randomization to Day 90 post-CPB (surgery with CPB was within 7 days after study drug administration on Day 1)"
  },
  {
   "measure": "Estimated Median Length of Post-operative Intensive Care Unit (ICU) Stay",
