{
 "nctId": "NCT06164704",
 "briefTitle": "A Study to Investigate the Efficacy and Safety of Verekitug (UPB-101) in Participants With Chronic Rhinosinusitis With Nasal Polyps",
 "officialTitle": "A Phase 2, Randomized, Double-blind, Placebo-controlled, Multi-center Study to Assess the Efficacy and Safety of Verekitug (UPB-101) in Participants With Chronic Rhinosinusitis With Nasal Polyps on a Background of Nasal Corticosteroids (VIBRANT)",
 "leadSponsor": {
  "name": "Upstream Bio Inc.",
  "class": "INDUSTRY"
 },
 "startDate": "2023-12-18",
 "firstRegistered": "2023-12-01",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Chronic Rhinosinusitis With Nasal Polyps"
 ],
 "keywords": [
  "CRSwNP",
  "Nasal Corticosteroids",
  "VIBRANT",
