 },
 "enrollment": 81,
 "briefSummary": "The primary purpose of this study is to assess the effect of verekitug (UPB-101) on the endoscopically determined size and extend of nasal polyps in participants with chronic rhinosinusitis with nasal polyps (CRSwNP) and to assess the safety and tolerability of verekitug (UPB-101) compared to placebo.",
 "detailedDescription": "This is a multicenter, randomized, placebo controlled, parallel group study to assess the efficacy and safety of verekitug (UPB-101) administered subcutaneously (SC) in participants with CRSwNP on background therapy with stable dosage of intranasal corticosteroids (INCS). Approximately 70 participants will be randomized. Participants will receive verekitug (UPB-101) or placebo over a 24-week treatment period. In addition, this study consists of a 3 to 5-week Screening Period and a 4-week Follow-up Period.",
 "arms": [
  {
   "label": "Verekitug (UPB-101)",
   "type": "EXPERIMENTAL",
   "description": "Participants will be administered 0.5 milliliter (mL) of verekitug (UPB-101) formulated solution (containing 100 milligrams \\[mg\\] of verekitug \\[UPB-101\\]) subcutaneously, every 12 weeks for 24 weeks.",
   "interventionNames": [
    "Drug: Verekitug (UPB-101)"
   ]
  },
  {
   "label": "Matching placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Participants will be administered verekitug (UPB-101) matching placebo solution, subcutaneously, every 12 weeks for 24 weeks.",
   "interventionNames": [
    "Drug: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Verekitug (UPB-101)",
