 "briefTitle": "Ilofotase Alfa for Prevention of Renal Damage After Cardiac Surgery",
 "officialTitle": "Double-Blind, Randomized, Placebo-Controlled Trial to Evaluate the Efficacy and Safety of Ilofotase Alfa in Patients at Risk for Renal Damage Following Open Heart Surgery",
 "leadSponsor": {
  "name": "AM-Pharma",
  "class": "INDUSTRY"
 },
 "collaborators": [
  {
   "name": "FGK Clinical Research GmbH",
   "class": "INDUSTRY"
