 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Open Heart Surgery"
 ],
 "keywords": [
  "Renal",
  "Kidney",
  "Cardiac",
  "CPB",
  "CABG"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "TRIPLE",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 271,
 "briefSummary": "The aim of this clinical trial is to evaluate the efficacy and safety of two intravenous administrations of ilofotase alfa in patients at risk for renal damage following open heart surgery.",
 "detailedDescription": "This is a Phase 2, multi-center, randomized, double-blind, placebo-controlled, 2-arm parallel group design trial in patients at risk for renal damage following open heart surgery. After screening and baseline assessments, eligible patients will be randomized 1:1 to either 2 doses of 128 mg ilofotase alfa, or 2 doses of placebo control. Randomization will be stratified by baseline eGFR and type of surgery. The patient will be treated with the investigational product (ilofotase alfa or placebo) at the same day before and after the surgery (Day 1). Follow-up clinic visits will be performed daily up to Day 5 for efficacy, safety, and pharmocokinetics assessments. A safety follow-up can be performed by telephone at Day 28. At Day 61, an end of trial visit will be done at site for efficacy, safety, and anti-drug antibodies assessments.",
 "arms": [
  {
   "label": "Ilofotase alfa",
   "type": "EXPERIMENTAL",
   "interventionNames": [
    "Drug: Ilofotase alfa"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "interventionNames": [
    "Drug: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Ilofotase alfa",
   "description": "After dilution of the concentrate, the investigational medicinal product will be administered by intravenous infusion for 1 hour at the same day before and after the surgery (Day 1)",
   "armGroupLabels": [
    "Ilofotase alfa"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "After dilution of the concentrate, the investigational medicinal product will be administered by intravenous infusion for 1 hour at the same day before and after the surgery (Day 1)",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Serum Creatinine Level Ratio",
   "description": "Ratio between the highest serum creatinine value post-surgery (post-surgery Day 1 and Days 2, 3, 4, and 5) and baseline serum creatinine (pre-surgery, Day -1/Day 1). The values at post-surgery Day 1 and Days 2, 3, 4, and 5 compared to the value at baseline (Day -1/Day 1) are used to calculate the serum creatinine ratio. The reported means and standard deviations are based on patient-level ratios and include observed and imputed values.",
   "timeFrame": "From Baseline (Day -1/1) to Day 5"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Assessment of Major Adverse Kidney Events (MAKE) 60",
   "description": "Major adverse kidney events (MAKE) 60, defined as died up to and including Day 61, have received or are receiving new renal replacement therapy (RRT) up to and including Day 61, or have a decrease in estimated glomerular filtration rate (eGFR) ≥25% on Day 61 compared to the pre-surgery baseline eGFR reference value. With Day 1 being the day of surgery.",
   "timeFrame": "60 days"
  },
  {
   "measure": "(Serious) Adverse Events up to Day28",
   "description": "All AEs that occured up to and including Day 28 or patient's trial completion, whichever occurs first.",
   "timeFrame": "Day1 to Day28"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1. Age ≥18 years\n2. Planned for one of the following types of open chest cardiovascular surgery with the use of cardiopulmonary bypass pump (CPB):\n\n   1. 1\\. combined valve and CABG surgery; 2. aortic valve plus aortic root and/or ascending aorta (excluding aortic arch)\n   2. CABG with 3 or more distal anastomoses\n3. Screening eGFR ≥25 mL/min/1.73m2 and ≤65 mL/min/1.73m2\n4. Female patients of childbearing potential agreeing to use effective contraception within IP treatment and 14 days thereafter\n\n   Post-menopausal females do not require contraception during the trial.\n5. Male patients agreeing to refrain from donating sperm, use a male condom when having sexual intercourse and in case their partner is of childbearing potential they must agree to use adequate and effective contraception method (see inclusion criterion 4) within IP treatment and 14 days thereafter\n\nThe five most important Exclusion Criteria:\n\n1. Body weight ≤55 kg\n2. Known or suspected glomerulonephritis (other than diabetic kidney disease) or other systemic vasculitis\n3. Confirmed or treated endocarditis requiring antimicrobial or antiviral treatment within 30 days prior to surgery or other current active infection requiring antimicrobial or antiviral treatment within 14 days prior to surgery\n4. Known chronic liver disorder with Child-Pugh C classification\n5. Current planned (or scheduled) surgical intervention under conditions of circulatory arrest, including planned deep hypothermic circulatory arrest",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years"
 },
 "siteCount": 13,
 "countries": [
  "Belgium",
  "Germany",
  "Netherlands",
  "Switzerland",
  "United Kingdom"
 ]
}

