forecastInput:
{
 "nctId": "NCT05014087",
 "briefTitle": "Digoxin In Treatment of Alcohol Associated Hepatitis",
 "officialTitle": "Digoxin In Treatment of Alcohol Associated Hepatitis (DIGIT-AlcHep)",
 "leadSponsor": {
  "name": "Yale University",
  "class": "OTHER"
 },
 "startDate": "2021-10-08",
 "firstRegistered": "2021-07-20",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Acute Alcoholic Hepatitis",
  "Chemical and Drug Induced Liver Injury",
  "Alcohol-Induced Disorders",
  "Steatohepatitis Caused by Ingestible Alcohol"
 ],
 "keywords": [
  "Acute alcoholic hepatitis",
  "Liver injury",
  "Liver inflammation",
  "Liver disease",
  "Digoxin"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "interventionModelDescription": "Prospective, single center, open label, randomized 1:1 controlled trial.",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "NONE"
  }
 },
 "enrollment": 23,
 "briefSummary": "Prospective, single center, open label, randomized controlled trial to explore whether digoxin treatment affects cytokine levels as biomarkers of inflammation in patients with acute alcohol associated hepatitis, digoxin administration and dose adjustment.\n\nThe study intervention will be intravenous digoxin (renal-based dosing for maximum of 28 days) versus no digoxin in an open-label 1:1 randomized allocation of patients with severe acute alcohol associated hepatitis.",
 "detailedDescription": "Severe alcohol associated hepatitis is a condition of acute on chronic immune liver dysfunction that is associated with high mortality, necessitating a search for drugs that may prove safe and efficacious in treating this disease. Pre-clinical studies suggest that digoxin, which is currently used for treating cardiac conditions, is also effective in improving alcohol-associated liver injury. To date, there have been no clinical studies of digoxin use in patients with alcohol associated hepatitis.\n\nThe primary objective of this randomized control study of digoxin versus no digoxin in patients with severe alcohol associated hepatitis is to explore whether digoxin treatment affects cytokine levels as biomarkers of inflammation in patients hospitalized with severe alcohol associated hepatitis.",
 "arms": [
  {
   "label": "Arm A: Digoxin",
   "type": "EXPERIMENTAL",
   "description": "In the digoxin arm, the intervention to be administered will be intravenous digoxin dosed by weight and by renal function using an adaption of the established FDA nomogram. Participants randomized to digoxin will receive an intravenous digoxin loading dose administered in 3 doses over 24 hours starting on Day 1. Digoxin levels will be monitored daily throughout the participant's hospital stay, to a maximum of 28 days. Digoxin will be discontinued at the time discharge if before 28 days.",
   "interventionNames": [
    "Drug: Intravenous digoxin"
   ]
  },
  {
   "label": "Arm B: No Digoxin",
   "type": "NO_INTERVENTION",
   "description": "In the no digoxin arm, no study drug or placebo will be administered."
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Intravenous digoxin",
   "description": "Loading dose: the total loading dose of digoxin will be determined using the Loading nomogram. The FDA-recommended total IV digoxin loading dose range is 8 to 12 mcg/kg. The lowest recommended dose of 8 mcg/kg was used in constructing the digoxin Loading nomogram that will be used in this trial.\n\nMaintenance dose: the maintenance dose will be started approximately 24 hours after initiation of digoxin loading. The post-loading digoxin trough will be reviewed prior to starting maintenance dosing.\n\nSubjects on P-gp inhibitors or spironolactone, will have an additional digoxin level performed 12-hours after any dose adjustment. Once digoxin levels are stable, 24-hour blood draws will be performed.",
   "armGroupLabels": [
    "Arm A: Digoxin"
   ],
   "otherNames": [
    "Lanoxin"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change in Biomarkers of Inflammation",
   "description": "Change in IL-6, IL-10 and TNF-alpha levels (pg/ml) at day 3 in participants with acute alcohol associated hepatitis treated with digoxin vs no digoxin.",
   "timeFrame": "Day 3"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Practicality of Daily Digoxin Measurements",
   "description": "Practicality of daily digoxin measurements is recorded at the participant level as the proportion of timepoints where serum digoxin levels are checked within the pre-specified time window. It is summarized and reported as the mean and standard deviation of the proportion of eligible timepoints.",
   "timeFrame": "From Day 2 to Day 28 or until discharge, whichever sooner"
  },
  {
   "measure": "Feasibility of Digoxin Dosing in a Timely Manner.",
   "description": "Feasibility of digoxin dosing is recorded at the participant level as the proportion of eligible timepoints where the scheduled digoxin dose was given. It is summarized and reported as the mean and standard deviation of the proportion of scheduled timepoints.",
   "timeFrame": "From Day 1 to Day 28 or until discharge, whichever sooner"
  },
  {
   "measure": "Feasibility of Digoxin Dose Adjustments in Renal Insufficiency.",
   "description": "Feasibility of digoxin dose adjustments in renal insufficiency is recorded at the participant level as the proportion of timepoints where necessary dose adjustments were made appropriately in response to digoxin levels. Renal insufficiency was defined as a creatinine rise ≥ 0.3 mg/dL over 48 hours or ≥ 20% from baseline or requiring renal replacement therapy. It is reported as the mean and standard deviation of the proportion of timepoints.",
   "timeFrame": "From Day 0 to Day 28 or until discharge, whichever sooner"
  },
  {
   "measure": "Mortality at 7, 14, 28, 90 Days. All Cause Mortality of Patients Enrolled in the Trial.",
   "description": "The mortality rates at different time points",
   "timeFrame": "Day 7, Day 14, Day 28, and Day 90"
  },
  {
   "measure": "Development of Arrhythmia",
   "description": "It refers to any type of arrhythmia which represents a change from baseline. It is reported as the proportion of individuals who developed an arrhythmia.",
   "timeFrame": "From Day 0 to Day 28 or until discharge, whichever sooner"
  },
  {
   "measure": "Recruitment",
   "description": "Ability to recruit 4 patients per month to reach anticipated enrollment of 60. Data presented here is the number participants enrolled.",
   "timeFrame": "up to 90 days"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1\\. Diagnosis of alcohol associated hepatitis based on clinical criteria or histologic evidence\n\n1. Clinical criteria:\n\n   * Onset of jaundice (bilirubin \\>3 mg/dL) within the prior 8 weeks\n   * Regular alcohol use \\> 6 months, with intake of \\> 40 g/day (\\>280 g/week) for women; and \\> 60 g/day (\\>420 g/week) for men\n   * AST \\> 50 IU/l\n   * AST: ALT \\> 1.5 and both values \\< 400 IU/l\n2. Histological evidence of alcohol associated hepatitis\\*\n\n   2\\. MDF \\>32 or MELD ≥ 20 to ≤ 35 on Day 0 of the trial\n\n   3\\. Age between 21 and 70 years, inclusive\n\n   \\* In patients with possible alcohol associated hepatitis with confounding factors such as possible ischemic hepatitis, possible DILI, uncertain history of alcohol use, or atypical/abnormal laboratory tests (e.g., AST \\< 50 IU/IU/L or \\> 400 IU/IU/L, AST/ALT ratio \\< 1.5), antinuclearantibody \\> 1:160 or SMA \\> 1:80, standard of care liver biopsy may be performed as per discretion of the primary attending physician to confirm alcohol associated hepatitis and exclude competing etiologies. The decision to perform liver biopsy will be made by the primary team and will occur regardless of the study. As per current SOC, a liver biopsy may be obtained to confirm suspected alcohol-associated hepatitis and to rule out other potential etiologies of liver disease.\n\n   If a liver biopsy is performed for clinically indicated reasons, we will store liver tissue that is left over after the portion needed for the primary indication has been identified.\n\n   Exclusion Criteria:\n   1. \\- Currently pregnant or breastfeeding\n   2. \\- Inability of patient, legally authorized representative or next-of-kin to provide informed consent\n   3. \\- Allergy or intolerance to digoxin\n   4. \\- Clinically active C. diff infection\n   5. \\- Positive test for COVID-19 within 14 days prior to the screening visit\n   6. \\- Acute hepatitis E, Cytomegalovirus, Epstein Barr Virus, Herpes Simplex Virus\n\n   7- History of other liver diseases including hepatitis B (positive HBsAg or HBV DNA), hepatitis 8-C (positive HCV RNA), autoimmune hepatitis, Wilson disease, genetic hemochromatosis, alpha1-antitrypsin deficiency.\n\n   8-Diagnosis of Drug Induced Liver Injury (DILI), or other etiologies seen on liver imaging.\n\n   9 - History of HIV infection (positive HIV RNA or on treatment for HIV infection)\n\n   10 - Current diagnosis of cancer\n\n   11- Renal failure defined by GFR \\<30 mL/min\n\n   12 - Refractory ascites, defined as having more than 4 paracenteses in the preceding 8 weeks despite diuretic therapy\n\n   13 - Prior exposure to experimental therapies or other clinical trial in last 3 months\n\n   14 - Current acute or chronic pancreatitis\n\n   15 - Active gastrointestinal bleeding unless resolved for \\>48 hours\n\n   16 - Experiencing withdrawal seizures or considered at high risk for alcohol withdrawal seizures or delirium tremens\n\n   17 - Heart rate less than 60 bpm at screening visit or at baseline\n\n   18 - Current diagnosis of atrial fibrillation\n\n   19 - Cardiomyopathy\n\n   20 - Heart failure\n\n   21 - Severe aortic valve disease\n\n   22 - Presence of Accessory arterio-ventricular pathway (eg Wolf-Parkinson-White syndrome)\n\n   23 - Complete heart block or second degree arterio-ventricular block without pacemaker or implantable cardiac device\n\n   24 - Any of the following within the previous 6 months: myocardial infarction, percutaneous intervention, pacemaker/implantable cardiac device implantation, cardiac surgery or stroke\n\n   25 - Current use of the following medications:\n   * Antiarrhythmic (amiodarone, dofetilide, sotalol, dronedarone)\n   * Parathyroid hormone analog (teriparatide)\n   * Thyroid supplement (thyroid, levothyroxine sodium)\n   * Sympathomimetics or ionotropic drugs (epinephrine, norepinephrine, dopamine, dobutamine, milrinone)\n   * Neuromuscular blocking agents (succinylcholine)\n   * Calcium supplement\n   * Ivabradine\n   * Disulfiram",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "21 Years",
  "maximumAge": "70 Years"
 },
