 "enrollment": 348,
 "briefSummary": "The purpose of the study is to see if daily transdermal nicotine is able to produce a significant cognitive, clinical and functional improvement in participants with MCI. Neuronal nicotinic receptors have long been known to play a critical role in memory function in preclinical studies, with nicotine improving attention, learning, and memory function.\n\nThe study will enroll 380 participants for a 2 year period. Participants will be randomized (50:50) to either the transdermal nicotine, beginning at 7mg/day, and increasing to 21mg/day, or placebo skin patch.",
 "arms": [
  {
   "label": "Nicotine Transdermal Patch",
   "type": "EXPERIMENTAL",
   "description": "Participants will wear nicotine transdermal patches during waking hours. Active dose will titrate up from 3.5mg to 21mg in the first 5 weeks of treatment, remain at 21mg up to 24 month, and then taper down for 3 weeks.",
   "interventionNames": [
    "Drug: Nicotine Transdermal Patch"
   ]
  },
  {
   "label": "Placebo Patch",
   "type": "PLACEBO_COMPARATOR",
   "description": "Participants will wear matching placebo patches during waking hours.",
   "interventionNames": [
    "Drug: Placebo Patch"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Nicotine Transdermal Patch",
   "description": "21mg Nicotine transdermal patches worn during waking hours. Active dose will titrate up from 3.5mg to 21mg in the first 5 weeks of treatment, remain at 21mg up to month 24, and then taper down for three weeks.",
   "armGroupLabels": [
    "Nicotine Transdermal Patch"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo Patch",
   "description": "Matching placebo patches worn during waking hours.",
   "armGroupLabels": [
    "Placebo Patch"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Cogstate Battery International Shopping List Test - Total Immediate Recall (ISLT-TIR)",
   "description": "The ISLT - TIR represents the number of correct responses made when remembering the twelve word shopping list on three consecutive trials. The unit of the variable is correct responses count and higher score is better performance. Scores range from 0 to 36.",
   "timeFrame": "From Baseline to month 24"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline in Mild Cognitive Impairment - Clinical Global Impression of Change (MCI-CGIC) to Month 24",
   "description": "The MCI-CGIC is the MCI version of the clinician's global impression of change. In this trial it will measure change in the participant's condition between the baseline visit and subsequent visits.",
   "timeFrame": "From Baseline to month 24"
  },
  {
   "measure": "International Shopping List Test - Delayed Recall (ISRL)",
   "description": "This battery will be used for the purpose of assessing the cognitive status of the participants and will assist in documenting multiple domains of cognitive impairment.",
   "timeFrame": "From Baseline to month 24"
  },
  {
   "measure": "Identification Task",
   "description": "The IDN evaluates attention and is assessed in speed of performance. Lower score is better performance.",
   "timeFrame": "From Baseline to month 24"
  },
  {
   "measure": "One Card Learning Task (OCL)",
   "description": "The OCL evaluates visual learning and is assessed in accuracy of performance; performance; arcsine square root proportion correct. Higher score is better performance. Ranges from 0 to 1.5708",
