   "timeFrame": "From Baseline to month 24"
  },
  {
   "measure": "One Back Task (ONB)",
   "description": "The ONB evaluates working memory and is assessed in speed of performance; mean of the log10 transformed reaction times for correct responses. Lower score is better performance, ranges from ranges from 2.001 to 6.",
   "timeFrame": "From Baseline to month 24"
  },
