   "measure": "Number of Participants Who Had an Ischemic Stroke",
   "description": "A participant is counted if a first ischemic stroke occurred after randomization. A time-to-event analysis using a Cox proportional hazards model was used to compare treatment groups over the full follow-up period.",
   "timeFrame": "Up to 32 months"
  },
