   "description": "A participant is counted if a first symptomatic intracranial hemorrhage occurred after randomization during the on-treatment period (including 2 days after treatment discontinuation). Time-to-event analysis was performed using a stratified Cox proportional hazards model to compare treatment groups over the follow-up period.",
   "timeFrame": "Up to 32 months"
  },
  {
   "measure": "Number of Participants Who Had Hemorrhagic Stroke",
   "description": "A participant is counted if a first hemorrhagic stroke occurred after randomization during the on-treatment period (including 2 days after treatment discontinuation). Time-to-event analysis was performed using a stratified Cox proportional hazards model to compare treatment groups over the follow-up period.",
   "timeFrame": "Up to 32 months"
  },
  {
   "measure": "Number of Participants Who Had Fatal Bleeding",
   "description": "A participant is counted if a first fatal bleeding event occurred after randomization during the on-treatment period (including 2 days after treatment discontinuation). Time-to-event analysis was performed using a stratified Cox proportional hazards model to compare treatment groups over the follow-up period.",
   "timeFrame": "Up to 32 months"
  },
  {
   "measure": "Number of Participants Who Had Minor Bleeding",
   "description": "A participant is counted if a first occurrence of minor bleeding occurred after randomization during the on-treatment period (including 2 days after treatment discontinuation). Time-to-event analysis was performed using a stratified Cox proportional hazards model to compare treatment groups over the follow-up period.",
   "timeFrame": "Up to 32 months"
  },
  {
   "measure": "Number of Participants Who Had Composite of Ischemic Stroke or ISTH Major Bleeding",
   "description": "A participant is counted if a first occurrence of ischemic stroke or ISTH major bleeding occurred after randomization during the on-treatment period (including 2 days after treatment discontinuation). Time-to-event analysis was performed using a stratified Cox proportional hazards model to compare treatment groups over the follow-up period.",
   "timeFrame": "Up to 32 months"
  },
  {
   "measure": "Number of Participants Who Had Composite of Cardiovascular Death, Any Stroke, Myocardial Infarction, or ISTH Major Bleeding",
   "description": "A participant is counted if a first occurrence of cardiovascular death, any stroke (ischemic or hemorrhagic), myocardial infarction, or ISTH major bleeding occurred after randomization during the on-treatment period (including 2 days after treatment discontinuation). Time-to-event analysis was performed using a stratified Cox proportional hazards model to compare treatment groups over the follow-up period.",
   "timeFrame": "Up to 32 months"
  },
  {
   "measure": "Number of Participants Who Had Composite of All-cause Mortality, Disabling Stroke, Fatal Bleeding, or Symptomatic Intracranial Hemorrhage",
   "description": "A participant is counted if a first occurrence of all-cause mortality, disabling stroke, fatal bleeding, or symptomatic intracranial hemorrhage occurred after randomization during the on-treatment period (including 2 days after treatment discontinuation). Time-to-event analysis was performed using a stratified Cox proportional hazards model to compare treatment groups over the follow-up period.",
   "timeFrame": "Up to 32 months"
  },
  {
   "measure": "Number of Participants Who Had an Ischemic Stroke in the First 90 Days",
   "description": "A participant is counted if a first ischemic stroke occurred within 90 days after randomization. Time-to-event analysis was performed using a Cox proportional hazards model restricted to the first 90 days of follow-up to compare treatment groups.",
   "timeFrame": "Up to 90 days"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Participants must be ≥ 18 years of age\n* Acute non-cardioembolic stroke or high-risk TIA\n* Systemic or cerebrovascular atherosclerosis or acute non-lacunar infarct\n\nExclusion Criteria:\n\n* Ischemic stroke ≤ 7 days before the index event\n* Index stroke following procedures or strokes due to other rare causes\n* History of atrial fibrillation/flutter, left ventricular thrombus, mechanic valve or other cardioembolic source of stroke requiring anticoagulation",
