 "briefTitle": "An Efficacy, Safety, and Tolerability Study of Veligrotug (VRDN-001), in Participants With Chronic Thyroid Eye Disease (TED)",
 "officialTitle": "A Randomized, Double-masked, Placebo-controlled Safety, Tolerability, and Efficacy Study of VRDN-001, a Humanized Monoclonal Antibody Directed Against the IGF-1 Receptor, in Participants With Chronic Thyroid Eye Disease (TED)",
 "leadSponsor": {
  "name": "Viridian Therapeutics, Inc.",
  "class": "INDUSTRY"
 },
 "startDate": "2023-11-01",
