   ]
  }
 },
 "enrollment": 188,
 "briefSummary": "This is a clinical trial assessing the efficacy, safety, and tolerability of an investigational drug, veligrotug (VRDN-001), in participants with chronic thyroid eye disease (TED).",
 "detailedDescription": "This is a randomized (meaning participants will be assigned to study arms by chance), double-masked (meaning study doctor and participant will not know which study arm participant is assigned to), placebo-controlled study that will include participants with chronic TED. The key objectives of this study are to determine if veligrotug (VRDN-001) is efficacious, safe, and tolerable when administered as 5 IV infusions given every 3 weeks for a total of 12 weeks in participants with chronic TED.",
 "arms": [
  {
   "label": "Veligrotug",
   "type": "EXPERIMENTAL",
   "description": "Participants will receive veligrotug 10 mg/kg as an intravenous (IV) infusion every 3 weeks (Q3W) for 12 weeks.",
   "interventionNames": [
    "Drug: Veligrotug"
   ]
  },
  {
   "label": "Placebo",
   "type": "EXPERIMENTAL",
   "description": "Participants will receive placebo matched to veligrotug as an IV infusion Q3W for 12 weeks.",
   "interventionNames": [
    "Drug: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Veligrotug",
   "description": "5 IV Infusions of veligrotug 10 mg/kg",
   "armGroupLabels": [
    "Veligrotug"
   ],
   "otherNames": [
    "VRDN-001"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "5 IV Infusions of veligrotug matched placebo",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Proptosis Responder Rate (PRR) in the Most Proptotic Eye as Measured by Exophthalmometer",
   "description": "Proptosis response in the most proptotic eye was defined as a reduction of proptosis of ≥2 millimeters (mm) from baseline in the most proptotic eye (without a corresponding increase of ≥2 mm in the other eye) as measured by exophthalmometer. Missing data were imputed with the Multiple Imputation (MI) method.",
   "timeFrame": "Baseline to Week 15"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline in Proptosis in the Most Proptotic Eye as Measured by Exophthalmometer",
   "description": "Proptosis was defined as distance between the lateral orbital rim and the most anterior position of the cornea in mm, measured using an exophthalmometer. Missing data were imputed with the MI method.",
   "timeFrame": "Baseline, Week 15"
  },
  {
   "measure": "PRR in the Most Proptotic Eye, as Measured by Magnetic Resonance Imaging (MRI)/Computed Tomography (CT)",
   "description": "Proptosis responder in the most proptotic eye by MRI/CT was defined as a reduction of proptosis of ≥2 mm from baseline in the most proptotic eye by MRI/CT (without a corresponding increase of ≥2 mm in the other eye) as measured by MRI/CT. Missing data were imputed using the Exophthalmometer Imputation (EXI) method, as applicable.",
   "timeFrame": "Baseline to Week 15"
  },
  {
   "measure": "Change From Baseline in Proptosis in the Most Proptotic Eye as Measured by MRI/CT",
   "description": "Measurement of proptosis was conducted by the central imaging reading center using MRI/CT of the orbits acquired without contrast. Measurements were conducted by 2 independent readers with adjudication if the difference between the 2 primary readers in proptosis measurement exceeded 5% (calculated as the difference divided by the larger measurement). The average of 2 (or 3 if adjudicated) measurements were used for analyses. Missing data were imputed using the EXI method, as applicable.",
   "timeFrame": "Baseline, Week 15"
  },
  {
   "measure": "Clinical Activity Responder Rate in the Most Proptotic Eye as Measured by Exophthalmometer",
   "description": "Clinical activity responder in the most proptotic eye was defined as no worsening in clinical activity score (CAS) from baseline in the most proptotic eye without a corresponding increase of ≥2 points in the other eye. Missing data were imputed with the MI method.",
   "timeFrame": "Week 15"
  },
  {
   "measure": "Overall Responder Rate (ORR) Comprising PRR and Clinical Activity Responder Rate in the Most Proptotic Eye as Measured by Exophthalmometer",
   "description": "ORR was comprised of PRR in the most proptotic eye (reduction of proptosis of ≥2 mm from baseline in the most proptotic eye \\[without a corresponding increase of ≥2 mm in the other eye\\]) as measured by exophthalmometer at Week 15 and Clinical Activity Responder rate in the most proptotic eye (no worsening in CAS from baseline in the most proptotic eye without a corresponding increase of ≥2 points in the other eye) as measured by exophthalmometer at Week 15. Missing data were imputed with the MI method.",
   "timeFrame": "Baseline to Week 15"
  },
  {
   "measure": "Diplopia Responder Rate",
   "description": "A diplopia responder was defined as having a decrease of ≥1 from baseline for participants with a baseline Gorman subjective diplopia score \\>0. Gorman subjective diplopia score (range, 0 to 3) includes 4 categories: no diplopia (absent, scored as 0), diplopia in the primary position of gaze when the participant is tired or awakening (intermittent, scored as 1), diplopia at extremes of gaze (inconstant, scored as 2), and continuous diplopia in the primary or reading position (constant, scored as 3). Missing data were imputed with the MI method.",
   "timeFrame": "Week 15"
  },
  {
   "measure": "Diplopia Resolution Rate",
   "description": "Diplopia resolution was defined as reduction in Gorman subjective diplopia score to 0 from baseline for participants with baseline Gorman subjective diplopia score \\>0. Gorman subjective diplopia score (range, 0 to 3) includes 4 categories: no diplopia (absent, scored as 0), diplopia in the primary position of gaze when the participant is tired or awakening (intermittent, scored as 1), diplopia at extremes of gaze (inconstant, scored as 2), and continuous diplopia in the primary or reading position (constant, scored as 3). Missing data were imputed with the MI method.",
   "timeFrame": "Week 15"
  }
 ],
 "eligibility": {
  "criteria": "Key Inclusion Criteria:\n\n* Must have moderate to severe chronic TED with documented evidence of ocular symptoms or signs that began greater than 15 months prior to screening\n* Must have had a clinical diagnosis of TED, with any CAS (0-7)\n* Must agree to use highly effective contraception as specified in the protocol\n* Female TED participants must have a negative serum pregnancy test at screening\n\nKey Exclusion Criteria:\n\n* Must not have received prior treatment with another anti-IGF-1R therapy\n* Must not have received systemic corticosteroids for any condition, including TED, or selenium within 2 weeks prior to first dose\n* Must not have received other immunosuppressive drugs or another investigational agent for any condition, including TED, or any other therapy for TED, within 8 weeks prior to first dose\n* Must not have received radioactive iodine (RAI) treatment within 8 weeks prior to first dose\n* Must not have a pre-existing ophthalmic condition in the study eye that in the opinion of the study doctor would confound interpretation of the study results\n* Must not have had previous orbital irradiation or decompression surgery for TED to the study eye's orbit\n* Must not have inflammatory bowel disease\n* Must not have abnormal baseline audiometry Pure Tone Average (PTA) assessment or history of significant (as determined by the Investigator) ear pathology, relevant ear surgery or hearing loss.\n* Female TED participants must not be pregnant or lactating",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "75 Years"
 },
 "siteCount": 57,
 "countries": [
  "United States",
  "Australia",
  "France",
  "Germany",
  "Hungary",
  "Poland",
  "Spain",
  "Turkey (Türkiye)",
  "United Kingdom"
 ]
}

