  {
   "measure": "Change in Alkaline Phosphatase (ALP) From Baseline in the Double-Blind Treatment Period",
   "description": "Serum samples were collected at scheduled visits during the double-blind treatment period. Changes in ALP over time will be analyzed using a mixed model for repeated measures (MMRM) to assess treatment group effects across study visits. Baseline was defined as the mean of all available evaluations prior to the first administration of investigational product in the DB period. Change from Baseline was calculated as post Baseline value minus Baseline value.",
   "timeFrame": "Baseline to Week 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Percentage of Participants With Response Rates of ≥10%, ≥20%, ≥30% and ≥40% Reduction From Baseline in ALP in the Double-Blind Treatment Period",
