 },
 "enrollment": 535,
 "briefSummary": "This randomized phase III trial studies how well human papillomavirus (HPV) vaccine therapy works in reducing high-grade cervical lesions in patients with human immunodeficiency virus (HIV) and HPV. Vaccines made from HPV peptides or antigens may help the body build an effective immune response to kill the HPV virus and prevent cervical lesions from developing or coming back after being removed.",
 "detailedDescription": "At screening, potential participants will be tested for cervical human papillomavirus (HPV) infection (GeneXpert hrHPV assay and HPV DNA PCR) and undergo cervical colposcopy to confirm the absence of cervical cancer. If eligible, the participant will be randomized to receive either the 9-valent HPV vaccine or saline placebo.\n\nParticipants will return 4 and 26 weeks later for the second dose of vaccine or placebo. At week 4, participants will have cervical colposcopy and undergo cryotherapy or loop electrosurgical excisional procedure (LEEP) as appropriate. Participants undergoing cervical cryotherapy will have cervical biopsies before the treatment. Participants will be followed with HPV testing (Gene Xpert and HPV DNA PCR) at weeks 26, 52, 78, and 104, and will have cervical cytology and colposcopy with biopsies at weeks 26, 52, and 104.",
 "arms": [
  {
   "label": "Arm I, recombinant HPV 9-valent vaccine",
   "type": "EXPERIMENTAL",
   "description": "Patients receive Recombinant Human Papillomavirus Nonavalent Vaccine (Gardasil 9) IM at baseline, 4, and 26 weeks in the absence of disease progression or unacceptable toxicity, with sample collection for Laboratory Biomarker Analysis.",
   "interventionNames": [
    "Other: Laboratory Biomarker Analysis",
    "Biological: Recombinant Human Papillomavirus Nonavalent Vaccine"
   ]
  },
  {
   "label": "Arm II, saline",
   "type": "PLACEBO_COMPARATOR",
   "description": "Patients receive saline placebo vaccine IM at baseline, 4, and 26 weeks, with sample collection for Laboratory Biomarker Analysis.",
   "interventionNames": [
    "Other: Laboratory Biomarker Analysis",
    "Other: Saline"
   ]
  }
 ],
 "interventions": [
  {
   "type": "OTHER",
   "name": "Laboratory Biomarker Analysis",
   "description": "Correlative studies",
   "armGroupLabels": [
    "Arm I, recombinant HPV 9-valent vaccine",
    "Arm II, saline"
   ]
  },
  {
   "type": "BIOLOGICAL",
   "name": "Recombinant Human Papillomavirus Nonavalent Vaccine",
   "description": "Given IM",
   "armGroupLabels": [
    "Arm I, recombinant HPV 9-valent vaccine"
   ],
   "otherNames": [
    "Gardasil 9",
    "Nonavalent HPV VLP Vaccine",
    "Recombinant HPV Nonavalent Vaccine",
    "Recombinant Human Papillomavirus 9-valent Vaccine",
    "Recombinant HPV 9-valent Vaccine"
   ]
  },
  {
   "type": "OTHER",
   "name": "Saline",
   "description": "Given IM",
   "armGroupLabels": [
    "Arm II, saline"
   ],
   "otherNames": [
    "Sodium Chloride 0.9%"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Occurrence of Cervical High-grade Squamous Intraepithelial Lesions (HSIL) or Cervical Cancer",
   "description": "For each arm (vaccine and placebo), the HSIL or cancer event rate will be estimated using its point estimate and 95% Poisson confidence intervals. Poisson regression analyses will be used to compare the two arms with respect to event rate. In addition, time to event from week 4 to 52 will be described using the Kaplan-Meier method for each arm, and the two arms will be compared with respect to time to event using the log-rank test.",
   "timeFrame": "After week 4 study visit to week 52 post-randomization"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Occurrence of Cervical HSIL or Invasive Cancer From Weeks 52-104",
   "description": "The event rate for each arm from week 52 to week 104 for women who are event-free at 52 weeks will be estimated using its point estimate and 95% Poisson confidence interval.\n\nPoisson regression will be used to compare the two groups with respect to the event rate from week 52 to 104.",
   "timeFrame": "After week 52 to week 104"
  },
  {
   "measure": "Predictors of Sustained Absence of Cervical HSIL Through Week 104 and HPV Clearance",
   "description": "Role of baseline types and quantity of HPV, presence of HSIL at baseline, cryotherapy vs. LEEP, CD4+ cell count, plasma HIV-1 RNA, ART use, age, sexual behavior, and vaccination use will be investigated.\n\nPoisson regression analyses will be used to determine if these factors are associated with of sustained absence of cervical HSIL and clearance of HPV infections after cryotherapy or LEEP. These analyses will also control for use of LEEP or cryotherapy.",
   "timeFrame": "At baseline through week 104"
  },
  {
   "measure": "Incident Cervical Vaccine Type HPV Infections",
   "description": "Incident cervical vaccine type HPV infections are defined as HPV infections detected at 2 consecutive timepoints and assessed using type specific HPV DNA polymerase chain reaction (PCR) Vaccine and placebo participants will be compared with respect to these proportions using the chi-square test corrected for continuity.",
   "timeFrame": "Up to week 104"
  },
  {
   "measure": "Abnormal Cervical Cytology",
   "description": "The proportion of women with abnormal cervical cytology at baseline, week 26, 52, and 104 will be reported and compared between arms.",
   "timeFrame": "Baseline, week 26, 52, and 104"
  },
  {
   "measure": "Prevalent Vulvar HSIL or Cancer",
   "description": "The prevalence of vulvar HSIL or cancer at baseline will be estimated using the binomial proportion and its 95% confidence interval.",
   "timeFrame": "Up to week 4"
  },
  {
   "measure": "Incident Vulvar HSIL or Cancer",
   "description": "The proportion of women who acquire vulvar HSIL or cancer among those negative for vulvar HSIL or cancer at baseline for both intervention arms will be estimated as a binomial proportion for both groups. The chi-square test corrected for continuity will be used to compare arms with respect to the proportions who acquire vulvar HSIL during the study.",
   "timeFrame": "Up to week 104"
  },
  {
   "measure": "Number of Participants Stratified by the Presence or Absence of Incident Vulvar HSIL/Cancers.",
   "description": "Due to insufficient number of participants with outcome assessments, association (Logistic regression) analysis with clinical and demographic factors was not performed",
   "timeFrame": "Up to week 104"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* HIV-1 infection, documented by any licensed rapid HIV test or HIV enzyme or chemiluminescence immunoassay (E/CIA) test kit at any time prior to study entry and confirmed by a licensed western blot or a second antibody test by a method other than the initial rapid HIV and/or E/CIA, or by HIV-1 antigen, plasma HIV-1 RNA viral load, or documentation of receipt of antiretroviral therapy; Note: the term \"licensed\" refers to a kit that has been certified or licensed by an oversight body within the participating country and validated internally; WHO (World Health Organization) and CDC (Centers for Disease Control and Prevention) guidelines mandate that confirmation of the initial test result must use a test that is different from the one used for the initial assessment; a reactive initial rapid test should be confirmed by either another type of rapid assay or an E/CIA that is based on a different antigen preparation and/or different test principle (e.g., indirect versus competitive), or a western blot or a plasma HIV-1 RNA viral load\n* HPV positive by the GeneXpert hrHPV assay with HPV16, HPV 18/45, or HPV31/33/35/52/58 detected; Note: participants who are hrHPV positive with only HPV51/59 or HPV 39/68/56/66 detected are not eligible\n* Receipt of ART for at least 180 days prior to randomization\n* Participants of childbearing potential, defined as a sexually mature woman who: (1) has not undergone a hysterectomy or bilateral oophorectomy or (2) has not been naturally postmenopausal for at least 24 consecutive months (i.e., has had menses at any time in the preceding 24 consecutive months), must have a negative urine or serum pregnancy test within 3 weeks prior to enrollment and agree to use an effective form of contraception (e.g., barrier contraception or hormonal contraception), delaying pregnancy for at least 12 months and ideally for the duration of the study; Note: those willing to participate delay pregnancy for at least 6 months, while receiving the recombinant human papillomavirus nonavalent (9vHPV) vaccine (or placebo)\n* If the participant is of childbearing potential, she should be at least 3 months postpartum\n* Karnofsky score \\>= 70%\n* Ability to understand and the willingness to sign a written informed consent document\n\nExclusion Criteria:\n\n* Current sexually transmitted infection (STI) requiring treatment (women may participate after adequate treatment, at the discretion of the treating provider)\n* History of allergic reactions attributed to compounds of similar chemical or biologic composition to Gardasil or Gardasil 9\n* Uncontrolled intercurrent illness that would limit compliance with study requirements\n* Prior hysterectomy with removal of the cervix\n* Prior treatment for cervical HSIL\n* Prior history of cervical, vulvar, or vaginal cancer\n* Cervical, vulvar, or vaginal lesions suspicious for cancer based on clinical appearance (e.g. necrotic, ulcerated, and/or fungating masses), unless biopsies show no invasive cancer\n* Known bleeding diathesis\n* Prior HPV vaccination\n* Current or planned use of anticoagulants other than aspirin or non-steroidal anti-inflammatory agents",
  "healthyVolunteers": false,
  "sex": "FEMALE",
  "minimumAge": "25 Years"
 },
 "siteCount": 6,
 "countries": [
  "Kenya",
  "Malawi",
  "South Africa",
  "Uganda",
  "Zimbabwe"
 ]
}

