forecastInput:
{
 "nctId": "NCT05210790",
 "briefTitle": "A Study of Rusfertide in Adults With Polycythemia Vera (PV)",
 "officialTitle": "A Phase 3 Study of the Hepcidin Mimetic Rusfertide (PTG-300; TAK-121) in Patients With Polycythemia Vera",
 "leadSponsor": {
  "name": "Protagonist Therapeutics, Inc.",
  "class": "INDUSTRY"
 },
 "startDate": "2022-04-11",
 "firstRegistered": "2022-01-14",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Polycythemia Vera"
 ],
 "keywords": [
  "Polycythemia Vera",
  "PV"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "TRIPLE",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 293,
 "briefSummary": "Polycythemia vera (PV) is a long-term condition in which the bone marrow makes too many red blood cells (RBCs). Bone marrow is the soft tissue inside the large bones where blood cells are made. When there are too many RBCs, called erythrocytosis, the blood can become thicker and move less easily through blood vessels and organs. This can raise the risk of blood clots (thrombosis) in veins or arteries. Sometimes, these clots can be life-threatening and may cause a stroke or heart attack. Treatment aims to keep the percentage of RBCs in the blood (hematocrit) in a safe range. For adults with PV, this means keeping the hematocrit below 45%. This helps lower the blood thickness and the risk of thrombosis. PV can also be linked to low iron levels (iron deficiency), because the body uses iron to make more RBCs. Many people with PV are treated with blood removal (phlebotomy) to lower RBC levels in the blood. This can worsen the iron deficiency, because each blood removal also takes iron out of the body.\n\nRusfertide is a medicine that lowers the amount of iron available in the blood. It works like hepcidin, a natural hormone that helps control iron levels in the body. By limiting iron available for RBC production, rusfertide may help keep hematocrit below 45% and may improve symptoms. It may also reduce, or even remove, the need for phlebotomy in people.\n\nThe main aim of this study is to check how well rusfertide works compared with placebo to lower the number of phlebotomies. A placebo looks like rusfertide but does not have any medicine in it.\n\nOther aims are to learn how safe rusfertide is compared with placebo and to understand how well it works to reduce the need for phlebotomy and to keep hematocrit levels under control. The study also wants to learn how rusfertide moves through the body (pharmacokinetics) and how it affects the body (pharmacodynamics or PD).\n\nThis study has 4 parts that follow each other:\n\n* In part 1a, participants will receive either rusfertide or placebo.\n* In part 1b, all participants will receive rusfertide.\n* In part 2, participants can continue to receive rusfertide if they benefit from treatment with rusfertide.\n* Part 3 will include participants who finish Part 2 and still benefit from rusfertide.\n\nDuring the study, participants will visit the study clinical several times at fixed timepoints.",
 "arms": [
  {
   "label": "Part 1a: Randomized, Double-Blind Period: Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Participants received their ongoing therapy for polycythemia vera (PV) along with rusfertide-matching placebo, subcutaneous (SC) injection, once weekly, from baseline up to Week 32.",
   "interventionNames": [
    "Drug: Placebo"
   ]
  },
  {
   "label": "Part 1a: Randomized, Double-Blind Period: Rusfertide",
   "type": "EXPERIMENTAL",
   "description": "Participants received their ongoing therapy for PV along with rusfertide once weekly, SC injection, from baseline up to Week 32. Rusfertide doses were titrated to maintain hematocrit less than (\\<) 45 percent (%). The starting dose was 19 milligrams (mg). The doses that were administered to Part 1a participants were 9.5, 19, 28, 41, 54, 69 and 82 mg.",
   "interventionNames": [
    "Drug: Rusfertide"
   ]
  },
  {
   "label": "Part 1b: Open-Label Treatment Period: Rusfertide",
   "type": "EXPERIMENTAL",
   "description": "Participants received rusfertide once weekly, SC injection, from Weeks 32 to 52. Rusfertide doses were titrated to maintain hematocrit \\< 45%. Participants who received rusfertide in Part 1a continued at their current dose unless dose adjustment was required. Participants who received placebo in Part 1a started rusfertide at 19 mg. The doses that were administered to Part 1b participants were 9.5, 19, 28, 41, 54, 69 and 82 mg.",
   "interventionNames": [
    "Drug: Rusfertide"
   ]
  },
  {
   "label": "Part 2: Long Term Extension Period: Rusfertide",
   "type": "EXPERIMENTAL",
   "description": "Participants received rusfertide once weekly, SC injection, from Weeks 52 to 156. Rusfertide doses were titrated to maintain hematocrit \\< 45%. The doses that were administered to Part 2 participants were 9.5, 19, 28, 41, 54, 69, 82, 95 and 108 mg. For weekly doses greater than (\\>) 90 mg, the dose of rusfertide was and will be divided into 2 doses administered 3 to 4 days apart.",
   "interventionNames": [
    "Drug: Rusfertide"
   ]
  },
  {
   "label": "Part 3: Treatment Extension Period: Rusfertide",
   "type": "EXPERIMENTAL",
   "description": "Participants will receive rusfertide once weekly, SC injection, from Week 156 to the end of the study (approximately 5 years). Rusfertide doses will be titrated to maintain hematocrit \\< 45%. The doses that will be administered to Part 3 participants are 9.5, 19, 28, 41, 54, 69, 82, 95 and 108 mg. For weekly doses \\> 90 mg, the dose of rusfertide will be divided into 2 doses administered 3 to 4 days apart.",
   "interventionNames": [
    "Drug: Rusfertide"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Rusfertide",
   "description": "Rusfertide SC injection",
   "armGroupLabels": [
    "Part 1a: Randomized, Double-Blind Period: Rusfertide",
    "Part 1b: Open-Label Treatment Period: Rusfertide",
    "Part 2: Long Term Extension Period: Rusfertide",
    "Part 3: Treatment Extension Period: Rusfertide"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "Rusfertide-matching placebo SC injection",
   "armGroupLabels": [
    "Part 1a: Randomized, Double-Blind Period: Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Part 1a: Percentage of Participants Who Achieved Response",
   "description": "Response was defined as absence of phlebotomy eligibility. Phlebotomy eligibility was defined as either: 1) A confirmed hematocrit (HCT) greater than or equal to (≥) 45% that was at least 3% higher than the baseline HCT, where confirmation was defined as 2 consecutive HCT assessments that were ≥ 45% and at least 3% higher than the baseline HCT, or 2) HCT ≥ 48%.",
   "timeFrame": "From Weeks 20 to 32"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Part 1a: Number of Phlebotomies",
   "timeFrame": "Baseline to Week 32"
  },
  {
   "measure": "Part 1a: Percentage of Participants With All Hematocrit Values < 45%",
   "timeFrame": "Baseline to Week 32"
  },
  {
   "measure": "Part 1a: Change From Baseline in the Patient Reported Outcomes Measurement Information System (PROMIS) Fatigue Short Form 8a Total T-score",
   "description": "The PROMIS Fatigue SF 8a T-score will be obtained via the item-response theory (IRT) response-pattern scoring approach using the PROMIS Scoring Service available at https://www.assessmentcenter.net/ac\\_scoringservice. It is an National Institutes of Health (NIH)-developed fatigue survey of 8 items that asks the participant about fatigue experience and impact over the past 7 days. Each item will be scored on a 5-point Likert scale (1=never/not at all to 5=almost always/very much). Raw scores (range: 8-40) will be converted into standardized T scores (range: 34.1-80.9), with higher scores indicating greater fatigue severity. A negative change from baseline indicates an improvement.",
   "timeFrame": "Baseline, Week 32"
  },
  {
   "measure": "Part 1a: Change From Baseline in the Myelofibrosis Symptom Assessment Form (MFSAF) Version 4.0 Total Symptom Score-7 (TSS7) Items",
   "description": "The MFSAF version 4.0 (v4.0) TSS7 is a questionnaire developed by the Patient-Reported Outcome (PRO) Consortium's Myelofibrosis Working Group that focuses on the 7 core symptoms of myelofibrosis: fatigue, night sweats, pruritus, abdominal discomfort, pain under the ribs on the left side, early satiety, and bone pain. It includes 7 items on a 0 (absent) to 10 (worst imaginable) numeric rating scale. A higher score indicates worse symptoms. A negative change from baseline indicates an improvement.",
   "timeFrame": "Baseline, Week 32"
  },
