{
 "nctId": "NCT04959032",
 "briefTitle": "Lumateperone for the Prevention of Relapse in Patients With Schizophrenia",
 "officialTitle": "A Randomized, Double-blind, Placebo-controlled, Parallel-group Study of Lumateperone for the Prevention of Relapse in Patients With Schizophrenia",
 "leadSponsor": {
  "name": "Intra-Cellular Therapies, Inc.",
  "class": "INDUSTRY"
 },
 "startDate": "2021-07-08",
 "firstRegistered": "2021-06-30",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Schizophrenia"
 ],
 "keywords": [
  "Schizophrenia",
  "Relapse Prevention",
  "Maintenance Design"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 592,
 "briefSummary": "This is a multicenter, randomized, double-blind, placebo-controlled, parallel-group, fixed-dose study in adult patients with a primary diagnosis of schizophrenia according to criteria of the Diagnostic and Statistical Manual of Mental Disorders, Fifth Edition, (DSM-5).",
 "detailedDescription": "The study will be conducted in the following 5 phases:\n\n* A no-drug Screening Phase up to 7 days in duration during which patient eligibility will be assessed;\n* A 6-week, open-label Run-in Phase (RIP) during which all patients will receive oral lumateperone 42 mg/day;\n* A 12-week, open-label Stabilization Phase (SP) during which all patients will receive oral lumateperone 42 mg/day;\n* A Double-blind Treatment Phase (DBTP) 26 weeks in duration during which patients receive either lumateperone 42 mg or placebo (1:1 ratio);\n* A 2-week Safety Follow-up (SFU) Phase.",
 "arms": [
  {
   "label": "Lumateperone 42 mg",
   "type": "EXPERIMENTAL",
   "interventionNames": [
    "Drug: Lumateperone 42 mg"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "interventionNames": [
    "Drug: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Lumateperone 42 mg",
   "description": "Lumateperone 42 mg capsules administered orally, once daily.",
   "armGroupLabels": [
    "Lumateperone 42 mg"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "Matching capsules administered orally, once daily.",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Time to First Symptom Relapse During the Double-blind Treatment Phase",
   "description": "Relapse during the DBTP was defined as meeting any one of the following criteria:\n\n* Psychiatric hospitalization or need for increased level of psychiatric care due to worsening of the patient's underlying condition;\n* Increase in PANSS total score by ≥ 30% for patients who scored 50 or higher at randomization or a 10-point or more increase in PANSS total score for patients who scored less than 50 at randomization ;\n* Increase in the Visit 14 CGI-S score by 2 or more points;\n* Deliberate self-injury or aggressive/violent behavior;\n* Any suicidal ideation or homicidal ideation;\n* Score of greater than 4 on 1 or more of the following PANSS items: P1, P2, P3, P6, P7, G8 or G14",
   "timeFrame": "Number of days from the randomization date to the first relapse date up to 26 weeks."
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Male or female, 18 to 60 years of age, inclusive.\n* Current diagnosis of schizophrenia according to DSM-5 criteria as determined by the modified Structured Clinical Interview for DSM-5 (modified SCID-5).\n* Diagnosis of schizophrenia for a minimum of 1 year before Visit 1.\n* Current psychotic episode \\< 4 weeks duration at Visit 1.\n* PANSS total score ≥ 70 and ≤ 120 at Visit 1 and Visit 2.\n* Rating of at least 4 (moderate) on at least two of the following four PANSS positive symptoms: delusions (P1), hallucinatory behavior (P3), conceptual disorganization (P2), suspiciousness/persecution (P6) at Visit 1 and Visit 2.\n* Patient must identify a caregiver who provides consents to participate in the study.\n* In the opinion of the Investigator, the patient has significant risk for suicidal behavior during the course of his/her participation in the study.\n\nExclusion Criteria:\n\n* Currently meeting DSM-5 criteria for any of the following:\n\nSchizoaffective disorder, schizophreniform disorder, and other psychotic disorders; Bipolar I or Bipolar II Disorder; Intellectual developmental disorder, delirium, dementia, amnestic and other cognitive disorders; Known or suspected borderline or antisocial personality disorder or other DSM 5 personality disorder of sufficient severity to interfere with participation in this study; Substance use disorder (other than nicotine) within the 3 months prior to Visit 1 of this study.\n\n* Patients in their first episode of psychosis.\n* Treatment-resistant schizophrenia over the last 2 years, defined as little or no symptomatic response to at least 2 courses of antipsychotic treatment of an adequate duration (at least 6 weeks) and at a therapeutic dose (according to the package insert for the antipsychotic treatment).",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "60 Years"
 },
 "siteCount": 43,
 "countries": [
  "United States",
  "Bulgaria",
  "Poland",
  "Serbia"
 ]
}

