{
 "nctId": "NCT05237960",
 "briefTitle": "Metformin for the Prevention of Oral Cancer in Patients With Oral Leukoplakia or Erythroplakia",
 "officialTitle": "M4OC-Prevent 2.0: Phase IIb Trial of Metformin for Oral Cancer Prevention",
 "leadSponsor": {
  "name": "University of Arizona",
  "class": "OTHER"
 },
 "collaborators": [
  {
   "name": "National Cancer Institute (NCI)",
   "class": "NIH"
  }
 ],
 "startDate": "2023-01-12",
 "firstRegistered": "2022-02-04",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Erythroplakia",
  "Oral Leukoplakia"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "PREVENTION",
  "maskingInfo": {
   "masking": "DOUBLE",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 34,
 "briefSummary": "This phase IIb trial tests whether metformin works in preventing oral cancer in patients with oral leukoplakia (white patches) or erythroplakia (red patches). Metformin is in a class of drugs called biguanides. Metformin helps to control the amount of glucose (sugar) in the blood. It decreases the amount of glucose patients absorb from food and the amount of glucose made by the liver. Metformin also increases the body's response to insulin, a natural substance that controls the amount of glucose in the blood. This trial may help researchers determine if metformin can stop changes in the mouth that are related to pre-cancer growths in the mouth.",
 "detailedDescription": "PRIMARY OBJECTIVE:\n\nI. To determine the histological response to metformin hydrochloride (metformin) intervention in the target lesion.\n\nSECONDARY OBJECTIVES:\n\nI. Clinical response to metformin intervention in the target lesion. II. Effect of metformin on cell proliferation (Ki67) and its molecular targets (pS6 and nuclear YAP) in the target lesion.\n\nIII. Metformin effect on serum metabolic markers (C-peptide, glucose and HbA1c).\n\nIV. Trough plasma metformin concentrations.\n\nEXPLORATORY OBJECTIVES:\n\nI. Expression of dysregulated molecular mechanisms in the target lesion, including, in order of priority, p53, PTEN, p16, EGFR, and pEGFR.\n\nII. Immune cell infiltration and markers of inflammation in the target lesion. III. Analysis of genomic alterations in the target lesion and blood deoxyribonucleic acid (DNA).\n\nIV. Microbiome in oral rinses.\n\nOUTLINE: Patients are randomized to 1 of 2 arms.\n\nARM I: Patients receive extended release metformin hydrochloride orally (PO) once daily (QD) for 24 weeks in the absence of disease progression or unacceptable toxicity. Patients also undergo collection of blood and biopsy at baseline and week 24.\n\nARM II: Patients receive a placebo PO QD for 24 weeks in the absence of disease progression or unacceptable toxicity. Patients also undergo collection of blood and biopsy at baseline and week 24.\n\nAfter completion of study treatment, patients are followed for up to 3 weeks.",
 "arms": [
  {
   "label": "Arm I (extended release metformin)",
   "type": "EXPERIMENTAL",
   "description": "Patients receive extended release metformin hydrochloride PO QD for 24 weeks in the absence of disease progression or unacceptable toxicity. Patients will also undergo biopsies and blood collections on study.",
   "interventionNames": [
    "Procedure: Biopsy",
    "Procedure: Biospecimen Collection",
    "Drug: Extended Release Metformin Hydrochloride"
   ]
  },
  {
   "label": "Arm II (placebo)",
   "type": "PLACEBO_COMPARATOR",
   "description": "Patients receive a placebo PO QD for 24 weeks in the absence of disease progression or unacceptable toxicity. Patients will also undergo biopsies and blood collections on study.",
   "interventionNames": [
    "Procedure: Biopsy",
    "Procedure: Biospecimen Collection",
    "Drug: Placebo Administration"
   ]
  }
 ],
 "interventions": [
