forecastInput:
{
 "nctId": "NCT03310125",
 "briefTitle": "Colchicine For The Prevention Of Perioperative Atrial Fibrillation In Patients Undergoing Thoracic Surgery (COP-AF)",
 "officialTitle": "Colchicine For The Prevention Of Perioperative Atrial Fibrillation In Patients Undergoing Thoracic Surgery (COP-AF)",
 "leadSponsor": {
  "name": "Population Health Research Institute",
  "class": "OTHER"
 },
 "collaborators": [
  {
   "name": "Hamilton Health Sciences Corporation",
   "class": "OTHER"
  }
 ],
 "startDate": "2018-02-14",
 "firstRegistered": "2017-10-10",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Atrial Fibrillation",
  "Atrial Flutter",
  "Myocardial Injury After Non-Cardiac Surgery"
 ],
 "keywords": [
  "Atrial Fibrillation",
  "Inflammation",
  "Thoracic Surgery",
  "Randomized",
  "Colchicine",
  "Myocardial Injury"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "PREVENTION",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 3209,
 "briefSummary": "The prevention of perioperative atrial fibrillation (AF) and myocardial injury after non-cardiac surgery (MINS) has the potential to reduce mortality, stroke, and hospital stays in patients undergoing major thoracic surgery. Data from cardiac surgery patients suggest that prevention of perioperative atrial fibrillation using an anti-inflammatory agent, such as colchicine, is feasible. The COP-AF trial will assess whether the administration of oral colchicine will reduce the incidence of perioperative atrial fibrillation and myocardial injury after non-cardiac surgery in patients undergoing major thoracic surgery.",
 "detailedDescription": "Perioperative atrial fibrillation (AF) and myocardial injury after noncardiac surgery (MINS) are among the most common serious complications occurring after thoracic surgery. AF is the most common perioperative cardiac arrhythmia. The incidence of perioperative AF in patients undergoing major thoracic surgery ranges from 10% in low-risk patients to as high as 20% in high-risk patients. The course of patients with perioperative AF is frequently complicated by hemodynamic instability, problems with managing anticoagulation in the early postoperative period, prolonged intensive care unit and hospital stays, and increased costs. Patients who develop perioperative AF (POAF) or MINS also have a significantly increased risk of death and stroke.\n\nColchicine is an inexpensive drug and a highly effective anti-inflammatory agent that holds great potential for preventing POAF and MINS in patients undergoing thoracic surgery. Data from cardiac surgery patients suggest that prevention of POAF using colchicine is feasible, but whether this concept is also applicable to patients undergoing thoracic surgery, where the risk of POAF is lower and underlying mechanisms may be different, is currently unclear. The 'Colchicine for the prevention of perioperative AF' (COP-AF) trial has been designed as a large randomized, double blind, placebo controlled trial to determine whether colchicine, a potent, safe and inexpensive anti-inflammatory drug, lowers the risk of perioperative AF, MINS, and other inflammatory complications in patients undergoing thoracic surgery. The primary objective of this trial is to determine whether a 10-day course of colchicine 0.5mg twice daily reduces the incidence of perioperative AF and MINS within 14 days after thoracic surgery.",
 "arms": [
  {
   "label": "Active Colchicine",
   "type": "EXPERIMENTAL",
   "description": "Oral colchicine 0·5 mg twice daily, starting within 4 h before surgery and continuing for 10 days",
   "interventionNames": [
    "Drug: Active Colchicine"
   ]
  },
  {
   "label": "Active Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Oral placebo 0·5 mg twice daily, starting within 4 h before surgery and continuing for 10 days.",
   "interventionNames": [
    "Drug: Active Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Active Colchicine",
   "description": "Oral colchicine 0·5 mg twice daily, starting within 4 h before surgery and continuing for 10 days.",
   "armGroupLabels": [
    "Active Colchicine"
   ]
  },
  {
   "type": "DRUG",
   "name": "Active Placebo",
   "description": "Oral placebo 0·5 mg twice daily, starting within 4 h before surgery and continuing for 10 days.",
   "armGroupLabels": [
    "Active Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Number of Participants With Clinically Important Perioperative Atrial Fibrillation",
   "description": "Clinically important perioperative atrial fibrillation was defined as atrial fibrillation or atrial flutter that results in angina, heart failure, or symptomatic hypotension, or that requires treatment with a rate-controlling drug, anti-arrhythmic drug, or electrical cardioversion.",
   "timeFrame": "14 days after randomisation"
  },
  {
   "measure": "Number of Participants With Myocardial Injury After Non-cardiac Surgery (MINS)",
   "timeFrame": "14 days after randomisation"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Number of Participants With Composite of All-cause Death, Non-fatal MINS, and Non-fatal Stroke",
   "timeFrame": "14 days after randomisation"
  },
  {
   "measure": "Number of Participants With Composite of All-cause Death, Non-fatal Myocardial Infarction, and Non-fatal Stroke",
   "timeFrame": "14 days after randomisation"
  },
  {
   "measure": "Number of Participants With MINS Not Fulfilling the Fourth Universal Definition of Myocardial Infarction",
   "timeFrame": "14 days after randomisation"
  },
  {
   "measure": "Number of Participants With Myocardial Infarction",
   "timeFrame": "14 days after randomisation"
  },
  {
   "measure": "Time to Chest Tube Removal, Days",
   "timeFrame": "14 days after randomisation"
  },
  {
   "measure": "Days in Hospital",
   "timeFrame": "14 days after randomisation"
  },
  {
   "measure": "Nights in Step-down Unit",
   "timeFrame": "14 days after randomisation"
  },
  {
   "measure": "Nights in Intensive Care Unit",
   "timeFrame": "14 days after randomisation"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\nPatients are eligible if they:\n\n1. are undergoing thoracic surgery with general anesthesia;\n2. are greater than or equal to 55 years of age at the time of randomization;\n3. are expected to require at least an overnight hospital admission after surgery; and\n4. provide written informed consent to participate.\n\nExclusion Criteria:\n\nWe will exclude patients who meet any of the following criteria:\n\n1. patients with a prior history of documented AF;\n2. patients currently taking anti-arrhythmic medication other than β-blockers, calcium channels blockers or digoxin;\n3. patients undergoing minor thoracic interventions/procedures (i.e., minor chest-wall surgeries, chest tube insertions, or needle pleural/lung biopsies);\n4. patients with contraindications to colchicine (i.e., allergy to colchicine, myelodysplastic disorders, or an estimated glomerular filtration rate \\[eGFR\\] \\<30 mL/min/1.73m);\n5. patients not expected to take oral medications for \\>24 hours after surgery (e.g., esophagectomy);\n6. patients scheduled for lung transplantation;\n7. patients currently taking non-study colchicine before surgery;\n8. patients with severe hepatic dysfunction;\n9. patients with aplastic anemia;\n10. women of childbearing potential who are not taking effective contraception, pregnant or breast-feeding;\n11. patients who took within the last 14 days or scheduled to take during the first 10 days after surgery clarithromycin, erythromycin, telithromycin, cyclosporine, ketoconazole, or itraconazole\\* (While systemic administration of these medications is contraindicated, patients with local administration only (e.g., eye drops, creams) are eligible for the trial);\n12. human immunodeficiency virus (HIV) patients treated with antiretroviral therapy; or\n13. patients scheduled for thoracoscopic lung wedge resection only†. (Patients scheduled for multiple thoracoscopic lung wedge resection only are eligible for inclusion).",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "55 Years"
 },
 "siteCount": 46,
 "countries": [
  "United States",
  "Austria",
  "Belgium",
  "Canada",
  "Colombia",
  "Hong Kong",
  "Italy",
  "Malaysia",
  "Pakistan",
  "Spain",
  "Switzerland"
 ]
}

