 "detailedDescription": "This is a phase 3 double blind, placebo controlled study evaluating the efficacy and safety of AL001 administered intravenously in participants at risk for or with frontotemporal dementia due to heterozygous mutations in the progranulin gene. Study completion marks the end of the open label extension period following the 96-week blinded portion of the study.",
 "arms": [
  {
   "label": "Part 1 Blinded - AL001",
   "type": "EXPERIMENTAL",
   "description": "Participants receive AL001 60 mg/kg administered by intravenous (IV) infusion every 4 weeks during the double-blind treatment period.",
   "interventionNames": [
    "Drug: Part 1 Blinded - AL001"
   ]
  },
  {
   "label": "Part 1 Blinded - Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Participants receive placebo administered by intravenous (IV) infusion every 4 weeks during the double-blind treatment period.",
   "interventionNames": [
    "Drug: Part 1 Blinded - Placebo"
   ]
  },
  {
   "label": "Part 2 (OLE Treatment) - AL001",
   "type": "EXPERIMENTAL",
   "description": "Participants who received AL001 during the double-blind treatment period and enroll in the optional open-label extension receive AL001 60 mg/kg administered by intravenous (IV) infusion every 4 weeks.",
   "interventionNames": [
    "Drug: Part 2 (OLE Treatment) - AL001"
   ]
  },
  {
   "label": "Part 2 (OLE Treatment) - Placebo Switched to AL001",
   "type": "EXPERIMENTAL",
   "description": "Participants who received placebo during the double-blind treatment period and enroll in the optional open-label extension receive AL001 60 mg/kg administered by intravenous (IV) infusion every 4 weeks.",
   "interventionNames": [
    "Drug: Part 2 (OLE Treatment) - Placebo Switched to AL001"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Part 1 Blinded - AL001",
   "description": "Administered via intravenous (IV) infusion",
   "armGroupLabels": [
    "Part 1 Blinded - AL001"
   ]
  },
  {
   "type": "DRUG",
   "name": "Part 1 Blinded - Placebo",
   "description": "Administered via intravenous (IV) infusion",
   "armGroupLabels": [
    "Part 1 Blinded - Placebo"
   ]
  },
  {
   "type": "DRUG",
   "name": "Part 2 (OLE Treatment) - AL001",
   "description": "Administered via intravenous (IV) infusion",
   "armGroupLabels": [
    "Part 2 (OLE Treatment) - AL001"
   ]
  },
  {
   "type": "DRUG",
   "name": "Part 2 (OLE Treatment) - Placebo Switched to AL001",
   "description": "Administered via intravenous (IV) infusion",
   "armGroupLabels": [
    "Part 2 (OLE Treatment) - Placebo Switched to AL001"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Part 1 Double Blind - Evaluation of Efficacy of AL001 Compared With Placebo as Measured by the CDR® Plus NACC FTLD-SB in Symptomatic Patients",
   "description": "Part 1 Primary Endpoint - Change from baseline to Weeks 48, 72, and 96 in the CDR® plus NACC FTLD-SB.\n\nThe Clinical Dementia Rating Dementia Staging Instrument PLUS National Alzheimer's Disease Coordinating Center frontotemporal lobar degeneration Behavior \\& Language Domains Sum of Boxes (CDR® plus NACC FTLD-SB) is administered by a healthcare professional and based on individual ratings of the eight domains: memory, orientation, judgment and problem solving, community affairs, home and hobbies, personal care, language and behavior. Impairment is scored on a scale in which none = 0, questionable = 0.5, mild = 1, moderate = 2 and severe = 3. The 8 individual domain ratings, or \"box scores\", were added together to give the CDR® plus NACC FTLD-SB which ranges from 0-24. Higher score indicates severe impairment.",
   "timeFrame": "Through study completion, on average up to 96 weeks"
  },
  {
   "measure": "Part 1 Double Blind (Co-Primary US Endpoint) - Evaluation of the Treatment Effect of AL001 Compared With Placebo as Measured by Pharmacodynamic and Disease Pathology Biomarkers in Symptomatic Patients",
   "description": "Geometric Mean Fold Change from baseline to Week 96 in PGRN concentrations in plasma",
   "timeFrame": "Baseline to 96 weeks"
  },
  {
   "measure": "Part 2 OLE - To Assess the Long-term Safety and Tolerability of AL001 in Participants Who Have Completed Part 1 of the Study",
   "description": "Part 2 OLE Primary Endpoint - Incidence, nature, and severity of AEs and SAEs in Part 2 OLE",
   "timeFrame": "96 weeks"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Part 1 Double Blind - Evaluation of Efficacy of AL001 Compared With Placebo in Symptomatic Participants as Measured by CGI-S",
   "description": "Change from baseline to Weeks 48, 72, and 96 on the CGI-S. The CGI-S is used by a clinician to rate the severity of a participant's disease relative to the clinician's past experience with patients who have the same disease using an ordinal scale ranging from 1=normal, not at all ill; 2=borderline ill; 3=mildly ill; 4=moderately ill; 5=markedly ill; 6=severely ill; and 7=among the most extremely ill patients. Higher scores indicate worsening.",
   "timeFrame": "Baseline to 96 weeks"
  },
  {
   "measure": "Part 1 Double Blind - Evaluation of Efficacy of AL001 Compared With Placebo in Symptomatic Participants as Measured by CGI-I",
   "description": "Actual values at Weeks 48, 72, and 96 on the CGI-I. The CGI-I is used by a clinician to rate how much a participant's disease has improved or worsened relative to baseline using an ordinal scale ranging from 1=very much improved; 2=much improved; 3=minimally improved; 4=no change from baseline; 5=minimally worse; 6= much worse; and 7=very much worse. Higher scores indicate worsening.",
   "timeFrame": "Baseline to 96 weeks"
  },
  {
   "measure": "Part 1 Double Blind - Evaluation of Efficacy of AL001 Compared With Placebo in Symptomatic Participants as Measured by Repeatable Battery for the Assessment of Neuropsychological Status (RBANS) Score",
   "description": "Change from baseline to Weeks 48, 72, and 96 on the RBANS. RBANS is 20 to 25 minute battery developed for cognitive assessment, detection, and characterization of dementia. RBANS includes 12 subtests that measure following 5 indices: (1)Attention Index, composed of Digit Span and Coding; (2)Language Index, consisting of Picture Naming and Semantic Fluency subtests; (3)Visuospatial/Construction Index, made up of Figure Copy and Line Orientation subtests; (4)Immediate Memory Index, composed of List Learning and Story Memory subtests, and (5)Delayed Memory Index, consisting of List Recall, List Recognition, Story Recall, and Figure Recall subtests. Completion of RBANS yields 5 index scores based on participant performance on various subtests, as well as a composite Total Index score for battery. Total index scores range from 40 to 160, and are normalized to a mean of 100 and standard deviation (SD) of 15. Higher scores indicate less impairment.",
   "timeFrame": "Baseline to 96 weeks"
  },
  {
   "measure": "Part 1 Double Blind - Evaluation of the Safety and Tolerability of AL001 Compared With Placebo as Measured by Safety Assessments",
   "description": "Incidence of adverse events",
   "timeFrame": "Baseline to 96 weeks"
  },
  {
   "measure": "Part 1 Double Blind: Clinical Progression as Measured by Frontotemporal Dementia Rating Scale (FRS) Logit Score in Symptomatic Participants",
   "description": "The FRS is a 30-item scale with item responses of 'All the time,' 'Sometimes,' 'Never,' or 'Not applicable' for each item. The total percentage score is calculated as the number of items with a response of 'Never,' divided by the number of applicable items, excluding those marked 'not applicable.' The percentage score ranges from 0 to 100, inclusive, with higher scores indicating better function (fewer behavioral/functional problems) and lower scores indicating worse function. The percentage score is converted to a logit score ranging from -6.66 to 5.39 using a look-up table defined as part of the FRS instrument, where a higher (more positive) logit score indicates better function/less disease severity (5.39 = normal) and a lower (more negative) logit score indicates worse function/greater disease severity (-6.66 = advanced/profound impairment). A decrease in logit score over time reflects clinical progression",
   "timeFrame": "baseline to 96 weeks"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Persons with a progranulin gene mutation and at risk of developing FTD symptoms as evidenced by a biomarker, or persons with a progranulin gene mutation and diagnosed with FTD.\n* If symptomatic, one or more of the criteria for the diagnosis of possible behavioral variant FTD, or a diagnosis of Primary Progressive Aphasia.\n* Study partner who consents to study participation and who cares for/visits the participant daily for at least 5 hours per week.\n* Written informed consent must be obtained and documented (from the participant or, where jurisdictions allow it, from their legal decision maker).\n\nExclusion Criteria:\n\n* Dementia due to a condition other than FTD including, but not limited to, Alzheimer's disease, Parkinson's disease, dementia with Lewy bodies, Huntington disease, or vascular dementia.\n* Known history of severe allergic, anaphylactic, or other hypersensitivity reactions to chimeric, human, or humanized antibodies or fusion proteins.\n* Current uncontrolled hypertension, diabetes mellitus or thyroid disease. Clinically significant heart disease, liver disease or kidney disease. History or evidence of clinically significant brain disease other than FTD.\n* Females who are pregnant or breastfeeding, or planning to conceive within the study period.\n* Any experimental vaccine or gene therapy.\n* History of cancer, unless in remission or stable/adequately controlled.\n* Current use of anticoagulant medications (e.g., coumadin, heparinoids, apixaban).\n* Residence in a skilled nursing facility, convalescent home, or long term care facility at screening; or requires continuous nursing care.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "25 Years",
  "maximumAge": "85 Years"
 },
 "siteCount": 44,
