forecastInput:
{
 "nctId": "NCT05305664",
 "briefTitle": "A Multicenter Trial Assessing the Impact of Lipoprotein(a) Lowering With Pelacarsen (TQJ230) on the Rate of Weekly Lipoprotein Apheresis Sessions in Patients With Hyperlipoproteinemia(a) and Established Cardiovascular Disease in Germany",
 "officialTitle": "A Randomized, Double-blind, Placebo-controlled, Multicenter Trial Assessing the Reduction of the Rate of Lipoprotein Apheresis After Treatment With Pelacarsen (TQJ230) Compared to Placebo in Patients With Hyperlipoproteinemia(a) and Established Cardiovascular Disease Undergoing Weekly Lipoprotein Apheresis in Germany",
 "leadSponsor": {
  "name": "Novartis Pharmaceuticals",
  "class": "INDUSTRY"
 },
 "startDate": "2022-08-19",
 "firstRegistered": "2022-03-14",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Hyperlipoproteinemia(a)"
 ],
 "keywords": [
  "Lipoprotein (a)",
  "cardiovascular disease",
  "apheresis",
  "TQJ230",
  "pelacarsen"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 51,
 "briefSummary": "Phase III study to test the hypothesis that treatment with pelacarsen (TQJ230) 80 mg Q4W compared to placebo significantly reduces the rate of lipoprotein apheresis in patients with hyperlipoproteinemia (a) and established cardiovascular disease currently undergoing lipoprotein apheresis in Germany on a weekly schedule.",
 "detailedDescription": "Lipoprotein apheresis to date is the only approved therapeutic option for cardiovascular (CV) risk reduction in patients with severely elevated Lp(a) levels in Germany. Lipoprotein apheresis is an expensive, burdensome, and time-consuming procedure. The current study (CTQJ230A12302) investigated if treatment with pelacarsen (TQJ230) 80 mg Q4W vs placebo reduces the rate of lipoprotein apheresis in patients with hyperlipoproteinemia(a) and established CV disease",
 "arms": [
  {
   "label": "Pelacarsen (TQJ230)",
   "type": "EXPERIMENTAL",
   "description": "Pelacarsen (TQJ230) 80 mg s.c. Q4W",
   "interventionNames": [
    "Drug: Pelacarsen (TQJ230) 80 mg s.c."
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Placebo to Pelacarsen s.c. Q4W",
   "interventionNames": [
    "Drug: Corresponding Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Pelacarsen (TQJ230) 80 mg s.c.",
   "description": "Pelacarsen (TQJ230) 80 mg s.c. Q4W",
   "armGroupLabels": [
    "Pelacarsen (TQJ230)"
   ],
   "otherNames": [
    "TQJ230"
   ]
  },
  {
   "type": "DRUG",
   "name": "Corresponding Placebo",
   "description": "Placebo to Pelacarsen",
   "armGroupLabels": [
    "Placebo"
   ],
   "otherNames": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Rate of Lipoprotein Apheresis Sessions Performed Over 52 Weeks Normalized to the Weekly Lipoprotein Apheresis Schedule",
   "description": "Rate (proportion) of apheresis sessions was calculated as the number of actual lipoprotein apheresis (LA) sessions received, divided by the number of planned LA sessions during the 52-week period, which is 52 for patients who completed all study visits, or pro-rated for those who discontinued early. This rate could range from 0 to 1, with 0 indicating that the patient had skipped all planned LA sessions, and 1 indicating that the patient had received all planned sessions. Multiple imputation for missing Lp(a) data was performed, and missing apheresis data was imputed.",
   "timeFrame": "Up to Week 52"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Time to Lipoprotein Apheresis Avoidance",
   "description": "Lipoprotein apheresis avoidance is defined as at least 24 consecutive weeks of no lipoprotein apheresis until end of study.",
   "timeFrame": "From randomization up to Week 52"
  },
  {
   "measure": "Number of Participants With Total Lipoprotein Apheresis Avoidance From Week 12 to Week 52",
   "description": "Total lipoprotein apheresis avoidance is defined as no apheresis performed from Week 12 to Week 52.",
   "timeFrame": "Week 12 up to Week 52"
  },
  {
   "measure": "Change From Baseline to Week 52 in the Log-transformed Lp(a) Reported as mg/dL",
   "description": "Week 52 / Baseline ratio in Lp(a) of pelacarsen (TQJ230) vs placebo reported as particle mass (mg/dL). Baseline Lp(a) was defined as the last non-missing pre-lipoprotein apheresis assessment prior to the first dose of randomized study drug.",
   "timeFrame": "Baseline, week 52"
  },
  {
   "measure": "Change From Baseline to Week 52 in the Log-transformed Lp(a) Reported as Nmol/L",
   "description": "Week 52 / Baseline ratio in Lp(a) of pelacarsen (TQJ230) vs placebo reported as molar concentration (nmol/L). Baseline Lp(a) was defined as the last non-missing pre-lipoprotein apheresis assessment prior to the first dose of randomized study drug.",
   "timeFrame": "Baseline, week 52"
  }
 ],
 "eligibility": {
