   "timeFrame": "Baseline, Days 8, 15, 22, 29, 36, 43, 50, 57, 64, 71, 78, 85, 92, 99, 106, 113, 141, 169 and 197"
  },
  {
   "measure": "Number of Participants With Gastrointestinal (GI) Adverse Event of Clinical Interest (AECI): Part A",
   "description": "An adverse event (AE) was defined as any untoward medical occurrence in a participant administered an investigational product and which did not necessarily have a causal relationship with the treatment. Gastrointestinal AECIs included nausea, vomiting and diarrhea.",
   "timeFrame": "From Day 1 of dosing up to 28 days after last dose for Part A"
  },
  {
   "measure": "Number of Participants With Treatment Related Gastrointestinal AECIs: Part A",
   "description": "An AE was defined as any untoward medical occurrence in a participant administered an investigational product and which did not necessarily have a causal relationship with the treatment. Gastrointestinal AECIs included nausea, vomiting and diarrhea. Treatment related gastrointestinal AECIs were GI AECIs that were related to study drug and relatedness was judged by investigator.",
   "timeFrame": "From Day 1 of dosing up to 28 days after last dose for Part A"
  },
  {
   "measure": "Number of Participants With Gastrointestinal AECI and Treatment Related AECIs by Severity: Part A",
   "description": "An AE was defined as any untoward medical occurrence in a participant administered an investigational product and which did not necessarily have a causal relationship with the treatment. Gastrointestinal AECIs included nausea, vomiting and diarrhea. Treatment related GI AECIs were GI AECIs that were related to study drug and relatedness was judged by investigator. Severity was assessed as mild: asymptomatic or mild symptoms, clinical or diagnostic observations only, intervention not indicated; moderate: minimal, local or non-invasive intervention indicated, limiting age-appropriate instrumental activities of daily living and severe: medically significant but not immediately life-threatening, hospitalization or prolongation of hospitalization indicated, disabling, limiting self-care activities of daily living or life-threatening consequences, urgent intervention indicated or death related to an AE.",
   "timeFrame": "From Day 1 of dosing up to 28 days after last dose for Part A"
  },
  {
   "measure": "Number of Participants With Treatment Emergent Adverse Events (TEAEs) and Treatment-Related TEAEs: Part A",
   "description": "An AE was defined as any untoward medical occurrence in a participant administered an investigational product and which does not necessarily have a causal relationship with the treatment. A TEAE was defined as any AE which on or after exposure to study treatment. Treatment related TEAEs were TEAEs that were related to study drug and relatedness was judged by investigator.",
