   "measure": "Minimum Observed Concentration (Cmin) of Berobenatide: Part A",
   "timeFrame": "From pre-dose on Day 1 up to 168 hours post-dose"
  },
  {
   "measure": "Area Under the Concentration Versus Time Curve During the Dosing Interval (AUC[0-tau]) of Berobenatide: Part A",
   "description": "AUCtau was area under the concentration versus time curve during the dosing interval (tau), where, tau=168 hours.",
   "timeFrame": "From pre-dose on Day 1 up to 168 hours post-dose"
  },
  {
   "measure": "Maximum Observed Concentration (Cmax) of Berobenatide: Part A",
   "description": "Cmax was observed directly from data.",
   "timeFrame": "From pre-dose on Day 1 up to 168 hours post-dose"
  },
  {
   "measure": "Time to Maximum Concentration (Tmax) of Berobenatide: Part A",
   "timeFrame": "From pre-dose on Day 1 up to 168 hours post-dose"
  },
  {
   "measure": "Plasma Concentration of Berobenatide: Part A",
   "timeFrame": "From pre-dose on Day 1 up to 168 hours post-dose"
  },
  {
   "measure": "Percent Change From Baseline in Body Weight: Part B",
   "timeFrame": "Baseline (last available measurement prior to first dose received in Part A), End of study"
  },
  {
   "measure": "Number of Participants With TEAEs: Part B",
   "description": "An AE was defined as any untoward medical occurrence in a participant administered an investigational product and which does not necessarily have a causal relationship with the treatment. A TEAE was defined as any AE which on or after exposure to study treatment up to 28 days following the last dose.",
   "timeFrame": "From Day 1 of dosing in Part B up to 28 days after last dose for Part B"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Body mass index (BMI) at Screening of:\n\n  * BMI ≥30 kg/m2 and ≤50.0 kg/m2 (can have the weight-related co-morbidities listed below)\n  * BMI ≥27.0 kg/m2 to \\<30.0 kg/m2 with at least one of the following weight-related co-morbidities:\n\n    1. Hypertension: on blood pressure (BP)-lowering medication or having systolic BP ≥130 mmHg or diastolic BP ≥80 mmHg at Screening\n    2. Dyslipidemia: on lipid-lowering medication or having low-density lipoprotein cholesterol (LDL-C) ≥160 mg/dL (4.1 mmol/L) or triglycerides ≥150 mg/dL (1.7 mmol/L), or high-density lipoprotein-cholesterol (HDL-C) \\<40 mg/dL (1.0 mmol/L) for men or HDL-C \\<50 mg/dL (1.3 mmol/L) for women at Screening\n\nStable body weight (increase or decrease ≤5 kg) within 3 months prior to Screening\n\nExclusion Criteria:\n\n* Diagnosis of diabetes (T1DM or T2DM) or glycated hemoglobin A1c (HbA1c) ≥ 6.5% or fasting plasma glucose \\>125 mg/dL.\n* Estimated glomerular filtration rate (eGFR) \\<75 mL/min/1.73 m2\n* History of pancreatitis\n* Family or personal history of medullary thyroid carcinoma (MTC) or multiple endocrine neoplasia syndrome type 2 (MEN-2)\n* History of significant active or unstable major depressive disorder (MDD) or other severe psychiatric disorder within the last 2 years\n* Any lifetime history of a suicide attempt.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "70 Years"
 },
 "siteCount": 2,
 "countries": [
  "United States"
 ]
}

