   ]
  },
  {
   "type": "DRUG",
   "name": "Abreva",
   "description": "Patients will treat their cold sore with Abreva based upon their randomization",
   "armGroupLabels": [
    "Active Comparator (Abreva)"
   ],
   "otherNames": [
    "Docosanol"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Proportion of Subjects Using Acyclovir-penciclovir Cream Versus Those Using the Comparator, Who do Not Progress to Stage 3 (Vesicle) of a Herpes Labialis Outbreak Following UV Radiation Exposure",
   "description": "Number of participants who did not progress to Stage 3 (vesicle) of a UV-induced herpes labialis outbreak following UV radiation exposure.",
   "timeFrame": "up to 25 days per participant"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Time to Healing, Defined as Loss of Hard Crust",
   "description": "Number of days from lesion onset to healing, defined as loss of hard crust, in participants treated with acyclovir-penciclovir cream compared with participants treated with docosanol 10% cream (Abreva).",
   "timeFrame": "up to 25 days per participant"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Understands the requirements of the study and provides written informed consent prior to undergoing any study-related procedures.\n* Subject is a male or female between the ages of 18-80 years old, inclusive.\n* Fitzpatrick skin type II or III.\n* History of at least one year of herpes labialis induced by UV exposure.\n* Able to recall exact location of most common or most recent outbreak.\n* History of at least 50% of cold sore outbreaks occurring with UV (sun) exposure.\n* At least 1 HSV-1 outbreak within the past 12 months.\n* Experiences prodromal symptoms before HSV-1 outbreaks.\n* Subject is willing and able to comply with protocol-specified dosing, visits to the clinic and tracking of pain.\n\nExclusion Criteria:\n\n* Outbreak \\<2 weeks prior to enrollment.\n* History of herpes simplex vaccine.\n* On antiviral suppression within the past 30 days.\n* Requires more than acetaminophen for pain from recurrent HSV outbreaks.\n* On any systemic or topical steroid, immune suppressant or chemotherapeutic agent within the past 14 days.\n* Use of tanning beds, history of sunburn, or beach vacation \\<2 weeks prior to enrollment.\n* History of photosensitivity, lupus erythematosus, or current use of a highly photosensitizing medication in the opinion of the investigator.\n* Current immunosuppressed state due to underlying disease (i.e. HIV infection) concomitant treatment (i.e. chemotherapy).\n* Current upper respiratory tract infection or any active illness that could trigger cold sores or affect overall health of the patient or the assessment of the study agent.\n* Pregnant or intending to become pregnant during the study.\n* Abnormal skin conditions in the area of the recurrent HSV1 outbreaks.\n* Enrolled in another clinical trial within the past 30 days.\n* On any analgesics or NSAIDs that cannot be stopped during the study.\n* Alcohol or drug abuse.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "80 Years"
 },
 "siteCount": 1,
 "countries": [
  "United States"
 ]
}

