 "primaryOutcomes": [
  {
   "measure": "Progression-Free Survival (PFS) as Assessed by Investigator Per Response Evaluation Criteria in Solid Tumors (RECIST) Version (v) 1.1",
   "description": "PFS: time from randomization to the first documented disease progression (PD) (as assessed by investigator per RECIST 1.1) or death from any cause, whichever occurred first. PD: \\>=20% increase in sum of diameters of target lesions, taking as reference the smallest sum of diameter recorded since the treatment started or the appearance of 1 or more new lesions. Participants without documentation of PD/ death at the time of analysis, were censored at date of last tumor assessment with an overall response of complete response (CR), partial response (PR), stable disease (SD), non-CR/non-PD or no evidence of disease (NED). CR: disappearance of all target lesions; PR: \\>=30% decrease in the sum of the diameters of target lesions, taking as reference the baseline sum of diameters; SD: neither sufficient shrinkage to qualify for PR nor sufficient increase to qualify for PD, taking as reference the smallest sum of diameter since the treatment started. Kaplan-Meier method was used for analysis.",
   "timeFrame": "From randomization until the first documentation of PD or death from any cause or censoring date, whichever occurred first (maximum treatment exposure was of 41.3 months)"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Overall Survival (OS)",
   "description": "OS: time from randomization to death due to any cause. For a participant who would not known to have died by the end of study follow-up, observation of OS would be censored on the date the participant was last known to be alive (i.e., the date of last contact).",
   "timeFrame": "From the date of randomization until date of death or censoring date (approximately 66.7 months)"
  },
  {
   "measure": "PFS as Assessed by Blinded Independent Central Review (BICR) Per RECIST v1.1",
   "description": "PFS per BICR was defined as the time from the date of randomization to the documented disease progression assessed by BICR according to RECIST v1.1 or death from any cause, whichever occurred first. As per RECIST v1.1, PD: \\>=20% increase in sum of diameter of target lesions, taking as reference the smallest sum of diameters recorded since treatment started or appearance of 1 or more new lesions, unequivocal progression of existing non-target lesions. Participants without documentation of PD/ death were censored at date of last tumor assessment with an overall response of CR, PR, SD, non-CR/non-PD or NED. CR: disappearance of all target lesions; PR: \\>=30% decrease in the sum of the diameters of target lesions, taking as reference the baseline sum of diameters; SD: neither sufficient shrinkage to qualify for PR nor sufficient increase to qualify for PD, taking as reference the smallest sum of diameter since the treatment started. Kaplan-Meier method was used for analysis.",
   "timeFrame": "From randomization until the first documentation of PD or death from any cause or censoring date, whichever occurred first (maximum treatment exposure was of 41.3 months)"
  },
  {
   "measure": "Time to Deterioration (TTD) of Health-Related Quality of Life (HRQoL)",
   "description": "Time to deterioration of HRQoL was defined as time to 10-point decrease in the global health status/QoL scale of the European Organization for Research and Treatment of Cancer (EORTC) quality of life questionnaire (QLQ-C30). EORTC QLQ-C30 is 30 item questionnaires composed of 5 multi-item functional domains (physical, role, cognitive, emotional, and social), 3 symptom scales (fatigue, pain, nausea, and vomiting) and 6 single items for symptoms (shortness of breath, loss of appetite, sleep disturbance, constipation, diarrhea and financial impact of the disease), 2 global items (health, overall QoL). Higher functional/global QoL score = better functioning and higher symptom score = greater degree of symptoms.",
