forecastInput:
{
 "nctId": "NCT04221750",
 "briefTitle": "Diet and Exercise Plus Metformin to Treat Frailty in Obese Seniors",
 "officialTitle": "Lifestyle Intervention Plus Metformin to Treat Frailty in Older Veterans With Obesity",
 "leadSponsor": {
  "name": "VA Office of Research and Development",
  "class": "FED"
 },
 "collaborators": [
  {
   "name": "Michael E. DeBakey VA Medical Center",
   "class": "FED"
  },
  {
   "name": "Baylor College of Medicine",
   "class": "OTHER"
  }
 ],
 "startDate": "2021-05-14",
 "firstRegistered": "2020-01-02",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Frailty",
  "Sarcopenic Obesity",
  "Aging"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "TRIPLE",
   "maskingDescription": "Placebo controlled",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 114,
 "briefSummary": "The continuing increase in prevalence of obesity in older adults including many older Veterans has become a major health concern. The clinical trial will test the central hypothesis that a multicomponent intervention consisting of lifestyle therapy (diet-induced weight loss and exercise training) plus metformin will be the most effective strategy for reversing sarcopenic obesity and frailty in older Veterans with obesity.",
 "detailedDescription": "The growing prevalence of obesity in older adults including many older Veterans, has become a major concern in the US already strained health care system in general and in the VA in particular. In older adults, obesity exacerbates the age-related decline in physical function resulting in frailty, decrease in quality of life, loss of independence, and increase in nursing home admissions. The investigators' group demonstrated that weight loss from lifestyle therapy improves physical function and ameliorates frailty but the improvement was modest at best and most obese older adults remained frail. More importantly, there are concerns that the weight-loss induced loss of muscle and bone mass could worsen underlying age-related sarcopenia and osteopenia in the subset of frail obese elderly. Metformin, a biguanide, is a widely available drug used as first line treatment of type 2 diabetes. Animal studies suggest that metformin improves health span and increases lifespan, hence may represent a novel intervention for frailty. Because metformin reduces cellular senescence and senescence-associated phenotype (SASP), it is believed to retard accelerated aging most especially in older adults with obesity. The objective is to conduct a head-head comparative efficacy, placebo controlled, randomized controlled trial to test the hypothesis that lifestyle therapy + metformin for six months will be more effective than lifestyle therapy alone or metformin alone in improving physical function and preventing the weight loss-induced reduction in muscle and bone mass in obese (BMI \\> 30 kg/m2) older (age 65 - 85 years) Veterans with physical frailty.",
 "arms": [
  {
   "label": "Lifestyle Therapy plus Metformin",
   "type": "EXPERIMENTAL",
   "description": "Diet-induced weight loss and Exercise Training plus Metformin 1500 mg daily",
   "interventionNames": [
    "Behavioral: Lifestyle therapy",
    "Drug: Metformin Hydrochloride"
   ]
  },
  {
   "label": "Lifestyle Therapy plus Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Diet-induced weight loss and Exercise Training plus Placebo",
   "interventionNames": [
    "Behavioral: Lifestyle therapy",
    "Drug: Placebo"
   ]
  },
  {
   "label": "Healthy lifestyle plus Metformin",
   "type": "ACTIVE_COMPARATOR",
   "description": "Healthy lifestyle and Metformin 1500 mg daily",
   "interventionNames": [
    "Drug: Metformin Hydrochloride",
    "Behavioral: Healthy Lifestyle"
   ]
  }
 ],
 "interventions": [
  {
   "type": "BEHAVIORAL",
   "name": "Lifestyle therapy",
   "description": "Weight management program, in which participants are prescribed a balanced diet that provides and energy deficit of 500 to 750 kcal per day to induced \\~10% weight loss plus Supervised combined aerobic and resistance exercise training three times weekly",
   "armGroupLabels": [
    "Lifestyle Therapy plus Metformin",
    "Lifestyle Therapy plus Placebo"
   ],
   "otherNames": [
    "Diet-induced weight loss and exercise training"
   ]
  },
  {
   "type": "DRUG",
   "name": "Metformin Hydrochloride",
   "description": "Given orally starting at 500 mg (one tablet) taken orally once a day with meals. After a week, the dose of metformin will be increased to 1000 mg (two tablets) daily. After another week, the dose of metformin will be increased to 1500 mg (three tablets) daily.",
   "armGroupLabels": [
    "Healthy lifestyle plus Metformin",
    "Lifestyle Therapy plus Metformin"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "Given orally starting at 500 mg (one tablet) taken orally once a day with meals. After a week, the dose of placebo will be increased to 1000 mg (two tablets) daily. After another week, the dose of placebo will be increased to 1500 mg (three tablets) daily.",
   "armGroupLabels": [
    "Lifestyle Therapy plus Placebo"
   ]
  },
  {
   "type": "BEHAVIORAL",
   "name": "Healthy Lifestyle",
   "description": "Group educational sessions that focus on healthy diet, exercise, and social support once a month",
   "armGroupLabels": [
    "Healthy lifestyle plus Metformin"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change in the Modified Physical Performance Test (PPT)",
   "description": "The Physical Performance Test includes seven standardized tasks (walking 15.2 m \\[50 ft\\], putting on and removing a coat, picking up a penny, standing up from a chair, lifting a book, climbing one flight of stairs, and performing a progressive Romberg test) plus two additional tasks (going up and down four flights of stairs and making a 360-degree turn). The score for each task ranges from 0 to 4, with higher scores indicating better physical performance; lowest score is 0 and a perfect score would be 36.",
   "timeFrame": "6 months"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change in Muscle Strength",
   "description": "Knee extension muscle strength measured using a Biodex dynamometer",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Gait Speed",
   "description": "Gait speed was calculated from the time required to walk 4 meters at the participant's usual walking pace and expressed in meters per minute.",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Peak Aerobic Power",
   "description": "Assessed by indirect calorimetry during a graded exercise test",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Lean Body Mass",
   "description": "Assessed by dual-energy x-ray absorptiometry (DXA)",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Body Fat",
   "description": "Assessed by using dual energy x-ray absorptiometry",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Thigh Muscle",
   "description": "Assessed by magnetic resonance imaging (MRI)",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Distal Tibia Bone Microarchitecture: Cortical Thickness",
   "description": "Assessed by high-resolution peripheral quantitative computed tomography (HR-pQCT) at the distal tibia",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Bone Strength",
   "description": "Assessed as distal tibia failure load estimated using finite-element analysis of HR-pQCT scans.",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Bone Mineral Density (BMD) at the Total Hip",
   "description": "Assessed by dual-energy X-ray absorptiometry (DXA) at the total hip site",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Bone Mineral Density at the Lumbar Spine",
   "description": "Assessed by dual-energy X-ray absorptiometry (DXA) at the lumbar spine site",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Serum C-telopeptide",
   "description": "Bone resorption marker assessed by electrochemiluminescence immunoassay. Values represent least-squares mean ratios of 6-month to baseline C-telopeptide derived from mixed-effects models (exp\\[post - pre\\]).",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Mood",
   "description": "Assessed by geriatric depression scale (score range: 0 to 30, where lower scores indicating better mood)",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Serum Procollagen Type 1 N Propeptide",
   "description": "Bone formation marker assessed in fasting serum samples by radioimmunoassay (RIA). Values represent least-squares mean ratios of 6-month to baseline procollagen type 1 N propeptide derived from mixed-effects models (exp\\[post - pre\\]).",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Serum 25-OH Vitamin D",
   "description": "Measured by automated immunoassay",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Serum Parathyroid Hormone",
   "description": "Assessed by Beckman Coulter immunoassay",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in High-sensitivity C-reactive Protein",
   "description": "Assessed by immunoturbidimetric assay. CRP was log-transformed prior to analysis. Values represent least-squares mean ratios of 6-month to baseline CRP derived from mixed-effects models (exp\\[post - pre\\]).",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Medical Outcomes 36-Item Short Form Health Survey (SF-36)",
   "description": "Assessed by Physical component summary component summary score (score range 0 to 100, with higher scores indicating better health status)",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Impact of Weight on Quality of Life_Lite (IWQOL-lite) Score",
   "description": "Assessed by Impact of Weight on Quality of Life-Lite (IWQOL-lite) questionnaire. Score ranges from 0 to 100, with higher scores indicating better weight-related quality of life.",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Serum Adiponectin",
   "description": "Assessed by enzyme linked immunosorbent assay (ELISA)",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Serum Leptin",
   "description": "Assessed by radioimmunoassay",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Fasting Serum Insulin",
   "description": "Assessed by chemiluminescent immunoassay",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Fasting Serum Glucose",
   "description": "Assessed by glucose oxidase method",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Systolic Blood Pressure",
   "description": "Seated systolic blood pressure assessed using an oscillometric blood pressure monitor.",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Serum Lipids: Triglycerides",
   "description": "Assessed by automated enzymatic/colorimetric assays: triglycerides are reported.",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Serum Insulin Growth Factor 1",
   "description": "Measured using an automated immunochemiluminometric assay (ICMA)",
   "timeFrame": "6 months"
  },
  {
   "measure": "Change in Cognitive Function Composite Score",
   "description": "Global cognitive function was assessed using the NIH Toolbox Cognition Battery Total Cognition Composite Score, a standardized measure of overall cognitive performance. Age-Corrected Standard Scores were used. These scores are standardized relative to individuals of the same age, with a normative mean of 100 and a standard deviation of 15. Higher scores indicate better cognitive performance.",
   "timeFrame": "6 months"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Age 65 - 85 years\n* BMI = or \\> 30 kg/m2\n* Mild to moderate frailty (score of 18 to 31 in the modified Physical Performance Test)\n* Stable body weight (plus/minus 2 kg) during the past 6 months\n* Sedentary (regular exercise \\<1 h/wk or \\<2 x/wk for the last 6 months)\n* Willing to provide informed consent\n\nExclusion Criteria:\n\n* Any major chronic diseases, or any condition that would interfere with exercise or dietary restriction, or use of metformin, in which exercise, dietary restrictions, or metformin are contraindicated, or that would interfere with interpretation of results\n* Cardiopulmonary disease (e.g. recent MI, unstable angina, stroke) or unstable disease (e.g., NYHA Class III or IV congestive heart failure, severe pulmonary disease requiring steroid pills or the use of supplemental oxygen) that would contraindicate exercise or dietary restriction\n* Severe orthopedic (e.g. awaiting joint replacement) and/or neuromuscular (e.g. multiple sclerosis, active rheumatoid arthritis) disease or impairments that would contraindicate participation in exercise\n* Renal impairment as defined by an estimated glomerular filtration rate (eGFR of less than 30 mL/min/1.73 m2) in which metformin is contraindicated\n* Other significant co-morbid disease that would impair ability to participate in the exercise intervention (e.g. severe psychiatric disorder \\[e.g. bipolar, schizophrenia\\], excess alcohol use \\[\\>14 drinks per week\\])\n* Severe visual or hearing impairments that would interfere with following directions\n* Significant cognitive impairment, defined as a known diagnosis of dementia or positive screening test for dementia using the Mini-Mental State Exam (i.e. MMSE score \\<24)69\n* Uncontrolled hypertension (BP\\>160/90 mm Hg)\n* History of malignancy during the past 5 years (except non-melanoma skin cancers)\n* Current use of bone acting drugs (e.g. use of estrogen, or androgen containing compound,raloxifene, calcitonin, parathyroid hormone during the past year or bisphosphonates during the last two years)\n* Osteoporosis (T-score -2.5 and below on hip or spine scan) or history of fragility fractures\n* Known history of diabetes mellitus or any of the following:\n* Fasting blood glucose of 126 mg/dl, or HbA1c of 6.5% or \\>\n* Terminal illness with life expectancy less than 12 months, as determined by a physician\n* Use of any drugs or natural products designed to induce weight loss within past three months\n* History of excessive alcohol consumption (e.g. 8 or more drinks a week for women and 15 or more drinks a week for men)\n* Positive exercise stress test for ischemia or any indication for early termination of exercise stress testing\n* Taking metformin or any other glucose lowering drug\n* Lives outside of the study site or is planning to move out of the area in the next 2 years",
  "healthyVolunteers": true,
  "sex": "ALL",
  "minimumAge": "65 Years",
  "maximumAge": "85 Years"
 },
 "siteCount": 1,
 "countries": [
  "United States"
 ]
}

