{
 "nctId": "NCT05472779",
 "briefTitle": "Periurethral vs Intravaginal Estrogen for Prevention of Recurrent Urinary Tract Infections",
 "officialTitle": "Periurethral vs Intravaginal Estrogen for Prevention of Recurrent Urinary Tract Infections: TAPER (Techniques of APplying Vaginal Estrogen for Prevention of Recurrent Urinary Tract Infections) Trial",
 "leadSponsor": {
  "name": "Stephanie Wang Zuo",
  "class": "OTHER"
 },
 "startDate": "2023-01-03",
 "firstRegistered": "2022-07-21",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Recurrent Urinary Tract Infection"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "PREVENTION",
  "maskingInfo": {
   "masking": "NONE"
  }
 },
 "enrollment": 114,
 "briefSummary": "Due to rising antibiotic resistance, there has been a focus on non-antibiotic prophylactic measures for postmenopausal patients with recurrent urinary tract infections (rUTI), one of which is the safe and efficacious option of vaginal estrogen therapy. Standard application of vaginal estrogen cream entails intravaginal application of the cream twice a week, but some providers counsel patients with rUTI to apply a small, pea-sized amount to the periurethral area. This ideally reduces the amount of vaginal estrogen used while attaining a similar effect. However, to date, there is no data to prove that the periurethral technique of application is similar or non-inferior to intravaginal application in preventing UTI.",
 "arms": [
  {
   "label": "Intravaginal Estrogen Application",
   "type": "ACTIVE_COMPARATOR",
   "description": "Intravaginal application of 1 gram estradiol cream at bedtime twice a week for 6 months",
   "interventionNames": [
    "Drug: Intravaginal application of estradiol cream"
   ]
  },
  {
   "label": "Periurethral Estrogen Application",
   "type": "EXPERIMENTAL",
   "description": "Periurethral application of 0.5 gram estradiol cream at bedtime twice a week for 6 months",
   "interventionNames": [
    "Drug: Periurethral application of estradiol cream"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Periurethral application of estradiol cream",
   "description": "The experimental group will apply estradiol cream in a different location (periurethral) and at a smaller dose (0.5 gram) compared to the control group.",
   "armGroupLabels": [
    "Periurethral Estrogen Application"
   ]
  },
  {
   "type": "DRUG",
   "name": "Intravaginal application of estradiol cream",
   "description": "The control group will apply 1 gram estradiol cream intravaginally using an applicator.",
   "armGroupLabels": [
    "Intravaginal Estrogen Application"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Percentage of Participants Who Are UTI-free at 6 Months",
   "description": "The primary outcome was the percentage of participants who were UTI-free at 6 months after study drug initiation.",
   "timeFrame": "6 months"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline in Urinary Symptoms at 6 Months",
   "description": "Questionnaire assessment of urinary symptoms and symptom distress (Urogenital Distress Inventory, Short Form), total score range 0-100 with higher numbers representing worse urinary symptoms",
   "timeFrame": "Baseline, 6 months"
  },
  {
   "measure": "Change From Baseline in Sexual Function at 6 Months",
   "description": "Questionnaire assessment of sexual function (Female Sexual Function Index-6) with scores ranging from 2 to 30, with 19 and below denoting sexual dysfunction.",
   "timeFrame": "Baseline, 6 months"
  },
  {
   "measure": "Change From Baseline in Vaginal pH at 6 Months",
   "description": "Assessment using pH strips during pelvic examination",
   "timeFrame": "Baseline, 6 months"
  },
  {
   "measure": "Participant Experience With Study Drug",
   "description": "Agreement with the statement: \"I am satisfied with the estrogen cream.\" (Positive response of \"agree\" or \"strongly agree\" on 5-point Likert Scale)",
   "timeFrame": "6 months"
  },
  {
   "measure": "Vaginal Maturation Value",
   "description": "Vaginal maturation value at 3 months (score 0-100, higher values correlating with greater vaginal estrogenization)",
   "timeFrame": "3 months"
  },
  {
   "measure": "Average Amount of Estrogen Used Per Tube",
   "description": "Study drug tubes were weighed at baseline and then at follow-up visits (weight in grams) and the average amount of study drug used per tube was calculated.",
   "timeFrame": "6 months"
  },
  {
   "measure": "Percentage of Participants With Lactobacillus Crispatus Positive Vaginal Specimens",
   "description": "Lactobacillus crispatus is a species of Lactobacillus known to assist with UTI prevention through the maintenance of an acidic environment. It generally is elevated in the vagina in the presence of estrogen.",
   "timeFrame": "6 months"
  },
  {
   "measure": "Percentage of Participants With E. Coli Positive Vaginal Specimens",
   "description": "E. coli is a common uropathogen and thus was investigated in the pilot translational sub-aim of this research study.",
   "timeFrame": "6 months"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Postmenopausal (definition: No menses for 1 or more years or surgical menopause (bilateral oophorectomy). If there is a past history of hysterectomy, patient must be age 56 or older (95th percentile for age at menopause) or have laboratory evidence of menopause (ie. FSH \\>30)\n* Meets criteria for recurrent urinary tract infections (UTIs) with 2 or more UTI in 6 months or 3 or more UTI in 1 year\n* May include patients who used vaginal estrogen previously if they have stopped use for 3 or more months prior to inclusion into study.\n* Patients must be recommended vaginal estrogen as part of normal clinical care for prevention of recurrent UTI\n\nExclusion Criteria:\n\n* Current use of vaginal or oral estrogen products\n* Inability or refusal to use vaginal estrogen\n* Daily antibiotic use\n* Significant vaginal stenosis (eg. due to lichen sclerosis, radiation or obliterative prolapse surgery) that would prohibit use of a vaginal applicator (ie. genital hiatus \\<1cm)\n* Inability to use vaginal applicator and without caregiver who can administer (eg. provider-managed pessary use, significant arthritis)\n* Frequent (1x weekly or more frequent) use of bladder instillations containing an antibiotic\n* Known hydronephrosis as a result of incomplete bladder emptying\n* Use of intermittent or indwelling urinary catheterization\n* Known bladder stones, mesh erosion into bladder, or foreign object in bladder\n* Unable to consent for self\n* Active treatment for an estrogen-dependent malignancy",
  "healthyVolunteers": false,
  "sex": "FEMALE",
  "minimumAge": "18 Years"
 },
 "siteCount": 4,
 "countries": [
  "United States"
 ]
}

