forecastInput:
{
 "nctId": "NCT04513912",
 "briefTitle": "A Study of Seltorexant Compared to Quetiapine XR as Adjunctive Therapy to Antidepressants in Adult and Elderly Participants With Major Depressive Disorder With Insomnia Symptoms Who Have Responded Inadequately to Antidepressant Therapy",
 "officialTitle": "Double-Blind, Randomized, Parallel-Group Study With Quetiapine Extended Release as Comparator to Evaluate the Efficacy and Safety of Seltorexant 20 mg as Adjunctive Therapy to Antidepressants in Adult and Elderly Patients With Major Depressive Disorder With Insomnia Symptoms Who Have Responded Inadequately to Antidepressant Therapy",
 "leadSponsor": {
  "name": "Janssen Research & Development, LLC",
  "class": "INDUSTRY"
 },
 "startDate": "2020-09-15",
 "firstRegistered": "2020-08-13",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Depressive Disorder, Major"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "DOUBLE",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 757,
 "briefSummary": "The purpose of this study is to assess the efficacy of seltorexant compared with quetiapine extended-release (XR) as adjunctive therapy to an antidepressant drug in treatment response in participants with major depressive disorder with insomnia symptoms (MDDIS) who have had an inadequate response to current antidepressant therapy with a selective serotonin reuptake inhibitor (SSRI) or serotonin-norepinephrine reuptake inhibitor (SNRI).",
 "detailedDescription": "Major depressive disorder (MDD) is a common, serious, recurrent disorder. Seltorexant (JNJ-42847922) is a potent and selective antagonist of the human orexin-2 receptor (OX2R) that is being developed for the adjunctive treatment of MDDIS. The hypothesis for this study is that seltorexant is superior to quetiapine XR in leading to a response after 26 weeks of treatment (greater than or equal to \\[\\>=\\] 50 percent \\[%\\] improvement on baseline Montgomery Asberg Depression Rating Scale \\[MADRS\\] total score), when administered as adjunctive treatment to an antidepressant in adult and elderly participants with MDDIS who have had an inadequate response to treatment with an SSRI/SNRI. The study will be conducted in 3 phases: a screening phase (up to 30 days), a double-blind (DB) treatment phase (26 weeks), and a post treatment follow-up phase (7 to 14 days after the end of DB treatment phase for all participants, and up to 196 days from baseline for participants who stop study treatment early). The total study duration for each participant will be approximately 32 weeks. Efficacy, safety, pharmacokinetics, and biomarkers will be assessed at specified time points during this study.",
 "arms": [
  {
   "label": "Seltorexant",
   "type": "EXPERIMENTAL",
   "description": "Adult participants will receive seltorexant once daily from Day 1-7 and together with matching placebo from Day 8 till Day 182. Elderly participants will receive seltorexant once daily from Day 1-3 and together with matching placebo from Day 4 till Day 182.",
   "interventionNames": [
    "Drug: Seltorexant",
    "Drug: Matching placebo to Seltorexant"
   ]
  },
  {
   "label": "Quetiapine Extended-Release (XR)",
   "type": "ACTIVE_COMPARATOR",
   "description": "Adult participants will receive quetiapine XR once daily from Day 1-2, followed by an increase in dose from Day 3-7, and from Day 8-14 together with matching placebo. After Day 14, quetiapine XR twice daily from Day 14 till Day 182. Elderly participants will receive quetiapine XR once daily from Day 1-3 and twice from Day 4-7, followed by an increase in dose once daily from Day 8-14 together with matching placebo. After Day 14 till Day 182, quetiapine XR will be adjusted by investigator based on the participant's clinical response and tolerability.",
   "interventionNames": [
    "Drug: Quetiapine XR",
    "Drug: Matching placebo to Quetiapine XR"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Seltorexant",
   "description": "Participants will receive seltorexant over-encapsulated tablet orally.",
   "armGroupLabels": [
    "Seltorexant"
   ]
  },
  {
   "type": "DRUG",
   "name": "Matching placebo to Seltorexant",
   "description": "Participants will receive placebo over-encapsulated tablet matching to seltorexant orally.",
   "armGroupLabels": [
    "Seltorexant"
   ]
  },
  {
   "type": "DRUG",
   "name": "Quetiapine XR",
   "description": "Participants will receive quetiapine XR capsule orally.",
   "armGroupLabels": [
    "Quetiapine Extended-Release (XR)"
   ]
  },
  {
   "type": "DRUG",
   "name": "Matching placebo to Quetiapine XR",
   "description": "Participants will receive placebo capsule matching to quetiapine XR orally.",
   "armGroupLabels": [
    "Quetiapine Extended-Release (XR)"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Percentage of Participants Who Achieved Response (Greater Than or Equal to [>=50] Percent Improvement in Montgomery-Asberg Depression Rating Scale [MADRS] Total Score From Baseline) at Week 26",
   "description": "Percentage of participants who achieved response at Week 26 was reported. Responders were defined as participants with \\>= 50 percent (%) improvement in the MADRS total score from baseline. MADRS was a clinician-administered scale designed to measure depression severity and detected changes due to antidepressant treatment. The MADRS evaluates the following 10 items: apparent sadness, reported sadness, inner tension, reduced sleep, reduced appetite, concentration difficulties, lassitude, inability to feel, pessimistic thoughts, and suicidal thoughts. Each item was scored from 0 (item not present or normal) to 6 (severe or continuous presence of symptoms). MADRS total score was the sum of scores from individual question items, which ranged from 0 to 60, higher scores represented a more severe condition.",
   "timeFrame": "Week 26"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline to Week 26 in Weight",
   "description": "Change from baseline to Week 26 in weight was reported.",
   "timeFrame": "Baseline (Day 1) and Week 26"
  },
  {
   "measure": "Time to Potentially Treatment Related Discontinuation of Study Drug",
   "description": "Time to potentially treatment related discontinuation of study drug was reported. Time to discontinuation of study drug was defined as the number of days from the first dose of study drug to the last dose of study drug. Potentially treatment related discontinuation of study drug was defined as all study drug discontinuations excluding the potentially non-treatment related discontinuations (such as, loss of insurance for antidepressant therapy, movement/travel out of the area, change of work-schedule being unable to accommodate visit schedule, family circumstances, site terminated by sponsor, study terminated by sponsor). Kaplan-Meier estimate was used.",
   "timeFrame": "From first dose of study drug (Day 1) up to Week 30"
  },
  {
   "measure": "Change From Baseline to Week 26 in Montgomery-Asberg Depression Rating Scale (MADRS) Total Score",
   "description": "Change from baseline to Week 26 in MADRS total score were reported. MADRS was a clinician-administered scale designed to measure depression severity and detects changes due to antidepressant treatment. The MADRS evaluated the following 10 items: apparent sadness, reported sadness, inner tension, reduced sleep, reduced appetite, concentration difficulties, lassitude, inability to feel, pessimistic thoughts, and suicidal thoughts. Each item was scored from 0 (item not present or normal) to 6 (severe or continuous presence of symptoms). MADRS total score was the sum of scores from individual question items, which ranged from 0 to 60, higher scores represented a more severe condition.",
   "timeFrame": "Baseline (Day 1) and Week 26"
  },
  {
   "measure": "Change From Baseline to Week 26 in MADRS-6 Total Score",
   "description": "Change from baseline to Week 26 in MADRS-6 total score was reported. The MADRS-6 scale was a clinician-administered questionnaire used to measure the severity of MDD symptoms. The MADRS-6 scale was a subset of the MADRS-10 scale, comprised of the following individual questionnaire items: apparent sadness, reported sadness, inner tension, lassitude, inability to feel, and pessimistic thoughts. Each item was scored from 0 (item not present or normal) to 6 (severe or continuous presence of symptoms), the overall score ranged from 0 to 36, higher scores represented a more severe condition.",
   "timeFrame": "Baseline (Day 1) and Week 26"
  },
  {
   "measure": "Change From Baseline to Week 26 in the MADRS Without Sleep Item (MADRS-WOSI) Total Score",
