forecastInput:
{
 "nctId": "NCT04543591",
 "briefTitle": "Ravulizumab in Thrombotic Microangiopathy After Hematopoietic Stem Cell Transplant",
 "officialTitle": "A Phase 3, Randomized, Double-Blind, Placebo-Controlled, Multicenter Study of Ravulizumab in Adult and Adolescent Participants Who Have Thrombotic Microangiopathy (TMA) After Hematopoietic Stem Cell Transplant (HSCT)",
 "leadSponsor": {
  "name": "Alexion Pharmaceuticals, Inc.",
  "class": "INDUSTRY"
 },
 "startDate": "2020-12-10",
 "firstRegistered": "2020-08-17",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Thrombotic Microangiopathy"
 ],
 "keywords": [
  "Thrombotic Microangiopathy (TMA) Ultomiris",
  "Ravulizumab",
  "Hematopoietic Stem Cell Transplant (HSCT) Transplant-associated TMA",
  "HSCT-TMA"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 148,
 "briefSummary": "This study will evaluate the efficacy, safety, pharmacokinetics, and pharmacodynamics of ravulizumab in adult and adolescent participants with hematopoietic stem cell transplant-associated thrombotic microangiopathy (HSCT-TMA). In Stage 1, an open-label, single-arm period, the dosing regimen will be confirmed. In Stage 2, participants will be randomized to receive either blinded ravulizumab plus best supportive care or matching placebo plus best supportive care. The treatment period is 26 weeks (open-label for Stage 1, and randomized, double-blind, and placebo-controlled for Stage 2) followed by a 26-week follow-up period.",
 "arms": [
  {
   "label": "Ravulizumab",
   "type": "EXPERIMENTAL",
   "description": "In Stage 1, all participants will receive open-label ravulizumab plus Best Supportive Care (BSC).\n\nIn Stage 2, participants will receive blinded ravulizumab plus Best Supportive Care (BSC).",
   "interventionNames": [
    "Biological: Ravulizumab",
    "Other: Best supportive care"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "In Stage 2, participants randomized to the placebo arm will receive matching placebo plus BSC.",
   "interventionNames": [
    "Other: Placebo",
    "Other: Best supportive care"
   ]
  }
 ],
 "interventions": [
  {
   "type": "BIOLOGICAL",
   "name": "Ravulizumab",
   "description": "Weight-based doses of ravulizumab will be administered intravenously as loading dose regimen followed by maintenance dosing every 8 weeks.",
   "armGroupLabels": [
    "Ravulizumab"
   ],
   "otherNames": [
    "Ultomiris, ALXN1210"
   ]
  },
  {
   "type": "OTHER",
   "name": "Placebo",
   "description": "Matching placebo",
   "armGroupLabels": [
    "Placebo"
   ]
  },
  {
   "type": "OTHER",
   "name": "Best supportive care",
   "description": "Participants will receive medications, therapies, and interventions per standard hospital treatment protocols (unless specifically prohibited by the protocol).",
   "armGroupLabels": [
    "Placebo",
    "Ravulizumab"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Stage 2: Proportion of Participants With Event-free Survival During the 26-week Treatment Period",
   "description": "Event-free survival was defined as the time from randomization until the first of the 2 following events: death (due to any cause) and clinical worsening up through Week 26. Clinical worsening was defined as meeting 2 or more of the following criteria: doubling of serum creatinine from baseline or new requirement of dialysis; increase in lactate dehydrogenase (LDH) \\>25% compared to baseline; reduction in platelets of \\>25% compared to baseline; reduction in hemoglobin \\>10% compared to baseline; increased requirement for platelets or red blood cells at any time. The criteria for clinical worsening had to be confirmed by 2 independent samples collected at least 8 hours apart (ideally 24 hours apart).",
   "timeFrame": "Up to Week 26"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Stage 2: Overall Survival",
   "description": "The Kaplan-Meier method was used to measure overall survival estimate. For Day 100 and Week 26, overall survival was calculated from randomization to death (due to any cause), up to Day 100/Week 26. Participants who survived were censored at the earliest of an additional hematopoietic stem cell transplant (HSCT), Day 100/Week 26, or their last known date alive. For Week 52, overall survival was calculated from randomization to death (due to any cause), up to Week 52. Participants who survived were censored at the earlier of an additional HSCT, or their last known date alive up to Week 52.",
   "timeFrame": "Up to Day 100 (Treatment Period), Week 26 (Treatment Period), and Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Non-relapse Mortality",
   "description": "Cumulative incidence for each group was estimated using a competing risks model. Non-relapse mortality was defined as a participant's death due to any cause during the study, with the exception of death due to underlying disease (malignant or non-malignant reason for HSCT) progression or relapse.",
   "timeFrame": "Baseline through Day 100 (Treatment Period), Week 26 (Treatment Period), and Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Mean Number of Thrombotic Microangiopathy (TMA) Response Criteria Met During the 26-week Treatment Period",
   "description": "The TMA response parameters included: platelet response, normalization of LDH and absence of schistocytes, and renal response. A participant could have met 0, 1, 2, or 3 TMA response criteria during the 26-week Treatment Period. If the participants met more than 1 TMA response criterion, the number of responses overlapping for at least 24 hours was counted. Least squares mean determined from a general linear model adjusted by acute GVHD status and geographic region, assuming normal data distribution.",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Percentage of Participants With Hematologic Response During the 26-week Treatment Period",
   "description": "Clinical laboratory assessments were performed according to the protocol and assessed against the following predetermined criteria for hematologic response: if baseline platelet count was ≤50000/cubic millimeter (mm\\^3), then the absolute platelet count had to be \\>50000/mm\\^3 without platelet transfusion support during the prior 7 days; if the baseline platelet count had to be \\>50000/mm\\^3, then there must be a ≥50% increase in platelet count compared to baseline value without platelet transfusion support during the prior 7 days; normalization of LDH and absence of schistocytes (defined as ≤1% or a result of \"none\", per the International Council for Standardization in Hematology recommendations for schistocyte counting).",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Change From Baseline in the Estimated Glomerular Filtration Rate (eGFR) at Week 26 and Week 52",
   "description": "The eGFR was calculated based on serum creatinine using the Chronic Kidney Disease Epidemiology Collaboration (CKD EPI) formula. Serum creatinine was collected according to the protocol. Data reported as milliliters/minute/1.73 square meters (mL/min/1.73 m\\^2).",
   "timeFrame": "Baseline, Week 26 (Treatment Period), Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Percentage of Participants With TMA Response During the 26-week Treatment Period",
   "description": "The criteria for TMA response included a hematological response and a renal response. Hematological Response: if baseline platelet count was ≤50000/mm\\^3, then the absolute platelet count had to be \\>50000/mm\\^3 without platelet transfusion support during the prior 7 days; if the baseline platelet count was \\>50000/mm\\^3, then there had to be a ≥50% increase in platelet count compared to baseline value without platelet transfusion support during the prior 7 days; normalization of LDH and absence of schistocytes. Renal response: at least 50% reduction of proteinuria from baseline. Participants must have met each of the response criteria, with each parameter meeting the requirements at 2 separate assessments obtained at least 24 hours apart, and any measurement in between. A participant could meet 0, 1, 2, or 3 TMA response criteria during the treatment period. If the participant met more than 1 TMA response criterion, the number of responses overlapping for at least 24 hours was counted.",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Cumulative Proportion of Participants Who Experienced a Complete TMA Response During the 26-week Treatment Period",
   "description": "Cumulative proportion of participants who experienced a complete TMA response was estimated using a competing risks model based on the time (days) to complete TMA response. Time to complete TMA response was defined as the days from randomization to the first day during the 26-week Treatment Period on which a participant met all criteria for a complete TMA response. The date of complete TMA response was defined as the first date on which all individual response criteria were met simultaneously.",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Cumulative Proportion of Participants Experiencing Each Individual Component of TMA During the 26-week Treatment Period",
   "description": "Cumulative proportion of participants experiencing individual TMA components included those for platelet count, LDH, and protein/creatinine ratio. For platelet count: if baseline platelet count was ≤50000/mm\\^3, then the absolute platelet count had to be \\>50000/mm\\^3 without platelet transfusion support during the prior 7 days; if the baseline platelet count was \\>50000/mm\\^3, then there had to be a ≥50% increase in platelet count compared to baseline value without platelet transfusion support during the prior 7 days. For LDH: normalization of LDH and absence of schistocytes. For protein/creatinine ratio: at least 50% reduction of proteinuria from baseline.",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Cumulative Proportion of Participants Experiencing a Hematologic Response During the 26-week Treatment Period",
   "description": "Clinical laboratory assessments were performed according to the protocol and assessed against the following predetermined criteria for hematologic response: if baseline platelet count was ≤50000/mm\\^3, then the absolute platelet count had to be \\>50000/mm\\^3 without platelet transfusion support during the prior 7 days; if the baseline platelet count was \\>50000/mm\\^3, then there had to be a ≥50% increase in platelet count compared to baseline value without platelet transfusion support during the prior 7 days.",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Percentage of Participants With Hemoglobin Response During the 26-week Treatment Period",
   "description": "Hemoglobin response was defined as the ability to maintain hemoglobin ≥10 grams/deciliter (g/dL) without any support. The criterion had to be met at 2 separate assessments obtained at least 24 hours apart, and any measurement in between, and without any support during the prior 7 days.",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Percentage of Participants With Platelet Response During the 26-week Treatment Period",
   "description": "Platelet response was defined as: if baseline platelet count was ≤50000/mm\\^3, then the absolute platelet count had to be \\>50000/mm\\^3 without platelet transfusion support during the prior 7 days; if the baseline platelet count was \\>50000/mm\\^3, then there had to be a ≥50% increase in platelet count compared to baseline value without platelet transfusion support during the prior 7 days. The criteria had to be met at 2 separate assessments obtained at least 24 hours apart, and any measurement in between.",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Percentage of Participants With Partial Response During the 26-week Treatment Period",
   "description": "The criteria for TMA response included a hematological response and a renal response. Hematological response: if baseline platelet count was ≤50000/mm\\^3, then the absolute platelet count had to be \\>50000/mm\\^3 without platelet transfusion support during the prior 7 days; if the baseline platelet count was \\>50000/mm\\^3, then there had to be a ≥50% increase in platelet count compared to baseline value without platelet transfusion support during the prior 7 days; normalization of LDH and absence of schistocytes. Renal response: at least 50% reduction of proteinuria from baseline. Partial response occurred when the participant met ≥1, but not all, criteria for TMA response.",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Percentage of Participants With Loss of TMA Response During the 26-week Treatment Period",
   "description": "For participants that met the criteria for TMA response during the 26-week Treatment Period, loss of TMA response was defined as when the participant failed to meet the criteria for 1 or more components of TMA response at a subsequent visit during the 26-week Treatment Period. At least 1 parameter must have failed to meet the response criteria at 2 separate assessments obtained at least 24 hours apart, and any measurement in between.",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Duration of TMA Response",
   "description": "This analysis includes data for each participant after achieving TMA response under the composite strategy through Weeks 26 and 52. The criteria for TMA response included a hematological response and a renal response. Time was calculated as the number of days from TMA response under the composite strategy to first loss of response or intercurrent event in the treatment period, or TMA relapse in the follow-up period. Participants must have met each of the response criteria, with each parameter meeting the requirements at 2 separate assessments obtained at least 24 hours apart, and any measurement in between. Participants with TMA response who did not experience these events were censored at their end of study date. The estimate is calculated based on the Kaplan-Meier method. Non-responders were counted as an event with a duration of zero day.",
   "timeFrame": "Baseline through Week 52"
  },
  {
   "measure": "Stage 2: Change From Baseline in Haptoglobin at Week 26 and Week 52",
   "description": "Protocol-specified blood samples were taken for the analysis of haptoglobin in plasma at designated time points. Results are reported as grams/liter (g/L).",
   "timeFrame": "Baseline, Week 26 (Treatment Period), Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Change From Baseline in Platelets at Week 26 and Week 52",
   "description": "Protocol-specified blood samples were taken for the analyses of platelets in plasma at designated time points.",
   "timeFrame": "Baseline, Week 26 (Treatment Period), Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Change From Baseline in LDH at Week 26 and Week 52",
   "description": "Protocol-specified blood samples were taken for the analyses of LDH in plasma at designated time points. Results are reported as units/liter (U/L).",
   "timeFrame": "Baseline, Week 26 (Treatment Period), Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Change From Baseline in Hemoglobin at Week 26 and Week 52",
   "description": "Protocol-specified blood samples were taken for the analyses of hemoglobin in plasma at designated time points.",
   "timeFrame": "Baseline, Week 26 (Treatment Period), Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Percentage of Participants With Modified TMA Response During the 26-week Treatment Period",
   "description": "The modified criteria for TMA response included a hematological response and a renal response. Hematological Response: if baseline platelet count ≤50000/mm\\^3, then the absolute platelet count had to be \\>50000/mm\\^3 without platelet transfusion support during the prior 7 days; if baseline platelet count \\>50000/mm\\^3, then there had to be a ≥50% increase in platelet count compared to baseline value without platelet transfusion support during the prior 7 days; at least 50% reduction of LDH from baseline and absence of schistocytes or normalization of LDH and absence of schistocytes. Renal response: at least 50% reduction of proteinuria from baseline. Participants must have met each response criterion, with each parameter meeting the requirement at 2 separate assessments obtained at least 24 hours apart, and any measurement in between.",
   "timeFrame": "Baseline through Week 26"
  },
  {
   "measure": "Stage 2: Change From Baseline in Number of Participants With TMA-associated Organ Dysfunction in the Renal System Through Week 26 and Week 52",
   "description": "Renal dysfunction was defined as doubling of serum creatinine from baseline or requirement of dialysis. Requirements for dialysis included: at the baseline visit, if there was any dialysis within 5 days prior to the first dose of study treatment; at the post-baseline visit, if there was any dialysis within 5 days prior to the visit. Participants categorized as those experiencing no symptoms at baseline and those experiencing symptoms at baseline.",
   "timeFrame": "Baseline, Week 26 (Treatment Period), Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Change From Baseline in Number of Participants With TMA-associated Organ Dysfunction in the Cardiopulmonary System Through Week 26 and Week 52",
   "description": "Cardiopulmonary dysfunction was defined as the presence of cardiopulmonary symptoms (excluding hypertension) or use of any mechanical ventilation. Cardiopulmonary symptoms included, but were not limited to, pleural effusion, pulmonary edema, pericardial effusion, and serositis. The presence of cardiopulmonary symptoms at baseline and post-baseline visits were assessed and recorded on the electronic case report form (eCRF). Use of any ventilatory or respiratory support, including mechanical ventilation, was reported on the participant's Nonpharmacologic Therapies and Procedures eCRF page. Participants categorized as those experiencing no symptoms at baseline and those experiencing symptoms at baseline.",
   "timeFrame": "Baseline, Week 26 (Treatment Period), Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Change From Baseline in Number of Participants With TMA-associated Organ Dysfunction in the Central Nervous System Through Week 26 and Week 52",
   "description": "Central nervous system dysfunction was defined as confirmed posterior reversible encephalopathy syndrome, or any signs of headache, confusion, visual loss, or seizures at baseline and post-baseline visits, as recorded on the eCRF. Participants categorized as those experiencing no symptoms at baseline and those experiencing symptoms at baseline.",
   "timeFrame": "Baseline, Week 26 (Treatment Period), Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Change From Baseline in Number of Participants With TMA-associated Organ Dysfunction in the Gastrointestinal System Through Week 26 and Week 52",
   "description": "Gastrointestinal dysfunction was defined as presence of signs and symptoms of gastrointestinal involvement at baseline and post-baseline visits, including diarrhea, vomiting, pain, and bleeding as recorded on the eCRF. Participants categorized as those experiencing no symptoms at baseline and those experiencing symptoms at baseline.",
   "timeFrame": "Baseline, Week 26 (Treatment Period), Week 52 (Follow-up Period)"
  },
  {
   "measure": "Stage 2: Percentage of Participants With TMA Relapse",
   "description": "For participants that met the criteria for TMA response during the 26-week Treatment Period, TMA relapse was defined as evidence of worsening hematologic and renal dysfunction due to TMA during the post-treatment Follow-up Period and required treatment intervention, as determined by the investigator.",
   "timeFrame": "Baseline through Week 52"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1. 12 years of age or older at time of consent/assent.\n2. Received HSCT within the past 12 months.\n3. Diagnosis of TMA that persists for at least 72 hours after initial management of any triggering agent/condition.\n4. A TMA diagnosis based on meeting the laboratory-based criteria during the Screening Period and/or ≤14 days prior to the Screening Period.\n5. Body weight ≥ 30 kilograms at Screening or ≤7 days prior to the start of the Screening Period (date of consent).\n6. Female participants of childbearing potential and male participants with female partners of childbearing potential must use highly effective contraception.\n7. Participants must be vaccinated against meningococcal infections if clinically feasible. Participants who cannot receive meningococcal vaccine should receive antibiotic prophylaxis. Participants \\<18 years of age must be re-vaccinated against Haemophilus influenzae type b (Hib) and Streptococcus pneumoniae if clinically feasible.\n8. Participants or their legally authorized representative must be capable of giving signed informed consent or assent.\n\nExclusion Criteria:\n\n1. Thrombotic thrombocytopenic purpura (TTP) evidenced by ADAMTS13 deficiency\n2. Known Shiga toxin-related hemolytic uremic syndrome as demonstrated by positive test.\n3. Positive direct Coombs test indicative of a clinically significant immune-mediated hemolysis not due to TMA.\n4. Clinical diagnosis of disseminated intravascular coagulation (DIC).\n5. Known bone marrow/graft failure for the current HSCT.\n6. Diagnosis of veno-occlusive disease which is unresolved at the time of Screening.\n7. Human immunodeficiency virus (HIV) infection.\n8. Unresolved meningococcal disease.\n9. Presence of sepsis requiring vasopressor support.\n10. Pregnancy or breastfeeding.\n11. Hypersensitivity to murine proteins or to one of the excipients of ravulizumab.\n12. Any ongoing or history of medical or psychological conditions unrelated to HSCT-TMA that could increase the risk to the participant or confound the outcome of the study.\n13. Respiratory failure requiring mechanical ventilation.\n14. Acute and/or chronic heart failure with an ejection fraction ≤ 40%.\n15. Previously or currently treated with a complement inhibitor.\n16. Participation in an interventional treatment study of any therapy for TMA.",
  "healthyVolunteers": false,
