forecastInput:
{
 "nctId": "NCT04287062",
 "briefTitle": "Examining the Role of the Orexin System in Sleep and Stress in Persons With Opioid Use Disorder",
 "officialTitle": "Examining the Role of the Orexin System in Sleep and Stress in Persons With Opioid Use Disorder",
 "leadSponsor": {
  "name": "Johns Hopkins University",
  "class": "OTHER"
 },
 "collaborators": [
  {
   "name": "National Heart, Lung, and Blood Institute (NHLBI)",
   "class": "NIH"
  }
 ],
 "startDate": "2020-11-20",
 "firstRegistered": "2020-02-25",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Sleep Disturbance",
  "Opioid-use Disorder"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 249,
 "briefSummary": "This study is designed to elucidate the role of the orexin neurotransmitter system in sleep disturbance and circadian rhythms of stress that might in turn influence relapse behaviors in persons on medication-assisted treatments (MAT) who are in early recovery from opioid use disorder (OUD). Briefly, the study will enroll recently abstinent OUD patients (N=200) maintained on either extended-release naltrexone (XR-NTX), buprenorphine, or methadone. Within each MAT group, participants will be randomized to either suvorexant or placebo. The study is expected to have a 20% treatment attrition rate which will result in N=160 completers in the entire study. Patients will be recruited from and treated at Ashley Addiction Treatment, Addiction Treatment Services at Johns Hopkins Bayview Medical Center, Man Alive, or community providers.",
 "arms": [
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Placebo sleep medication (2 placebo oral capsules)",
   "interventionNames": [
    "Drug: Placebos"
   ]
  },
  {
   "label": "Suvorexant",
   "type": "ACTIVE_COMPARATOR",
   "description": "Sleep medication (20mg suvorexant; 2 10mg capsules; patients can self-titrate to 1 10mg capsule)",
   "interventionNames": [
    "Drug: Suvorexant"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Suvorexant",
   "description": "Dual orexin receptor antagonist",
   "armGroupLabels": [
    "Suvorexant"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebos",
   "description": "Weight and color matched placebo",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Total Sleep Time",
   "description": "Mean total number of minutes slept per night as measured by actigraphy and self-reported sleep diary. Mean total sleep time will be collected over a seven-night period in weeks 0, 1, 4, and 8 of the trial.",
   "timeFrame": "28 days (collected over a seven-day period in weeks 0, 1, 4, and 8 of the trial)"
  },
  {
   "measure": "Total Wake Time After Sleep Onset",
   "description": "Mean total number of minutes awake between initial sleep onset and final morning awakening, measured by actigraphy and self-reported sleep diary. Mean wake after sleep onset will be collected over a seven-night period in weeks 0, 1, 4, and 8 of the trial.",
   "timeFrame": "28 days (collected over a seven-day period in weeks 0, 1, 4, and 8 of the trial)"
  },
  {
   "measure": "Change in Perceived Stress Scale 4 (PSS-4) Score",
   "description": "Mean daily scores on the PSS-4 (a four item scale self-reported scale than measures stress using a 0-4 Likert scale); total range of PSS-4 scores is 0-16; lower scores indicate lower daily stress relative to higher scores, which indicate higher daily stress. Mean PSS-4 scores will be collected over a seven-day period in weeks 0, 1, 4, and 8 of the trial.",
   "timeFrame": "28 days (collected over a seven-day period in weeks 0, 1, 4, and 8 of the trial)"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Between the ages of 21-65, inclusive.\n* Past 30-day sleep disturbance as evidenced by a Pittsburgh Sleep Quality Index Total Score \\>5.\n* Enrolled in either outpatient methadone-maintenance, buprenorphine-maintenance, or XR-NTX treatment for OUD.\n* Willingness to be maintained on a protocolized dose starting between 60-130mg methadone or 380mg XR-NTX for the duration of the study.\n* At least two weeks of continuous abstinence from illicit opioids as evidenced by self-report and urine drug screens collected as part of routine care.\n* Willing to comply with the study protocol, which will include weekly study visits, daily actigraphy and ecological momentary assessments.\n* Use of birth control throughout study.\n* Have no clinically significant chronic medical disorders or conditions that are judged by the investigators to prevent participation.\n\nExclusion Criteria:\n\n* Serious mental illnesses that are unstable and could affect study participation (thought disorders, hallucinations, delusions, thoughts of harm to self/others).\n* Current moderate to severe substance use disorder other than OUD.\n* Current illicit stimulant use, including cocaine and methamphetamine.\n* Pregnant or breast feeding.\n* Have a known allergy to the study medications.\n* Past 30-day prescribed use of suvorexant.\n* Current use of a benzodiazepine or other schedule IV medication for insomnia.\n* Use of Cytochrome P450 3A inhibitors.\n* Current narcolepsy, sleep paralysis, or restless leg syndrome as assessed by medical history\n* Apnea-hypopnea index \\> 30.\n* Use of glucocorticoid medications and any medication that would alter the hypothalamic-pituitary-adrenal axis.\n* Past 30-day suicidal behavior as assessed by the Columbia Suicide Severity Rating Scale (C-SSRS).\n* Have circumstances that would interfere with study participation (e.g., impending jail; severe clinical issues).",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "21 Years",
  "maximumAge": "65 Years"
 },
 "siteCount": 5,
 "countries": [
  "United States"
 ]
}

