forecastInput:
{
 "nctId": "NCT02104674",
 "briefTitle": "A Study Evaluating the Efficacy and Safety of Lebrikizumab in Adult Patients With Mild to Moderate Asthma",
 "officialTitle": "A Phase III, Randomized, Double-Blind, Placebo-Controlled Study to Evaluate the Efficacy and Safety of Lebrikizumab in Adult Patients With Mild to Moderate Asthma",
 "leadSponsor": {
  "name": "Hoffmann-La Roche",
  "class": "INDUSTRY"
 },
 "startDate": "2014-06-07",
 "firstRegistered": "2014-03-26",
 "conditions": [
  "Asthma"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "interventionModelDescription": "Participants will be randomized in a 1:1:1 ratio to receive lebrikizumab 125 mg, placebo, or Montelukast 10 mg.",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "DOUBLE",
   "maskingDescription": "Participants and investigators will remain blinded to the lebrikizumab and placebo arms only. Montelukast will be administered in tablet form and given in an open-label fashion.",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 313,
 "briefSummary": "This Phase III, randomized, double-blind, placebo-controlled, multicenter study will assess the efficacy and safety of lebrikizumab in adult patients with mild to moderate asthma treated with short-acting beta-agonist (SABA) therapy alone. Patients will be randomized in a 1:1:1 ratio to receive either blinded lebrikizumab or placebo treatment by subcutaneous (SC) injection (every 4 weeks for a total of 3 doses) or open-label treatment with Singulair (Montelukast; 10 mg daily). Time on study treatment will last 12 weeks.",
 "arms": [
  {
   "label": "Lebrikizumab",
   "type": "EXPERIMENTAL",
   "interventionNames": [
    "Drug: Lebrikizumab"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "interventionNames": [
    "Other: Placebo"
   ]
  },
  {
   "label": "Montelukast",
   "type": "ACTIVE_COMPARATOR",
   "interventionNames": [
    "Drug: Montelukast"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Lebrikizumab",
   "description": "Lebrikizumab 125 mg subcutaneous (SC) injection given on Days 1, 29, and 57",
   "armGroupLabels": [
    "Lebrikizumab"
   ],
   "otherNames": [
    "RO5490255"
   ]
  },
  {
   "type": "DRUG",
   "name": "Montelukast",
   "description": "10 mg tablet given orally once daily for 12 weeks, according to the approved label.",
   "armGroupLabels": [
    "Montelukast"
   ],
   "otherNames": [
    "Singulair"
   ]
  },
  {
   "type": "OTHER",
   "name": "Placebo",
   "description": "Lebrikizumab-matched placebo SC injection given on Days 1, 29, and 57",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline in Pre-bronchodilator Forced Expiratory Volume in 1 Second (FEV1) at Week 12",
   "description": "FEV1 is the amount of air which can be forcibly exhaled from the lungs in the first second of a forced exhalation. The active comparator treatment arm of open-label montelukast was included in the study design so that the sensitivity of the study could be evaluated with respect to the primary outcome measure, FEV1. Two mixed-effect models of repeated measures (MMRM) were used to estimate the absolute change from baseline values: one for the lebrikizumab vs. placebo primary comparison and the second for the montelukast vs. placebo sensitivity comparison.",
   "timeFrame": "Baseline through Week 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Lebrikizumab vs. Placebo: Change From Baseline in Asthma Reliever Medication Use at Week 12",
   "description": "Participants could only receive SABA therapy for asthma treatment as asthma reliever medication (\\<10 puffs daily). SABA use was recorded in the eDiary. A mixed-effect model of repeated measures (MMRM) was used to estimate the absolute change from baseline values for the comparison between the double-blind lebrikizumab and placebo study arms.",
   "timeFrame": "Baseline through Week 12"
  },
  {
   "measure": "Lebrikizumab vs. Placebo: Change From Baseline in the Standardized Asthma Quality of Life Questionnaire (AQLQ[S]) Overall Score at Week 12",
   "description": "The AQLQ\\[S\\] was used to assess the participant's asthma-specific health-related quality of life. The 32-item questionnaire contains four domains: activity limitations, symptoms, emotional function, and environmental stimuli. The AQLQ\\[S\\] has a recall specification of 2 weeks. Participants were asked to think about how they had been during the previous 2 weeks and to respond to each of the 32 questions on a 7-point scale (7 = not impaired at all; 1 = severely impaired). An increase in the AQLQ score indicates a better quality of life. The overall AQLQ score is the mean of all 32 responses and the individual domain scores are the means of the items in those domains. A mixed-effect model of repeated measures (MMRM) was used to estimate the change from baseline values.",
   "timeFrame": "Baseline through Week 12"
  },
  {
   "measure": "Change From Baseline in Fractional Exhaled Nitric Oxide (FeNO) Levels at Week 12",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Montelukast vs. Placebo: Change Fom Baseline in Morning Pre-bronchodilator Peak Expiratory Flow (PEF) at Week 12",
   "description": "PEF is defined as the maximum airflow during a forced expiration beginning with the lungs fully inflated. The active comparator treatment arm of open-label montelukast was included in the study design so that the sensitivity of the study could be evaluated with respect to this secondary outcome measure of PEF. A mixed-effect model of repeated measures (MMRM) was used to estimate the absolute change from baseline values for the sensitivity comparison between montelukast (open-label, active comparator) and placebo study arms.",
   "timeFrame": "Baseline through Week 12"
  },
  {
   "measure": "Lebrikizumab vs. Placebo: Change From Baseline in Morning Pre-bronchodilator PEF at Week 12",
   "description": "Peak expiratory flow (PEF) is defined as the maximum airflow during a forced expiration beginning with the lungs fully inflated. A mixed-effect model of repeated measures (MMRM) was used to estimate the absolute change from baseline values for the comparison between the double-blind lebrikizumab and placebo study arms.",
   "timeFrame": "Baseline through Week 12"
  },
  {
   "measure": "Lebrikizumab vs. Placebo: Number of Participants With Treatment Failure",
   "description": "Treatment failure was defined as a worsening of asthma symptoms (per investigator's assessment of participant report) in association with either relative decline in pre-bronchodilator FEV1 \\>=20%; or \\>=20% decline in morning pre-bronchodilator PEF on 2 consecutive days compared with baseline; or use of \\>=10 puffs of albuterol metered dose inhaler (MDI); or \\>=2 additional administrations (or any new use) of nebulized short-acting β-agonist (SABA) therapy within any calendar day; or need for any inhaled, oral, or parenteral corticosteroid or for a controller medication. The hazard ratio from the Cox Proportional Hazards model compared the risk of treatment failure for the lebrikizumab-treated and placebo participants.",
   "timeFrame": "Baseline up to Week 12"
  },
  {
   "measure": "Lebrikizumab vs. Placebo: Time to Treatment Failure",
   "description": "Treatment failure was defined as a worsening of asthma symptoms (per investigator's assessment of participant report) in association with either relative decline in pre-bronchodilator FEV1 \\>=20%; or \\>=20% decline in morning pre-bronchodilator PEF on 2 consecutive days compared with baseline; or use of \\>=10 puffs of albuterol metered dose inhaler (MDI); or \\>=2 additional administrations (or any new use) of nebulized short-acting β-agonist (SABA) therapy within any calendar day; or need for any inhaled, oral, or parenteral corticosteroid or for a controller medication. Time to treatment failure was estimated using Kaplan-Meier method.",
   "timeFrame": "Basleine up to Week 12"
  },
  {
   "measure": "Change From Baseline in Blood Eosinophil Count at Week 12",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Change From Baseline in Serum Periostin at Week 12",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Change From Baseline in Total Immunoglobulin E (IgE) Levels at Week 12",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Change From Baseline in C-C Motif Chemokine Ligand 13 (CCL-13) Levels at Week 12",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Change From Baseline in CCL-17 Levels at Week 12",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Maximum Serum Lebrikizumab Concentration (Cmax) After the First Dose",
   "description": "According to the protocol and statistical analysis plan, a single PK sample was collected per participant after the first dose at the expected time of the maximum serum lebrikizumab concentration.",
   "timeFrame": "Predose on Day 0 and post-Day 1 dose on Day 7"
  },
  {
   "measure": "Time to Reach Maximum Lebrikizumab Concentration After the First Dose (Tmax)",
   "description": "According to the protocol and statistical analysis plan, the Tmax, Week1 (first dose) value was estimated on the basis of a single pharmacokinetic (PK) timepoint per participant after the first dose, which was taken at the expected time of the maximum serum lebrikizumab concentration.",
   "timeFrame": "Post-Day 1 dose on Day 7"
  },
  {
   "measure": "Elimination Half-Life (t1/2) of Lebrikizumab",
   "description": "According to the protocol and statistical analysis plan, the t1/2 was estimated based on the seven total PK samples collected per participant.",
   "timeFrame": "Predose on Days 0, 28, and 56, and on Days 7, 84, 112, and 140"
  },
  {
   "measure": "Predose Serum Lebrikizumab Concentration (Cmin) at Week 4",
   "timeFrame": "Predose on Day 28 (Week 4)"
  },
  {
   "measure": "Serum Lebrikizumab Concentration at Week 12",
   "timeFrame": "On Day 84 (Week 12)"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Age 18-75 years old at study start\n* Asthma diagnosis for \\>/= 12 months prior to study start\n* Bronchodilator response at screening\n* Pre-bronchodilator FEV1 of 60% - 85% predicted at both screening visits 2 and 3\n* No other clinically significant lung disease as confirmed by chest X-ray or computed tomography (CT) scan\n* Stable and symptomatic asthma during the screening period\n* Use of effective contraception, as defined by the protocol, until 24 weeks after the last dose\n\nExclusion Criteria:\n\n* Maintenance of corticosteroid therapy, defined as daily or alternate-day oral corticosteroid maintenance therapy within 3 months prior to study start\n* Treatment with systemic or inhaled corticosteroids within 4 weeks prior to study start or during the screening period for any reason, including an acute exacerbation event\n* Treatment with a leukotriene receptor antagonist (LTRA), long-acting beta-agonist (LABA) long-acting muscarinic antagonist (LAMA), zileuton, roflumilast, or theophylline within 2 weeks prior to study start\n* Documented prior treatment failure with Montelukast\n* Treatment with intra-articular corticosteroids within 4 weeks prior to study start or during the screening period or anticipated need for intra articular corticosteroids during the course of the study\n* Any infection requiring hospital, IV or IM antibiotic treatment or any respiratory infection within 4 weeks of study start. Any infection requiring oral antibiotic treatment within 2 weeks of study start, or any parasitic infection within 6 months of study start\n* Clinically significant abnormality found during screening or clinically significant medical disease that is uncontrolled despite treatment that is likely, in the opinion of the investigator, to impact the patient's ability to participate in the study, or impact the study assessments\n* History of interstitial lung disease, chronic obstructive pulmonary disease (COPD), or other clinically significant lung disease other than asthma\n* History of alcohol or drug abuse that would impair or risk the patient's full participation in the study, in the opinion of the investigator\n* Current or history of smoking (\\> 10 pack-years), or unwillingness to abstain from smoking for the duration of the study\n* Past and/or current use of any anti-IL-13 or anti- IL4/IL-13 therapy, including lebrikizumab\n* Use of a licensed or investigational monoclonal antibody other than anti IL-13 or anti-IL-4/IL-13, including, but not limited to, omalizumab, anti-IL-5, or anti IL-17, within 6 months or 5 drug half-lives prior to Visit 1 (whichever is longer) or during screening\n* Use of a systemic immunomodulatory or immunosuppressive therapy within 3 months or 5 drug half-lives prior to study start or during screening\n* Use of other investigational therapy within 4 weeks or 5 drug half-lives prior to study start (whichever is longer) or during screening\n* Initiation of or change in allergen immunotherapy within 3 months prior to study start or during screening\n* Receipt of a live attenuated vaccine within 4 weeks prior to study start of during screening\n* Pregnancy or breast feeding\n* Body mass index \\> 38 kg/m2\n* Body weight \\< 40 kg\n* History of bronchial thermoplasty",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "75 Years"
 },
