    "Placebo SC Q2W"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Annualized Rate of Moderate and Severe COPD Exacerbations Over the 52-week Treatment Period",
   "description": "A moderate COPD exacerbation was defined as new or increased COPD symptoms (e.g., dyspnea, sputum volume, and sputum purulence) that lead to treatment (duration ≥ 3 days) with systemic corticosteroids (oral, intravenous \\[IV\\], or intramuscular \\[IM\\]) at a dose of \\> 10 milligrams per day (mg/day) prednisolone equivalent and/or antibiotics. A severe COPD exacerbation was defined as new or increased COPD symptoms that lead to hospitalization (duration \\> 24 hours) or death. The unadjusted AER was estimated as the total number of exacerbations observed over the treatment period divided by the total participant-years at risk (participant-years = date of first study drug administration to completion or discontinuation during the double-blind treatment period divided by 365.25 days). The adjusted AER was estimated using negative binomial regression. Adjusted rate values have been reported. A method of dispersion was not specified in the SAP.",
   "timeFrame": "Up to 52 weeks"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Annualized Rate of Moderate and Severe COPD Exacerbations Over the 52-week Treatment Period in Participants With Low Baseline Blood Eosinophil Level (<300 Cells Per Microliter [Cells/µL])",
   "description": "A moderate COPD exacerbation was defined as new or increased COPD symptoms (e.g., dyspnea, sputum volume, and sputum purulence) that lead to treatment (duration ≥ 3 days) with systemic corticosteroids (oral, intravenous \\[IV\\], or intramuscular \\[IM\\]) at a dose of \\> 10 milligrams per day (mg/day) prednisolone equivalent and/or antibiotics. A severe COPD exacerbation was defined as new or increased COPD symptoms that lead to hospitalization (duration \\> 24 hours) or death. The unadjusted AER was estimated as the total number of exacerbations observed over the treatment period divided by the total participant-years at risk (participant-years = date of first study drug administration to completion or discontinuation during the double-blind treatment period divided by 365.25 days). The adjusted AER was estimated using negative binomial regression. Adjusted rate values have been reported A method of dispersion was not specified in the SAP.",
   "timeFrame": "Up to 52 weeks"
  },
  {
   "measure": "Time to First Moderate or Severe COPD Exacerbation During the 52-week Treatment Period",
   "description": "Time to first moderate or severe COPD exacerbation was defined as the time from the first administration of study drug to the first incidence of moderate or severe COPD exacerbation event during the 52-week treatment period. A moderate COPD exacerbation was defined as new or increased COPD symptoms (e.g., dyspnea, sputum volume, and sputum purulence) that lead to treatment (duration ≥3 days) with systemic corticosteroids (oral, IV, or IM) at a dose of \\>10 mg/day prednisolone equivalent and/or antibiotics. A severe COPD exacerbation was defined as new or increased COPD symptoms that lead to hospitalization (duration \\> 24 hours) or death. Kaplan-Meier (K-M) method was used to estimate the median time.",
   "timeFrame": "Up to 52 weeks"
  },
  {
   "measure": "Absolute Change From Baseline in Health-related Quality-of-life (HRQoL) at Week 52, as Assessed Through the Saint George's Respiratory Questionnaire-COPD (SGRQ-C) Total Score",
   "description": "SGRQ-C is a disease-specific, self-administered instrument designed to assess the impact of COPD on participants' health status and well-being based on their perception of COPD-related experiences. The questionnaire consists of 40 items across three sub-domains: symptoms (respiratory symptoms and severity- 7 items), activity (activities causing or limited by breathlessness-13 items) and impacts (social functioning and psychological disturbances due to airway disease- 20 items). Each response is assigned a unique empirically derived weight. Total score is calculated by summing the weights to all the positive responses across each domain, with scores ranging from 0 (no impairment) to 100 (maximum impairment), with lower scores indicating better HRQoL. Adjusted mean of change from baseline (CFB) is reported here.",
   "timeFrame": "At Week 52"
  },
  {
   "measure": "Absolute Change From Baseline in Post-bronchodilator Forced Expiratory Volume in 1 Second (FEV1) (Liters) at Week 52",
   "description": "Post-bronchodilator FEV1 was defined as the FEV1 value measured with spirometry 20-30 minutes after bronchodilator use. Maximal bronchodilation was achieved via administration of either albuterol (90 micrograms \\[µg\\] metered dose) or salbutamol (100 µg metered dose), with or without a spacer device, up to a maximum of 4 inhalations. Adjusted mean of CFB is reported here.",
   "timeFrame": "At Week 52"
  },
  {
   "measure": "Absolute Change From Baseline in Evaluating Respiratory Symptoms in COPD (E-RS: COPD) Total Score at Week 52",
   "description": "The EXAcerbations of Chronic Pulmonary Disease Tool (EXACT) is a 14-item participant-reported instrument used to assess the frequency, severity, and duration of COPD exacerbations using a daily electronic diary (eDiary). It includes four domains: breathlessness (5 items), cough and sputum (3 items), chest symptoms (3 items), and additional attributes (tired or weak, sleep disturbance, and scared or worried; 3 items). The E-RS:COPD is an 11-item subset of the EXACT designed to assess the severity of cardinal respiratory symptoms of COPD, including breathlessness, cough, sputum, chest congestion, and chest tightness. It consists of three subscales: RS-Breathlessness, RS-Cough \\& Sputum, and RS-Chest Symptoms. Items are scored on 5- or 6-point Likert scales, and the total score is calculated by summing the item scores, ranging from 0 (no impact) to 40 (high impact), with higher scores indicating greater symptom severity. Adjusted mean of CFB is reported here.",
   "timeFrame": "At Week 52"
  },
  {
   "measure": "Percentage of Participants With Improvement in HRQoL at Week 52, as Assessed by SGRQ-C",
   "description": "Percentage of participants with SGRQ-C improvement was defined as the percentage of participants with an absolute decrease from baseline of ≥4 points in SGRQ-C total score. SGRQ-C is a disease-specific, self-administered instrument designed to assess the impact of COPD on participants' health status and well-being based on their perception of COPD-related experiences. The questionnaire consists of 40 items across three sub-domains: symptoms (respiratory symptoms and severity- 7 items), activity (activities causing or limited by breathlessness-13 items) and impacts (social functioning and psychological disturbances due to airway disease- 20 items). Each response is assigned a unique empirically derived weight. Total score is calculated by summing the weights to all the positive responses across each domain, with scores ranging from 0 (no impairment) to 100 (maximum impairment), with lower scores indicating better HRQoL.",
   "timeFrame": "At Week 52"
  },
  {
   "measure": "Annualized Rate of Severe COPD Exacerbations Over the 52-week Treatment Period",
   "description": "A severe COPD exacerbation was defined as new or increased COPD symptoms that lead to hospitalization (duration \\> 24 hours) or death. The unadjusted AER was estimated as the total number of exacerbations observed over the treatment period divided by the total participant-years at risk (participant-years = date of first study drug administration to completion or discontinuation during the double-blind treatment period divided by 365.25 days). The adjusted AER was estimated using negative binomial regression. Adjusted rate values have been reported. A method of dispersion was not specified in the SAP.",
   "timeFrame": "Up to 52 weeks"
  },
  {
   "measure": "Number of Participants With Treatment-emergent Adverse Events (TEAEs), Including Serious Adverse Events (SAEs), and Adverse Events of Special Interest (AESIs)",
   "description": "An AE was defined as any untoward medical occurrence in a clinical study participant temporally associated with the use of a study treatment, whether or not considered related to the study treatment. An AE can therefore be any unfavorable and unintended sign (including an abnormal laboratory finding), symptom, or disease (new or exacerbated) temporally associated with the use of study intervention. An SAE was defined as any untoward medical occurrence that, at any dose: results in death; is life-threatening; requires inpatient hospitalization or prolongation of existing hospitalization; results in persistent disability or incapacity; is a congenital anomaly or birth defect; is medically significant. An AESI was defined as any of the following: cases of potential drug-induced liver injury; suspected transmission of an infectious agent by a study treatment; major adverse cardiovascular events (MACE); anaphylaxis, anaphylactoid, and hypersensitivity reactions.",
   "timeFrame": "Up to a maximum of 62 weeks"
  },
  {
   "measure": "Number of Participants Who Died or Discontinued Study Due to TEAEs",
   "description": "An AE was defined as any untoward medical occurrence in a clinical study participant temporally associated with the use of a study treatment, whether or not considered related to the study treatment. An AE can therefore be any unfavorable and unintended sign (including an abnormal laboratory finding), symptom, or disease (new or exacerbated) temporally associated with the use of study intervention. Participants who died or discontinued the study due to TEAEs will be reported here.",
   "timeFrame": "Up to a maximum of 62 weeks"
  },
  {
   "measure": "Serum Concentration of Astegolimab",
   "timeFrame": "Up to a maximum of 62 weeks"
  },
  {
   "measure": "Number of Participants With Anti-drug Antibodies (ADAs) to Astegolimab",
   "description": "Participants were considered to be ADA positive if they were ADA negative at baseline but developed an ADA response following astegolimab administration (treatment-induced ADA response), or if they were ADA positive at baseline and the titer of one or more post-baseline samples was greater than the titer of the baseline sample by a scientifically reasonable margin such as at least 0.60 titer unit (t.u.) greater than the baseline titer result (treatment-enhanced ADA response).",
   "timeFrame": "Up to a maximum of 62 weeks"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria\n\n* Documented COPD diagnosis for ≥ 12 months\n* History of frequent exacerbations, defined as having had 2 or more moderate or severe COPD exacerbations within 12 months prior to screening\n* Post-bronchodilator FEV1 ≥ 20% and \\< 80% of predicted at screening\n* Post-bronchodilator FEV1/FVC \\< 0.70 at screening\n* Modified Medical Research Council (dyspnea scale) (mMRC) score ≥ 2\n* Current tobacco smoker or former smoker with a history of smoking ≥ 10 pack-years\n* On optimized COPD maintenance therapy as defined below for ≥ 12 months prior to screening, and stable on current therapy for at least 4 weeks prior to screening: Inhaled corticosteroid (ICS) plus long-acting beta-agonist (LABA), Long-acting muscarinic antagonist (LAMA) plus LABA, ICS plus LAMA plus LABA\n* Chest X-ray or computed tomography (CT) scan within 6 months prior to screening or chest X-ray during the screening period that confirms the absence of clinically significant lung disease besides COPD\n\nExclusion Criteria\n\n* Current documented diagnosis of asthma\n* History of clinically significant pulmonary disease other than COPD\n* Diagnosis of 1-antitrypsin deficiency\n* History of long-term treatment with oxygen at \\> 4.0 liters/minute\n* Lung volume reduction surgery or procedure within 12 months prior to screening\n* Individuals participating in, or scheduled for, an intensive COPD rehabilitation program (participants who are in the maintenance phase of a rehabilitation program are eligible)\n* History of lung transplant\n* Any infection that resulted in hospital admission for ≥ 24 hours and/or treatment with oral, IV, or IM antibiotics within 4 weeks prior to or during screening\n* Upper or lower respiratory tract infection within 4 weeks prior to or during screening\n* Treatment with oral, IV, or IM corticosteroids within 4 weeks prior to initiation of study drug\n* Initiation of or change in non-biologic immunomodulatory or immunosuppressive therapy within 3 months prior to screening\n* Unstable cardiac disease, myocardial infarction, or New York Heart Association Class III or IV heart failure within 12 months prior to screening",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "40 Years",
  "maximumAge": "80 Years"
 },
