{
 "nctId": "NCT06470828",
 "briefTitle": "A Study of TAK-861 for the Treatment of Narcolepsy Type 1",
 "officialTitle": "A Randomized, Double-Blind, Placebo-Controlled Study to Evaluate the Efficacy and Safety of TAK-861 for the Treatment of Narcolepsy With Cataplexy (Narcolepsy Type 1)",
 "leadSponsor": {
  "name": "Takeda",
  "class": "INDUSTRY"
 },
 "startDate": "2024-07-02",
 "firstRegistered": "2024-06-18",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Narcolepsy Type 1"
 ],
 "keywords": [
  "Drug Therapy"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "DOUBLE",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 168,
 "briefSummary": "The main aim of this study is to learn how effective TAK-861 (oveporexton) is in improving excessive sleepiness during the day (called excessive daytime sleepiness or EDS) after 3 months of treatment. Other aims are to learn how effective TAK-861 (oveporexton) is in lowering the number of sudden, unexpected attacks of muscle weakness while staying conscious (cataplexy) in a week; to learn the effect TAK-861 (oveporexton) has on participants' ability to maintain attention, participant's overall quality of life, the spectrum of narcolepsy symptoms, and daily life functions; and to learn about the safety of TAK-861 (oveporexton).",
 "detailedDescription": "The drug being tested in this study is called TAK-861 (oveporexton). TAK-861 (oveporexton) is being tested to evaluate its efficacy and safety in people with narcolepsy type 1 (NT1).\n\nThe study will enroll approximately 152 patients. Participants will be randomly assigned (by chance, like flipping a coin) to one of the three treatment groups:\n\n1. TAK-861 Dose 1\n2. TAK-861 Dose 2\n3. Placebo\n\nThe study drug will be administered for 12 weeks. This multi-center trial will be conducted globally.",
 "arms": [
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Participants received oveporexton (OVE)-matching placebo tablets, orally, for 12 weeks.",
   "interventionNames": [
    "Drug: Placebo"
   ]
  },
  {
   "label": "OVE 1 mg BID",
   "type": "EXPERIMENTAL",
   "description": "Participants received OVE tablets, 1 milligram (mg), orally, for 12 weeks.",
   "interventionNames": [
    "Drug: Oveporexton"
   ]
  },
  {
   "label": "OVE 2 mg BID",
   "type": "EXPERIMENTAL",
   "description": "Participants received OVE tablets, 2 mg, orally, for 12 weeks.",
   "interventionNames": [
    "Drug: Oveporexton"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Oveporexton",
   "description": "Oral tablet.",
   "armGroupLabels": [
    "OVE 1 mg BID",
    "OVE 2 mg BID"
   ],
   "otherNames": [
    "TAK-861"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "OVE-matching placebo tablet.",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline to Week 12 in Mean Sleep Latency From the 4 Maintenance of Wakefulness Test (MWT) Wake Trials",
   "description": "The MWT evaluates a person's ability to remain awake under soporific conditions for a defined period of time. Because there is no biological measure of wakefulness, wakefulness is measured indirectly by the inability or delayed tendency to fall asleep. This tendency to fall asleep is measured via electroencephalography-derived sleep latency in the MWT. The MWT consists of four 40-minute sessions (trials) done 2 hours apart. Sleep latency in each session was recorded. Participants were required to stay awake in between the four sessions. A positive change from baseline indicates an improvement. The linear mixed effects model for repeated measures (MMRM) was used for analysis.",
   "timeFrame": "Baseline, Week 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline to Week 12 in Epworth Sleepiness Scale (ESS) Total Score",
   "description": "The ESS provides individuals with 8 different situations of daily life and asks them how likely they are to fall asleep in those situations (scored 0 to 3) and to try to imagine their likelihood of dozing even if they have not actually been in the identical situation; the scores are summed to give an overall score of 0 to 24. Higher scores indicate stronger subjective daytime sleepiness. A negative change from baseline indicates an improvement. The linear MMRM was used for analysis.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Weekly Cataplexy Rate (WCR) at Week 12",
   "description": "Participants completed a daily participant-reported cataplexy diary to record self-reported episodes of cataplexy attacks. WCR = (total number of cataplexy attacks over a number of non-missing diary days for a given period/number of non-missing diary days in that period)\\*7. The generalized estimating equations (GEE) model was used for analysis. Reported here is the estimated mean of incidence rate with a 95 percent (%) confidence interval (CI).",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Change From Baseline to Week 12 in Mean Number of Lapses on the Psychomotor Vigilance Test (PVT)",
   "description": "The PVT is a simple reaction performance task that aims to measure sustained attention. The mean number of lapses (delayed responses to a visual cue from intraday sessions) from the two 10-minute intraday sessions was used as a measure of objective sustained attention. A negative change from baseline indicates an improvement. A constrained Longitudinal Data Analysis (cLDA) model was used to analyze the mean number of lapses and to estimate change from baseline at each visit.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Responder Rate on Patient Global Impression of Change (PGI-C) Score at Week 12",
   "description": "The PGI-C is a participant self-rated scale to assess change in daytime sleepiness and overall narcolepsy symptoms. The PGI-C includes 7 items being scored from 1 (best outcome) to 7 (worst outcome) with 4 being no change. Responders were the participants reporting \"1=very much improved\" or \"2=much improved\" on PGI-C. Responder rate (proportion of participants who were responders) was estimated using a GEE model.",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Change From Baseline to Week 12 in Narcolepsy Severity Scale for Clinical Trials (NSS-CT) Total Score",
   "description": "The NSS-CT is a 15-item self-administered questionnaire that assesses the severity and consequences of the 5 major narcolepsy symptoms such as daytime sleepiness, cataplexy, hallucinations, sleep paralysis, and disturbed nighttime sleep (DNS) with a total score range of 0 to 57 (sum of 6 items that assess symptoms severity are rated using a six-point Likert scale \\[0-5\\] and 9 items that describe the symptom effect on daily life are rated using a four-point Likert scale \\[0-3\\]). Higher total scores mean a worse outcome. A negative change from baseline indicates an improvement. The linear MMRM was used for analysis.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Change From Baseline to Week 12 in Functional Impacts of Narcolepsy Instrument (FINI) Domain Scores",
   "description": "The FINI measures the functional impacts of narcolepsy across 6 domains Tiredness (items 1-7), Cognitive Functioning (items 8-12), Cataplexy (items 13-17), Social Activities (items 18-21), Everyday Activities (items 22-25), and Everyday Responsibilities (items 26-28). Each item asks about the impact that narcolepsy has had on their daily functioning during the past 7 days, and is scored from 0 to 4, where 0 indicates the best health and 4 the worst. An average score is calculated for each domain and then standardized to a 0-100 scale, where 0 indicates the best health and 100 the worst health. Standardized score = average score/4 × 100. A negative change from baseline indicates and improvement. The linear MMRM was used for analysis.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Change From Baseline to Week 12 in Short Form-36 Survey (SF-36) Mental and Physical Component Scores",
   "description": "The SF-36 is participant-reported survey of participant health that assesses the quality of life and includes both physical and mental components. The scores for each component range from 0 to 100. Higher scores represent better health-related quality of life. A positive change from baseline indicates an improvement. The linear MMRM was used for analysis.",
   "timeFrame": "Baseline, Week 12"
  },
  {
   "measure": "Number of Participants With At Least One Treatment-Emergent Adverse Event (TEAE)",
   "description": "An adverse event (AE) is any untoward medical occurrence in a clinical investigation participant administered a pharmaceutical product. A TEAE is defined as any event emerging or manifesting at or after the initiation of treatment with a study intervention or medicinal product or any existing event that worsens in either intensity or frequency following exposure to the study intervention or medicinal product.",
   "timeFrame": "Up to 16 weeks"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1. The participant has a body mass index (BMI) within the range 18 to 40 kilograms per meter square (kg/m\\^2).\n2. The participant has an International Classification of Sleep Disorders, Third Edition (ICSD-3) or International Classification of Sleep Disorders, Third Edition, Text Revision (ICSD-3-TR) diagnosis of NT1.\n3. The participant has greater than or equal to (≥)4 partial or complete episodes of cataplexy/week (WCR).\n4. The participant is positive for the human leukocyte antigen (HLA) genotype HLA-DQB1\\*06:02 or results from radioimmunoassay indicate the participant's cerebrospinal fluid (CSF) orexin (OX)/hypocretin-1 concentration is less than or equal to (≤)110 picograms per milliliter (pg/mL) \\[or less than one-third of the mean values obtained in normal participants within the same standardized assay\\].\n\nExclusion Criteria:\n\n1. The participant has a current medical disorder, other than narcolepsy with cataplexy, associated with EDS.\n2. The participant: (a) has a history of myocardial infarction; (b) has a history of clinically significant hepatic disease, thyroid disease, coronary artery disease, cardiac rhythm abnormality or heart failure; or (c) has any medical condition (such as unstable cardiovascular, pulmonary, renal or gastrointestinal disease).\n3. The participant has current or recent (within 6 months) gastrointestinal disease that is expected to influence the absorption of drugs.\n4. The participant has a history of cancer in the past 5 years.\n5. The participant has a clinically significant history of head injury or head trauma.\n6. The participant has a history of epilepsy, seizure, or convulsion.\n7. The participant has a history of cerebral ischemia, transient ischemic attack (\\<5 years from screening), intracranial aneurysm, or arteriovenous malformation.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "16 Years",
  "maximumAge": "70 Years"
 },
 "siteCount": 53,
 "countries": [
