   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline in the 24-Hour Average Pain Intensity (API) Between Week 2 and Week 12 [Core Phase]",
   "description": "NOTES:\n\n* For non-US regulatory authorities: Change from baseline to the average score of the entire period between Week 2 and Week 12 in the 24 h API analyzed using ANCOVA.\n* The 24 h API was assessed and reported in the e-diary once daily in the evening, using an 11 point numeric pain rating scale NPRS\\] (from 0 = no pain to 10 = pain as bad as you can imagine).\n* The outcome was the change from baseline to the average score over the entire period between Week 2 and Week 12. A negative change indicates a reduction in pain.",
   "timeFrame": "From the Baseline Phase (Day -7 to Day -1) to Visit 6 (Week 12/Day 84)."
  },
  {
   "measure": "Change From Baseline in the 24-Hour API to Week 12 [Core Phase]",
   "description": "NOTES:\n\n* For US regulatory authority: Change from baseline to the weekly average score of Week 12 in the 24 h API analyzed using MMRM.\n* The 24 h API was assessed and reported in the e-diary once daily in the evening, using an 11 point numeric pain rating scale NPRS\\] (from 0 = no pain to 10 = pain as bad as you can imagine).\n* The outcome was the change from baseline to the weekly average score at Week 12. A negative change indicates a reduction in pain.",
   "timeFrame": "From the Baseline Phase (Day -7 to Day -1) to Visit 6 (Week 12/Day 84)."
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline in the 24-Hour API Between Week 2 and Week 42 [Extension Phase]",
   "description": "NOTES:\n\n* For non-US regulatory authorities: Change from baseline to the average score of the entire period between Weeks 2-42 in the 24 h API.\n* The 24 h API was assessed and reported in the e-diary once daily in the evening, using an 11 point numeric pain rating scale NPRS\\] (from 0 = no pain to 10 = pain as bad as you can imagine).\n* The outcome was the change from baseline to the average score over the entire period between Week 2 and Week 42. A negative change indicates a reduction in pain.",
   "timeFrame": "Baseline Phase (Day -7 to Day -1) up to the Final Visit (Week 42/Day 294)."
  },
  {
   "measure": "Change From Baseline in the 24-Hour API at Week 42 [Extension Phase]",
   "description": "NOTES:\n\n* For US regulatory authority: Change from baseline to the weekly average score of Week 42 in the 24 h API analyzed using ANCOVA..\n* The 24 h API was assessed and reported in the e-diary once daily in the evening, using an 11 point numeric pain rating scale NPRS\\] (from 0 = no pain to 10 = pain as bad as you can imagine).\n* The outcome was the change from baseline to the weekly average score at Week 42. A negative change indicates a reduction in pain.",
   "timeFrame": "Baseline Phase (Day -7 to Day -1) up to the Final Visit (Week 42/Day 294)."
  },
  {
   "measure": "Change From Baseline in Treatment Area Size at Week 12 [Core Phase]",
   "description": "Treatment area size was measured in square centimeters (cm²) and comprised the area identified by the participant as the usually most painful area(s), and/or the area characterized by dynamic mechanical allodynia (DMA), and/or the area of pinprick hyperalgesia. Treatment area size was assessed at Visit 2 (Day 1) before IMP application and at Visit 6 (Week 12/Day 84) before IMP application. The outcome was the change from baseline to Week 12 in treatment area size. A negative change indicates a reduction in treatment area size.",
   "timeFrame": "From Visit 2 (Day 1, before IMP application) to Visit 6 (Week 12/Day 84, before IMP application)."
  },
  {
   "measure": "Change From Baseline in Treatment Area Size at Week 42 [Extension Phase]",
   "description": "Treatment area size was measured in square centimeters (cm²) and comprised the area identified by the participant as the usually most painful area(s), and/or the area characterized by dynamic mechanical allodynia (DMA), and/or the area of pinprick hyperalgesia. The outcome was the change from baseline to the Final Visit at Week 42 in treatment area size. A negative change indicates a reduction in treatment area size.",
   "timeFrame": "From baseline to the Final Visit at Week 42."
