 "primaryOutcomes": [
  {
   "measure": "Adjusted Exacerbation Rate of Asthma During the 52-Week PCP",
   "description": "Asthma exacerbation is defined as new or increased asthma symptoms (i.e., wheeze, cough, dyspnea, chest tightness, and/or night-time awakening due to these symptoms) that lead to systemic corticosteroid (CS) treatment (oral, intravenous (IV), or intramuscular (IM) CS for ≥ 3 days or an emergency department visit with at least one dose of IV or IM CS) or to hospitalization.\n\nResults are reported as a 'Number' representing the model-adjusted incidence rate of asthma exacerbations per person-year. To account for early discontinuation, for each patient, the time at risk (in years) was computed as the duration of this time period (last day minus first day \\[in days\\] plus 1) divided by 365.25. The 'first day' was the day of randomization to the PCP. For patients entering the ATE, the 'last day' was the day prior to ATE randomization. For patients not entering the ATE, the 'last day' was at the last study visit on/prior to Study Day 379 (365 days plus a 14-day window).",
   "timeFrame": "Baseline up to 52 weeks"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Absolute Change From Baseline in Pre-Bronchodilator FEV1 at Week 52",
   "description": "FEV1 is the maximal amount of air, which can be forcefully exhaled in one second. Measurements were performed before use of bronchodilator. Reported is the absolute change from baseline in FEV1 to the end of the placebo-controlled period at Week 52.",
   "timeFrame": "Week 52"
  },
  {
   "measure": "Time to First Asthma Exacerbation During the 52-week PCP",
   "description": "An asthma exacerbation is defined as new or increased asthma symptoms (including wheeze, cough, dyspnea, chest tightness, and/or night-time awakening due to these symptoms) that lead to treatment with systemic corticosteroids or to hospitalisation. Treatment with systemic corticosteroids is defined as treatment with oral, intravenous (IV), or intramuscular (IM) corticosteroids for at least 3 days or an emergency department visit with at least one dose of IV or IM corticosteroids. Reported is the time to first asthma exacerbation during the 52-week placebo-controlled period.",
   "timeFrame": "Baseline up to 52 weeks"
  },
  {
   "measure": "Rate of Urgent Asthma-Related Health Care Utilization (HCU) During the 52-week PCP",
   "description": "Urgent health care utilization was defined as hospitalizations, emergency department visits, and acute care visits.\n\nResults are reported as a 'Number' representing the model-adjusted incidence rate of urgent asthma-related HCU events per person-year. To account for early discontinuation, for each patient, the time at risk (in years) was computed as the duration of this time period (last day minus first day \\[in days\\] plus 1) divided by 365.25. The 'first day' was the day of randomization to the PCP. For patients entering the ATE, the 'last day' was the day prior to ATE randomization. For patients not entering the ATE, the 'last day' was at the last study visit on/prior to Study Day 379 (365 days plus a 14-day window).",
   "timeFrame": "Baseline up to Week 52"
  },
  {
   "measure": "Absolute Change From Baseline in Standardized AQLQ Score at Week 52",
   "description": "Asthma-specific health-related quality of life was assessed by the overall score of the Standardized AQLQ. The AQLQ is a self-administered test with 32 questions; each with seven possible answers ranging from 1 to 7 with a higher score being more favorable. Total score is calculated as follows: sum of items 1to 32 divided by 32 for a score range of 1 to 7 with a higher score indicating a better outcome. Reported is the change in AQLQ score from baseline to the end of the placebo-controlled period at Week 52.",
   "timeFrame": "Week 52"
  },
  {
   "measure": "Absolute Change From Baseline In Asthma Rescue Medication Use at Week 52",
   "description": "Reported here is the change in the number of puffs or nebulized treatments of asthma rescue medication from baseline to the end of the PCP at Week 52.",
   "timeFrame": "Week 52"
  },
  {
   "measure": "Absolute Change From Baseline in ACQ-5 Score at Week 52",
   "description": "The ACQ-5 is test with 5 questions; each with seven possible answers ranging from 0 to 6 with a lower score being more favorable. Total score range is 0 to 30 with a lower score indicating a better outcome. Reported is the change in ACQ-5 score from baseline to the end of the PCP at Week 52.",
   "timeFrame": "Baseline, Week 52"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Asthma diagnosis for greater than equal to (\\>/=) 12 months prior to Visit 1\n* Bronchodilator response at Visit 1, 2, or 3\n* Pre-bronchodilator FEV1 of 40 percent (%) - 80% predicted at both Visits 2 and 3\n* On ICS therapy at a total daily dose of 500-2000 micrograms (mcg) of fluticasone propionate dry powder inhaler (DPI) or equivalent for \\>/=6 months prior to Visit 1\n* On an eligible second controller medication (long-acting beta-agonist \\[LABA\\], leukotriene receptor antagonist \\[LTRA\\], long-acting muscarinic antagonist \\[LAMA\\], or theophylline) for 6 months prior to Visit 1\n* Uncontrolled asthma at Visit 1 and/or Visit 2, and at Visit 3\n* Chest X-ray or computed tomography (CT) scan within 3 months prior to Visit 1 or chest X-ray during the screening period (prior to Visit 3) confirming the absence of other clinically significant lung disease\n* Demonstrated adherence with controller medication during the screening period\n\nExclusion Criteria:\n\n* History of severe allergic reaction or anaphylactic reaction to a biologic agent or known hypersensitivity to any component of the lebrikizumab injection\n* Maintenance oral corticosteroid therapy within 3 months of Visit 1\n* Treatment with systemic (oral, intravenous \\[IV\\], or intramuscular \\[IM\\]) corticosteroids within 4 weeks prior to Visit 1 or during the screening period\n* Treatment with intra-articular corticosteroids within 4 weeks prior to Visit 1 or during the screening period or anticipated need for intra-articular corticosteroids during the course of the study\n* Infection requiring hospital admission for \\>/=24 hours or requiring treatment with IV or IM antibiotics within 4 weeks prior to Visit 1 or during screening; Upper or lower respiratory tract infection within 4 weeks prior to Visit 1 or during screening; Active infection that required treatment with oral antibiotics within 2 weeks prior to Visit 1 or during screening; Active parasitic infection or Listeria monocytogenes infection within 6 months prior to Visit 1 or during screening\n* Active tuberculosis requiring treatment within 12 months prior to Visit 1\n* Known immunodeficiency, including, but not limited to, human immunodeficiency virus (HIV) infection\n* Evidence of acute or chronic hepatitis or known liver cirrhosis\n* History of interstitial lung disease, chronic obstructive pulmonary disease (COPD), or other clinically significant lung disease other than asthma\n* Known current malignancy or current evaluation for potential malignancy\n* Current smoker or former smoker with a history of greater than (\\>) 10 pack-years\n* History of alcohol or drug abuse\n* Past and/or current use of any anti-interleukin (IL)-13 or anti-IL-4/IL-13 therapy, including lebrikizumab\n* Use of other monoclonal antibody therapy, including omalizumab, within 6 months or 5 drug half-lives prior to Visit 1 (whichever is longer) or during screening\n* Initiation of or change in allergen immunotherapy within 3 months prior to Visit 1 or during screening",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "75 Years"
 },
