forecastInput:
{
 "nctId": "NCT02546700",
 "briefTitle": "A Study to Evaluate Safety and Efficacy of Lebrikizumab in Participants With Chronic Obstructive Pulmonary Disease (COPD)",
 "officialTitle": "A Phase II, Randomized, Double-Blind, Placebo-Controlled Study to Assess the Efficacy and Safety of Lebrikizumab in Patients With Chronic Obstructive Pulmonary Disease and a History of Exacerbations",
 "leadSponsor": {
  "name": "Hoffmann-La Roche",
  "class": "INDUSTRY"
 },
 "startDate": "2015-09-17",
 "firstRegistered": "2015-09-09",
 "conditions": [
  "Chronic Obstructive Pulmonary Disease"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "DOUBLE",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 309,
 "briefSummary": "Phase II, randomized, double-blind, placebo-controlled, parallel-group clinical trial of lebrikizumab in participants with COPD and a history of exacerbations who are treated with inhaled corticosteroid (ICS) and at least one long-acting bronchodilator inhaler medication. This study will be conducted to assess the safety, efficacy, and patient-reported outcome (PRO) measures.",
 "arms": [
  {
   "label": "Lebrikizumab: Biomarker-high",
   "type": "EXPERIMENTAL",
   "description": "Lebrikizumab will be administered subcutaneously once in every 4 weeks up to 24 weeks to the participants considered as biomarker-high.",
   "interventionNames": [
    "Drug: Lebrikizumab"
   ]
  },
  {
   "label": "Lebrikizumab: Biomarker-low",
   "type": "EXPERIMENTAL",
   "description": "Lebrikizumab will be administered subcutaneously once in every 4 weeks up to 24 weeks to the participants considered as biomarker-low.",
   "interventionNames": [
    "Drug: Lebrikizumab"
   ]
  },
  {
   "label": "Placebo: Biomarker-high",
   "type": "PLACEBO_COMPARATOR",
   "description": "Matching placebo will be administered subcutaneously once in every 4 weeks up to 24 weeks to the participants considered as biomarker-high.",
   "interventionNames": [
    "Drug: Placebo"
   ]
  },
  {
   "label": "Placebo: Biomarker-low",
   "type": "PLACEBO_COMPARATOR",
   "description": "Matching placebo will be administered subcutaneously once in every 4 weeks up to 24 weeks to the participants considered as biomarker-low.",
   "interventionNames": [
    "Drug: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Lebrikizumab",
   "description": "Lebrikizumab 125 milligrams (mg) will be administered subcutaneously once in every 4 weeks.",
   "armGroupLabels": [
    "Lebrikizumab: Biomarker-high",
    "Lebrikizumab: Biomarker-low"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "Matching placebo will be administered subcutaneously once in every 4 weeks.",
   "armGroupLabels": [
    "Placebo: Biomarker-high",
    "Placebo: Biomarker-low"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline in Pre-bronchodilator Forced Expiratory Volume in One Second (FEV1) at Week 12",
   "description": "Adjusted mean change from baseline in pre-bronchodilator FEV1 (assessed using spirometry) at Week 12 was calculated.",
   "timeFrame": "Baseline, Week 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Rate of Moderate or Severe COPD Exacerbation",
   "description": "A moderate COPD exacerbation was defined as new or increased COPD symptoms (for example, dyspnea, sputum volume, and sputum purulence) for at least 2 consecutive days that lead to treatment with systemic corticosteroids and/or antibiotics. A severe COPD exacerbation was defined as new or increased COPD symptoms (for example, dyspnea, sputum volume, and sputum purulence) for at least 2 consecutive days that lead to hospitalization. Adjusted exacerbation rate per year was calculated.\n\nResults are reported as a 'Number' representing the unadjusted annualized rate of COPD exacerbations per person-year. The total number of exacerbations observed during the period was defined as starting at the date of randomization and ending at most 172 days after randomization (including data collected during safety follow-up in the case of early drug discontinuation) regardless of adherence to study drug divided by the total patient-weeks at risk divided by 52 weeks per year.",
   "timeFrame": "Baseline up to Week 24"
  },
  {
   "measure": "Change From Baseline in Post-bronchodilator FEV1 at Week 24",
   "description": "Adjusted mean change from baseline in post-bronchodilator FEV1 at Week 24 was calculated.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Change From Baseline in Pre-bronchodilator FEV1 at Week 24",
   "description": "Adjusted mean change from baseline in pre-bronchodilator FEV1 at Week 24 was calculated.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Time to First COPD Exacerbation",
   "description": "COPD exacerbation was defined as new or increased COPD symptoms (for example, dyspnea, sputum volume, and sputum purulence) for at least 2 consecutive days. Time to first COPD exacerbation was estimated using Kaplan-Meier analysis.",
   "timeFrame": "Baseline up to Week 24"
  },
  {
   "measure": "Change From Baseline in Health-Related Quality of Life as Assessed by the Overall Score of the Saint George's Respiratory Questionnaire for COPD (SGRQ-C) at Week 24",
   "description": "SGRQ-C was assessed by asking participants to recall their COPD-related experiences and to respond to 40 questions included within three domains: symptoms (7 items), activity (13 items), and impacts (20 items). Overall SGRQ-C score ranged from 0 to 100, where lower score indicated better health-related quality of life. Change from baseline in overall SGRQ-C score at Week 24 was reported.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Change From Baseline in COPD Symptoms as Measured by the Overall Score of the Exacerbations of Chronic Pulmonary Disease Tool (EXACT) at Week 24",
   "description": "EXACT comprised of 14-item questionnaire containing four domains: breathlessness (5 items), cough and sputum (3 items), chest symptoms (3 items), and additional attributes (3 items). Overall EXACT score was the average of domain scores. It ranged from 0 to 100, where higher score indicated a more severe condition. Change from baseline in overall EXACT score at Week 24 was reported.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Change From Baseline in Cough and Sputum as Measured by the Cough and Sputum Domain Score of the EXACT at Week 24",
   "description": "EXACT comprised of 14-item questionnaire containing four domains: breathlessness (5 items), cough and sputum (3 items), chest symptoms (3 items), and additional attributes (3 items). Cough and Sputum domain score ranged from 0 to 100, where higher score indicated a more severe condition. Change from baseline in cough and sputum domain EXACT score at Week 24 was reported.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Change From Baseline in Dyspnea as Assessed by the Baseline Dyspnea Index/Transition Dyspnea Index (BDI/TDI) at Week 24",
   "description": "The BDI scores ranged from 0 (very severe impairment) to 4 (no impairment) for each of 3 domains (functional impairment, magnitude of task, and magnitude of effort) and were summed to determine the BDI total score (0 to 12). The TDI scores ranged from -3 (major deterioration) to +3 (major improvement) for each of the 3 domains (functional impairment, magnitude of task, and magnitude of effort). The sum of all domains yielded the TDI total score (-9 to +9). Change from baseline in BDI/TDI at Week 24 was reported.",
   "timeFrame": "Baseline, Week 24"
  },
  {
   "measure": "Percentage of Participants With Anti-Therapeutic Antibody (ATA) to Lebrikizumab",
   "description": "This outcome measure was planned to be analyzed only in overall lebrikizumab arm.",
   "timeFrame": "Baseline up to Week 36"
  },
  {
   "measure": "Minimum Observed Serum Trough Concentration (Cmin) of Lebrikizumab",
   "description": "This outcome measure was planned to be analyzed only in overall lebrikizumab arm.",
   "timeFrame": "Pre-dose (Hour 0) at Weeks 4 and 12, at Week 24"
  },
  {
   "measure": "Elimination Half-Life (t1/2) of Lebrikizumab",
   "description": "Elimination half-life was defined as the time measured for the serum concentration to decrease by one half. This outcome measure was planned to be analyzed only in overall lebrikizumab arm.",
   "timeFrame": "Pre-dose (Hour 0) on Day 1 (Baseline) and Weeks 1, 4, 12, 24, 28, and 36"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Documented history of COPD greater than or equal to (\\>/=) 12 months prior to Visit 1\n* Post-bronchodilator FEV1/FVC less than (\\<) 0.70 at Visit 1 or 2\n* Post bronchodilator FEV1 \\<80% predicted at Visit 1 or 2\n* Documented history of one or more acute COPD exacerbations requiring treatment with systemic corticosteroids and/or antibiotics or hospitalization within 12 months prior to Visit 1\n* Current tobacco smoker or former smoker (having stopped smoking for at least 6 months prior to Visit 1) with a history of smoking \\>/=10 pack-years (20 cigarettes/day for 10 years)\n* On inhaled corticosteroids (ICS) therapy for \\>/=6 months prior to Visit 1\n* On an eligible bronchodilator medication for \\>/=6 months prior to Visit 1\n* Chest X-ray or computed tomography (CT) scan within 6 months prior to Visit 1 or chest X-ray prior to Visit 2 that confirms absence of clinically significant lung disease besides COPD\n* Demonstrated adherence with background COPD inhaler medication during screening period\n* For female participants of childbearing age, use of single or combined contraceptive methods for the duration of the study\n\nExclusion Criteria:\n\n* History of severe allergic reaction or anaphylactic reaction to biologic agent or known hypersensitivity to lebrikizumab injection\n* History of clinically significant pulmonary disease other than COPD\n* Diagnosis of alpha-1-antitrypsin deficiency\n* Lung volume reduction surgery or procedure within 12 months prior to Visit 1\n* Supplemental oxygen requirement \\>2 liters/minute (L/min) at rest or with exertion\n* Current diagnosis of asthma\n* Participants participating in, or scheduled for, an intensive COPD rehabilitation program\n* Maintenance oral corticosteroid therapy\n* Treatment with systemic corticosteroids within 4 weeks prior to Visit 1 or during screen period\n* Unstable ischemic heart disease or other relevant cardiovascular disorders\n* Use of an immunomodulatory or immunosuppressive therapy including monoclonal antibodies (includes anti-interleukin-13 (IL) or anti-IL-4/IL-13 therapy)\n* Body weight \\<40 kg\n* Any infection that resulted in hospital admission for \\>/= 24 hours and/or treatment with oral, intravenous (IV), or intramuscular (IM) antibiotics within 4 weeks prior to Visit 1 or during screening\n* Upper or lower respiratory tract infection within 4 weeks prior to Visit 1 or during screening\n* Active parasitic or Listeria monocytogenes infection within 6 months prior to Visit 1 or during screening\n* Received a live attenuated vaccine within 4 weeks prior to Visit 1 or during screening\n* Active tuberculosis requiring treatment within 12 months prior to Visit 1\n* Human immunodeficiency virus (HIV) or other known immunodeficiency\n* Hepatitis or known liver cirrhosis\n* Aspartate Aminotransferase (AST), Alanine Aminotransferase (ATL), or total bilirubin elevation \\>/=2.0 x upper limit of normal (ULN) during screening\n* Clinically significant abnormality on screening electrocardiogram (ECG) or laboratory tests\n* History of alcohol or drug abuse\n* Pregnant or lactating",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "40 Years",
  "maximumAge": "80 Years"
 },
