{
 "nctId": "NCT05834738",
 "briefTitle": "Randomized, Double-blind, Placebo-controlled, Crossover Study of Atrasentan in Subjects With IgA Nephropathy",
 "officialTitle": "A Randomized, Double-blind, Placebo-controlled, Crossover Study of Atrasentan in Subjects With IgA Nephropathy on Sodium-glucose Cotransporter-2 Inhibitors (SGLT2i)",
 "leadSponsor": {
