   "name": "Setmelanotide",
   "description": "Subcutaneous Injection",
   "armGroupLabels": [
    "LEPR variant",
    "NCOA1 (SRC1) variant",
    "POMC or PCSK1 variant",
    "SH2B1 variant"
   ]
