 ],
 "primaryOutcomes": [
  {
   "measure": "Treatment Period: Percent Change From Baseline in Body Mass Index (BMI)",
   "description": "BMI was calculated using participant's weight and height assessments as weight in kilograms (kg)/(height in meters \\[m\\])\\^2. Baseline was defined as the last available measurement taken prior to the start of treatment administration. An analysis of covariance (ANCOVA) model was used to calculate the least-squares mean with randomization stratification factors and baseline value as a covariate.",
   "timeFrame": "Baseline, Week 52"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Treatment Period: Percentage of Participants Who Achieved at Least a 5% Reduction in Baseline BMI",
   "description": "BMI was calculated using participant's weight and height assessments as weight in kg/(height in m)\\^2. Baseline was defined as the last available measurement taken prior to the start of treatment administration.",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period (Participants Aged ≥18 Years): Percent Change From Baseline in Body Weight",
   "description": "Data reported are for mean percent change from baseline in body weight measured in kg. Baseline was defined as the last available measurement taken prior to the start of treatment administration",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period (Participants Aged ≥12 Years): Percent Change From Baseline in Weekly Average Most Hunger Score",
   "description": "Participants ≥12 years of age who were able to validly and reliably self-report were administered \"Hunger Questions for Participants ≥12 Years of Age©.\" The 'most hunger' item was designed to be evaluated separately and was averaged on a weekly basis. Participants were asked 'In the last 24 hours, how hungry did you feel when you were the most hungry?' and rated their hunger on an 11-point numeric rating scale ranging from 0 to 10 (0 = not hungry at all and 10 = hungriest possible). Data reported are for mean percent change from baseline in the weekly average daily most hunger score. Baseline was defined as the last available measurement taken prior to the start of treatment administration.",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period: Percentage of Participants Who Achieved at Least a 10% Reduction in Baseline BMI",
   "description": "BMI was calculated using participant's weight and height assessments as weight in kg/(height in m)\\^2. Baseline was defined as the last available measurement taken prior to the start of treatment administration.",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period (Participants <18 Years): Percent Change From Baseline in BMI Z-score",
   "description": "BMI z-scores were calculated according to the Centers for Disease Control and Prevention (CDC) Growth Charts and according to participant's gender and age at screening. A Z-score of 0 is equal to the mean of a reference population (i.e., healthy, age and sex-matched individuals). A decrease in BMI Z-score (\\< 0) indicates a reduction in BMI from Baseline whereas an increase in BMI-Z score (\\> 0) indicated an increase in BMI from Baseline. Data reported are for mean percent change from baseline in BMI Z-score. Baseline was defined as the last available measurement taken prior to the start of treatment administration.",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period (Participants <18 Years): Percent Change From Baseline in BMI 95th Percentile",
   "description": "The percentage change from baseline in BMI 95th percentile was calculated as (\\[BMI at Week 52 / BMI 95th percentile\\]) - \\[BMI at baseline / BMI 95th percentile\\])\\*100. BMI percentile scores are measures of relative weight adjusted for child age and gender. The percent of the BMI 95th percentile score expresses the participant's BMI as a percentage of the Centers for Disease Control (CDC) 95th percentile reference population. Data reported are for mean percent change from baseline in BMI 95th percentile. Baseline was defined as the most recent measurement prior to the first administration of study drug.",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period: Percent Change From Baseline in Waist Circumference",
   "description": "The waist circumference (in centimeters \\[cm\\]) was measured according to the National Heart, Lung, and Blood Institute (NHLBI) criteria. Data reported are for mean percent change from baseline in waist circumference. Baseline was defined as the last available measurement taken prior to the start of treatment administration.",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period: Number of Participants With Treatment-emergent Adverse Events (TEAEs)",
   "description": "TEAEs were defined as any untoward medical occurrence temporally associated with the use of study treatment, whether or not considered related to the study treatment that happened on or after the date of the first study treatment administration. A summary of all Serious Adverse Events and Other Adverse Events (nonserious) regardless of causality is located in the 'Reported Adverse Events' Section.",
   "timeFrame": "Baseline up to 60 weeks"
  },
  {
   "measure": "Treatment Period (Participants ≥18 Years): Percent Change From Baseline in Physical Functioning Score on the Impact of Weight on Quality of Life (IWQOL)-Lite",
   "description": "The IWQOL-Lite is a validated 31-item self-reported measure of obesity-specific quality of life questionnaire. The physical function domain comprised 11 items which had 5 response items: Always True=5, Usually True=4, Sometimes True=3, Rarely True=2, Never True=1. The score of each item was summed to calculate the raw score. The raw score range of the physical function domain was 11-55 and was transformed on a scale of 0 to 100, where 100 represented the best quality of life. The transformed score was calculated as (maximum score - raw score) / (maximum score - minimum score) \\*100. Data reported are for mean percent change from baseline in physical functioning score on the IWQOL-Lite. Baseline was defined as the last available measurement taken prior to the start of treatment administration.",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period (Participants 11 to <18 Years): Percent Change From Baseline in Physical Comfort Score on the IWQOL-Kids-Parent-Proxy",
   "description": "The IWQOL-Kids-Parent-Proxy is a psychometrically validated 27-item self-reported measure of obesity-specific quality of life questionnaire. The physical comfort domain comprised 6 items which used a 5-point Likert scale: Always True=1, Usually True=2, Sometimes True=3, Rarely True=4, Never True=5. The items were summed to calculate the raw score. The raw score range of the physical function domain was 6-30 and was transformed on a scale of 0 to 100, where 100 represented the best quality of life. The transformed score was calculated as (maximum score - raw score) / (maximum score - minimum score) \\*100. Data reported are for mean percent change from baseline in Physical Comfort Score on the IWQOL-Kids-Parent-Proxy. Baseline was defined as the last available measurement taken prior to the start of treatment administration.",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period (Participants ≥18 Years): Percent Change From Baseline in Impact on Quality of Life Total Score on the IWQOL-Lite",
   "description": "The IWQOL-Lite is a validated 31-item self-reported measure of obesity-specific quality of life questionnaire which comprised of 5 domains (physical function, self-esteem, sexual life, distress and work) and had 5 response items: Always True=5, Usually True=4, Sometimes True=3, Rarely True=2, Never True=1. The items were summed to calculate the raw total score. The raw total score range was 31-155 and was transformed on a scale of 0 to 100, where 100 represented the best quality of life. The transformed score was calculated as (maximum score - raw score) / (maximum score - minimum score) \\*100. Data reported are for mean percent change from baseline in Impact on Quality of Life Total Score on the IWQOL-Lite. Baseline was defined as the last available measurement taken prior to the start of treatment administration.",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period (Participants 11 to <18 Years): Percent Change From Baseline in Impact on Quality of Life Total Score on the IWQOL-Kids-Parent-Proxy",
   "description": "The IWQOL-Kids-Parent-Proxy is a psychometrically validated 27-item self-reported measure of obesity-specific quality of life questionnaire and comprised of 4 domains (physical comfort, body esteem, social life, family relations) and used a 5-point Likert scale: Always True=1, Usually True=2, Sometimes True=3, Rarely True=4, Never True=5. The items were summed to calculate the raw total score. The raw total score range was 27 to 135 and was transformed on a scale of 0 to 100, where 100 represented the best quality of life. The transformed score was calculated as (maximum score - raw score) / (maximum score - minimum score) \\*100. Data reported are for mean percent change from baseline in Impact on Quality of Life Total Score on the IWQOL-Kids-Parent-Proxy. Baseline was defined as the last available measurement taken prior to the start of treatment administration.",
   "timeFrame": "Baseline, Week 52"
  },
  {
   "measure": "Treatment Period: Percent Change From Baseline in Body Weight in Setmelanotide Initial Responders Versus Placebo",
   "description": "Initial responders were defined as setmelanotide treated participants with ≥5% body weight loss (≥18 years of age) or a decrease in BMI by ≥3% (\\<18 years of age) at the time of consecutive 12 weeks with the increased 3.0 mg/day or with final increased dose level. Data reported are for mean percent change from baseline in body weight measured in kg. Baseline was defined as the last available measurement taken prior to the start of treatment administration.",
   "timeFrame": "Baseline, Week 52"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Participants must have a pre-identified:\n\n  * Heterozygous genetic variant in the POMC gene or PCSK1 gene\n  * Heterozygous genetic variant in the LEPR gene\n  * Homozygous, heterozygous, or compound heterozygous variant in the NCOA1 (SRC1)\n  * Homozygous, heterozygous, or compound heterozygous variant in SH2B1 gene, or chromosomal 16p11.2 deletion encompassing the SH2B1 gene\n* Between 6 and 65 years of age at the time of provision of informed consent/assent\n* Obesity, defined as body mass index (BMI) ≥30 kg/m\\^2 for participants ≥18 years of age or BMI ≥95th percentile for age and gender for participants 6 up to 17 years of age\n* Participant and/or parent or guardian is able to understand and comply with the requirements of the study and is able to understand and sign the written informed consent/assent\n* Participant and/or parent or guardian reports that participant experienced childhood obesity, defined as the participant and/or parent or guardian reporting that the participant had obesity or was significantly overweight during childhood\n* Agree to use a highly effective form of contraception throughout the study and for 90 days following the study\n* Reported history of lifestyle intervention of diet and exercise\n* Symptoms or behaviors of hyperphagia persistent during the participant's life, including manifestations in childhood, as determined by the Investigator at screening.\n\nKey Exclusion Criteria:\n\n* Weight loss of 2% or greater in the previous 3 months\n* Bariatric surgery or procedure within the previous 6 months\n* Significant psychiatric disorder(s)\n* Suicidal ideation, attempt or behavior\n* Clinically significant pulmonary, cardiac, endocrine/metabolic, hepatic or oncologic disease\n* Glycated hemoglobin (HbA1C) \\>10% at Screening\n* History of significant liver disease or severe kidney disease\n* History or close family history (parents or siblings) of melanoma, or participant history of oculocutaneous albinism\n* Significant dermatologic findings relating to melanoma or pre-melanoma skin lesions (excluding non-invasive basal or squamous cell lesion)\n* Participation in any clinical study with an investigational drug/device within 3 months prior to the first day of dosing\n* Previously enrolled in a clinical study involving setmelanotide or any previous exposure to setmelanotide\n* Significant hypersensitivity to any excipient in the study drug\n* If female, pregnant or breastfeeding",
