 "primaryOutcomes": [
  {
   "measure": "Number of Investigator-confirmed Hereditary Angioedema (HAE) Attacks (Expressed as the Normalized Number of Attacks Per Month [4 Weeks] of Exposure) During the Treatment Period in Part 1",
   "description": "HAE attack was defined as signs or symptoms in ≥1 location: peripheral angioedema (cutaneous swelling involving an extremity, face, neck, torso, and/or genitourinary region), abdominal angioedema (abdominal pain with or without abdominal distension, nausea, vomiting, or diarrhea), or upper airway angioedema (lump sensation, difficulty swallowing, throat tightening, difficulty speaking, hoarseness, stridor, dyspnea, or swelling of tongue, palate, uvula, or larynx). A new attack was counted if symptoms occurred ≥24 hours after complete resolution of a prior attack. Attacks were recorded via daily electronic patient-reported outcome (ePRO) diaries and confirmed by the investigator. Monthly attack rate was calculated as number of attacks during treatment divided by treatment days, multiplied by 28. Mean rate ratio, confidence interval (CI), and p-value were estimated using a generalized linear model with Poisson distribution, with baseline attack rate included as a factor.",
   "timeFrame": "Up to Day 84"
  }
 ],
 "secondaryOutcomes": [
