forecastInput:
{
 "nctId": "NCT04153136",
 "briefTitle": "The ENCHANTMENT HIV Study",
 "officialTitle": "Ending Subclinical Heart Failure Using an Aldosterone and Natriuretic Peptide Targeted Treatment in HIV--The ENCHANTMENT HIV Study",
 "leadSponsor": {
  "name": "Massachusetts General Hospital",
  "class": "OTHER"
 },
 "startDate": "2020-09-11",
 "firstRegistered": "2019-10-30",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "HIV/AIDS",
  "Heart Failure With Preserved Ejection Fraction"
 ],
 "keywords": [
  "HIV",
  "Sacubitril/valsartan",
  "Heart Failure with Preserved Ejection Fraction",
  "Aldosterone",
  "Natriuretic Peptides",
  "Myocardial Dysfunction",
  "Cardiovascular Disease"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 39,
 "briefSummary": "Persons with HIV, even those well-treated, are at increased risk for heart disease when compared to the general population. Two hormones called aldosterone and brain natriuretic peptide (BNP), which have been shown to be abnormal in HIV, may be associated with inflammation as well as early changes in structure and function of the heart. This study is being conducted to evaluate whether therapies to block aldosterone and increase BNP levels may reduce the burden and progression of heart failure to improve cardiovascular health.",
 "detailedDescription": "This is a 6-month study enrolling persons with HIV with no known history of heart disease. Participants will be screened for early signs of heart failure using cardiac ultrasound (cardiac transthoracic echocardiography or cardiac TTE). Those participants who have early changes in the structure and function of the heart and may be at future risk for heart failure will be enrolled into the study. Additional imaging of the heart will occur using cardiac magnetic resonance imaging (cardiac MRI). Following baseline studies, participants will either receive a medication called sacubitril/valsartan or placebo for 6 months. Sacubitril/valsartan in an Food and Drug Administration (FDA) approved medication currently being used for heart failure with reduced ejection fraction in the general population, and we are evaluating whether this medication could be useful to reduce HIV-related heart failure with preserved ejection fraction. Sacubitril/valsartan is an oral medication taken twice daily that may block aldosterone hormone and increase natriuretic peptide hormone. Overall, this study aims to investigate the effect of sacubitril/valsartan on measures of heart disease related to inflammation, structure and function of the heart muscle in HIV using cardiac TTE and cardiac MRI imaging as well as blood markers of heart failure and inflammation.",
 "arms": [
  {
   "label": "Sacubitril/Valsartan",
   "type": "EXPERIMENTAL",
   "description": "Sacubitril/Valsartan 49-51mg twice daily along with lifestyle modification (counseling regarding diet and healthy activity) for 6 months",
   "interventionNames": [
    "Drug: Sacubitril-Valsartan 49-51Mg Oral Tablet"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Placebo twice daily along with lifestyle modification (counseling regarding diet and healthy activity) for 6 months",
   "interventionNames": [
    "Drug: Placebo oral tablet"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Sacubitril-Valsartan 49-51Mg Oral Tablet",
   "description": "By mouth twice daily",
   "armGroupLabels": [
    "Sacubitril/Valsartan"
   ],
   "otherNames": [
    "Entresto"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo oral tablet",
   "description": "Placebo oral tablet By mouth twice daily",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Myocardial Inflammation/Fibrosis",
   "description": "Change in myocardial inflammation/fibrosis measured by extracellular volume fraction via cardiac magnetic resonance imaging. Extracellular volume fraction is presented as a ratio of the volume of the extracellular compartment to the volume of the total myocardial tissue volume. A higher value indicates more inflammation/fibrosis.",
   "timeFrame": "Baseline and 6 months"
  },
  {
   "measure": "Myocardial Dysfunction",
   "description": "Change in myocardial dysfunction as measured by Left Atrial Volume Index measured by cardiac transthoracic echocardiography. Left Atrial Volume Index is presented as the left atrial volume divided by body surface area. A higher value indicates more myocardial dysfunction.",
   "timeFrame": "Baseline and 6 Months"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Other Indices of Myocardial Dysfunction",
   "description": "Change in myocardial fibrosis measured by T1 via cardiac magnetic resonance imaging. T1 refers to the longitudinal relaxation time. A higher T1 value indicates increased myocardial fibrosis.",
   "timeFrame": "Baseline and 6 Months"
  },
  {
   "measure": "Markers of Myocardial Inflammation and Fibrosis",
   "description": "Change in serum high-sensitivity cardiac troponin (hs-cTnT)",
   "timeFrame": "Baseline and 6 Months"
  },
  {
   "measure": "Cardiac Natriuretic Peptides",
   "description": "Change in serum N-terminal pro b-type natriuretic peptide (NT-proBNP)",
   "timeFrame": "Baseline and 6 Months"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1. Antiretroviral therapy use for \\>12 months\n2. HIV Viral Load \\<200 copies/mL\n3. Left Ventricular Ejection Fraction\\>50%\n4. Demonstration of one or more criteria for myocardial dysfunction on cardiac transthoracic echocardiogram, relevant to the progression of heart failure with preserved ejection fraction:\n\n   * Left Atrial Volume Index \\> 28 mL/m2\n   * Global Longitudinal Strain \\<18%\n   * Left Ventricular Mass Index \\> 95g/m2 (female), 115 g/m2 (male)\n\nExclusion Criteria:\n\n1. Known history of congestive heart failure or valvular disease\n2. Recent cardiac event or stroke within 3 months\n3. Current medication use acting along the renin-angiotensin-aldosterone-system (RAAS) pathway \\[angiotensin-converting enzyme inhibitor (ACEi), angiotensin receptor blocker (ARB), mineralocorticoid receptor blockade, direct renin inhibitor), potassium (K) supplementation or diuretic\n4. Angioedema to ACEi or ARB\n5. Systolic blood pressure\\<100 mmHg\n6. Medication suspected to have contraindication with active study drug\n7. Steroid use within last 3 months\n8. Uncontrolled diabetes requiring insulin and/or hemoglobin A1c (HbA1c) \\> 7.5%\n9. Creatinine (Cr)\\>1.5 mg/dL and estimated glomerular filtration rate (eGFR) \\<60 mL/min/1.73m2\n10. K\\>5.5 mEq/L\n11. Hemoglobin \\<10.0 g/dL\n12. Known liver disease or alanine transaminase (ALT)\\>3x upper limit normal\n13. Pregnant, actively seeking pregnancy or breastfeeding\n14. Estrogen, progestin derivative, or other sex steroid use within 3 months. Stable physiologic testosterone replacement (\\> 3 months) is acceptable\n15. Current bacterial or other infection\n16. Active substance abuse\n17. Known reaction to gadolinium",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "40 Years",
  "maximumAge": "70 Years"
 },
 "siteCount": 1,
 "countries": [
  "United States"
 ]
}

