   "timeFrame": "Week 36, Week 48, Week 72, Week 96"
  },
  {
   "measure": "Main: Change From Baseline in Enhanced Liver Fibrosis (ELF) Score",
   "description": "ELF score is a composite serum biomarker score derived from HA, PIIINP, and TIMP-1 concentrations. Scores range approximately from 6 to 16, with higher scores indicating greater liver fibrosis severity.",
   "timeFrame": "Week 36, Week 48, Week 72, Week 96"
  },
