   "timeFrame": "Week 36, Week 48, Week 72, Week 96"
  },
  {
   "measure": "Main: Change From Baseline in Adiponectin (mg/L)",
   "description": "Adiponectin is involved in glucose and lipid metabolism and is used as a marker of metabolic status. Change from baseline represents the difference between the post-baseline value and the baseline measurement.",
