{
 "nctId": "NCT03644667",
 "briefTitle": "Tocilizumab in Cardiac Transplantation",
 "officialTitle": "Targeting Inflammation and Alloimmunity in Heart Transplant Recipients With Tocilizumab (RTB-004)",
 "leadSponsor": {
  "name": "National Institute of Allergy and Infectious Diseases (NIAID)",
  "class": "NIH"
 },
 "collaborators": [
  {
   "name": "InCHOIR at Mount Sinai School of Medicine",
   "class": "UNKNOWN"
  }
 ],
 "startDate": "2018-12-20",
 "firstRegistered": "2018-08-21",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Heart Transplant"
 ],
 "keywords": [
  "heart transplant recipients",
  "alloimmunity",
  "anti-inflammatory",
  "tocilizumab",
  "efficacy clinical trial",
  "immunosuppression (IS)"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "TRIPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 385,
 "briefSummary": "The purpose of this research study is to see if a study drug called Tocilizumab will, when given with standard anti-rejection medicines, lead to better heart transplantation outcomes at 1 year after the transplant. Specifically, the investigators will evaluate whether taking tocilizumab leads to less rejection, less development of unwanted antibodies, and better heart function.",
 "detailedDescription": "This is a prospective, multi-center phase 2 clinical trial in which 200 primary heart transplant recipients will be randomized (1:1) to receive either tocilizumab (Actemra®) or placebo (normal saline) plus standard triple maintenance immunosuppression. Investigators will recruit primary heart transplant recipients from 14 participating centers. Subjects will be screened, consented, and enrolled while on the United Network for Organ Sharing (UNOS) wait list. When the recipient has received the transplant and is deemed hemodynamically stable, randomization will occur.\n\nStudy duration: The study duration will be approximately 4 years. There will be a 36-month accrual period, and participants will be followed for a minimum 12-month, and a maximum 24 months after heart transplantation.\n\n\\*\\*\\* IMPORTANT NOTICE: \\*\\*\\* The National Institute of Allergy and Infectious Diseases does not recommend the discontinuation of immunosuppressive therapy for recipients of cell, organ, or tissue transplants outside of physician-directed, controlled clinical studies. Discontinuation of prescribed immunosuppressive therapy can result in serious health consequences and should only be performed in certain rare circumstances, upon the recommendation and with the guidance of your health care provider.",
 "arms": [
  {
   "label": "Tocilizumab + Standard of Care Triple IS",
   "type": "EXPERIMENTAL",
   "description": "Tocilizumab plus standard of care triple immunosuppression (IS). Heart transplant recipients will receive tocilizumab (Actemra®) plus standard triple maintenance immunosuppression.\n\nStandard of care triple maintenance immunosuppression includes:\n\n* a calcineurin inhibitor (tacrolimus),\n* an anti-proliferative treatment (mycophenolate mofetil) or Myfortic® (enteric-coated mycophenolate sodium), and\n* steroids (methylprednisolone/prednisone) as prescribed by site physician investigator.\n\nParticipants enrolled in the study will be followed for 24 months after their transplant surgery. Randomization will occur once a participant has weaned from cardiopulmonary bypass and has achieved hemodynamic stability without significant ongoing bleeding within the first 72 hours after transplant.",
   "interventionNames": [
    "Biological: tocilizumab",
    "Drug: Standard of Care Triple IS"
   ]
  },
  {
   "label": "Placebo + Standard of Care Triple IS",
   "type": "PLACEBO_COMPARATOR",
   "description": "Placebo plus standard of care triple maintenance immunosuppression (IS). Heart transplant recipients will receive placebo plus standard triple maintenance immunosuppression.\n\nStandard of care triple maintenance immunosuppression includes:\n\n* a calcineurin inhibitor (tacrolimus),\n* an anti-proliferative treatment (mycophenolate mofetil) or Myfortic® (enteric-coated mycophenolate sodium), and\n* steroids (methylprednisolone/prednisone) as prescribed by site physician investigator.\n\nParticipants enrolled in the study will be followed for 24 months after their transplant surgery. Randomization will occur once a participant has weaned from cardiopulmonary bypass and has achieved hemodynamic stability without significant ongoing bleeding within the first 72 hours after transplant.",
   "interventionNames": [
    "Biological: Placebo",
    "Drug: Standard of Care Triple IS"
   ]
  }
 ],
 "interventions": [
  {
   "type": "BIOLOGICAL",
   "name": "tocilizumab",
   "description": "6 doses: 8mg/kg (maximum of 800 mg) given once every four weeks by intravenous infusion over a 20-week period, with a minimum of 21 days between each infusion.",
   "armGroupLabels": [
    "Tocilizumab + Standard of Care Triple IS"
   ],
   "otherNames": [
    "Actemra®"
   ]
  },
  {
   "type": "BIOLOGICAL",
   "name": "Placebo",
   "description": "The placebo is 0.9% sterile normal saline. 6 doses: 8mg/kg (maximum of 800 mg) given once every four weeks by intravenous infusion over a 20-week period, with a minimum of 21 days between each infusion.",
   "armGroupLabels": [
    "Placebo + Standard of Care Triple IS"
   ],
   "otherNames": [
    "Placebo for tocilizumab",
    "Placebo for Actemra®"
   ]
  },
  {
   "type": "DRUG",
   "name": "Standard of Care Triple IS",
   "description": "Standard of care triple maintenance IS includes:\n\n1. A calcineurin inhibitor-tacrolimus (Prograf ®) per site standards by sublingual, oral or intravenous route to attain target trough levels.\n\n   Exception: Should a participant be unable to tolerate tacrolimus, the site physician investigator may choose cyclosporine treatment.\n2. An anti-proliferative treatment-mycophenolate mofetil or Myfortic® (enteric-coated mycophenolate sodium) will be administered, per protocol.\n\n   Exception: Should a participant be unable to tolerate mycophenolate mofetil, the site physician investigator may choose an alternative treatment.\n3. Steroids-methylprednisolone/prednisone dosing will be given according to the local center standard of practice early post transplantation. After 6 months, prednisone may be withdrawn at the discretion of the site physician investigator, per protocol.",
   "armGroupLabels": [
    "Placebo + Standard of Care Triple IS",
    "Tocilizumab + Standard of Care Triple IS"
   ],
   "otherNames": [
    "calcineurin inhibitor: (tacrolimus (Prograf ®))",
    "anti-proliferative treatment: (mycophenolate mofetil ),",
    "MMF, CellCept®",
    "Myfortic®, enteric-coated mycophenolate sodium",
    "steroids: methylprednisolone/prednisone"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Percentage of Participants Positive for Event of dnDSA, ACR, AMR, Hemodynamic Compromise, Death or Re-Transplantation",
   "description": "The primary endpoint is defined by a composite 1 year post-transplant endpoint of:\n\n1. Any detection of de novo donor-specific antibodies (dnDSA) (as assessed by the Core Laboratory),\n2. Acute cellular rejection (ACR) ≥ ISHLT 2R rejection (as assessed by the Core Laboratory),\n3. Antibody mediated rejection (AMR) ≥ ISHLT AMR 1 (as assessed by the Core Laboratory),\n4. Hemodynamic compromise rejection whether or not a biopsy is performed and whether or not there is biopsy-proven rejection (as assessed by the Core Laboratory). The following criteria are required for hemodynamic compromise:\n\n   * The need for inotropic agents due to either cardiac index \\<2.0 L/min/m2 or clinical evidence of acute decompensated heart failure\n   * Ejection fraction of ≤40%\n5. Death,\n6. Re-transplantation.",
   "timeFrame": "From transplant through 12 months post transplant surgery (12 months)"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Freedom of Detection of de Novo Donor-Specific Antibodies (dnDSA)",
   "description": "A comparison by treatment group of the cumulative incidence of freedom from development of de novo donor-specific antibodies (dnDSA). dnDSA is a newly developed alloantibody that is against the donor organ. The numbers presented in the \"Measured Values\" table represent the cumulative incidence (accounting for the competing risk of death) of the event in each group.",
   "timeFrame": "From transplant through 12 months post transplant surgery (12 months)"
  },
  {
   "measure": "Freedom From Acute Cellular Rejection (ACR) ≥ International Society of Heart and Lung Transplantation (ISHLT) 2R Rejection",
   "description": "A comparison by treatment group of the cumulative incidence of freedom from development of acute cellular rejection ≥2R (Reference: International Society of Heart and Lung Transplantation \\[ISHLT\\] acute cellular rejection-grade 2R or greater severity). The numbers presented in the \"Measured Values\" table represent the cumulative incidence (accounting for the competing risk of death) of the event in each group.",
   "timeFrame": "From transplant through 12 months post transplant surgery (12 months)"
  },
  {
   "measure": "Freedom From Antibody Mediated Rejection (AMR) ≥ International Society of Heart and Lung Transplantation (ISHLT) AMR 1 - by Treatment Group",
   "description": "A comparison by treatment group of the cumulative incidence of freedom from development of antibody-mediated rejection defined as ISHLT grade AMR 1 or greater severity. The numbers presented in the \"Measured Values\" table represent the cumulative incidence (accounting for the competing risk of death) of the event in each group.",
   "timeFrame": "From transplant through 12 months post transplant surgery (12 months)"
