   ],
   "otherNames": [
    "Intuniv-er"
   ]
  },
  {
   "type": "OTHER",
   "name": "Placebo",
   "description": "placebo will be dispensed similar to the active arm.",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change in Cannabis Use as Measured by Ecological Momentary Assessments (EMA).",
   "description": "Change in quartiles of use as compared to baseline. Participants will complete ecological momentary assessments (EMA) daily on any internet-accessible device (smart phone, computer, tablet). The daily EMA will assess cannabis use during quartiles of the day. Participants will mark \"Yes\" if they used cannabis from 12AM-6AM, 6AM-12PM, 12PM-6PM, or 6PM-12AM for each 24 hour period of the study.",
   "timeFrame": "12 weeks of study"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Meets DSM-V criteria for a current cannabis use disorder\n* Seeking treatment for cannabis use disorder with goal to reduce or stop use\n* THC-positive drug screen\n* Capable of giving informed consent and complying with study procedures\n* Access to internet and devices capable of completing study procedures\n* capability of receiving mailed packages for study supplies\n\nExclusion Criteria:\n\n* Lifetime history of DSM-V diagnosis of schizophrenia or schizoaffective disorder\n* Current DSM-V criteria for a psychiatric disorder supported by the MINI that in the investigator's judgment is unstable, would be disrupted by the study medication, or is likely to require new pharmacotherapy or psychotherapy during the study period. Individuals who are currently stable on psychotropic medication for at least 2 months may be included if in the investigator's opinion the psychotropic medication is compatible with the study medication (guanfacine-ER). Any medical or psychiatric conditions that in the investigator's judgment would interfere with safe participation in the study will be exclusionary.\n* Individuals who meet DSM-V criteria for any moderate to severe substance use disorder other cannabis, caffeine or nicotine use disorders\n* Pregnancy, lactation, or failure to use adequate contraceptive method in female patients who are currently engaging in sexual activity that can result in pregnancy\n* Legally mandated to participate in a substance use disorder treatment program\n* Current or recent history of significant violent or suicidal behavior, risk for suicide or homicide\n* Known history of allergy, intolerance, or hypersensitivity to guanfacine\n* Bradycardia (\\< 50 beats/minute), hypotension (sitting or standing BP \\< 90/50), or symptoms attributable to hypotension (i.e. lightheadedness or dizziness on standing)\n* Individuals currently being treated with the antihypertensive medications, including the class of alpha 2 agonists that have a potential drug-interaction with guanfacine based on adrenergic modulation\n* Individuals currently taking medications that may interact adversely with guanfacine and deemed not clinically safe by study physician at consent, such as rifampicin, ketoconazole, St. John's Wort, and amitriptyline.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
