 ],
 "secondaryOutcomes": [
  {
   "measure": "To Investigate the Feasibility of Home Research Visits and Procedures in Adult Males With FXS",
   "description": "Quality and test-retest reliability of assessments performed at home compared with the hospital setting. This includes blood testing for Fragile X messenger ribonucleoprotein (FMRP: range of 0-40 picomolar) and eye-tracking of eye gaze to eye regions when viewing faces (range of value from 0 percent to 100 percent; higher values are associated with a neurotypical phenotype).",
   "timeFrame": "Pre-dose, 60 minutes post-dose"
  },
  {
   "measure": "To Investigate the Feasibility of High Density EEG Recording at Home in Adult Males With FXS",
   "description": "This endpoint examined the reliability of pre-dose resting-state EEG absolute power estimates between in-lab and in-home assessments using intraclass correlation (ICC). ICCs were calculated separately for 129 electrodes using absolute power estimates (μV²/Hz). The reported ICC represents the mean ICC across electrodes, with the standard deviation reflecting variability in ICC values across electrodes. whole-head, pre-dose resting state EEG power estimates from data collected in-lab vs in-home using intraclass correlation (ICC).",
