 ],
 "primaryOutcomes": [
  {
   "measure": "Percentage of Participants Achieving an American College of Rheumatology 50% (ACR50) Response at Week 12",
   "description": "The ACR50 response criteria was a response of at least 50% improvement from baseline based on both swollen joint count (66 joints) and tender joint count (68 joints), and at least 50% improvement from baseline in at least 3 of the following 5 variables: 1) participant's assessment of arthritis pain (PtAAP) on a Visual Analog Scale (VAS, no pain =0 to severe pain =100); 2) participant's global assessment of disease activity (PtGADA) on a VAS (very well =0 to very poor =100); 3) physician's global assessment of disease activity (phGADA) on a VAS (very well =0 to very poor =100); 4) participant's assessment of physical function as measured by the Health Assessment Questionnaire Disability Index (HAQ-DI) (overall score ranging from 0 \\[mild disability\\] to 3 \\[very severe disability\\]); and 5) high sensitivity C-reactive protein (hs-CRP, decrease indicates improvement). A non-responder imputation (NRI) method was used for missing data.",
   "timeFrame": "At Week 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Percentage of Participants Achieving an American College of Rheumatology 20% (ACR20) Response at Weeks 2, 4, and 8 and 12",
   "description": "The ACR20 response criteria was a response of at least 20% improvement from baseline based on both swollen joint count (66 joints) and tender joint count (68 joints), and at least 20% improvement from baseline in at least 3 of the following 5 variables: 1) PtAAP on a VAS (no pain =0 to severe pain =100); 2) PtGADA on a VAS (very well =0 to very poor =100); 3) phGADA on a VAS (very well =0 to very poor =100); 4) participant's assessment of physical function as measured by the HAQ-DI (overall score ranging from 0 \\[mild disability\\] to 3 \\[very severe disability\\]); and 5) hs-CRP (decrease indicates improvement). An NRI method was used for missing data. ACR20 response rate at Week 12 was analyzed as a key secondary outcome measure.",
   "timeFrame": "At Weeks 2, 4, 8, and 12"
  },
  {
   "measure": "Percentage of Participants Achieving a Psoriasis Area and Severity Index 90 (PASI90) Response at Weeks 4, 8 and 12, in Participants With Psoriasis Involving at Least 3% Body Surface Area (BSA) at Baseline",
   "description": "The PASI is a validated tool to dynamically assess psoriasis severity. The PASI produces a numeric score that ranges from 0 (no disease) to 72 (maximal disease). A PASI90 response was defined as greater than or equal to 90% improvement (reduction) in PASI score from baseline. An NRI method was used for missing data. PASI90 response at Week 12 was analyzed as a key secondary outcome measure.",
   "timeFrame": "At Weeks 4, 8, and 12"
  },
  {
   "measure": "Percentage of Participants Achieving an ACR50 Response at Weeks 2, 4, and 8",
   "description": "The ACR50 response criteria was a response of at least 50% improvement from baseline based on both swollen joint count (66 joints) and tender joint count (68 joints), and at least 50% improvement from baseline in at least 3 of the following 5 variables: 1) PtAAP on a VAS (no pain =0 to severe pain =100); 2) PtGADA on a VAS (very well =0 to very poor =100); 3) phGADA on a VAS (very well =0 to very poor =100); 4) participant's assessment of physical function as measured by the HAQ-DI (overall score ranging from 0 \\[mild disability\\] to 3 \\[very severe disability\\]); and 5) hs-CRP (decrease indicates improvement). An NRI method was used for missing data.",
   "timeFrame": "At Weeks 2, 4, and 8"
  },
  {
   "measure": "Percentage of Participants Achieving an American College of Rheumatology 70% (ACR70) Response at Weeks 2, 4, 8, and 12",
   "description": "The ACR70 response criteria was a response of at least 70% improvement from baseline based on both swollen joint count (66 joints) and tender joint count (68 joints), and at least 70% improvement from baseline in at least 3 of the following 5 variables: 1) PtAAP on a VAS (no pain =0 to severe pain =100); 2) PtGADA on a VAS (very well =0 to very poor =100); 3) phGADA on a VAS (very well =0 to very poor =100); 4) participant's assessment of physical function as measured by the HAQ-DI (overall score ranging from 0 \\[mild disability\\] to 3 \\[very severe disability\\]); and 5) hs-CRP (decrease indicates improvement). An NRI method was used for missing data.",
   "timeFrame": "At Weeks 2, 4, 8, and 12"
  },
  {
   "measure": "Percentage of Participants Achieving Minimal Disease Activity at Week 12",
   "description": "Minimal disease activity was defined as meeting 5 of the following 7 criteria: tender joint count (68 joints) ≤1; swollen joint count (66 joints) ≤1; psoriasis area and severity index ≤1 or psoriasis affecting ≤1% of body surface area; PtAAP ≤15 on a VAS (0 = no pain to 100 = severe pain); PtGADA ≤20 on a VAS (0 = very well to 100 = very poor); HAQ-DI ≤0.5 (overall score ranging from 0 \\[mild disability\\] to 3 \\[very severe disability\\]); and Leeds Enthesitis Index (LEI) ≤1 (overall score ranging from 0 to 6, with higher scores indicating greater disease severity). An NRI method was used for missing data.",
   "timeFrame": "At Week 12"
  },
  {
   "measure": "Percentage of Participants Who Achieved a PASI75 Response at Week 12, in Participants With Psoriasis Involving at Least 3% BSA at Baseline",
   "description": "The PASI is a validated tool to dynamically assess psoriasis severity. The PASI produces a numeric score that ranges from 0 (no disease) to 72 (maximal disease). A PASI75 response was defined as greater than or 75% improvement (reduction) in PASI score from baseline. An NRI method was used for missing data.",
   "timeFrame": "At Week 12"
  },
  {
   "measure": "Percentage of Participants Achieving a PASI100 Response at Week 12, in Participants With Psoriasis Involving at Least 3% BSA at Baseline",
   "description": "The PASI is a validated tool to dynamically assess psoriasis severity. The PASI produces a numeric score that ranges from 0 (no disease) to 72 (maximal disease). A PASI100 response was defined as 100% improvement (reduction) in PASI score from baseline. An NRI method was used for missing data.",
   "timeFrame": "At Week 12"
  },
  {
   "measure": "Change From Baseline in Modified Nail Psoriasis Severity Index (mNAPSI) Score at Week 12",
   "description": "The mNAPSI is a tool to assess psoriatic nail involvement. Three groups of features (pitting, onycholysis, and oil-drop dyshromia and crumbling) for each fingernail are graded on a scale from 0 to 3. Four features (leukonychia, splinter hemorrhages, hyperkeratosis, and red spots in the lunula) are graded as either present (1) or absent (0) in each fingernail. The total score was calculated by summing the score for each feature and each fingernail and ranged from 0 to 130, with higher scores indicating greater nail disease. A negative change from baseline indicated an improvement in nail disease.",
   "timeFrame": "Baseline and Week 12"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1. Participant is ≥18 years of age;\n2. Participant has a confirmed diagnosis of PsA per the 2006 Classification criteria for Psoriatic Arthritis (CASPAR) with symptoms for ≥6 months prior to the Screening Visit;\n3. Participant has active disease (defined by a TJC68 of ≥3 and a SJC66 of ≥3);\n4. Participant has either current active PsO or a dermatologist confirmed history of PsO;\n5. Participant tests negative for rheumatoid factor (RF) at the Screening Visit;\n6. Participant tests negative for anti-cyclic citrullinated peptide (CCP) antibodies at the Screening Visit;\n7. Participant must be, in the opinion of the investigator, a suitable candidate for treatment with adalimumab per approved local product information.\n\nExclusion Criteria:\n\n1. Participant with known hypersensitivity to sonelokimab or any of its excipients;\n2. Participant with known hypersensitivity to adalimumab or any of its excipients;\n3. Participant who has previously failed on anti-interleukin (IL)-17 therapy;\n4. Participant who has previously failed on anti-tumor necrosis factor alpha (TNFα) therapy;\n5. Participant who has had previous exposure to more than 2 biologic agents of any type to treat PsA prior to the Screening Visit;\n6. Participant who has a diagnosis of chronic inflammatory conditions other than PsO or PsA;\n7. Participant who has a diagnosis of arthritis mutilans",
  "healthyVolunteers": false,
  "sex": "ALL",
