forecastInput:
{
 "nctId": "NCT02553733",
 "briefTitle": "Effect of Beetroot Juice on Coronary Blood Flow and Walking Performance in PAD",
 "officialTitle": "Effects of Dietary Nitrate Supplementation on Coronary Blood Flow and Walking Performance in Peripheral Arterial Disease",
 "leadSponsor": {
  "name": "David N. Proctor, PhD",
  "class": "OTHER"
 },
 "collaborators": [
  {
   "name": "Milton S. Hershey Medical Center",
   "class": "OTHER"
  },
  {
   "name": "Wake Forest University Health Sciences",
   "class": "OTHER"
  }
 ],
 "startDate": "2015-12",
 "firstRegistered": "2015-09-15",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Peripheral Arterial Disease"
 ],
 "keywords": [
  "Dietary nitrate supplementation",
  "Beetroot juice"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "CROSSOVER",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "DOUBLE",
   "whoMasked": [
    "PARTICIPANT",
    "INVESTIGATOR"
   ]
  }
 },
 "enrollment": 11,
 "briefSummary": "In this study the investigators will test the hypothesis that short-term consumption of inorganic nitrate (supplied in concentrated beetroot juice) enhances coronary blood flow responses, large artery hemodynamics, and leg oxygenation/exercise tolerance in patients with peripheral arterial disease (PAD). Understanding and improving blood flow regulation in the heart and skeletal muscles of patients with PAD is important because exercise triggers symptoms of leg pain and substantially raises blood pressure and myocardial demand in these patients.",
 "detailedDescription": "Peripheral arterial disease (PAD) is a strong predictor of cardiovascular mortality and negatively affects functional capacity and quality of life for as many as 14 million patients in the U.S. alone. One open-label study showed that acute consumption of beetroot juice improved 6 min walk performance, reduced blood pressure, and enhanced leg muscle oxygenation in PAD patients. However, no studies have rigorously confirmed these findings in a double-blind manner, nor have the effects of this supplement been investigated (acutely or short-term) in the coronary circulation of PAD patients.\n\nIn addition to studying its effects on graded treadmill walking performance and consequent large artery vasodilation, the present study will examine the effects of short-term beetroot juice consumption (twice/day) on both coronary and leg vasodilator (graded calf flexion) and vasoconstrictor (isometric handgrip, voluntary apnea) responses in patients with PAD. Participants will randomly consume either nitrate-rich or nitrate-depleted beetroot juice with a 7 to 14 day wash-out period between. Effects of beetroot juice consumption on plasma nitrate, nitrite and methemoglobin will also be assessed.",
 "arms": [
  {
   "label": "Beetroot juice (Beet-It Organic Shot)",
   "type": "ACTIVE_COMPARATOR",
   "description": "Subjects will consume 70 ml of beetroot juice (Beet-It Organic Shot) twice per day (morning, afternoon) for 5 to 7 days to assess the short term effects of this nitrate supplement on graded treadmill walking responses (day 4) and vasodilator/vasoconstrictor responses in the coronary and lower leg circulations (day 5 or 6 or 7). On both study visits, subjects will consume their morning dose 1 hour 45 min before experiments begin.",
   "interventionNames": [
    "Drug: Beetroot juice"
   ]
  },
  {
   "label": "Placebo Comparator: Beetroot juice (Beet-It Organic Shot)",
   "type": "PLACEBO_COMPARATOR",
   "description": "Subjects will consume 70 ml of beetroot juice (Beet-It Organic Placebo) twice per day (morning, afternoon) for 5 to 7 days to assess the short term effects of this nitrate supplement on graded treadmill walking responses (day 4) and vasodilator/vasoconstrictor responses in the coronary and lower leg circulations (day 5 or 6 or 7). On both study visits, subjects will consume their morning dose 1 hour 45 min before experiments begin.",
   "interventionNames": [
    "Drug: Beetroot juice placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Beetroot juice",
   "description": "This beverage contains 0.3 g of inorganic nitrate per 70 ml container, and is bottled and supplied by James White Drinks (UK).",
   "armGroupLabels": [
    "Beetroot juice (Beet-It Organic Shot)"
   ],
   "otherNames": [
    "Beet-It Organic Shot"
   ]
  },
  {
   "type": "DRUG",
   "name": "Beetroot juice placebo",
   "description": "This beverage is identical in look and taste to the Beet-It organic shot, but has the nitrate removed. It is also bottled and supplied by James White Drinks (UK).",
   "armGroupLabels": [
    "Placebo Comparator: Beetroot juice (Beet-It Organic Shot)"
   ],
   "otherNames": [
    "Beet-It organic placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Peak Treadmill Time",
   "description": "Peak treadmill time was determined using the Gardner treadmill protocol, measured as the number of seconds the participant was able to walk until they asked to stop the test due to leg fatigue.",
   "timeFrame": "4 to 6 days after initiating daily ingestion of beetroot juice"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Coronary Flow Velocity Response to Peak Plantar Flexion Exercise",
   "description": "Change in LAD coronary artery flow velocity, measured using transthoracic ultrasound, from baseline rest to peak plantar flexion exercise. Single leg plantar flexion exercise of the most symptomatic leg was performed at a rate of 20 contractions per minute, with increases in workload (1 kg) every minute until volitional fatigue, or until maximum exercise duration of 14 min was reached.",
   "timeFrame": "4 days after initiating daily ingestion of beetroot juice"
  },
  {
   "measure": "Resting Blood Pressure",
   "description": "Resting mean arterial blood pressure (mmHg) obtained prior to the exercise treadmill test obtained using an automated arm blood pressure cuff.",
   "timeFrame": "4 to 6 days after initiating daily ingestion of beetroot juice"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1. Patients with peripheral arterial disease (PAD)\n2. Capable of giving informed consent\n3. Men and women age 21- 85 years\n4. Diagnosed with PAD (i.e., ankle-brachial index below 0.9)\n5. Fontaine stage II or less - no pain while resting\n6. Satisfactory history and physical exam\n\nExclusion Criteria:\n\n1. Children\n2. Pregnant or nursing women\n3. Patients taking nitroglycerine or nitrate preparations\n4. Patients taking phosphodiesterase inhibitors such as sildenafil or tadalafil\n5. Patients taking proton pump inhibitors\n6. Ejection fraction \\< 40%\n7. Uncontrolled hypertension\n8. Uncontrolled diabetes\n9. Myocardial infarction within past 6 months or unstable angina\n10. Severe lung disease (i.e., on supplemental oxygen or frequently use rescue inhalers)\n11. Abnormality in hemoglobin or hematocrit or methemoglobin\n12. Impaired renal function\n13. Impaired liver function\n14. History or diagnosis of Barrett's esophagus\n15. Known allergy to beetroot juice or lemon juice\n16. Inability to walk on a treadmill at a moderate pace (2.0 miles/hour)",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "21 Years",
  "maximumAge": "85 Years"
 },
 "siteCount": 1,
 "countries": [
  "United States"
 ]
}

