forecastInput:
{
 "nctId": "NCT05901831",
 "briefTitle": "A Study to Learn How Well the Study Treatment Finerenone Works and How Safe it is in People With Long-term Decrease in the Kidneys' Ability to Work Properly (Chronic Kidney Disease) Together With Type 1 Diabetes",
 "officialTitle": "A Parallel-group, Randomized, Prospective, Interventional, Double-blind, Multicenter Global Phase 3 Study to Investigate the Efficacy and Safety of Finerenone Versus Placebo, in Addition to Standard of Care, in Participants With Chronic Kidney Disease and Type 1 Diabetes",
 "leadSponsor": {
  "name": "Bayer",
  "class": "INDUSTRY"
 },
 "startDate": "2024-02-26",
 "firstRegistered": "2023-06-05",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Chronic Kidney Disease",
  "Type 1 Diabetes Mellitus"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 242,
 "briefSummary": "Researchers are looking for a better way to treat people with chronic kidney disease (CKD), a progressive decrease in the kidneys' ability to work properly, and type 1 diabetes.\n\nIn people with type 1 diabetes, the body does not make enough of a hormone called insulin, resulting in high blood sugar levels that can cause damage to the kidneys. CKD often occurs together with or as a consequence of type 1 diabetes.\n\nThe study treatment finerenone works by blocking certain proteins, called mineralocorticoid receptors. An increased stimulation of these proteins is thought to damage the kidneys and the heart. By lowering their stimulation, finerenone reduces the risk of kidney disease progressively getting worse. Finerenone is approved for doctors to prescribe to people with CKD and type 2 diabetes.\n\nIn this study, researchers want to learn if finerenone works better than placebo in reducing the participants' kidney disease from getting worse when given in addition to standard of care (SOC) treatment. A placebo looks like a treatment but does not have any medicine in it. SOC is a procedure or treatment that medical experts consider most appropriate for a condition or disease. To find out how well finerenone works, the level of a protein (albumin) in the urine will be measured.\n\nResearchers also want to know how safe finerenone is. To do this, the researchers will collect the number of participants with:\n\n* medical problems (also called treatment-emergent adverse events (TEAEs))\n* serious TEAEs. A TEAE is considered 'serious' when it leads to death, puts the participant's life at risk, requires hospitalization, causes disability, causes a baby being born with medical problems, or is medically important\n* higher than normal blood levels of potassium (hyperkalaemia). Depending on the treatment group, the participants will either take finerenone or placebo, Importantly, the participants will also continue to take their regular SOC medicines.\n\nThe participants will be in the study for up to 7.5 months and will take the study treatments for 6 months. During the study, they will visit the study site at least 6 times.\n\nThe study team will:\n\n* collect blood and urine samples\n* check the participants' vital signs such as blood pressure and heart rate\n* do a physical examination including height and weight\n* check the participants' heart health by using an electrocardiogram (ECG)\n* do pregnancy tests in women of childbearing potential",
 "arms": [
  {
   "label": "Finerenone arm",
   "type": "EXPERIMENTAL",
   "description": "Participants with eGFR ≥25 to \\<60 mL/min/1.73 m\\^2 at Screening visit will take Finerenone Dose A. Participants with eGFR ≥60 mL/min/1.73 m\\^2 at Screening visit will take Dose B. Up-titration and down-titration of study intervention will be based on local potassium and kidney function (eGFR) values. Treatment duration is 6 months.",
   "interventionNames": [
    "Drug: Finerenone"
   ]
  },
  {
   "label": "Placebo arm",
   "type": "PLACEBO_COMPARATOR",
   "description": "Participants will take Finerenone matching placebo for 6 months.",
   "interventionNames": [
    "Other: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Finerenone",
   "description": "Dose A, Dose B, oral",
   "armGroupLabels": [
    "Finerenone arm"
   ]
  },
  {
   "type": "OTHER",
   "name": "Placebo",
   "description": "Oral",
   "armGroupLabels": [
    "Placebo arm"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change in UACR From Baseline (Ratio to Baseline) Over 6 Months",
   "description": "UACR was assessed by a central laboratory at baseline, Month 3, and Month 6. The primary efficacy variable was change in UACR from baseline over 6 months, which was evaluated on the average of the Month 3 and Month 6 geometric mean UACR ratios to baseline within each treatment arm. A ratio to baseline below 1 indicates a reduction in UACR, with a smaller value indicating a better outcome. Both values were used to assess the treatment effect, with a ratio finerenone-versus-placebo below 1 indicating a better outcome with finerenone relative to placebo.",
   "timeFrame": "From baseline to Month 6"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Number of Participants With Treatment-emergent AEs (TEAEs), Treatment-emergent SAEs (TESAEs)",
   "description": "AE: An adverse event (AE) in this study is defined as any medical problem that the participants had during the study. This includes any new medical issue or a worsening of an existing condition that happens after the participant receives the study treatment, regardless of whether it is considered related to the study treatment. AEs that started or worsened after the first dose of study intervention up to 3 days after any temporary or permanent interruption of study intervention were considered as TEAEs; for the targeted AE reporting, non-serious AEs were not mandatory to be collected.",
   "timeFrame": "From the first dose of study intervention and up to 3 days after the last dose of study intervention, with a median treatment duration 6.07 months."
  },
  {
   "measure": "Number of Participants With Treatment-emergent Hyperkalaemia",
   "description": "Hyperkalemia (evaluated as the combined MedDRA Preferred terms blood potassium increased and hyperkalaemia) was an adverse event of special interest in this study and collected in the electronic case report form (eCRF).",
   "timeFrame": "From the first dose of study intervention and up to 3 days after the last dose of study intervention, with a median treatment duration 6.07 months."
  }
 ],
 "eligibility": {
