forecastInput:
{
 "nctId": "NCT05603754",
 "briefTitle": "Safety and Efficacy of Lorecivivint (SM04690) for the Treatment of Knee Osteoarthritis (STRIDES)",
 "officialTitle": "A Phase 3, Multicenter, Randomized, Double Blind, Placebo-Controlled Study to Evaluate the Efficacy and Safety of a Single Injection of Lorecivivint 0.07 mg in Subjects With Moderate to Severe Osteoarthritis Pain of the Knee",
 "leadSponsor": {
  "name": "Biosplice Therapeutics, Inc.",
  "class": "INDUSTRY"
 },
 "collaborators": [
  {
   "name": "NBCD A/S",
   "class": "INDUSTRY"
  }
 ],
 "startDate": "2022-11-18",
 "firstRegistered": "2022-10-27",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Knee Osteoarthritis"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
