 "enrollment": 499,
 "briefSummary": "This phase 3 study was a multicenter, randomized, double-blind, placebo-controlled study of lorecivivint injected intra-articularly (IA) into the target (most painful) knee joint of moderately to severely symptomatic osteoarthritis (OA) subjects at a single dose of 0.07 mg lorecivivint per 2 mL injection. This study utilized standard outcomes to evaluate the safety and efficacy of lorecivivint.",
 "detailedDescription": "SM04690-OA-21 was a phase 3, 16-week multicenter, randomized, double-blind, placebo-controlled, parallel group study investigating the safety, tolerability and efficacy of LOR 0.07 mg (compared with PBO) injected into the target knee joint of moderately to severely symptomatic knee OA subjects.\n\nPatient-reported outcomes included Pain Numeric Rating Scale (NRS) \\[0-10\\], Western Ontario and McMaster Universities Arthritis Index (WOMAC), and Patient Global Assessment (PGA) of knee osteoarthritis.\n\nThe primary efficacy endpoint was change from baseline in target knee Pain NRS at Week 12. Secondary endpoints included change at Week 12 in WOMAC Function and PGA.",
 "arms": [
  {
   "label": "Lorecivivint",
   "type": "EXPERIMENTAL",
   "description": "Healthcare professional-administered intra-articular injection; performed on Day 1.",
   "interventionNames": [
    "Drug: Lorecivivint"
   ]
  },
  {
   "label": "Vehicle",
   "type": "PLACEBO_COMPARATOR",
   "description": "Healthcare professional-administered intra-articular injection; performed on Day 1.",
