   ],
   "otherNames": [
    "SM04690"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "One intra-articular injection of 0 mg lorecivivint in 2 mL vehicle",
   "armGroupLabels": [
    "Vehicle"
   ],
   "otherNames": [
    "Vehicle"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline OA Pain in the Target Knee as Assessed by Weekly Average of Daily Pain Numeric Rating Scale (NRS) at Week 12",
   "description": "Evaluate change from baseline OA pain in the target knee as assessed by weekly average of daily pain NRS at Week 12.\n\nThe pain NRS is an 11-point scale \\[0-10\\] for subject self-reporting of average knee pain in the last 24 hours; 0 indicates no pain, and 10 indicates pain as bad as you can imagine.",
   "timeFrame": "Baseline to Week 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline OA Function as Assessed by Western Ontario and McMaster Universities Osteoarthritis Index (WOMAC) Physical Function Subscore (WOMAC Function) at Week 12",
   "description": "Evaluate change from baseline OA function as assessed by WOMAC Function at Week 12. The WOMAC is a widely-used, proprietary outcome measurement tool used to evaluate the condition of subjects with OA of the knee and hip, including pain (5 questions), stiffness (2 questions) and physical functioning (17 questions) of the joints. Each question is measured on an 11-point NRS scale \\[0-10\\], where 0 indicates no pain / no stiffness / no difficulty, and 10 indicates extreme pain / extreme stiffness / extreme difficulty.\n\nFor analysis, WOMAC Function scores were scaled to 0 to 100, where 0 represents \"No Functional Difficulty\" and 100 represents \"Extreme Functional Difficulty\".",
   "timeFrame": "Baseline and Week 12"
  },
  {
   "measure": "Change From Baseline OA Disease Activity as Assessed by Patient Global Assessment at Week 12",
   "description": "Evaluate change from baseline OA disease activity as assessed by Patient Global Assessment at Week 12. The Patient Global Assessment is an 11-point NRS \\[0-10\\] for subject self-reporting of how they feel their target knee is impacting them. For analysis, PGA scores were scaled to 0 to 100, where 0 represents \"Very Good\" and 100 represents \"Very Bad\".",
   "timeFrame": "Baseline and Week 12"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Males and females between 40 and 80 years of age, inclusive, in general good health apart from their knee OA\n* Ambulatory (single assistive devices such as canes allowed if needed less than 50% of the time, subjects requiring a walker are excluded)\n* Diagnosis of femorotibial OA in the target knee by standard American College of Rheumatology (ACR) criteria at the Screening Visit (clinical AND radiographic criteria); OA of the knee is not to be secondary to any rheumatologic conditions (e.g., rheumatoid arthritis)\n* Radiographic disease Stage 2 or 3 in target knee within 24 weeks of the Screening Visit according to the Kellgren-Lawrence (KL) grading of knee OA as assessed by independent central readers\n* Qualifying mean score on the 24-h average pain score (0-10 numeric rating scale)\n* Pain compatible with OA of the knee(s) for at least 26 weeks prior to the Screening Visit\n* Primary source of pain throughout the body is due to OA in the target knee\n* Body mass index (BMI) ≤ 35 kg/m2 at the Screening Visit\n\nExclusion Criteria:\n\n* Pregnant women, breastfeeding women, and women who are not post-menopausal (defined as 12 months with no menses without an alternative medical cause) or permanently surgically sterile (includes hysterectomy, bilateral salpingectomy, and bilateral oophorectomy) who have a positive or indeterminate pregnancy test result at the Screening Visit or Day 1\n* Partial or complete joint replacement in either knee\n* Currently requires use of a lower extremity prosthesis, and/or a structural knee brace (i.e., a knee brace that contains hardware)\n* Any surgery (e.g., arthroscopy) in either knee within 26 weeks prior to Day 1\n* Intra-articular (IA) injection into the target knee with a therapeutic aim including, but not limited to hyaluronic acid, platelet-rich plasma (PRP), and stem cell therapies within 26 weeks prior to Day 1; or IA glucocorticoids within 12 weeks prior to Day 1 allowed\n* Previous treatment with lorecivivint (SM04690)\n* Participation in a clinical research trial that included the receipt of an investigational product or any experimental therapeutic procedure within 26 weeks prior to the Screening Visit, or planned participation in any such trial\n* Subjects requiring the use of opioids \\> 1x per week within 12 weeks prior to Day 1\n* History of malignancy within the last 5 years; not including subjects with prior history of adequately treated in situ cervical cancer or basal or squamous cell skin cancer\n* Clinically significant abnormal screening hematology values, blood chemistry values, or urinalysis values as determined by the Investigator\n* Any known active infections, including urinary tract infection, upper respiratory tract infection, sinusitis, suspicion of IA infection, hepatitis B or hepatitis C infection, and/or infections that may compromise the immune system such as human immunodeficiency virus (HIV) at Day 1\n* Use of APAP or NSAIDs during washout period (between Screening Visit 2 and Day 1). Use of aspirin (up to 325 mg/day) for thrombosis prophylaxis is permitted.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "40 Years",
  "maximumAge": "80 Years"
 },
 "siteCount": 44,
 "countries": [
  "United States"
 ]
}

