 "primaryOutcomes": [
  {
   "measure": "Change From Baseline in Weekly Urticaria Activity Score (UAS7) at Week 12",
   "description": "The UAS7 score is a composite score containing both the hive severity score (HSS, ranging from 0 = None to 3 = more than 50 hives) and the itch severity score (ISS, ranging from 0 = None to 3 = intense). The daily UAS scores ranged from 0 to 6 points per day. Daily UAS scores were summed over a 7-day period to create the UAS7, ranging from 0 to 42, and are composed of the HSS7 and ISS7 components. A higher score indicates worse disease. Baseline is defined as the sum of the 7 days measurements obtained on and prior to the target visit day.",
   "timeFrame": "Baseline and Week 12"
  },
  {
   "measure": "Change From Baseline in Weekly Itch Severity Score (ISS7) at Week 12",
   "description": "The ISS represents the itch severity on a scale and was recorded by the participant in their e-diary ranging from 0 (None) to 3 (intense). The ISS7 is the sum of ISS for the previous 7 days. The ISS7 represents itch severity on a scale ranging from 0 (minimum) to 21 (maximum). Higher scores indicate greater intensity of itch. Baseline is defined as the sum of the 7 days measurements obtained on and prior to the target visit day.",
   "timeFrame": "Baseline and Week 12"
  }
 ],
 "secondaryOutcomes": [
