forecastInput:
{
 "nctId": "NCT04968184",
 "briefTitle": "Efficacy and Safety of KBP-5074 in Uncontrolled Hypertension and Moderate or Severe Chronic Kidney Disease (CKD)",
 "officialTitle": "A Phase 3 Randomized Double-Blind Placebo-Controlled Multicenter Study to Assess the Efficacy and Safety of KBP-5074 Mineralocorticoid Receptor Antagonist in Subjects With Uncontrolled Hypertension and Moderate or Severe (Stage 3b/4) CKD",
 "leadSponsor": {
  "name": "Novo Nordisk A/S",
  "class": "INDUSTRY"
 },
 "collaborators": [
  {
   "name": "KBP Biosciences",
   "class": "INDUSTRY"
  }
 ],
 "startDate": "2021-11-05",
 "firstRegistered": "2021-07-07",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Chronic Kidney Diseases"
 ],
 "keywords": [
  "Stage 3b/4 chronic kidney disease",
  "Hypertension",
  "Uncontrolled Hypertension",
  "Blood pressure",
  "Mineralocorticoid Receptor Antagonist",
  "Randomized withdrawal"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "maskingDescription": "All individuals directly involved in the conduct of the study, including participants, Investigators, site staff, clinical research organization (CRO) personnel, and Sponsor study personnel, will remain blinded to treatment assignments until all participants have completed the Week 56 end of study (EOS) Visit (Visit 17) and the database locked in preparation.",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 666,
 "briefSummary": "This Phase 3, randomized, Double-blind, placebo-controlled, 2-arm, parallel-group, multicenter study with randomized withdrawal will evaluate the efficacy, safety, and durability of KBP-5074 in adult participants who have stage 3b/4 chronic kidney disease (CKD) (estimated glomerular filtration rate \\[eGFR\\] calculated using the Chronic Kidney Disease Epidemiology Collaboration \\[CKD-EPI\\] formula \\[eGFR {EPI}\\] ≥15 to ≤44 mL/min/1.73 m\\^2) and uncontrolled hypertension (systolic blood pressure (SBP) ≥140 and \\<180 mm Hg and taking 2 or more antihypertensive medications.",
 "detailedDescription": "Participants in this study will be recruited, screened, and enrolled at approximately 140 study sites globally.\n\nThe study will consist of the following periods:\n\n1. Pretreatment Phase: This will include prescreening assessment and screening period of up to 4 weeks and 2-week Open-label placebo Run-In period.\n2. A 24-week Double-blind Treatment Period (Randomization to Week 24) will include: An initial 12-week (Randomization to Week 12) and second 12-week (Week 12 to Week 24) treatment period and a second 12-week treatment period (Week 12 to Week 24), during both the periods study drug will be titrated.\n3. A 24-week Open-label Treatment Period (Week 24 to Week 48) during which eligible participants will receive Open-label KBP-5074.\n4. A 4-week Randomized Double-blind Withdrawal Period (Week 48 to Week 52) during which eligible participants will be randomized to continue their current KBP-5074 dose at the end of Open-label treatment or receive matching placebo for 4 weeks.\n5. A 4-week post-treatment Follow-Up Period (Week 52 to Week 56).\n\nDuring, 24-week Double-blind Treatment Period, 24-week Open-label Treatment Period, and at 4-week Randomized Double-blind Withdrawal Period, the background antihypertensive medications change may or may not be allowed.\n\nAt Double-blind Treatment Period, eligible participants will be randomly assigned in a 1:1 ratio to KBP-5074 0.25 mg or matching placebo once daily (QD).\n\nAt the Randomized Double-blind Withdrawal Period, participants who meet the randomized withdrawal criteria will be randomly assigned in a 1:1 ratio to continue their current KBP-5074 dose at the end of the Open-label Treatment Period or matching placebo QD.\n\nThe study design included a pre-planned futility determination by an Independent Data Monitoring Committee (IDMC).\n\nThe trial was originally sponsored by KBP Biosciences PTE Ltd, but sponsorship was transferred to Novo Nordisk after the trial was terminated following the futility determination by IDMC.",
 "arms": [
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Open-label Placebo Run-In Period: All eligible participants will receive matching placebo, for approximately 2 weeks, during the Open-label placebo Run-In period.\n\nDouble-blind Treatment Period: All eligible participants will receive matching placebo, from week 2 thru week 24 during the Double-blind treatment Period\n\nOpen-label Treatment Period: All eligible participants will receive KBP-5074, from week 24 thru week 48 during the Open label Treatment Period\n\nRandomized Double-blind Withdrawal Period: All eligible participants will be randomized to either continue their current KBP-5074 dose at the end of the Open-Label Treatment Period or receive matching placebo from week 48 thru week 52.\n\nFollow up Period: All participants will discontinue matching placebo/KBP-5074 and be followed for safety until end of study visit from week 52 to week 56.",
   "interventionNames": [
    "Drug: Placebo"
   ]
  },
  {
   "label": "KBP-5074",
   "type": "EXPERIMENTAL",
   "description": "Open-label Placebo Run-In period: All eligible participants will receive matching placebo, for approximately 2 weeks during the Open-label placebo Run-In period.\n\nDouble-blind Treatment Period: All eligible participants will receive KBP-5074, from week 2 thru week 24 during the Double-blind Treatment Period\n\nOpen-label Treatment Period: All eligible participants will receive KBP-5074, from week 24 thru week 48 during the Open label Treatment Period\n\nRandomized Double-blind Withdrawal Period: All eligible participants will be randomized to either continue their current KBP-5074 dose at the end of the Open-Label Treatment Period or receive matching placebo from week 48 thru week 52.\n\nFollow up Period: All participants will discontinue matching placebo/KBP-5074 and be followed for safety until end of study visit from week 52 to week 56.",
   "interventionNames": [
    "Drug: KBP-5074"
   ]
  }
 ],
 "interventions": [
