 "briefSummary": "12-week, randomized, double-blind, placebo-controlled, parallel-group study of carbetocin nasal spray for the treatment of hyperphagia in Prader-Willi syndrome (PWS)",
 "detailedDescription": "This is a 12-week, multicenter, randomized, double-blind, placebo-controlled, parallel-group study comparing carbetocin nasal spray 3.2 mg TID with placebo (matched placebo nasal spray TID) in subjects with PWS.",
 "arms": [
  {
   "label": "Carbetocin",
   "type": "EXPERIMENTAL",
   "description": "Carbetocin nasal spray 3.2 mg administered TID",
   "interventionNames": [
    "Drug: Carbetocin"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Matching placebo nasal spray administered TID",
   "interventionNames": [
    "Drug: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Carbetocin",
   "description": "Carbetocin nasal spray 3.2 mg administered TID",
   "armGroupLabels": [
    "Carbetocin"
   ],
   "otherNames": [
    "ACP-101"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "Matching placebo nasal spray administered TID",
   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline at Week 12 in Hyperphagia Questionnaire for Clinical Trials (HQ-CT) Score",
   "description": "The HQ-CT is a caregiver-reported, 9-item assessment of observable hyperphagia-related behaviors in participants with PWS. The questionnaire is administered to the caregiver by a trained rater using standardized prompts, and the same caregiver is expected to complete the assessment throughout the study whenever possible. Each item is scored from 0 to 4, resulting in a total score ranging from 0 to 36, with higher scores indicating greater severity of hyperphagia. A decrease from baseline reflects improvement, and a reduction of 7.7 points has been identified as a clinically meaningful within-participant improvement.",
   "timeFrame": "Baseline to Week 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline at Week 12 in Clinical Global Impression of Severity (CGI-S) for PWS Score",
   "description": "The CGI-S for PWS is a clinician-rated assessment of the overall severity of PWS symptoms at the time of evaluation. The CGI-S is rated on a 7-point scale ranging from 1 (normal, not at all ill) to 7 (among the most severely ill participants), with higher scores indicating greater illness severity. The assessment is performed by the Investigator or a trained, qualified designee, and the same rater is expected to evaluate a given participant throughout the study whenever possible to maintain rating consistency.",
   "timeFrame": "Baseline to Week 12"
  },
  {
   "measure": "Clinical Global Impression of Change (CGI-C) for PWS Score at Week 12",
   "description": "The CGI-C for PWS is a clinician-rated assessment of change in the overall severity of PWS symptoms relative to Baseline. The CGI-C is rated on a 7-point scale ranging from 1 (very much improved) to 7 (very much worse), with lower scores indicating greater improvement from Baseline. The assessment is performed by the Investigator or a trained, qualified designee, and the same rater is expected to evaluate a given participant throughout the study whenever possible to maintain rating consistency.",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Percentage of Subjects With Treatment Response at Week 12 (Defined as Improvement From Baseline ≥8 Points) Based on the HQ-CT Score at Week 12",
   "description": "Treatment response was defined as an improvement from Baseline of at least 8 points in the HQ-CT total score at Week 12. The HQ-CT is a caregiver-reported, 9-item assessment of observable hyperphagia-related behaviors in participants with PWS. Total scores range from 0 to 36, with higher scores indicating greater severity of hyperphagia. Participants meeting the ≥8-point improvement threshold were classified as responders.",
   "timeFrame": "Week 12"
  },
  {
   "measure": "Change From Baseline at Week 12 in CGI-S for Hyperphagia in PWS Score",
   "description": "The CGI-S for PWS is a clinician-rated assessment of the overall severity of PWS symptoms at the time of evaluation. The CGI-S is rated on a 7-point scale ranging from 1 (normal, not at all ill) to 7 (among the most severely ill participants), with higher scores indicating greater illness severity. The assessment is performed by the Investigator or a trained, qualified designee, and the same rater is expected to evaluate a given participant throughout the study whenever possible to maintain rating consistency.",
   "timeFrame": "Baseline to Week 12"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria\n\n* Male or female participants aged 5 to 30 years\n* Diagnosis of Prader-Willi syndrome with a documented disease-causing genetic mutation\n* Evidence of hyperphagia, including increased appetite and decreased satiety with food-seeking behaviors\n* Meeting minimum severity thresholds for hyperphagia based on validated clinical assessments at Screening and Baseline\n* Residing with a caregiver who is able and willing to comply with study procedures and participate in study visits\n\nExclusion Criteria\n\n* Diagnosis of Schaaf-Yang syndrome or another genetic, hormonal, or chromosomal disorder other than Prader-Willi syndrome\n* Active upper respiratory infection at Screening or Baseline\n* Clinically significant medical conditions that could interfere with study participation or interpretation of results (e.g., cardiovascular, renal, hepatic, gastrointestinal, or respiratory disease)\n* History of significant neurological conditions (e.g., cerebrovascular disease, brain trauma, epilepsy, or frequent migraines), except for a history of febrile seizures\n* Recent or planned nasal surgery that could affect intranasal drug administration\n* Unwillingness to restrict use of intranasal medications that may interfere with study treatment\n* Recent clinically significant psychiatric instability, including irritability or agitation requiring changes in antipsychotic therapy\n* Use of medications or treatments that may interfere with the evaluation of hyperphagia or study endpoints within a defined period prior to Screening Active psychotic disorder or history of significant psychotic symptoms\n* History of suicide attempt or inpatient psychiatric hospitalization\n* Recent changes in food-related behavioral or environmental interventions that may confound assessment of hyperphagia\n\nAdditional inclusion and exclusion criteria apply. Participants will be evaluated at Screening to ensure all eligibility requirements are met.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "5 Years",
  "maximumAge": "30 Years"
 },
 "siteCount": 30,
