   "masking": "NONE"
  }
 },
 "enrollment": 863,
 "briefSummary": "The purpose of this study is to assess the efficacy and safety of pembrolizumab plus lenvatinib plus chemotherapy compared with pembrolizumab plus chemotherapy as first-line intervention in participants with metastatic esophageal carcinoma.\n\nThe primary hypotheses are that pembrolizumab plus lenvatinib plus chemotherapy is superior to pembrolizumab plus chemotherapy with respect to overall survival (OS) per Response Evaluation Criteria in Solid Tumors Version 1.1 (RECIST 1.1) by blinded independent central review (BICR).\n\nAs of Amendment 09, Study MK-7902-014 will begin close out activities. Any participant who discontinues study intervention for any reason will be discontinued from the study without further follow-up. Second Course and treatment beyond disease progression will no longer be offered. No safety concerns contributed to the termination of this study.",
 "detailedDescription": "There will be 2 parts to the study: the cisplatin and 5-fluorouracil (5-FU) (FP) and paclitaxel and cisplatin (TP) Safety Run-in (Part 1) and the Main Study (Part 2). In Part 1 (FP and TP Safety Run-in), participants will be treated with pembrolizumab plus lenvatinib plus FP or TP. Dose-limiting toxicities, safety, and tolerability will be assessed.\n\nIn Part 2 (Main Study), participants (not including those participating in Part 1) will be treated with pembrolizumab plus lenvatinib plus chemotherapy or pembrolizumab plus chemotherapy. Efficacy, safety, and tolerability will be assessed.\n\nThe protocol-specified analysis of the primary outcome measures was completed with a data cut-off of 08-May-2025 (Primary Completion Date) and served as the final analysis of the primary outcome measures. At the time of the protocol-specified analysis, 368 participants were ongoing in the study and will be included in the End of Trial analysis.",
 "arms": [
  {
   "label": "Part 1: Pembrolizumab + Lenvatinib + Chemotherapy",
   "type": "EXPERIMENTAL",
   "description": "In the Induction phase, participants receive pembrolizumab 400mg intravenously (IV) every 6 weeks (Q6W) for 2 cycles (each cycle length = 6 weeks) plus Lenvatinib 8 mg orally (PO) once daily (QD) plus chemotherapy with FP (cisplatin 80 mg/m\\^2 and 5-FU 400 mg/m\\^2 followed by 2400 mg/m\\^2) or TP (paclitaxel 175 mg/m\\^2 and cisplatin 75 mg/m\\^2) IV every 3 weeks for 4 administrations at the investigator's discretion (approximately 12 weeks). In the Consolidation phase, participants receive pembrolizumab 400 mg IV Q6W for 16 cycles (each cycle length = 6 weeks) and Lenvatinib 20 mg PO until progressive disease or discontinuation (approximately 96 weeks).",
   "interventionNames": [
    "Biological: Pembrolizumab",
    "Drug: Lenvatinib",
    "Drug: Cisplatin",
    "Drug: 5-FU",
