{
 "nctId": "NCT03832998",
 "briefTitle": "Efficacy and Safety of Erenumab in Pediatric Subjects With Chronic Migraine",
 "officialTitle": "A Phase 3, Randomized, Double-blind, Placebo-controlled, Parallel-group Study to Evaluate the Efficacy and Safety of Erenumab in Children (6 to < 12 Years) and Adolescents (12 to < 18 Years) With Chronic Migraine (OASIS PEDIATRIC [CM])",
 "leadSponsor": {
