 },
 "enrollment": 284,
 "briefSummary": "This study will evaluate the efficacy and safety of erenumab in migraine prevention in children (6 to \\<12 years) and adolescents (12 to \\<18 years) with chronic migraine. The study hypothesis is that in pediatric participants with chronic migraine, the combined erenumab dose group has a greater reduction from baseline to week 9 through week 12 (month 3) in monthly migraine days (MMDs) when compared with placebo in the double-blind treatment phase (DBTP).",
 "detailedDescription": "This study is a phase 3, randomized, double-blind, placebo-controlled, parallel-group study to evaluate the efficacy and safety of erenumab in migraine prevention in children (6 to \\<12 years) and adolescents (12 to \\<18 years) with chronic migraine. The trial consists of four phases: screening (up to 3 weeks of initial screening and a 4-week prospective baseline phase); the DBTP (24 weeks for Group 1 subjects; 12-weeks for Group 2 subjects) in which participants receive placebo or erenumab dose 1, dose 2 or dose 3 (based on participant's body-weight) via subcutaneous injection once a month; the optional dose level blinded extension phase (40 weeks), in which all participants are assigned to receive dose 1, dose 2 or dose 3 of erenumab; and a 12 weeks safety follow-up phase (16 weeks after the last dose of investigational drug). The study intends to enrol 286 participants (256 adolescents and 30 children).",
 "arms": [
  {
   "label": "Dose Level 1",
   "type": "EXPERIMENTAL",
   "description": "Participants will be randomized to one of two doses determined by their body weight at Day 1. Participants who enrolled under the original protocol or protocol amendment 1 will be identified as group 1. Those enrolled under protocol amendment 2 will be identified as group 2.",
   "interventionNames": [
    "Drug: Erenumab Dose 1",
    "Drug: Erenumab Dose 2"
   ]
  },
  {
   "label": "Dose Level 2",
   "type": "EXPERIMENTAL",
   "description": "Participants will be randomized to one of two doses determined by their body-weight at Day 1. Participants who enrolled under the original protocol or protocol amendment 1 will be identified as group 1. Those enrolled under protocol amendment 2 will be identified as group 2.",
   "interventionNames": [
    "Drug: Erenumab Dose 2",
    "Drug: Erenumab Dose 3"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "interventionNames": [
    "Other: Placebo"
   ]
  }
 ],
 "interventions": [
