   "armGroupLabels": [
    "Placebo"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline in MMD to Week 9 Through Week 12 (Month 3) of the DBTP",
   "description": "A migraine day was defined as any calendar day in which the participant developed a qualified migraine headache (onset, continuation, or recurrence of the migraine headache). MMD was defined as the number of migraine days between each monthly IP dose. MMD at baseline was the number of migraine days in the 4-week baseline phase.\n\nThe least squares mean (LSM) was calculated using a linear mixed effects repeated measures model including treatment group, baseline value as covariate, stratification factors of region and prior preventive treatment failure, scheduled visit, and interaction of treatment group with scheduled visit. Participants were used as a random effect.\n\nAs pre-specified in the Statistical Analysis Plan (SAP), only results from adolescents are presented.",
   "timeFrame": "Baseline to Week 12"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline in Monthly Headache Days to Week 9 Through Week 12 (Month 3) of the DBTP",
   "description": "A headache day was defined as any calendar day in which the participant develops a qualified headache (onset, continuation, or recurrence of the headache). Monthly headache days were defined as the number of headache days between each monthly IP dose. Monthly headache days at baseline was the number of headache days in the 4-week baseline phase.\n\nLSM was calculated using a linear mixed effects repeated measures model including treatment group, baseline value as covariate, stratification factors of region and prior preventive treatment failure, scheduled visit, and interaction of treatment with scheduled visit. Participants were used as a random effect.\n\nAs pre-specified in the SAP, only results from adolescents are presented.",
   "timeFrame": "Baseline to Week 12"
  },
  {
   "measure": "Number of Participants With at Least 50% Reduction in MMD From Baseline to Week 9 Through Week 12 (Month 3) of the DBTP",
   "description": "A migraine day was defined as any calendar day in which the participant developed a qualified migraine headache (onset, continuation, or recurrence of the migraine headache). MMD was defined as the number of migraine days between each monthly IP dose. MMD at baseline was the number of migraine days in the 4-week baseline phase. All participants included in the overall number of participants analyzed contributed to the post-baseline data for this endpoint.\n\nAs pre-specified in the SAP, only results from adolescents are presented.",
   "timeFrame": "Baseline to Week 12"
  },
  {
   "measure": "Change From Baseline in MMD to the Average of the First 3 Months (Week 1 Through Week 12) of the DBTP",
   "description": "A migraine day was defined as any calendar day in which the participant developed a qualified migraine headache (onset, continuation, or recurrence of the migraine headache). MMD was defined as the number of migraine days between each monthly IP dose. MMD at baseline was the number of migraine days in the 4-week baseline phase.\n\nLSM was calculated using a fixed effects analysis of covariance (ANCOVA) model, including terms for treatment group, baseline value as covariate, and stratification factors of region and prior preventive treatment failure.\n\nAs pre-specified in the SAP, only results from adolescents are presented.",
   "timeFrame": "Baseline to Week 12"
  },
  {
   "measure": "Change From Baseline in Monthly Average Severity of Migraine Attacks to Week 9 Through Week 12 (Month 3) of the DBTP",
   "description": "Severity of qualified migraine headache was measured by using 100 mm Visual Analogue Scale (VAS). Monthly average severity of migraine attack was defined as sum of the severity of each migraine episodes during the migraine attacks between two consecutive monthly IP doses divided by total number of observed migraine episodes during migraine attacks in that monthly interval. 100 mm VAS ranged from 0 to 100 mm, where 0 represents no pain (lowest severity of migraine) and 100 represents worst possible pain (highest severity of migraine). Negative change from baseline indicates an improvement in symptoms.\n\nLSM was calculated using a linear mixed effects repeated measures model including treatment group, baseline value as covariate, stratification factors of region and prior preventive treatment failure, scheduled visit, and interaction of treatment with scheduled visit. Participants were used as a random effect.\n\nAs pre-specified in the SAP, only results from adolescents are presented.",
   "timeFrame": "Baseline to Week 12"
  },
  {
   "measure": "Change From Baseline in Migraine-related Disability and Productivity as Measured by the Modified Pediatric Migraine Disability Assessment (PedMIDAS) to Week 9 Through Week 12 (Month 3) of the DBTP",
   "description": "Modified PedMIDAS is a 6-item self-administered questionnaire that measures the disability in 2 settings: at school and at home. Modified PedMIDAS score is the sum of missed school days, days when activities at school or home were reduced by at least half due to headaches, and days when other family, social, leisure activities were reduced by at least half due to headaches. Modified PedMIDAS: 0-10: little/none;11-30: mild; 31-50: moderate; \\>50; severe; Minimum value 0, maximum value 80, higher scores mean a worse outcome. Negative change from baseline indicates an improvement in symptoms.\n\nLSM was calculated using a linear mixed effects repeated measures model including treatment group, baseline value as covariate, stratification factors of region and prior preventive treatment failure, scheduled visit, and interaction of treatment with scheduled visit. Participants were used as a random effect.\n\nAs pre-specified in the SAP, only results from adolescents are presented.",
   "timeFrame": "Baseline to Week 12"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Children (6 to less than 12 years of age) or adolescent (12 to less than 18 years of age) at the time of signing, if developmentally appropriate, the formal assent to participate to the study.\n* Participant's parent or legal representative has provided written informed consent before initiation of any study-specific activities/procedures.\n* History of migraine (with or without aura) for ≥ 12 months before screening according to the IHS Classification ICHD-3 (Headache Classification Committee of the International Headache Society, 2013) ICHD-3 specifications for pediatric migraine (participants aged less than 18 years), should be considered for the diagnosis of migraine.\n* History of ≥ 15 headache days per month of which ≥ 8 headache days were assessed by the participant as migraine days per month in each of the 3 months prior to screening.\n* Migraine frequency: greater than or equal to 8 migraine days based on the eDiary data during the last 28 days of the baseline phase if more than 28 days in duration.\n* Headache frequency of greater than or equal to 15 headache days based on the eDiary data during the last 28 days of the baseline phase if more than 28 days in duration.\n* Demonstrated at least 80% compliance with the eDiary based on the last 28 days of the baseline period, if more than 28 days in duration (eg, completing eDiary items for at least 23 out of the last 28 days of the baseline phase).\n\nKey Exclusion Criteria:\n\n* History of cluster headache or hemiplegic migraine headache.\n* Chronic migraine with continuous pain, in which the participant does not have any pain free periods (of any duration) during the 1 month prior to screening.\n* No therapeutic response with greater than 3 medication categories for prophylactic treatment of migraine after an adequate therapeutic trial. No therapeutic response is defined as no reduction in headache frequency, duration, or severity after administration of the medication for at least 6 weeks at the generally-accepted therapeutic dose(s) based on the investigator's assessment.\n* History of suicidal behavior or the participant is at risk of self-harm or harm to others.\n* History of major psychiatric disorder. Participants with anxiety disorder and/or mild major depressive disorder (Patient Health Questionnaire Modified for Adolescents \\[PHQ-A\\] score 9 for adolescents or based on medical judgement of the investigator for children) are permitted in the study if they are considered by the investigator to be stable and are taking no more than 1 medication for each disorder. Participants must have been on a stable dose within the 3 months before the start of the baseline phase.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "6 Years",
  "maximumAge": "17 Years"
 },
