 ],
 "primaryOutcomes": [
  {
   "measure": "Six-minute Walk Performance",
   "description": "Participants walking up and down a 100 foot hallway for six minutes following a standardized protocol. The goal is for them to walk as far as possible in six minutes",
   "timeFrame": "Change from baseline to six-month follow-up"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Maximal Treadmill Walking Time",
   "description": "A Gardner treadmill exercise protocol will be used",
   "timeFrame": "Change from baseline to six-month follow-up"
  },
  {
   "measure": "Brachial Artery Flow-mediated Dilation",
   "description": "Upper brachial artery flow-mediated dilation was evaluated by measuring percent change in the brachial artery diameter in response to reactive hyperemia, induced by inflating a blood pressure cuff for five minutes over the brachial artery.",
   "timeFrame": "Percent change from baseline to six-month follow-up"
  },
  {
   "measure": "The Walking Impairment Questionnaire - Distance Score",
   "description": "The Walking impairment questionnaire is a patient reported outcome measure, in which participants indicate the ease of walking distances ranging from across the room to up to approximately 1500 feet. The score is calculated on a 0-100 scale, where 0 indicates the in ability to walk any of the distances and 100 indicates no difficulty walking any of the distances.",
   "timeFrame": "Change from baseline to six-month follow-up"
  },
