{
 "nctId": "NCT04628481",
 "briefTitle": "A Study of Oral Ladarixin in Recent Onset Type 1 Diabetes and a Low Residual β-cell Function",
 "officialTitle": "Phase 2, Multicenter, Randomized, Double-blind, Placebo-controlled Study to Assess Effect and Safety of 400 mg Twice a Day Oral Ladarixin in Patients With Recent Onset Type 1 Diabetes and Low Residual β-cell Function at Baseline (GLADIATOR)",
 "leadSponsor": {
  "name": "Dompé Farmaceutici S.p.A",
  "class": "INDUSTRY"
 },
 "startDate": "2021-01-12",
 "firstRegistered": "2020-11-09",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Recent Onset type1 Diabetes"
 ],
 "keywords": [
  "type1 diabetes"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "interventionModelDescription": "Patients were randomly (2:1) assigned to receive either ladarixin treatment (400 mg b.i.d. for 13 cycles of 14 days on/14 days off - treatment group) or matched placebo (control group). The two groups were balanced within centers.",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "maskingDescription": "The study proceeded under double-blind condition up to month 18 visit of the last patient randomized. Thereafter, the blind was broken and remaining follow-up will proceeded in an open fashion. This approach allowed to anticipate access to efficacy data without significantly affecting data integrity.",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 289,
 "briefSummary": "Objectives The objective of this clinical trial is to assess whether ladarixin treatment has an effect to preserve β-cell function and delay the progression of T1D in adolescent and adult patients.\n\nThe safety of ladarixin in the specific clinical setting will be also evaluated.",
 "detailedDescription": "The study will be a phase 2, multicenter, double-blind, placebo-controlled study. It will randomize approximately 130-140 patients (with up to an estimated 15-20% adolescents), with recent onset (within 180 days from 1st insulin administration) type 1 diabetes (T1D), assigned (2:1) to receive either oral ladarixin treatment (400 mg b.i.d. for 13 cycles of 14 days on/14 days off - treatment group) or placebo (control group). Recruitment will be competitive among the study sites, until the planned number of patients is randomized.\n\nLadarixin and placebo will be both administered for 1 year. All patients will be followed-up for 24 months from the 1st administration of the study medication. After the initial 12-m treatment period, all patients will enter into a 12-month follow-up (total period 24-month after first IMP administration). The study database (DB) will be locked when the last randomized patient has completed the month 12 visit (or being lost in follow-up), and relative data have been fully reconciled and cleaned; at that point, the DB will be unblinded and all endpoints, including the 6-month primary endpoint, will be analyzed, and the follow-up will continue under open-label conditions up to month 24.",
 "arms": [
  {
   "label": "Ladarixin",
   "type": "EXPERIMENTAL",
   "description": "400 mg b.i.d. for 13 cycles of 14 days on/14 days off",
   "interventionNames": [
    "Drug: Ladarixin"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "matching placebo b.i.d. for 13 cycles of 14 days on/14 days off",
   "interventionNames": [
    "Drug: Placebo"
   ]
