{
 "nctId": "NCT05810038",
 "briefTitle": "A Study to Learn About the Safety and Effects of Rimegepant to Prevent Migraine in Chinese Subjects.",
 "officialTitle": "A Phase 3, Randomized, Double-Blind, Placebo-Controlled Study to Evaluate the Efficacy and Safety of Rimegepant for Migraine Prevention in Chinese Participants",
 "leadSponsor": {
  "name": "Pfizer",
  "class": "INDUSTRY"
 },
 "startDate": "2023-05-15",
 "firstRegistered": "2023-03-30",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Migraine"
 ],
 "keywords": [
  "Rimegepent",
  "preventive treatment",
  "migraine."
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "QUADRUPLE",
   "whoMasked": [
    "PARTICIPANT",
    "CARE_PROVIDER",
    "INVESTIGATOR",
    "OUTCOMES_ASSESSOR"
   ]
  }
 },
 "enrollment": 787,
 "briefSummary": "The purpose of this study is to learn about the effects of Rimegepant to help prevent migraine.\n\nThis study is seeking for participants who:\n\n* Are male and female of 18 years of age or older.\n* Have at least 1 year history of migraine .\n* Did not take any medication for migraine before the start of this study. The study will go on for around 30 weeks, including 4 Phases and 11 Visits. Participants who are selected for the study will be randomly assigned to treatment groups. After which, the participants will enter a 12-week Double-blind Treatment (DBT) Phase. After finishing the DBT Phase, some selected participants may enter a 12-week Open-label Extension (OLE) Phase. Participants will come back to the study site at the end of Week 24 for the End of Treatment (EOT) Visit. There will be a follow-up Week 2 Visit around 14 days after the EOT visit.\n\nParticipants will be asked to take 1 tablet of study medicine every other calendar day. This need to be followed regardless of whether they have a migraine on that day or not. During the OLE Phase only, if a participant has a migraine on a non-scheduled dosing day, they may take 1 tablet of Rimegepant orally disintegrating tablet (ODT) as acute treatment for their migraine, if needed, with a maximum of 1 tablet of Rimegepant per calendar day. The study team will look at how each participant is doing with the study treatment during the regular visits at the study clinic.",
 "arms": [
  {
   "label": "DBT Rimegepant/OLE Rimegepant",
   "type": "EXPERIMENTAL",
   "description": "DBT Phase (Weeks 1 through 12): Participants will receive a single oral dose of rimegepant orally disintegrating tablet (ODT) EOD for 12 weeks.\n\nOLE Phase (Weeks 13 through 24): Participants who continue to meet study entry criteria, will enter the OLE phase and receive a single oral dose of rimegepant ODT EOD for 12 weeks. If participants have a migraine on a day that they are not scheduled to dose with rimegepant, they can take one tablet of rimegepant ODT on that calendar day to treat a migraine (as needed \\[PRN\\] dosing).",
   "interventionNames": [
    "Drug: Rimegepant"
   ]
  },
  {
   "label": "DBT Placebo/OLE Rimegepant",
   "type": "PLACEBO_COMPARATOR",
   "description": "DBT Phase (Weeks 1 through 12): Participants will receive a single oral dose of placebo matching to rimegepant ODT EOD for 12 weeks.\n\nOLE Phase (Weeks 13 through 24): Participants who continue to meet study entry criteria, will enter the OLE phase and receive a single oral dose of rimegepant ODT EOD for 12 weeks. If participants have a migraine on a day that they are not scheduled to dose with rimegepant, they can take one tablet of rimegepant ODT on that calendar day to treat a migraine (PRN dosing).",
   "interventionNames": [
    "Drug: Rimegepant",
    "Drug: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Rimegepant",
   "description": "Rimegepant",
   "armGroupLabels": [
    "DBT Placebo/OLE Rimegepant",
    "DBT Rimegepant/OLE Rimegepant"
   ],
   "otherNames": [
    "PF-07899801, BHV-3000"
   ]
  },
  {
   "type": "DRUG",
   "name": "Placebo",
   "description": "matching placebo",
   "armGroupLabels": [
    "DBT Placebo/OLE Rimegepant"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Mean Change From the Observation Phase (OP) in Number of Migraine Days Per Month Over the Entire DBT Phase (Weeks 1 to 12)",
   "description": "A migraine day(MD) was defined as any calendar day participant experienced a qualified migraine headache (onset,continuation,or recurrence), per electronic diary(eDiary). A qualified migraine headache was defined as a migraine with/without aura,lasted for \\>=30 minutes with \\>=2 pain features (unilateral location,pulsating quality\\[throbbing\\],moderate/severe pain intensity,aggravated by or caused avoidance of routine physical activity \\[e.g. walking/climbing stairs\\]) and/or with \\>=1 of the following associated symptoms (nausea and/or vomiting, both photophobia and phonophobia).The number(no.) of md per month (m) was prorated to 28 days and derived as:OP:28\\*\\[total no.of MD in OP analysis period\\]/(total no.of efficacy data day in OP analysis period), monthly (4-week interval) on-DBT efficacy analysis period: 28\\*(total no.of MD in m)/(total no. of efficacy data days in m),overall DBT in on-DBT efficacy analysis period:28\\*(total no.of MD through m3)/(total no.of efficacy data day through m3).",
   "timeFrame": "OP (screening of 4 weeks prior to randomization), DBT phase (Weeks 1 to 12)"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Percentage of Participants With >=50% Reduction From the OP in the Number of Moderate to Severe Migraine Days Per Month Over the Entire DBT Phase (Weeks 1 to 12)",
   "description": "A MD was defined as any calendar day participant experienced a qualified migraine headache(onset,continuation,or recurrence),per eDiary. A qualified migraine headache was defined as a migraine with/without aura,lasted for \\>=30 minutes with \\>=2 pain features(unilateral location,pulsating quality \\[throbbing\\], moderate/severe pain intensity, aggravated by or caused avoidance of routine physical activity \\[e.g. walking/climbing stairs\\]) and/or with \\>=1 of the following associated symptoms(nausea and/or vomiting, both photophobia and phonophobia).The number of MD per month was prorated to 28 days and derived as: OP: 28\\*\\[total number of MD in OP analysis period\\]/(total number of efficacy data days in OP analysis period), monthly (4-week interval) on-DBT efficacy analysis period: 28\\*(total number of MD in month)/(total number of efficacy data days in month),overall DBT in on-DBT efficacy analysis period:28\\*(total number of MD through month 3)/(total no .of efficacy data days through month 3).",
   "timeFrame": "OP (screening of 4 weeks prior to randomization), DBT Phase (Weeks 1 to 12)"
  },
  {
   "measure": "Mean Change From the OP in the Number of Migraine Days Per Month in the First 4 Weeks (Weeks 1 to 4) of the DBT Phase",
   "description": "A MD was defined as any calendar day participant experienced a qualified migraine headache(onset,continuation,or recurrence),per eDiary. A qualified migraine headache was defined as a migraine with/without aura,lasted for \\>=30 minutes with \\>=2 pain features (unilateral location,pulsating quality\\[throbbing\\],moderate/severe pain intensity,aggravated by or caused avoidance of routine physical activity\\[e.g. walking/climbing stairs\\]) and/or with \\>=1 of the following associated symptoms (nausea and/or vomiting, both photophobia and phonophobia).The number of MD per month was prorated to 28 days and derived as:OP:28\\*\\[total number of MD in OP analysis period\\]/(total number of efficacy data days in OP analysis period), monthly (4-week interval) on-DBT efficacy analysis period: 28\\*(total number of MD in month)/(total number of efficacy data days in month), overall DBT in on-DBT efficacy analysis period:28\\*(total number of MD through month 3)/(total number of efficacy data days through month 3).",
   "timeFrame": "OP (screening of 4 weeks prior to randomization), DBT phase (Weeks 1 to 4)"
  },
  {
   "measure": "Mean Change From the OP in the Number of Migraine Days Per Month in the Last 4 Weeks (Weeks 9 to 12) of the DBT Phase",
   "description": "A MD was defined as any calendar day participant experienced a qualified migraine headache(onset,continuation,or recurrence),per eDiary. A qualified migraine headache was defined as a migraine with/without aura,lasted for \\>=30 minutes with \\>=2 pain features (unilateral location,pulsating quality\\[throbbing\\],moderate/severe pain intensity,aggravated by or caused avoidance of routine physical activity \\[e.g. walking/climbing stairs\\]) and/or with \\>=1 of the following associated symptoms (nausea and/or vomiting, both photophobia and phonophobia).The number of MD per month was prorated to 28 days and derived as:OP:28\\*\\[total number of MD in OP analysis period\\]/(total number of efficacy data days in OP analysis period), monthly (4-week interval) on-DBT efficacy analysis period: 28\\*(total number of MD in month)/(total number of efficacy data days in month),overall DBT in on-DBT efficacy analysis period:28\\*(total number of MD through month 3)/(total number of efficacy data days through month 3).",
   "timeFrame": "OP (screening of 4 weeks prior to randomization), DBT phase (Weeks 9 to 12)"
  },
  {
   "measure": "Mean Change From Baseline in the Migraine-Specific Quality-of-Life Questionnaire (MSQoL) Role Function-Restrictive Domain Score at Week 12 of the DBT Phase",
   "description": "MSQoL:14-item instrument validated in 3 domains:restrictive role function,preventative role function and emotional function.Role function-restrictive domain consisted of 7 items that described how migraine limits one's daily social and work-related activities.Participants were required to respond to items using a 6-point scale ranging from 1-6, where 1=none of the time,2=little bit of the time,3=some of the time,4=good bit of the time,5=most of the time and 6=all of the time.Item scores were recorded using(7-original score).Raw dimension scores for restrictive role function domain were computed as a sum of recorded item scores(7-42) and rescaled from 0-100 scale such that lowest score(0) indicated poor quality of life(QOL) and highest scores(100) indicated better QOL.Change from baseline was calculated as MSQoL role function-restrictive domain score at Week 12 of DBT phase minus MSQoL role function-restrictive domain score at baseline.Data collected on Day 1 was referred to Baseline.",
   "timeFrame": "Baseline, DBT phase (Week 12)"
  },
  {
   "measure": "Mean Number of Acute Migraine Medication Days Per Month Over the Entire DBT Phase (Weeks 1 to 12)",
   "description": "Acute migraine-specific medication day was defined as any calendar day during which the participant took a migraine-specific medication (triptan). Acute migraine medication days were defined as either acute migraine-specific medication day or migraine day with \"yes\" response to the question about taking other medications to treat headache or aura. The number of migraine day per month was prorated to 28 days and derived as: OP: 28\\*\\[total number of migraine day in the OP analysis period\\]/(total number of efficacy data days in the OP analysis period), monthly (i.e., 4-week interval) in the on-DBT efficacy analysis period: 28\\*(total number of migraine day in the month)/(total number of efficacy data days in the month), overall DBT in the on-DBT efficacy analysis period: 28\\*(total number of migraine day through month 3)/(total number of efficacy data days through month 3).",
   "timeFrame": "DBT phase (Weeks 1 to 12)"
  },
  {
   "measure": "Number of Participants With Any On-Treatment Adverse Events (AEs) by Severity During the DBT Phase",
   "description": "An AE was defined as any new untoward medical occurrence or worsening of a pre-existing medical condition in a participant or clinical investigation participant administered an investigational (medicinal) product and that did not necessarily have a causal relationship with this treatment. AEs were graded per the common terminology criteria for adverse events (CTCAE) as grade 1 indicates mild AE, grade 2 indicates moderate AE, grade 3 indicates severe AE, grade 4 indicates life-threatening consequences and urgent intervention, and grade 5 indicates death related to AE. Number of participants who had grade 3 or 4 AEs were reported in this outcome measure.",
   "timeFrame": "From Day 1 up to 4 weeks post last dose (maximum up to 16 weeks)"
  },
  {
   "measure": "Number of Participants With Serious Adverse Events (SAEs) On-Treatment During the DBT Phase",
   "description": "An SAE was any event that met any of the criteria: death, life-threatening, inpatient hospitalization or prolongation of existing hospitalization, persistent or significant disability/incapacity, congenital anomaly/birth defect in the offspring of a participant who received rimegepant were considered an important medical event.",
   "timeFrame": "From Day 1 up to 4 weeks post last dose (maximum up to 16 weeks)"
  },
  {
   "measure": "Number of Participants With AEs Leading to Study Intervention Discontinuation During the DBT Phase",
   "description": "An AE was defined as any new untoward medical occurrence or worsening of a pre-existing medical condition in a participant or clinical investigation participant administered an investigational (medicinal) product and that does not necessarily have a causal relationship with this treatment. In this outcome measure participants with AEs leading to discontinuation of study intervention during the DBT phase were reported.",
   "timeFrame": "DBT phase: maximum of 12 weeks"
  },
  {
   "measure": "Number of Participants With Any On-Treatment Grade 3 to 4 Laboratory Test Abnormalities During the DBT Phase",
   "description": "Laboratory test included hematology (hemoglobin, lymphocytes, white blood cell count \\[high, low\\], neutrophils and platelets), serum chemistry (alkaline phosphatase \\[ALP\\], alanine aminotransferase \\[ALT\\], aspartate aminotransferase \\[AST\\], albumin, bilirubin, creatine kinase \\[CK\\], calcium \\[high, low\\], glucose fasting and non-fasting \\[high, low\\], cholesterol \\[total\\], glucose \\[low\\], creatinine, LDL cholesterol, potassium, sodium \\[high, low\\], triglycerides, uric acid \\[urate\\] and estimated glomerular filtration rate \\[eGFR\\] modification of diet in renal disease \\[MDRD\\]) and urinalysis (urine glucose and urine protein). Laboratory abnormalities were graded according to CTCAE as grade 3 indicates severe AE, grade 4 indicates life-threatening consequences and urgent intervention. Number of participants who had non-zero grade 3 to 4 laboratory test abnormalities were reported in this outcome measure.",
   "timeFrame": "From Day 1 up to 4 weeks post last dose (maximum up to 16 weeks)"
  },
  {
   "measure": "Number of Participants With Any On-Treatment AEs by Severity During the OLE Phase",
