 "nctId": "NCT06280391",
 "briefTitle": "A Proof-of-Concept Study to Assess the Efficacy, Safety and Tolerability of Itepekimab (Anti-IL-33 mAb) in Participants With Non-cystic Fibrosis Bronchiectasis",
 "officialTitle": "A Randomized, Double-blind, Placebo-controlled, Parallel-group, Proof-of-Concept (PoC) Study to Assess the Efficacy, Safety and Tolerability of Itepekimab, in Participants With Non-cystic Fibrosis Bronchiectasis",
 "leadSponsor": {
  "name": "Sanofi",
  "class": "INDUSTRY"
 },
 "collaborators": [
  {
   "name": "Regeneron Pharmaceuticals",
