 ],
 "startDate": "2024-02-20",
 "firstRegistered": "2024-02-20",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Bronchiectasis"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "TRIPLE",
   "whoMasked": [
