 "enrollment": 52,
 "briefSummary": "The primary objectives of this study are to evaluate the efficacy of DTX401 to reduce or eliminate dependence on exogenous glucose replacement therapy to maintain euglycemia and to maintain or improve the quality of glucose control.",
 "detailedDescription": "Study DTX401-CL301 is a phase 3 study to determine the efficacy and confirm the safety of DTX401 in patients 8 years and older with glycogen storage disease type Ia (GSDIa).\n\nParticipants were randomized 1:1 to DTX401 or placebo group and followed closely for 48 weeks. At week 48 eligible participants crossed over and received DTX401 if they had previously received placebo or placebo if they had previously received DTX401 and were followed closely for an additional 96 weeks. After completion of week 144 or early withdrawal, participants were offered enrollment into a Disease Monitoring Program (DMP) where they will be followed for at least 10 years post DTX401 infusion.\n\nIn Japan, there was a single open label study arm and all participants were treated with DTX401. At week 48, Japanese participants were offered enrollment into a Disease Monitoring Program (DMP) where they will be followed for at least 10 years post DTX401 infusion.",
 "arms": [
  {
   "label": "Placebo Followed by DTX401",
   "type": "EXPERIMENTAL",
   "description": "Participants received a single peripheral intravenous (IV) infusion of placebo on Day 1 along with a placebo-to-match (PTM) of the prophylactic steroid regimen of prednisolone. At Week 48, participants received a single peripheral IV infusion of 1.0 × 10\\^13 genome copies per kilogram \\[GC/kg\\]) of DTX401 along with a prophylactic steroid regimen of prednisolone.",
   "interventionNames": [
    "Genetic: DTX401",
    "Other: Placebo",
    "Drug: Oral prednisolone",
    "Drug: Placebo for oral prednisolone"
   ]
  },
  {
   "label": "DTX401 Followed by Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Participants received a single peripheral IV infusion of 1.0 × 10\\^13 GC/kg of DTX401 on Day 1, along with a prophylactic steroid regimen of prednisolone. At Week 48, participants received a single peripheral IV infusion of placebo with a PTM of the prophylactic steroid regimen of prednisolone.",
   "interventionNames": [
    "Genetic: DTX401",
    "Other: Placebo",
    "Drug: Oral prednisolone",
    "Drug: Placebo for oral prednisolone"
   ]
  },
  {
   "label": "DTX401 (Japan Only)",
   "type": "EXPERIMENTAL",
   "description": "Participants received a single peripheral IV infusion of 1.0 × 10\\^13 GC/kg of DTX401 on Day 1, along with a prophylactic steroid regimen of prednisolone.",
   "interventionNames": [
