   "timeFrame": "Baseline, Weeks 24, 30, 36, 42 and 48"
  },
  {
   "measure": "Japan Cohort: Percent Change From Baseline to Week 48 in Daily Cornstarch Intake (Grams)",
   "timeFrame": "Baseline, Weeks 24, 30, 36, 42 and 48"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Main Study: Change From Baseline to Week 48 in Number of Total Daily Doses of Cornstarch",
   "description": "The LS mean and SE are based on MMRM analysis.",
   "timeFrame": "Baseline, Weeks 24, 30, 36, 42 and 48"
  },
  {
   "measure": "Japan Cohort: Change From Baseline to Week 48 in Number of Total Daily Doses of Cornstarch",
   "timeFrame": "Baseline, Weeks 24, 30, 36, 42 and 48"
  },
  {
   "measure": "Main Study: Change From Baseline to Week 48 in Percentage of Glucose Values in Hypoglycemic Range (Less Than (<) 70 Milligrams Per Deciliter (mg/dL) [3.9 Millimoles Per Liter (mmol/L)])",
   "description": "The LS mean and SE are based on MMRM analysis.",
   "timeFrame": "Baseline, Weeks 24, 30, 36, 42 and 48"
  },
  {
   "measure": "Japan Cohort: Change From Baseline to Week 48 in Percentage of Glucose Values in Hypoglycemic Range (< 70 mg/dL [3.9 mmol/L])",
   "timeFrame": "Baseline, Weeks 24, 30, 36, 42 and 48"
  },
  {
   "measure": "Main Study: Patient Global Impression of Change (PGIC) Assessment Score at Week 48",
   "description": "The PGIC captures the participants' perspective on changes in their glycogen storage disease type Ia (GSDIa) since the start of the study using a 7-point response scale ranging from much improved (+ 3) to much worse (- 3). The total score ranges from + 3 to - 3, with a higher score indicating best outcome.",
   "timeFrame": "Week 48"
  },
  {
   "measure": "Japan Cohort: PGIC Assessment Score at Week 48",
   "description": "The PGIC captures the participants' perspective on changes in their GSDIa since the start of the study using a 7-point response scale ranging from much improved (+ 3) to much worse (- 3). The total score ranges from + 3 to - 3, with a higher score indicating best outcome.",
   "timeFrame": "Week 48"
  },
  {
   "measure": "Main Study: Change From Baseline to Week 48 in Time to Hypoglycemia (< 54 mg/dL [3.0 mmol/L]) During the Controlled Fasting Challenge (CFC)",
   "description": "The LS mean and SE are based on MMRM analysis.",
   "timeFrame": "Baseline, Weeks 36 and 48"
  },
  {
   "measure": "Japan Cohort: Change From Baseline to Week 48 in Time to Hypoglycemia (< 54 mg/dL [3.0 mmol/L]) During the CFC",
   "timeFrame": "Baseline, Weeks 36 and 48"
  },
  {
   "measure": "Main Study: Change From Baseline to Week 48 in Percentage of Glucose Values in the Range of 70-120 mg/dL (3.9-6.7 mmol/L)",
   "description": "The LS mean and SE are based on MMRM analysis.",
   "timeFrame": "Baseline, Weeks 24, 30, 36, 42 and 48"
  },
  {
   "measure": "Japan Cohort: Change From Baseline to Week 48 in Percentage of Glucose Values in the Range of 70-120 mg/dL (3.9-6.7 mmol/L)",
   "timeFrame": "Baseline, Weeks 24, 30, 36, 42 and 48"
  },
  {
   "measure": "Main Study: Number of Participants With Treatment Emergent Adverse Events (TEAEs), Adverse Events of Special Interest (AESIs), Serious TEAEs, Related TEAEs, Fatal AEs, and Discontinuation From Study or Investigational Product Due to AEs",
   "description": "Adverse event (AE) is defined as any untoward medical occurrence associated with use of a drug in humans, whether or not considered drug related. TEAE is defined as any AE not present prior to initiation of drug treatment or any AE already present that worsens in either intensity or frequency following exposure to drug treatment. SAE is an AE that meets any of following criteria in view of either Investigator or Ultragenyx: death; life-threatening; inpatient hospitalization or prolongation of existing hospitalization; disability/incapacity; congenital anomaly/birth defect not present at screening; other important medical events. AESIs are events of scientific or medical interest specific to drug treatment requiring further investigation and close monitoring to further characterize them. Hepatic reactions (vector-induced hepatic effects) were AESIs for this study and were defined as clinically significant increases in aminotransferase levels (AST/ALT) in the judgment of Investigator.",
   "timeFrame": "PEAP Arms - TEAEs with onset from Day 1 to Week 48; Crossover and Follow-up - Placebo to DTX401 Arm: TEAEs with onset after Week 48 dosing with DTX401 to Week 144; Crossover and Follow-up DTX401 Arm: TEAEs from Week 48 to Week 144"
  },
  {
   "measure": "Japan Cohort: Number of Participants With TEAEs, AESIs, Serious TEAEs, Related TEAEs, Fatal AEs, and Discontinuation From Study or Investigational Product Due to AEs",
   "description": "AE is defined as any untoward medical occurrence associated with use of a drug in humans, whether or not considered drug related. TEAE is defined as any AE not present prior to initiation of drug treatment or any AE already present that worsens in either intensity or frequency following exposure to drug treatment. SAE is an AE that meets any of following criteria in view of either Investigator or Ultragenyx: death; life-threatening; inpatient hospitalization or prolongation of existing hospitalization; disability/incapacity; congenital anomaly/birth defect not present at screening; other important medical events. AESIs are events of scientific or medical interest specific to drug treatment requiring further investigation and close monitoring to further characterize them. Hepatic reactions were considered to be important identified risk for this study and were defined as clinically significant increases in aminotransferase levels (AST/ALT) in the judgment of Investigator.",
   "timeFrame": "Day 1 to Week 48"
  }
 ],
 "eligibility": {
  "criteria": "Key Inclusion Criteria:\n\n* Documented GSDIa with confirmation by molecular testing or enzymatic activity on liver biopsy\n* Currently receiving a therapeutic regimen of cornstarch (or equivalent), following international guidance/recommendations with stable nutrition, glycemic, and clinical status.\n* Willing and able to complete the informed consent process and to comply with study procedures and visit schedule\n* Females of childbearing potential and fertile males must consent to use highly effective contraception from the period following informed consent through the duration of the 144-week study and in cases of early withdrawal at least 48 weeks after the last dose of investigational product (IP). Female subjects must agree not to become pregnant. Male subjects must agree not to father a child or donate sperm\n\nKey Exclusion Criteria:\n\n* Detectable pre-existing antibodies to the AAV8 capsid\n* History of liver transplant, including hepatocyte cell therapy/ transplant\n* History of liver disease\n* Presence of liver adenoma \\>5 cm in size\n* Presence of liver adenoma \\>3 cm and ≤5 cm in size that has a documented annual growth rate of ≥0.5 cm per year\n* Significant hepatic inflammation or cirrhosis as evidenced by imaging or any of the following laboratory abnormalities: alanine aminotransferase (ALT) or aspartate aminotransferase (AST) \\> upper limit of normal (ULN), total bilirubin \\>1.5 × ULN, alkaline phosphatase \\>2.5 × ULN\n* Non-fasting triglycerides ≥1000 mg/dL\n* Pregnant, breastfeeding, or planning to become pregnant (self or partner) at any time during the study.\n* Current or previous participation in another gene transfer study\n* History of illicit drug use within 60 days prior to screening or positive results from an 8-panel urine drug screen during the Screening Period completed at 2 time points at least 4 weeks apart\n\nNote: additional inclusion/exclusion criteria may apply, per protocol",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "8 Years"
 },
