    "Standard Tuberculosis Medicines and Metformin"
   ]
  },
  {
   "type": "DRUG",
   "name": "Metformin hydrochoride",
   "description": "Metformin hydrochloride 500 mg tablet once daily starting one week after the initiation of TB treatment, then increasing to twice daily through study week-12 (11 weeks total metformin treatment).",
   "armGroupLabels": [
    "Standard Tuberculosis Medicines and Metformin"
   ],
   "otherNames": [
    "Glucophage"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Number of Participants Experiencing Grade 3 or Higher Adverse Events",
   "description": "The cumulative number of participants in each arm experiencing grade 3 or higher adverse events, assessed on every visit from week-1 to week-24.",
   "timeFrame": "Up to 24 weeks"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Time to Sputum Liquid Culture Conversion",
   "description": "Number of weeks from baseline positive sputum culture to first negative sputum culture measured at every visit by study arm.",
   "timeFrame": "Up to 24 weeks"
  },
  {
   "measure": "Change in Radiographic Severity Score From Baseline to TB Treatment Completion",
   "description": "Difference in change in radiographic TB severity measured at baseline and week-24 by study arm. Two blinded readers scored de-identified 1-view chest X-rays using the Timika Scale. Differences in scores were resolved by consensus. The minimum score is 0 and the maximum score is 140, with a score of 140 indicating higher severity. The change in score from baseline to 24 weeks is analyzed by subtracting the baseline score from the 24 week score. High negative magnitude of change indicates greater improvement.",
   "timeFrame": "Baseline and 24 weeks"
  },
  {
   "measure": "Change in 6-minute Walk Test Distance From Baseline to TB Treatment Completion",
   "description": "Difference in change in 6-minute walk test distance measured in meters, assessed at baseline and week-24 by study arm. The 6-minute walk test measures the number of meters walked over six minutes with a higher score indicating a larger number of meters walked and a lower score indicating a smaller number of meters walked with a minimum score of 0 and a maximum score of 999. The change in 6-minute walk is calculated by subtracting the baseline walk score from the 24-week score. A higher number indicates a greater change from baseline.",
   "timeFrame": "Baseline and 24 weeks"
  },
  {
   "measure": "Change in 6-minute Walk Test Distance-saturation Product From Baseline to TB Treatment Completion",
   "description": "Difference in change in 6-minute walk test distance-saturation product measured in meters times percent oxygen saturation, assessed at baseline and at week-24 by study arm. The 6-minute walk test distance saturation product measures the number of meters a patient walks over six minutes multiplied by the oxygen saturation at completion of the walk with a higher score indicating better outcome with a minimum score of 0 and a maximum score or 999. The change in 6-minute walk saturation product is calculated by subtracting the baseline score from the 24-week score. A higher number indicates a greater change from baseline.",
   "timeFrame": "Baseline and 24 weeks"
  },
  {
   "measure": "Change in FVC From Baseline to TB Treatment Completion",
   "description": "Difference in change in Forced Vital Capacity (liters) measured at baseline and week-24 by study arm. The maximum FVC is 15 liters and the minimum is 0 liters. The difference from baseline to 24 weeks is calculated by subtracting the baseline FVC from the 24 week FVC. A higher number indicates a greater change from baseline.",
   "timeFrame": "Baseline and 24 weeks"
  },
  {
   "measure": "Change in FEV1% From Baseline to TB Treatment Completion",
   "description": "Difference between Forced Expiratory Volume in 1 second (% predicted) measured at baseline and week-24 by study arm. The maximum FEV1% is 150 and the minimum is 0. The difference from baseline to 24 weeks is calculated by subtracting the baseline FEV1% from the 24 week FEV1%. A higher number indicates a greater change from baseline.",
   "timeFrame": "Baseline and 24 weeks"
  },
  {
   "measure": "Change in St. George's Respiratory Questionnaire Score From Baseline to TB Treatment Completion",
   "description": "Difference in change in St. George's Respiratory Questionnaire score at baseline and week-24 by study arm. The St. George's Respiratory Questionnaire measures health impairment in patients with respirator disease. The potential scores range from 0 to 100 with higher scores indicating more severe impairment. The change in score from baseline to 24 weeks is analyzed by subtracting the baseline score from the 24 week score. High negative magnitude of change indicates greater improvement.",
   "timeFrame": "Baseline and 24 weeks"
  },
  {
   "measure": "Number of Participants Experiencing One or More Adverse Event of Any Grade",
   "description": "The cumulative number of participants in each arm experiencing adverse events of any grade, assessed on every visit from week-1 to week-24.",
   "timeFrame": "Up to 24 weeks"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1. Age 18 through 65 years.\n2. HIV-1 seropositive status prior to or after screening.\n3. Chest radiograph compatible with pulmonary TB.\n4. Positive sputum Xpert MTB/RIF or Xpert MTB/RIF Ultra with one cycle threshold (Ct) \\<25 or subsequent culture confirmation.\n5. RIF susceptibility diagnosed by an approved TB diagnostic test e.g. Xpert MTB/RIF (Cepheid), Xpert MTB/RIF Ultra (Cepheid) or BD MAX (Becton-Dickinson).\n6. Residence within study catchment area.\n7. If female of childbearing potential, willing to use contraception for the duration of study participation (Criteria for childbearing potential and for acceptable contraception). If male, willing to use condoms for the duration of metformin treatment plus 3 months after stopping metformin.\n8. Able and willing to provide informed consent.\n\nExclusion criteria:\n\n1. Any condition for which participation in the trial, as judged by the investigator, could compromise the well-being of the participant or prevent, limit or confound protocol-specified assessments.\n2. Is critically ill, and in the judgment of the investigator has a diagnosis likely to result in death during the trial or the follow-up period.\n3. TB meningitis or other forms of severe TB with high risk of a poor outcome as judged by the investigator.\n4. Pregnant or breastfeeding.\n5. Resistance to any first-line ATT drug demonstrated by susceptibility testing.\n6. More than 14 days ATT for the current episode of TB, prior to enrollment.\n7. Taking any fluoroquinolone antibiotic.\n8. History of diabetes mellitus or fasting blood glucose \\>7.0 mmol/L on screening evaluation.\n9. History of congestive heart failure, chronic liver disease, diabetes, autoimmune disease or malignancy.\n10. Consumption of \\>28 units (men) OR \\>21 units (women) of alcohol/week.\n11. Use of metformin within 1 year prior to enrollment.\n12. History of sensitivity to metformin.\n13. Acute or chronic metabolic acidosis based on reported medical history or laboratory tests performed on screening.\n14. Body mass index (BMI) \\<17kg/m\\^2 on screening evaluation.\n15. Peripheral blood CD4 + T cell count \\<50 cells/mm\\^3 on screening evaluation.\n16. Hemoglobin \\<9 g/dL for males, and \\<8 g/dL (women) for females on screening evaluation.\n17. Platelet count \\<50,000/mm\\^3 on screening evaluation.\n18. Absolute neutrophil count \\<750 cells/mm\\^3 on screening evaluation.\n19. Estimated glomerular filtration rate (eGFR) \\<60 mL/min/1.73m\\^2 calculated by the Chronic Kidney Disease Epidemiology Collaboration (CKD-EPI) equation.\n20. Serum bicarbonate \\<18 mmol/L on screening evaluation.\n21. Aspartate Aminotransferase (AST) or Alanine Aminotransferase (ALT) ≥3 times the upper limit of normal (ULN) on screening evaluation.\n22. Hepatitis B surface antigen positive.\n23. Enrollment in another interventional study at any time during participation in the METHOD trial.\n24. Imprisonment at the time of or after enrollment in the METHOD trial.\n25. Diagnosis of active Coronavirus Disease 2019 (COVID-19) at the time of screening or high suspicion of active COVID-19 disease during screening.",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years",
  "maximumAge": "65 Years"
 },
 "siteCount": 2,
 "countries": [
  "South Africa"
 ]
}

