 "officialTitle": "A Randomized Trial of Sirolimus (Rapamune(R)) for Relapse Prevention in Patients With Severe Aplastic Anemia Responsive to Immunosuppressive Therapy",
 "leadSponsor": {
  "name": "National Heart, Lung, and Blood Institute (NHLBI)",
  "class": "NIH"
 },
 "startDate": "2016-12-19",
 "firstRegistered": "2016-12-01",
 "hasDataMonitoringCommittee": true,
 "conditions": [
