{
 "nctId": "NCT04584255",
 "briefTitle": "Niraparib + Dostarlimab In BRCA Mutated Breast Cancer",
 "officialTitle": "A Phase II Study of Niraparib With Dostarlimab Therapy as Neoadjuvant Treatment for Patients With BRCA-mutated Breast Cancer",
 "leadSponsor": {
  "name": "Dana-Farber Cancer Institute",
  "class": "OTHER"
 },
 "collaborators": [
  {
   "name": "Translational Breast Cancer Research Consortium",
   "class": "OTHER"
  },
  {
   "name": "Johns Hopkins University",
   "class": "OTHER"
  },
  {
