  "Invasive Breast Cancer Stage II",
  "Invasive Breast Cancer Stage III",
  "Breast Cancer",
  "HER2-negative invasive tumor"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "NONE"
  }
 },
 "enrollment": 66,
 "briefSummary": "This research study involves pre-operative therapy that is specifically targeted for breast cancer in individuals with BRCA and PALB2 mutations.\n\nThe names of the study drugs involved in this study are:\n\n* Niraparib (Zejula)\n* Dostarlimab",
 "detailedDescription": "The research study procedures include screening for eligibility and study treatment including laboratory evaluations, two mandatory research biopsies, imaging assessments, and follow up visits.\n\nParticipants will receive treatment for 18 weeks. After 18 weeks, participants will be evaluated to determine if a candidate for surgery or if additional treatment outside of the study.\n\nParticipants with triple negative breast cancer will be randomized to one of two treatment arms.\n\n* Arm A: Niraparib with Dostarlimab for 18 weeks\n* Arm B: Niraparib alone for 3 weeks, followed by Niraparib with Dostarlimab for 15 weeks\n\nParticipants with estrogen receptor positive breast cancer will be placed directly into Arm C. There is no randomization for these participants.\n\n\\- Arm C: Niraparib with dostarlimab for 18 weeks\n\nIt is expected that about 62 people will take part in this research study.\n\nThis research study is a Phase II clinical trial. Phase II clinical trials test the safety and effectiveness of an investigational drug or drug combination to learn whether the drug combination works in treating a specific disease. \"Investigational\" means that the study drugs, Niraparib and Dostarlimab, are being studied for use in this setting and the research doctors are trying to learn more about the drug combination-the side effects the combination may cause and if it is effective in treating this type of cancer.\n\nThe U.S. Food and Drug Administration (FDA) has not yet approved either of the drugs in this study for your type of cancer. Niraparib has been approved by the FDA for treatment of advanced ovarian cancer in BRCA mutation carriers.\n\nThe use of Dostarlimab in this research study is experimental, which means that it is not approved by any regulatory auit is not approved by any regulatory authority, including the FDA, for treatment of breast cancer, or any other disease.",
 "arms": [
  {
   "label": "Arm A Triple Negative Breast Cancer (TNBC)",
   "type": "EXPERIMENTAL",
   "description": "Participants will be randomized 1:1 to treatment with the combination (Arm A)\n\n* Niraparib-Daily beginning with week 1, day 1\n* Dostarlimab-Once every three weeks beginning with week 1, day 1",
   "interventionNames": [
    "Drug: Niraparib",
    "Drug: Dostarlimab"
   ]
  },
  {
   "label": "Arm B TNBC",
   "type": "EXPERIMENTAL",
   "description": "Participants will be randomized 1:1 to treatment with the combination (Arm B)\n\n* 3-week lead-in of niraparib monotherapy followed by treatment with the combination\n* Niraparib Daily beginning with week 1, day 1\n* Dostarlimab Once every three weeks beginning with week 4, day 1",
   "interventionNames": [
    "Drug: Niraparib",
    "Drug: Dostarlimab"
   ]
  },
  {
   "label": "Arm C ER+/HER2-",
   "type": "EXPERIMENTAL",
   "description": "exploratory cohort of estrogen receptor (ER) positive HER2-negative participants will be enrolled to Arm C.\n\n* Niraparib Daily beginning with week 1, day 1\n* Dostarlimab Once every three weeks beginning with week 1, day 1",
   "interventionNames": [
    "Drug: Niraparib",
    "Drug: Dostarlimab"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Niraparib",
   "description": "Predetermined dosage PO Daily",
   "armGroupLabels": [
    "Arm A Triple Negative Breast Cancer (TNBC)",
    "Arm B TNBC",
    "Arm C ER+/HER2-"
   ],
   "otherNames": [
    "Zejula"
   ]
  },
  {
   "type": "DRUG",
   "name": "Dostarlimab",
   "description": "Predetermined Dosage, IV,q3 weeks",
   "armGroupLabels": [
    "Arm A Triple Negative Breast Cancer (TNBC)",
    "Arm B TNBC",
    "Arm C ER+/HER2-"
   ],
   "otherNames": [
    "TSR042"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change in Tumor-infiltrating Lymphocytes (TILs)",
   "description": "Change in TILs score from baseline to cycle 2 day 1; the score is estimated by a pathologist according to the International Immuno-Oncology Biomarker Working Group on Breast Cancer guidelines, as the percentage (0-100) of the tumor's stromal area occupied by mononuclear immune cells on a stained tissue slide; higher scores generally correlate with improved survival outcomes and better responses to chemotherapy",
   "timeFrame": "baseline to 21 days (cycle 2 day 1)"
  },
  {
   "measure": "Pathologic Complete Response (pCR) Rate in TNBC",
   "description": "The number and percentage of participants achieving pCR without additional neoadjuvant therapy; the residual cancer burden (RCB) method as described by Symmans et al. was used to assess response, with increasing RCB score associated with greater burden of residual disease after surgery; RCB-0 reflects pCR (no residual disease), whereas RCB-I, RCB-II, and RCB-III reflect minimal, moderate, and extensive residual disease, respectively",
   "timeFrame": "18 weeks"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "pCR Rate in ER+/HER2- Breast Cancer",
   "description": "The number and percentage of participants achieving pCR without additional neoadjuvant therapy; the residual cancer burden (RCB) method as described by Symmans et al. was used to assess response, with increasing RCB score associated with greater burden of residual disease after surgery; RCB-0 reflects pCR (no residual disease), whereas RCB-I, RCB-II, and RCB-III reflect minimal, moderate, and extensive residual disease, respectively",
   "timeFrame": "18 weeks"
  },
  {
   "measure": "Association Between Change in TILs Score and pCR",
   "description": "The association between change in TILs score (%) from baseline to cycle 2 day 1 (18 weeks) and pCR status (pCR vs. no pCR), evaluated using a two-sample Wilcoxon rank sum test; the odds ratio for a fixed change in TILs estimated using simple logistic regression; TILs score was measured as described in Outcome Measure 1, and because the TILs score reflects a percentage, the change was calculated as the raw difference in TILs score between time points; pCR was measured as described in Outcome Measure 2",
   "timeFrame": "baseline to 18 weeks"
  },
  {
   "measure": "Rate of Residual Cancer Burden (RCB)-0/1 Response",
   "description": "The residual cancer burden (RCB) method as described by Symmans et al. was used to assess response, with increasing RCB score associated with greater burden of residual disease after surgery; RCB-0 reflects pCR (no residual disease), whereas RCB-I, RCB-II, and RCB-III reflect minimal, moderate, and extensive residual disease, respectively; an RCB score of 0 or I is considered good response; this Outcome Measure reports the percentage of patients achieving an RCB score of 0 or I vs. not",
   "timeFrame": "18 Weeks"
  },
  {
   "measure": "Treatment-related Adverse Events",
   "description": "Number and percentage of patients with treatment-related, grade 2 or higher adverse events per NCI Common Terminology Criteria for Adverse Events (CTCAE) version 5.0",
   "timeFrame": "baseline up to 31 weeks"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Participants must meet the following criteria on screening examination to be eligible to participate in the study. Laboratory assessments for eligibility must be completed within 14 days prior to the date of registration. Diagnostic imaging, such as MRIs and CT scans, must be performed within 28 days of the planned treatment start.\n* Participants must have histologically or cytologically confirmed invasive breast cancer Stage I to III with primary tumor size at least 1.0 cm defined by physical exam or imaging (whichever is larger). In the case of a multifocal, multicentric, or bilateral disease, the largest lesion must be ≥ 1.0 cm and designated as the \"index\" lesion for tumor evaluations. Patients with inflammatory breast carcinoma are not eligible.\n* Participants must have documentation of estrogen receptor (ER) and progesterone receptor (PR) testing by IHC according to local institutional guidelines in a CLIA-approved setting. Central confirmation of ER/PR status is not required. All tumors must be HER2 negative.\n\n  * Arms A and B: Target lesion must be ER and PR negative (\\<10% staining) by local review.\n  * Arm C: Target lesion must be ER and/or PR positive (\\>10% staining) by local review.\n* Participants must have documented HER2-negative invasive tumor according to local institutional guidelines in a CLIA-approved setting. Central confirmation of HER2 status is not required. HER2 negative is defined as:\n\n  * 0 or 1+ by IHC, OR\n  * Lack of gene amplification with HER2/CEP17 ratio \\< 2 by ISH, OR\n  * Copy number \\< 6 by ISH\n* Participants must have documented germline mutation in BRCA1, BRCA2 or PALB2 that is deleterious or suspected to be deleterious (known or predicted to be detrimental/lead to loss of function). Mutation must be identified through a CLIA-approved laboratory. Final determination of eligibility for any discordant results in pathogenicity will be made by the sponsor-investigator. A formal eligibility exception will not be required in these cases as long as approval by overall study PI is granted and documented.\n* Participants with multifocal, multicentric or bilateral disease are eligible if at least one lesion meets criteria for the study. In this circumstance, the investigator must determine which will represent the target lesion to be assessed for response. This should remain consistent throughout the study. The target lesion should be selected on the basis of its size (lesion with the longest diameter) and suitability for accurate repetitive measurements.\n* Participants with an eligible target lesion, and another small HER2+ tumor (for example, \\< 6 mm), may be eligible for enrollment following discussion and agreement with the overall principal investigator. A formal eligibility exception will not be required in these cases as long as approval by the sponsor-investigator is granted and documented.\n* Female or male ≥ 18 years of age\n* Breast imaging should include imaging of the ipsilateral axilla. For subjects with a clinically positive axilla by physical examination or imaging, axillary tissue acquisition is not required. For patients with a clinically negative axilla by examination and imaging, tissue acquisition is not required. For equivocal imaging findings, tissue acquisition (a needle aspiration, core biopsy) is required. Sentinel Lymph Node (SLN) biopsy before neoadjuvant therapy is not allowed.\n* ECOG performance status of 0 or 1\n* Adequate organ and bone marrow function as defined below:\n\n  * Absolute neutrophil count (ANC) ≥ 1500/mm3\n  * Platelet count ≥ 100,000/mm3\n  * Hemoglobin ≥ 9 g/dl\n  * Total serum bilirubin ≤ 1.5 × institutional upper limit of normal (ULN), (≤2.0 in patients with documented Gilbert's Syndrome)\n  * AST (SGOT) and ALT (SGPT) ≤ 2.5 × institutional ULN\n  * Serum or plasma creatinine ≤ 1.5 × institutional ULN, OR calculated creatinine clearance \\> 50 mL/min using the Cockcroft-Gault equation\n  * International normalized ratio (INR) OR prothrombin time (PT) ≤1.5× ULN. Participants who are receiving anticoagulant therapy are eligible as long as PT or partial thromboplastin (PTT) is within therapeutic range of intended use of anticoagulants. Activated partial thromboplastin time (aPTT) must be ≤1.5× ULN unless patient is receiving anticoagulant therapy as long as PT or PTT is within therapeutic range of intended use of anticoagulants\n* Premenopausal women must have a negative urine or serum pregnancy test within 7 days of treatment start. Women are considered non-childbearing (by other than medical reasons) if they:\n\n  * are ≥45 years of age and without menses for \\>1 year\n  * have been amenorrhoeic for \\<2 years without history of a hysterectomy and oophorectomy with a follicle stimulating hormone value in the postmenopausal range upon screening evaluation\n  * are post-hysterectomy, post-bilateral oophorectomy, or post-tubal ligation. Documented hysterectomy or oophorectomy must be confirmed with medical records of the actual procedure or confirmed by an ultrasound. Tubal ligation must be confirmed with medical records of the actual procedure, otherwise the patient must be willing to use an adequate barrier method throughout the study, starting with the screening visit through 180 days after the last dose of study treatment. See list of acceptable birth control methods. Information must be captured appropriately within the site's source documents. Note: Abstinence is acceptable if this is the established and preferred contraception for the patient.\n* Male and female participants of childbearing potential must agree to adhere to adequate contraception as defined in the protocol for the duration of study participation and for 150 days after the last dose of study treatment.\n* Female participants must agree to not breastfeed during the study or for 150 days after the last dose of study treatment.\n* Participants must agree to not donate blood during the study or for 90 days after the last dose of study treatment.\n* Ability to understand and willingness to sign an informed consent document.\n* Ability to swallow and retain oral medication.\n* Patients undergoing breast conserving therapy (ie lumpectomy) should not have any contraindications to radiation therapy.\n* Participants must be willing to undergo the mandatory research biopsy at baseline and after 3 weeks on study treatment. Participants who undergo an attempted research biopsy procedure for the purpose of this protocol and in whom inadequate tissue is obtained are not required to undergo a repeat biopsy in order to continue on the protocol.\n\nExclusion Criteria:\n\n* Stage IV breast cancer.\n* Concurrent therapy with any other investigational product\n* Prior treatment for the current breast cancer, including prior chemotherapy, immune therapy, hormonal therapy, radiation, or investigational therapy for this diagnosis.\n* Excisional biopsy of the primary tumor and/or excision of axillary lymph nodes, including SLNB, prior to study treatment.\n* Participants with a history of malignancy are ineligible except in the following circumstances:\n\n  * Individuals with a history of invasive breast cancer are not eligible unless they have been disease-free for a minimum of three years.\n  * Individuals with a malignancy history other than invasive breast cancer are eligible if they have no active malignancy and are deemed by the investigator to be at low risk for recurrence of that malignancy.\n  * Individuals with the following cancer history are eligible: adequately treated nonmelanoma skin cancers, curatively treated in situ cancer of the cervix, ductal carcinoma in situ (DCIS) of the breast, stage 1 grade 1 endometrial carcinoma.\n  * Other exceptions may exist following agreement with the sponsor-investigator\n* Patients with a diagnosis of immunodeficiency, or currently receiving systemic steroid therapy or any other form of immunosuppressive within 7 days prior to the first dose of study treatment. Use of local corticosteroid injections (e.g. intraarticular injections), inhaled, intranasal, ophthalmic, and topical corticosteroids, and subjects requiring corticosteroid pre-medication for hypersensitivity reactions (e.g. CT scan pre-medication) are allowed.\n* Patients with autoimmune disease that has required systemic treatment within the past 2 years (i.e. with use of disease-modifying agents, corticosteroids, or immunosuppressive drugs). Replacement therapy (e.g. thyroxine, insulin, or physiologic corticosteroid replacement therapy for adrenal or pituitary insufficiency, etc.) is not considered a form of systemic treatment.\n* Patients with a history of interstitial lung disease or pneumonitis.\n* Patients who have received a live vaccine within 2 weeks prior to the start of study treatment.\n* Patients who have undergone any major surgery within 3 weeks prior to study entry, patients must have recovered to baseline from any effects of any major surgery.\n* Patients with concurrent HIV infection are eligible provided they meet the following criteria:\n\n  * CD4+ T-cell (CD4+) counts ≥ 350 cells/uL\n  * No history of AIDS-defining opportunistic infection within 12 months prior to enrollment\n  * Any medication used in an antiretroviral therapy (ART) regimen must have no known interaction with the study agents\n* Patients with active or chronic Hepatitis B or C are eligible provided they meet the liver function laboratory criteria described in 3.1.10 and cannot be on any medication with a known interaction with the study agents\n* Uncontrolled intercurrent illness including, but not limited to, ongoing or active infection, symptomatic congestive heart failure, unstable angina pectoris, cardiac arrhythmia, recent (within 90 days) myocardial infarction, uncontrolled major seizure disorder, unstable spinal cord compression, superior vena cava syndrome or psychiatric illness/social situations that would limit compliance with study requirements.\n* History of allergic reactions attributed to compounds of similar chemical or biologic composition to niraparib, dostarlimab, or their excipients.\n* Transfusion (platelets or red blood cells) ≤ 4 weeks prior to initiating protocol therapy.\n* Known history of myelodysplastic syndrome (MDS) or or acute myeloid leukemia (AML).",
  "healthyVolunteers": false,
  "sex": "ALL",
  "minimumAge": "18 Years"
 },
 "siteCount": 8,
 "countries": [
  "United States"
 ]
}

